  Future<void> _restoreSnapshotAndStart() async {
    await _loadUiPrefs();
    await _loadStoreState();
    await _loadAnalysisSettingsPrefs();
    await _loadSavedDefaultSnapshot();
    if (_activeSection == AppSection.menu ||
        _activeSection == AppSection.gambitQuiz) {
      unawaited(_playMenuMusic());
    }
  }

  Future<void> _loadUiPrefs() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      _muteSounds = prefs.getBool(_muteSoundsKey) ?? false;
      _hapticsEnabled = prefs.getBool(_hapticsEnabledKey) ?? true;
      _isCinematicThemeEnabled =
          prefs.getBool(_cinematicThemeEnabledKey) ?? false;
      _cinematicThemeNotifier.value = _isCinematicThemeEnabled;
      if (mounted) {
        final themeProvider = context.read<AppThemeProvider>();
        final boardThemeIndex = themeProvider.boardThemeIndex;
        final pieceThemeIndex = themeProvider.pieceThemeIndex;
        final arrowThemeIndex = themeProvider.arrowThemeIndex;
        if (boardThemeIndex >= 0 &&
            boardThemeIndex < BoardThemeMode.values.length) {
          _boardThemeMode = BoardThemeMode.values[boardThemeIndex];
        }
        if (pieceThemeIndex >= 0 &&
            pieceThemeIndex < PieceThemeMode.values.length) {
          _pieceThemeMode = PieceThemeMode.values[pieceThemeIndex];
        }
        if (arrowThemeIndex >= 0 &&
            arrowThemeIndex < ArrowThemeMode.values.length) {
          _arrowThemeMode = ArrowThemeMode.values[arrowThemeIndex];
        }
        unawaited(
          themeProvider.syncLegacySettings(
            cinematicEnabled: _isCinematicThemeEnabled,
            notify: false,
          ),
        );
      }
      _loadQuizPrefs(prefs);
    } catch (e) {
      debugPrint('Failed to load UI prefs: $e');
    }
  }

  Future<void> _loadAnalysisSettingsPrefs() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final savedPerspective = prefs.getInt(_analysisPerspectiveKey);
      final savedDepth = prefs.getInt(_analysisEngineDepthKey);
      final savedMultiPv = prefs.getInt(_analysisMultiPvKey);
      final savedMoveAssessment = prefs.getBool(
        _analysisMoveAssessmentEnabledKey,
      );
      final savedLockedHeadToHeadPerspective = prefs.getBool(
        _analysisLockedHeadToHeadPerspectiveKey,
      );
      final savedHeadToHeadEvalBarEnabled = prefs.getBool(
        _analysisHeadToHeadEvalBarEnabledKey,
      );
      final savedRemoteFriendTimeControl = prefs.getInt(
        _analysisRemoteFriendTimeControlKey,
      );
      final savedRemoteFriendSeatPreference = prefs.getInt(
        _analysisRemoteFriendSeatPreferenceKey,
      );
      final savedOpeningButtonMode = prefs.getInt(
        _analysisOpeningButtonModeKey,
      );
      final savedLocalFriendTimeControl = prefs.getInt(
        _analysisLocalFriendTimeControlKey,
      );

      if (savedPerspective != null &&
          savedPerspective >= 0 &&
          savedPerspective < BoardPerspective.values.length) {
        _perspective = BoardPerspective.values[savedPerspective];
        if (_perspective != BoardPerspective.headToHead) {
          _analysisStandardPerspective = _perspective;
        }
      }
      if (savedDepth != null) {
        _engineDepth = savedDepth.clamp(10, _maxDepthAllowed);
      }
      if (savedMultiPv != null) {
        _multiPvCount = savedMultiPv.clamp(0, _maxSuggestionsAllowed);
      }
      if (savedMoveAssessment != null) {
        _moveAssessmentEnabled = savedMoveAssessment;
      }
      if (savedLockedHeadToHeadPerspective != null) {
        _lockedHeadToHeadPerspective = savedLockedHeadToHeadPerspective;
      }
      if (savedHeadToHeadEvalBarEnabled != null) {
        _headToHeadEvalBarEnabled = savedHeadToHeadEvalBarEnabled;
      }
      if (savedRemoteFriendTimeControl != null &&
          savedRemoteFriendTimeControl >= 0 &&
          savedRemoteFriendTimeControl < _localFriendTimeControls.length) {
        _remoteFriendTimeControlIndex = savedRemoteFriendTimeControl;
      }
      if (savedRemoteFriendSeatPreference != null &&
          savedRemoteFriendSeatPreference >= 0 &&
          savedRemoteFriendSeatPreference <
              RemoteFriendSeatPreference.values.length) {
        _remoteFriendSeatPreference =
            RemoteFriendSeatPreference.values[savedRemoteFriendSeatPreference];
      }
      if (savedOpeningButtonMode != null &&
          savedOpeningButtonMode >= 0 &&
          savedOpeningButtonMode < OpeningMode.values.length) {
        final savedMode = OpeningMode.values[savedOpeningButtonMode];
        if (savedMode != OpeningMode.off) {
          _analysisOpeningButtonMode = savedMode;
        }
      }
      if (savedLocalFriendTimeControl != null &&
          savedLocalFriendTimeControl >= 0 &&
          savedLocalFriendTimeControl < _localFriendTimeControls.length) {
        _localFriendTimeControlIndex = savedLocalFriendTimeControl;
      }
    } catch (e) {
      debugPrint('Failed to load analysis settings prefs: $e');
    }
  }

  Future<void> _setMute(bool value) async {
    setState(() => _muteSounds = value);
    final prefs = await SharedPreferences.getInstance();
    await prefs.setBool(_muteSoundsKey, value);
    if (value) {
      await _introAudioPlayer.stop();
      await _stopMenuMusic(fadeOut: false);
      await _sfxAudioPlayer.stop();
      await Future.wait(_boardSfxPlayers.map((player) => player.stop()));
    } else if (_activeSection != AppSection.analysis) {
      await _playMenuMusic();
    }
  }

