  bool get _hasTimedLocalFriendClock =>
      _isLocalFriendMatchMode &&
      _selectedLocalFriendTimeControl.initialTime != null;

  Duration _localFriendDisplayedClock({required bool white}) {
    final stored = white
        ? _localFriendWhiteClockRemaining
        : _localFriendBlackClockRemaining;
    if (_localFriendActiveClockIsWhite != white ||
        _localFriendActiveClockStartedAt == null) {
      return stored;
    }

    final elapsed = DateTime.now().difference(
      _localFriendActiveClockStartedAt!,
    );
    final remaining = _localFriendActiveClockBaseline - elapsed;
    return remaining.isNegative ? Duration.zero : remaining;
  }

  String _formatLocalFriendClock(Duration remaining) {
    final totalMilliseconds = remaining.inMilliseconds.clamp(0, 59999999);
    final totalSeconds = totalMilliseconds ~/ 1000;
    final minutes = totalSeconds ~/ 60;
    final seconds = totalSeconds % 60;
    if (totalSeconds >= 60) {
      return '$minutes:${seconds.toString().padLeft(2, '0')}';
    }

    final tenths = (totalMilliseconds % 1000) ~/ 100;
    return '0:${seconds.toString().padLeft(2, '0')}.$tenths';
  }

  void _initializeLocalFriendClocks() {
    final initialTime = _selectedLocalFriendTimeControl.initialTime;
    _localFriendActiveClockBaseline = Duration.zero;
    _localFriendActiveClockStartedAt = null;
    _localFriendActiveClockIsWhite = null;
    if (initialTime == null) {
      _localFriendWhiteClockRemaining = Duration.zero;
      _localFriendBlackClockRemaining = Duration.zero;
      return;
    }

    _localFriendWhiteClockRemaining = initialTime;
    _localFriendBlackClockRemaining = initialTime;
  }

  void _stopLocalFriendClock({bool clearDisplay = false}) {
    _localFriendClockTimer?.cancel();
    _localFriendClockTimer = null;

    if (!clearDisplay &&
        _localFriendActiveClockIsWhite != null &&
        _localFriendActiveClockStartedAt != null) {
      final remaining = _localFriendDisplayedClock(
        white: _localFriendActiveClockIsWhite!,
      );
      if (_localFriendActiveClockIsWhite!) {
        _localFriendWhiteClockRemaining = remaining;
      } else {
        _localFriendBlackClockRemaining = remaining;
      }
    }

    _localFriendActiveClockBaseline = Duration.zero;
    _localFriendActiveClockStartedAt = null;
    _localFriendActiveClockIsWhite = null;

    if (clearDisplay) {
      _localFriendWhiteClockRemaining = Duration.zero;
      _localFriendBlackClockRemaining = Duration.zero;
    }
  }

  void _completeLocalFriendTurn({required bool moverIsWhite}) {
    if (!_isLocalFriendMatchMode) {
      return;
    }

    _stopLocalFriendClock();
    if (!_hasTimedLocalFriendClock) {
      return;
    }

    final increment = _selectedLocalFriendTimeControl.increment;
    if (increment <= Duration.zero) {
      return;
    }

    if (moverIsWhite) {
      _localFriendWhiteClockRemaining += increment;
    } else {
      _localFriendBlackClockRemaining += increment;
    }
  }

  void _startLocalFriendClockForCurrentTurn() {
    if (!_hasTimedLocalFriendClock ||
        _gameOutcome != null ||
        _activeSection != AppSection.analysis) {
      return;
    }

    _localFriendClockTimer?.cancel();
    _localFriendActiveClockIsWhite = _isWhiteTurn;
    _localFriendActiveClockBaseline = _isWhiteTurn
        ? _localFriendWhiteClockRemaining
        : _localFriendBlackClockRemaining;
    _localFriendActiveClockStartedAt = DateTime.now();
    _localFriendClockTimer = Timer.periodic(
      const Duration(milliseconds: 200),
      _tickLocalFriendClock,
    );
    if (mounted) {
      setState(() {});
    }
  }

  void _tickLocalFriendClock(Timer timer) {
    if (!_isLocalFriendMatchMode ||
        !_hasTimedLocalFriendClock ||
        _gameOutcome != null ||
        _localFriendActiveClockIsWhite == null) {
      timer.cancel();
      if (identical(_localFriendClockTimer, timer)) {
        _localFriendClockTimer = null;
      }
      return;
    }

    final whiteToFlag = _localFriendActiveClockIsWhite!;
    final remaining = _localFriendDisplayedClock(white: whiteToFlag);
    if (remaining <= Duration.zero) {
      timer.cancel();
      if (identical(_localFriendClockTimer, timer)) {
        _localFriendClockTimer = null;
      }
      if (!mounted) {
        return;
      }
      setState(() {
        if (whiteToFlag) {
          _localFriendWhiteClockRemaining = Duration.zero;
        } else {
          _localFriendBlackClockRemaining = Duration.zero;
        }
      });
      _endLocalFriendOnTime(whiteFlagged: whiteToFlag);
      return;
    }

    if (mounted) {
      setState(() {});
    }
  }

  void _endLocalFriendOnTime({required bool whiteFlagged}) {
    final outcome = whiteFlagged ? GameOutcome.blackWin : GameOutcome.whiteWin;
    _send('stop');
    _stopLocalFriendClock();
    if (!mounted) {
      return;
    }
    setState(() {
      _localFriendEndedOnTime = true;
      _recordLocalFriendSeriesOutcome(outcome);
      _gameOutcome = outcome;
      _gameDrawReason = null;
      _botThinking = false;
      _clearCheckAlertState();
    });
    unawaited(_startGameResultReveal(outcome));
  }

  String _localFriendTimeoutTitle(GameOutcome outcome) {
    return outcome == GameOutcome.whiteWin
        ? 'WHITE WINS ON TIME'
        : 'BLACK WINS ON TIME';
  }

  String _localFriendTimeoutSubtitle(GameOutcome outcome) {
    return outcome == GameOutcome.whiteWin
        ? 'Black ran out of time before the next move could be made.'
        : 'White ran out of time before the next move could be made.';
  }

  String _localFriendTimeoutDialogMessage(GameOutcome outcome) {
    return outcome == GameOutcome.whiteWin
        ? 'Black flagged before completing the move. Continue to inspect, or reset the board to start another shared game.'
        : 'White flagged before completing the move. Continue to inspect, or reset the board to start another shared game.';
  }

  void _resetLocalFriendSeries() {
    _localFriendBottomSeatIsWhite = false;
    _localFriendBottomSeatWins = 0;
    _localFriendTopSeatWins = 0;
  }

  bool get _localFriendTopSeatIsWhite => !_localFriendBottomSeatIsWhite;

  bool get _friendClockTopShowsWhite =>
      _isLocalFriendMatchMode ? _localFriendTopSeatIsWhite : false;

  bool get _friendClockBottomShowsWhite =>
      _isLocalFriendMatchMode ? _localFriendBottomSeatIsWhite : true;

  String _localFriendSeatLabelForColor(bool white) {
    return white == _localFriendBottomSeatIsWhite ? 'BOTTOM' : 'TOP';
  }

  int _localFriendSeatScoreForColor(bool white) {
    return white == _localFriendBottomSeatIsWhite
        ? _localFriendBottomSeatWins
        : _localFriendTopSeatWins;
  }

  void _recordLocalFriendSeriesOutcome(GameOutcome outcome) {
    if (!_isLocalFriendMatchMode) {
      return;
    }
    if (outcome == GameOutcome.draw) {
      return;
    }

    final whiteWon = outcome == GameOutcome.whiteWin;
    final bottomSeatWon = _localFriendBottomSeatIsWhite == whiteWon;
    if (bottomSeatWon) {
      _localFriendBottomSeatWins += 1;
    } else {
      _localFriendTopSeatWins += 1;
    }
  }

  void _advanceLocalFriendSeriesToNextRound() {
    _localFriendBottomSeatIsWhite = !_localFriendBottomSeatIsWhite;
  }

  Future<void> _startLocalFriendMatch() async {
    try {
      unawaited(_stopMenuMusic(fadeOut: true));
      if (!mounted) {
        return;
      }

      if (_activeSection == AppSection.analysis && _isAnalysisMatchMode) {
        _persistAnalysisSnapshotIfNeeded();
      }

      setState(() {
        _resetLocalFriendSeries();
        _prepareAnalysisMatchEntry(MatchMode.localFriend);
        _resetVsBotSessionState();
        _perspective = BoardPerspective.headToHead;
      });

      _resetBoard(initialLaunch: false, withIntro: false);
      if (!mounted) {
        return;
      }

      setState(() {
        _initializeLocalFriendClocks();
      });
      _startLocalFriendClockForCurrentTurn();
    } catch (e) {
      _addLog('Start local friend match failed: $e');
      debugPrint('Start local friend match failed: $e');
    }
  }

  RemoteFriendTimeControl get _selectedRemoteFriendTimeControl {
    final preset = _selectedRemoteFriendTimeControlPreset;
    return RemoteFriendTimeControl(
      initialSeconds: preset.initialTime?.inSeconds ?? 0,
      incrementSeconds: preset.increment.inSeconds,
    );
  }

  String _formatRemoteFriendTimeControl(RemoteFriendTimeControl control) {
    if (control.isUntimed) {
      return 'Untimed';
    }
    final minutes = control.initialSeconds ~/ 60;
    final seconds = control.initialSeconds % 60;
    final baseLabel = seconds == 0
        ? '$minutes'
        : '$minutes:${seconds.toString().padLeft(2, '0')}';
    return '$baseLabel+${control.incrementSeconds.clamp(0, 60)}';
  }

  int _remoteFriendDisplayedClockMs({required bool white}) {
    final snapshot = _remoteFriendSnapshot;
    if (snapshot == null) {
      return 0;
    }

    return _remoteFriendDisplayedClockMsForSnapshot(snapshot, white: white);
  }

  int _remoteFriendDisplayedClockMsForSnapshot(
    RemoteFriendMatchSnapshot snapshot, {
    required bool white,
  }) {
    final storedMs = white
        ? snapshot.whiteTimeRemainingMs
        : snapshot.blackTimeRemainingMs;
    if (snapshot.timeControl.isUntimed ||
        snapshot.status != RemoteFriendMatchStatus.active ||
        snapshot.outcome != null) {
      return max(0, storedMs);
    }

    final activeSeat = snapshot.activeClockSeat;
    final lastTickStartedAt = snapshot.lastTickStartedAt;
    if (activeSeat == null ||
        lastTickStartedAt == null ||
        (activeSeat == RemoteFriendSeat.white) != white) {
      return max(0, storedMs);
    }

    final elapsedMs = DateTime.now()
        .difference(lastTickStartedAt)
        .inMilliseconds;
    return max(0, storedMs - max(0, elapsedMs));
  }

  Duration _remoteFriendDisplayedClock({required bool white}) {
    return Duration(milliseconds: _remoteFriendDisplayedClockMs(white: white));
  }

  RemoteFriendSeat? _remoteFriendPlayerSeatForSnapshot(
    RemoteFriendMatchSnapshot snapshot,
  ) {
    final uid = _remoteFriendLocalUid;
    if (uid == null || uid.isEmpty) {
      return null;
    }
    if (snapshot.whiteUid == uid) {
      return RemoteFriendSeat.white;
    }
    if (snapshot.blackUid == uid) {
      return RemoteFriendSeat.black;
    }
    return null;
  }

  bool _remoteFriendPieceSelectionOpenForSnapshot(
    RemoteFriendMatchSnapshot snapshot,
  ) {
    final deadline = snapshot.pieceSelectionDeadlineAt;
    return snapshot.status == RemoteFriendMatchStatus.active &&
        snapshot.outcome == null &&
        deadline != null &&
        DateTime.now().isBefore(deadline);
  }

  String? _remoteFriendPieceSelectionSessionIdForSnapshot(
    RemoteFriendMatchSnapshot snapshot,
  ) {
    if (!_remoteFriendPieceSelectionOpenForSnapshot(snapshot)) {
      return null;
    }
    final deadline = snapshot.pieceSelectionDeadlineAt;
    final playerSeat = _remoteFriendPlayerSeatForSnapshot(snapshot);
    if (deadline == null || playerSeat == null) {
      return null;
    }
    return '${snapshot.matchId}:${playerSeat.name}:${deadline.millisecondsSinceEpoch}';
  }

  void _syncRemoteFriendPieceSelectionUi(RemoteFriendMatchSnapshot snapshot) {
    final sessionId = _remoteFriendPieceSelectionSessionIdForSnapshot(snapshot);
    if (sessionId == null) {
      _remoteFriendPieceSelectionReady = false;
      _remoteFriendPieceSelectionSessionId = null;
      return;
    }
    if (_remoteFriendPieceSelectionSessionId != sessionId) {
      _remoteFriendPieceSelectionSessionId = sessionId;
      _remoteFriendPieceSelectionReady = false;
    }
  }

  RemoteFriendInvite _remoteFriendInviteFromSnapshot(
    RemoteFriendMatchSnapshot snapshot,
  ) {
    return RemoteFriendInvite(
      matchId: snapshot.matchId,
      inviteCode: snapshot.inviteCode,
      hostUid: snapshot.hostUid,
      status: snapshot.status,
      createdAt: snapshot.createdAt,
      expiresAt: snapshot.expiresAt ?? snapshot.updatedAt,
    );
  }

  bool _remoteFriendSnapshotNeedsAuthoritativeRefresh(
    RemoteFriendMatchSnapshot snapshot,
  ) {
    final now = DateTime.now();
    final expiresAt = snapshot.expiresAt;
    if (snapshot.status == RemoteFriendMatchStatus.pending) {
      return expiresAt != null && !now.isBefore(expiresAt);
    }

    if (snapshot.status != RemoteFriendMatchStatus.active ||
        snapshot.outcome != null) {
      return false;
    }

    final pieceSelectionDeadlineAt = snapshot.pieceSelectionDeadlineAt;
    if (pieceSelectionDeadlineAt != null &&
        !now.isBefore(pieceSelectionDeadlineAt)) {
      return true;
    }

    if (expiresAt != null && !now.isBefore(expiresAt)) {
      return true;
    }

    final activeSeat = snapshot.activeClockSeat;
    if (snapshot.timeControl.isUntimed || activeSeat == null) {
      return false;
    }

    return _remoteFriendDisplayedClockMsForSnapshot(
          snapshot,
          white: activeSeat == RemoteFriendSeat.white,
        ) <=
        0;
  }

  Duration _remoteFriendPollIntervalForSnapshot(
    RemoteFriendMatchSnapshot snapshot,
  ) {
    if (snapshot.status == RemoteFriendMatchStatus.pending) {
      return const Duration(seconds: 4);
    }

    if (snapshot.status != RemoteFriendMatchStatus.active ||
        snapshot.outcome != null) {
      return const Duration(seconds: 6);
    }

    if (_remoteFriendPieceSelectionOpenForSnapshot(snapshot)) {
      return const Duration(seconds: 2);
    }

    final playerSeat = _remoteFriendPlayerSeatForSnapshot(snapshot);
    final isPlayersTurn =
        playerSeat != null &&
        ((playerSeat == RemoteFriendSeat.white && snapshot.whiteToMove) ||
            (playerSeat == RemoteFriendSeat.black && !snapshot.whiteToMove));
    return isPlayersTurn
        ? const Duration(seconds: 4)
        : const Duration(seconds: 2);
  }

  String _formatRemoteFriendMembershipTimestamp(DateTime updatedAt) {
    final now = DateTime.now();
    final difference = now.difference(updatedAt);
    if (difference.inMinutes < 1) {
      return 'just now';
    }
    if (difference.inHours < 1) {
      return '${difference.inMinutes}m ago';
    }
    if (difference.inDays < 1) {
      return '${difference.inHours}h ago';
    }
    final month = updatedAt.month.toString().padLeft(2, '0');
    final day = updatedAt.day.toString().padLeft(2, '0');
    final hour = updatedAt.hour.toString().padLeft(2, '0');
    final minute = updatedAt.minute.toString().padLeft(2, '0');
    return '$month/$day $hour:$minute';
  }

  String _remoteFriendMembershipStatusLabel(RemoteFriendMatchStatus status) {
    switch (status) {
      case RemoteFriendMatchStatus.pending:
        return 'Waiting for friend';
      case RemoteFriendMatchStatus.active:
        return 'In progress';
      case RemoteFriendMatchStatus.completed:
        return 'Completed';
      case RemoteFriendMatchStatus.expired:
        return 'Expired';
      case RemoteFriendMatchStatus.cancelled:
        return 'Cancelled';
    }
  }

  Future<void> _ensureRemoteFriendLocalUid() async {
    await FirebaseAuthService.instance.initialize();
    final uid = FirebaseAuthService.instance.uid;
    if (uid == null || uid.isEmpty) {
      throw StateError(
        'Remote friend play requires a valid anonymous identity.',
      );
    }
    _remoteFriendLocalUid = uid;
  }

  Future<String?> _promptRemoteFriendInviteCode() async {
    final controller = TextEditingController();
    try {
      final inviteCode = await showDialog<String?>(
        context: context,
        builder: (dialogContext) {
          return AlertDialog(
            title: const Text('Join Remote Friend Match'),
            content: TextField(
              controller: controller,
              autofocus: true,
              textCapitalization: TextCapitalization.characters,
              maxLength: 6,
              decoration: const InputDecoration(
                labelText: 'Invite code',
                hintText: 'ABC123',
              ),
              onSubmitted: (value) {
                Navigator.of(dialogContext).pop(value.trim().toUpperCase());
              },
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.of(dialogContext).pop(),
                child: const Text('Cancel'),
              ),
              FilledButton(
                onPressed: () => Navigator.of(
                  dialogContext,
                ).pop(controller.text.trim().toUpperCase()),
                child: const Text('Join'),
              ),
            ],
          );
        },
      );
      final normalized = inviteCode?.trim().toUpperCase();
      return normalized == null || normalized.isEmpty ? null : normalized;
    } finally {
      controller.dispose();
    }
  }

  Future<void> _copyRemoteFriendInviteCode({String? inviteCode}) async {
    final code =
        inviteCode?.trim().toUpperCase() ??
        _remoteFriendInvite?.inviteCode ??
        _remoteFriendSnapshot?.inviteCode;
    if (code == null || code.isEmpty) {
      return;
    }
    await Clipboard.setData(ClipboardData(text: code));
    if (!mounted) {
      return;
    }
    ChessIqTransientMessage.show(
      context,
      title: 'Invite code copied',
      message: code,
      icon: Icons.content_copy_rounded,
      emphasizeMessage: true,
    );
  }

  Future<void> _shareRemoteFriendInviteCode({String? inviteCode}) async {
    final code =
        inviteCode?.trim().toUpperCase() ??
        _remoteFriendInvite?.inviteCode ??
        _remoteFriendSnapshot?.inviteCode;
    if (code == null || code.isEmpty) {
      return;
    }

    try {
      final renderBox = context.findRenderObject() as RenderBox?;
      final shareOrigin = renderBox == null
          ? null
          : renderBox.localToGlobal(Offset.zero) & renderBox.size;
      await Share.share(
        'Join my private ChessIQ match with invite code $code. '
        'Open VS Mode, choose Friend on Another Phone, then enter the code.',
        subject: 'ChessIQ private match invite',
        sharePositionOrigin: shareOrigin,
      );
    } catch (e) {
      _addLog('Share remote invite failed: $e');
      if (!mounted) {
        return;
      }
      ChessIqTransientMessage.show(
        context,
        title: 'Share unavailable',
        message: 'Could not open the share sheet for this invite.',
        icon: Icons.share_rounded,
      );
    }
  }

  void _stopRemoteFriendSyncTimers() {
    _remoteFriendPollTimer?.cancel();
    _remoteFriendPollTimer = null;
    _remoteFriendClockDisplayTimer?.cancel();
    _remoteFriendClockDisplayTimer = null;
    _remoteFriendPollInFlight = false;
  }

  void _resetRemoteFriendSessionState({bool clearMemberships = false}) {
    _stopRemoteFriendSyncTimers();
    _remoteFriendInvite = null;
    _remoteFriendSnapshot = null;
    _remoteFriendLastError = null;
    _remoteFriendOutcomeReason = null;
    _remoteFriendOperationInProgress = false;
    _remoteFriendPieceSelectionReady = false;
    _remoteFriendReactionInFlight = false;
    _remoteFriendPieceSelectionSessionId = null;
    if (clearMemberships) {
      _remoteFriendMemberships = <RemoteFriendMatchMembership>[];
    }
  }

  void _startRemoteFriendSyncTimers({bool immediateRefresh = false}) {
    _stopRemoteFriendSyncTimers();
    final snapshot = _remoteFriendSnapshot;
    if (!_isRemoteFriendMatchMode || snapshot == null) {
      return;
    }

    if (_remoteFriendNeedsDisplayTickerForSnapshot(snapshot)) {
      final displayTickerInterval =
          (_isRemoteFriendTimedMatch || _isRemoteFriendPieceSelectionOpen)
          ? const Duration(milliseconds: 250)
          : const Duration(seconds: 1);
      _remoteFriendClockDisplayTimer = Timer.periodic(displayTickerInterval, (
        timer,
      ) {
        final currentSnapshot = _remoteFriendSnapshot;
        if (!mounted ||
            !_isRemoteFriendMatchMode ||
            currentSnapshot == null ||
            !_remoteFriendNeedsDisplayTickerForSnapshot(currentSnapshot) ||
            _gameOutcome != null) {
          timer.cancel();
          if (identical(_remoteFriendClockDisplayTimer, timer)) {
            _remoteFriendClockDisplayTimer = null;
          }
          return;
        }
        setState(() {});
      });
    }

    if (snapshot.status == RemoteFriendMatchStatus.pending ||
        snapshot.status == RemoteFriendMatchStatus.active) {
      _remoteFriendPollTimer = Timer.periodic(
        _remoteFriendPollIntervalForSnapshot(snapshot),
        (_) => unawaited(_refreshRemoteFriendMatch(silent: true)),
      );
      if (immediateRefresh) {
        unawaited(_refreshRemoteFriendMatch(silent: true));
      }
    }
  }

  Future<void> _loadRemoteFriendMemberships({bool silent = false}) async {
    if (_remoteFriendMembershipsLoading) {
      return;
    }

    if (mounted) {
      setState(() {
        _remoteFriendMembershipsLoading = true;
      });
    }

    try {
      await _ensureRemoteFriendLocalUid();
      final memberships = await RemoteFriendService.instance
          .fetchMyMatchMemberships();
      if (!mounted) {
        return;
      }
      setState(() {
        _remoteFriendMemberships = memberships;
        _remoteFriendMembershipsLoading = false;
        if (!silent) {
          _remoteFriendLastError = null;
        }
      });
    } catch (e) {
      _addLog('Load remote friend matches failed: $e');
      if (!mounted) {
        return;
      }
      setState(() {
        _remoteFriendMembershipsLoading = false;
        _remoteFriendLastError = e.toString();
      });
      if (!silent) {
        unawaited(
          _showThemedErrorDialog(
            title: 'Remote Matches Unavailable',
            message:
                'Could not load your private remote matches. Check your connection and try again.',
            includeInternetHint: true,
          ),
        );
      }
    }
  }

  GameOutcome? _remoteOutcomeToGameOutcome(RemoteFriendOutcomeCode? code) {
    switch (code) {
      case RemoteFriendOutcomeCode.whiteWin:
        return GameOutcome.whiteWin;
      case RemoteFriendOutcomeCode.blackWin:
        return GameOutcome.blackWin;
      case RemoteFriendOutcomeCode.draw:
        return GameOutcome.draw;
      case RemoteFriendOutcomeCode.aborted:
      case null:
        return null;
    }
  }

  DrawReason? _drawReasonFromRemoteOutcome(String? reason) {
    switch ((reason ?? '').trim()) {
      case 'threefoldRepetition':
        return DrawReason.threefoldRepetition;
      case 'fiftyMoveRule':
        return DrawReason.fiftyMoveRule;
      case 'insufficientMaterial':
        return DrawReason.insufficientMaterial;
      case 'stalemate':
        return DrawReason.stalemate;
    }
    return null;
  }

  _FenDerivedBoardPosition _deriveBoardPositionFromFen(String fen) {
    try {
      final parts = fen.trim().split(RegExp(r'\s+'));
      if (parts.length < 4) {
        throw const FormatException('FEN must contain at least 4 fields.');
      }
      final board = <String, String>{};
      final ranks = parts[0].split('/');
      if (ranks.length != 8) {
        throw const FormatException('FEN board must contain 8 ranks.');
      }
      for (int rankIndex = 0; rankIndex < ranks.length; rankIndex++) {
        final rank = ranks[rankIndex];
        int fileIndex = 0;
        for (final char in rank.split('')) {
          final emptyCount = int.tryParse(char);
          if (emptyCount != null) {
            fileIndex += emptyCount;
            continue;
          }
          final isWhite = char == char.toUpperCase();
          final pieceType = switch (char.toLowerCase()) {
            'p' => 'p',
            'r' => 't',
            'n' => 'n',
            'b' => 'b',
            'q' => 'q',
            'k' => 'k',
            _ => '',
          };
          if (pieceType.isEmpty || fileIndex > 7) {
            throw const FormatException('Unsupported FEN piece data.');
          }
          final square =
              '${String.fromCharCode(97 + fileIndex)}${8 - rankIndex}';
          board[square] = '${pieceType}_${isWhite ? 'w' : 'b'}';
          fileIndex += 1;
        }
      }

      final castlingRights = parts[2];
      final whiteKingMoved =
          !(castlingRights.contains('K') || castlingRights.contains('Q'));
      final blackKingMoved =
          !(castlingRights.contains('k') || castlingRights.contains('q'));

      return _FenDerivedBoardPosition(
        boardState: board,
        whiteToMove: parts[1] == 'w',
        whiteKingMoved: whiteKingMoved,
        blackKingMoved: blackKingMoved,
        whiteKingsideRookMoved: !castlingRights.contains('K'),
        whiteQueensideRookMoved: !castlingRights.contains('Q'),
        blackKingsideRookMoved: !castlingRights.contains('k'),
        blackQueensideRookMoved: !castlingRights.contains('q'),
        enPassantTarget: parts[3] == '-' ? null : parts[3],
      );
    } catch (e) {
      _addLog('Remote match FEN hydrate failed: $e');
      return _FenDerivedBoardPosition(
        boardState: _initialBoardState(),
        whiteToMove: true,
        whiteKingMoved: false,
        blackKingMoved: false,
        whiteKingsideRookMoved: false,
        whiteQueensideRookMoved: false,
        blackKingsideRookMoved: false,
        blackQueensideRookMoved: false,
        enPassantTarget: null,
      );
    }
  }

  List<MoveRecord> _buildRemoteFriendMoveHistory(
    RemoteFriendMatchSnapshot snapshot,
  ) {
    final history = <MoveRecord>[];
    var previousPosition = _FenDerivedBoardPosition(
      boardState: _initialBoardState(),
      whiteToMove: true,
      whiteKingMoved: false,
      blackKingMoved: false,
      whiteKingsideRookMoved: false,
      whiteQueensideRookMoved: false,
      blackKingsideRookMoved: false,
      blackQueensideRookMoved: false,
      enPassantTarget: null,
    );

    for (final move in snapshot.moves) {
      final nextPosition = _deriveBoardPositionFromFen(move.fen);
      final from = move.uci.length >= 2 ? move.uci.substring(0, 2) : '';
      final to = move.uci.length >= 4 ? move.uci.substring(2, 4) : '';
      final fallbackPiece = move.ply.isOdd ? 'p_w' : 'p_b';
      final pieceMoved = previousPosition.boardState[from] ?? fallbackPiece;

      String? pieceCaptured = previousPosition.boardState[to];
      if (pieceCaptured == null &&
          from.length == 2 &&
          to.length == 2 &&
          pieceMoved.startsWith('p_') &&
          from[0] != to[0]) {
        final captureSquare = '${to[0]}${from[1]}';
        pieceCaptured = previousPosition.boardState[captureSquare];
      }

      history.add(
        MoveRecord(
          notation: move.san.isNotEmpty ? move.san : move.uci,
          pieceMoved: pieceMoved,
          pieceCaptured: pieceCaptured,
          state: Map<String, String>.from(nextPosition.boardState),
          isWhite: pieceMoved.endsWith('_w'),
          whiteKingMoved: nextPosition.whiteKingMoved,
          blackKingMoved: nextPosition.blackKingMoved,
          whiteKingsideRookMoved: nextPosition.whiteKingsideRookMoved,
          whiteQueensideRookMoved: nextPosition.whiteQueensideRookMoved,
          blackKingsideRookMoved: nextPosition.blackKingsideRookMoved,
          blackQueensideRookMoved: nextPosition.blackQueensideRookMoved,
          enPassantTarget: nextPosition.enPassantTarget,
          uci: move.uci,
        ),
      );
      previousPosition = nextPosition;
    }

    return history;
  }

  void _applyRemoteFriendSnapshot({
    required RemoteFriendInvite invite,
    required RemoteFriendMatchSnapshot snapshot,
  }) {
    final previousSnapshot = _remoteFriendSnapshot;
    final shouldRebuildBoard =
        previousSnapshot == null ||
        previousSnapshot.matchId != snapshot.matchId ||
        previousSnapshot.fen != snapshot.fen ||
        previousSnapshot.nextPly != snapshot.nextPly ||
        previousSnapshot.status != snapshot.status ||
        previousSnapshot.outcome?.code != snapshot.outcome?.code ||
        previousSnapshot.outcome?.reason != snapshot.outcome?.reason;

    _remoteFriendInvite = invite;
    _remoteFriendSnapshot = snapshot;
    _remoteFriendOutcomeReason = snapshot.outcome?.reason;
    _remoteFriendLastError = null;
    _syncRemoteFriendPieceSelectionUi(snapshot);

    final playerSeat = _remoteFriendPlayerSeat;
    if (playerSeat != null) {
      _perspective = playerSeat == RemoteFriendSeat.black
          ? BoardPerspective.black
          : BoardPerspective.white;
    }

    if (!shouldRebuildBoard) {
      return;
    }

    final derivedPosition = _deriveBoardPositionFromFen(snapshot.fen);
    final moveHistory = _buildRemoteFriendMoveHistory(snapshot);
    final remoteOutcome = _remoteOutcomeToGameOutcome(snapshot.outcome?.code);

    _cancelGameResultReveal();
    _clearBotGhostArrows();
    _clearVsBotOverlayState();
    _cancelPendingMoveQualityGrading();
    _clearPositionAnalysisCache();
    _clearMoveQualityOverlay();
    _clearMoveQualityBadge();
    _holdSelectedFrom = null;
    _gambitSelectedFrom = null;
    _legalTargets.clear();
    _gambitAvailableTargets.clear();
    _selectedGambit = null;
    _gambitPreviewLines = <EngineLine>[];
    _openingMode = OpeningMode.off;
    _suggestionsEnabled = false;
    _vsBotEvalEnabled = false;
    _vsBotOptimalLineRevealActive = false;
    _vsBotCharge = 0;
    _botThinking = false;
    _topLines = <EngineLine>[];
    _analysisLines = <EngineLine>[];
    _analysisLinesFen = null;
    _currentDepth = 0;
    _currentEval = 0.0;
    _evalWhiteTurn = true;
    _gameResultDialogVisible = false;
    _clearCheckAlertState();
    _localFriendEndedOnTime = false;
    boardState = Map<String, String>.from(derivedPosition.boardState);
    _isWhiteTurn = derivedPosition.whiteToMove;
    _whiteKingMoved = derivedPosition.whiteKingMoved;
    _blackKingMoved = derivedPosition.blackKingMoved;
    _whiteKingsideRookMoved = derivedPosition.whiteKingsideRookMoved;
    _whiteQueensideRookMoved = derivedPosition.whiteQueensideRookMoved;
    _blackKingsideRookMoved = derivedPosition.blackKingsideRookMoved;
    _blackQueensideRookMoved = derivedPosition.blackQueensideRookMoved;
    _enPassantTarget = derivedPosition.enPassantTarget;
    _moveHistory
      ..clear()
      ..addAll(moveHistory);
    _historyIndex = _moveHistory.isEmpty ? -1 : _moveHistory.length - 1;
    _resetDerivedDrawState();
    for (final record in _moveHistory) {
      _recordDerivedDrawStateAfterMove(
        pieceMoved: record.pieceMoved,
        pieceCaptured: record.pieceCaptured,
      );
    }
    _currentOpening = '';
    _updateCurrentOpening();

    if (remoteOutcome == null) {
      _clearGameOutcomeState();
      _gameResultDialogVisible = false;
      _gameDrawReason = null;
    } else {
      _gameOutcome = remoteOutcome;
      _gameDrawReason = _drawReasonFromRemoteOutcome(snapshot.outcome?.reason);
    }
  }

  Future<void> _enterRemoteFriendMatch({
    required RemoteFriendInvite invite,
    required RemoteFriendMatchSnapshot snapshot,
  }) async {
    await _ensureRemoteFriendLocalUid();
    final localUid = _remoteFriendLocalUid;
    final seat = localUid != null && snapshot.blackUid == localUid
        ? RemoteFriendSeat.black
        : RemoteFriendSeat.white;

    try {
      unawaited(_stopMenuMusic(fadeOut: true));
      if (!mounted) {
        return;
      }

      if (_activeSection == AppSection.analysis && _isAnalysisMatchMode) {
        _persistAnalysisSnapshotIfNeeded();
      }

      setState(() {
        _prepareAnalysisMatchEntry(MatchMode.remoteFriend);
        _perspective = seat == RemoteFriendSeat.black
            ? BoardPerspective.black
            : BoardPerspective.white;
      });

      _resetBoard(initialLaunch: false, withIntro: false);
      if (!mounted) {
        return;
      }

      final previousOutcome = _remoteFriendSnapshot?.matchId == snapshot.matchId
          ? _remoteFriendSnapshot?.outcome?.code
          : null;
      setState(() {
        _applyRemoteFriendSnapshot(invite: invite, snapshot: snapshot);
      });
      _startRemoteFriendSyncTimers(immediateRefresh: true);
      unawaited(
        PushNotificationService.instance.prepareRemoteFriendNotifications(),
      );

      if (previousOutcome == null && snapshot.outcome != null) {
        final gameOutcome = _remoteOutcomeToGameOutcome(snapshot.outcome?.code);
        if (gameOutcome != null) {
          unawaited(_startGameResultReveal(gameOutcome));
        }
      }
    } catch (e) {
      _addLog('Enter remote friend match failed: $e');
      debugPrint('Enter remote friend match failed: $e');
      rethrow;
    }
  }

  ({String title, String message, bool includeInternetHint})
  _remoteFriendJoinFailurePresentation(String? reason) {
    switch ((reason ?? '').trim()) {
      case 'match-full':
        return (
          title: 'Match Full',
          message:
              'That private invite has already been claimed by another player.',
          includeInternetHint: false,
        );
      case 'expired':
        return (
          title: 'Invite Expired',
          message:
              'That private invite expired before you joined. Ask your friend to create a new code.',
          includeInternetHint: false,
        );
      case 'cancelled':
        return (
          title: 'Invite Cancelled',
          message: 'That private invite was cancelled by the host.',
          includeInternetHint: false,
        );
      case 'completed':
        return (
          title: 'Match Finished',
          message:
              'That invite now belongs to a finished match. Ask your friend for a fresh code.',
          includeInternetHint: false,
        );
      case 'match-unavailable':
        return (
          title: 'Invite Unavailable',
          message:
              'That private invite is no longer available. Ask your friend to create a new code.',
          includeInternetHint: false,
        );
      default:
        return (
          title: 'Join Failed',
          message:
              'Could not join that private invite code. Make sure the code is correct and the match is still available.',
          includeInternetHint: true,
        );
    }
  }

  ({String title, String message, bool includeInternetHint})
  _remoteFriendActionFailurePresentation(
    RemoteFriendMatchAction action,
    String? reason,
  ) {
    switch ((reason ?? '').trim()) {
      case 'cannot-cancel':
        return (
          title: 'Invite Already Changed',
          message:
              'This invite can no longer be cancelled because the match state changed.',
          includeInternetHint: false,
        );
      case 'cannot-resign':
        return (
          title: 'Resign Unavailable',
          message:
              'You can only resign an active remote match that you are currently playing.',
          includeInternetHint: false,
        );
      case 'cannot-offer-draw':
        return (
          title: 'Draw Unavailable',
          message:
              'A draw can only be offered while an active remote match is in progress.',
          includeInternetHint: false,
        );
      case 'draw-offer-pending':
        return (
          title: 'Draw Already Offered',
          message:
              'A draw offer is already waiting for the other player to respond.',
          includeInternetHint: false,
        );
      case 'cannot-accept-draw':
      case 'cannot-decline-draw':
      case 'no-draw-offer':
        return (
          title: 'Draw Offer Missing',
          message:
              'There is no active draw offer for you to respond to anymore.',
          includeInternetHint: false,
        );
      case 'expired':
      case 'cancelled':
      case 'completed':
      case 'match-unavailable':
        return (
          title: 'Match Unavailable',
          message:
              'That remote friend action could not be applied because the match is no longer active.',
          includeInternetHint: false,
        );
      default:
        final fallbackVerb = switch (action) {
          RemoteFriendMatchAction.cancelPending => 'cancel the invite',
          RemoteFriendMatchAction.resign => 'resign the match',
          RemoteFriendMatchAction.offerDraw => 'offer a draw',
          RemoteFriendMatchAction.acceptDraw => 'accept the draw',
          RemoteFriendMatchAction.declineDraw => 'decline the draw',
        };
        return (
          title: 'Action Unavailable',
          message:
              'ChessIQ could not $fallbackVerb because the match state changed. The board has been refreshed to the latest server state.',
          includeInternetHint: false,
        );
    }
  }

  String _remoteFriendMoveRejectionMessage(String? reason) {
    switch ((reason ?? '').trim()) {
      case 'stale-client':
        return 'The board changed before your move arrived. ChessIQ refreshed to the latest server position.';
      case 'not-your-turn':
        return 'It is no longer your turn. The board has been refreshed.';
      case 'piece-selection-pending':
        return 'Both players are still choosing piece skins. The match starts when the 10-second selection window ends.';
      case 'illegal-move':
        return 'That move is no longer legal in the current server position.';
      case 'invalid-position':
        return 'The server could not validate the current position. ChessIQ refreshed to the latest board state.';
      case 'expired':
      case 'cancelled':
      case 'completed':
        return 'This remote match is no longer active. The board has been refreshed.';
      case 'match-unavailable':
        return 'This remote match is no longer available. The board has been refreshed.';
      case 'not-participant':
        return 'This device is no longer recognized as a participant in that remote match.';
      default:
        return 'That move could not be synchronized, so ChessIQ refreshed to the latest server state.';
    }
  }

  String _cleanRemoteFriendErrorMessage(Object error) {
    final message = error.toString().trim();
    for (final prefix in const <String>['Exception: ', 'Bad state: ']) {
      if (message.startsWith(prefix)) {
        return message.substring(prefix.length).trim();
      }
    }
    return message;
  }

  void _showRemoteFriendNotice(String message) {
    if (!mounted || message.trim().isEmpty) {
      return;
    }
    ChessIqTransientMessage.show(
      context,
      title: 'Private match update',
      message: message,
      icon: Icons.groups_rounded,
    );
  }

  Future<void> _createRemoteFriendInvite() async {
    if (_remoteFriendOperationInProgress) {
      return;
    }
    setState(() {
      _remoteFriendOperationInProgress = true;
    });
    try {
      await _ensureRemoteFriendLocalUid();
      final result = await RemoteFriendService.instance.createInvite(
        timeControl: _selectedRemoteFriendTimeControl,
        defaultPieceThemeIndex: _pieceThemeMode.index,
        seatPreference: _remoteFriendSeatPreference,
      );
      if (!mounted) {
        return;
      }
      await _enterRemoteFriendMatch(
        invite: result.invite,
        snapshot: result.snapshot,
      );
      unawaited(_loadRemoteFriendMemberships(silent: true));
      await _copyRemoteFriendInviteCode(inviteCode: result.invite.inviteCode);
    } catch (e) {
      _addLog('Create remote friend invite failed: $e');
      if (!mounted) {
        return;
      }
      await _showThemedErrorDialog(
        title: 'Invite Failed',
        message:
            'Could not create a private remote invite. Check your connection and try again.',
        includeInternetHint: true,
      );
    } finally {
      if (mounted) {
        setState(() {
          _remoteFriendOperationInProgress = false;
        });
      }
    }
  }

  Future<void> _joinRemoteFriendInvite() async {
    if (_remoteFriendOperationInProgress) {
      return;
    }
    final inviteCode = await _promptRemoteFriendInviteCode();
    if (inviteCode == null) {
      return;
    }
    setState(() {
      _remoteFriendOperationInProgress = true;
    });
    try {
      await _ensureRemoteFriendLocalUid();
      final result = await RemoteFriendService.instance.joinInvite(
        inviteCode,
        defaultPieceThemeIndex: _pieceThemeMode.index,
      );
      if (!mounted) {
        return;
      }
      if (!result.success) {
        _addLog('Join remote invite rejected: ${result.reason ?? 'unknown'}');
        final failure = _remoteFriendJoinFailurePresentation(result.reason);
        await _showThemedErrorDialog(
          title: failure.title,
          message: failure.message,
          includeInternetHint: failure.includeInternetHint,
        );
        return;
      }
      await _enterRemoteFriendMatch(
        invite: result.invite,
        snapshot: result.snapshot,
      );
      unawaited(_loadRemoteFriendMemberships(silent: true));
    } catch (e) {
      _addLog('Join remote friend invite failed: $e');
      if (!mounted) {
        return;
      }
      await _showThemedErrorDialog(
        title: 'Join Failed',
        message:
            'Could not join that private invite code. Make sure the code is correct and the match is still available.',
        includeInternetHint: true,
      );
    } finally {
      if (mounted) {
        setState(() {
          _remoteFriendOperationInProgress = false;
        });
      }
    }
  }

  Future<void> _selectRemoteFriendPieceTheme(PieceThemeMode mode) async {
    final snapshot = _remoteFriendSnapshot;
    if (snapshot == null ||
        snapshot.matchId.isEmpty ||
        _remoteFriendOperationInProgress ||
        !_isRemoteFriendPieceSelectionOpen) {
      return;
    }

    setState(() {
      _remoteFriendOperationInProgress = true;
    });

    try {
      final result = await RemoteFriendService.instance.selectPieceTheme(
        matchId: snapshot.matchId,
        pieceThemeIndex: mode.index,
      );
      if (!mounted) {
        return;
      }
      setState(() {
        _applyRemoteFriendSnapshot(
          invite: result.invite,
          snapshot: result.snapshot,
        );
      });
      _startRemoteFriendSyncTimers();
      if (!result.success) {
        _showRemoteFriendNotice(
          'The piece-skin selection window already closed. The match will continue with the current skins.',
        );
      }
    } catch (e) {
      _addLog('Select remote friend piece theme failed: $e');
      if (!mounted) {
        return;
      }
      _showRemoteFriendNotice(
        'Could not update your piece skin before the match started.',
      );
      await _refreshRemoteFriendMatch(silent: true);
    } finally {
      if (mounted) {
        setState(() {
          _remoteFriendOperationInProgress = false;
        });
      }
    }
  }

  Future<void> _sendRemoteFriendReaction(String emoji) async {
    final snapshot = _remoteFriendSnapshot;
    if (snapshot == null ||
        snapshot.matchId.isEmpty ||
        snapshot.status != RemoteFriendMatchStatus.active ||
        snapshot.outcome != null ||
        _isRemoteFriendPieceSelectionOpen ||
        _remoteFriendReactionInFlight ||
        _remoteFriendOperationInProgress) {
      return;
    }

    final localCooldown = _remoteFriendReactionCooldownRemainingForSnapshot(
      snapshot,
    );
    if (localCooldown > Duration.zero) {
      _showRemoteFriendNotice(
        'Quick reacts recharge every 30 seconds. Try again in ${_formatRemoteFriendReactionCooldown(localCooldown)}.',
      );
      return;
    }

    setState(() {
      _remoteFriendReactionInFlight = true;
    });

    try {
      final result = await RemoteFriendService.instance.sendReaction(
        matchId: snapshot.matchId,
        emoji: emoji,
      );
      if (!mounted) {
        return;
      }

      setState(() {
        _applyRemoteFriendSnapshot(
          invite: result.invite,
          snapshot: result.snapshot,
        );
      });
      _startRemoteFriendSyncTimers();

      if (!result.success) {
        _addLog('Remote reaction rejected: ${result.reason ?? 'unknown'}');
        _showRemoteFriendNotice(
          _remoteFriendReactionFailureMessage(result.reason),
        );
        return;
      }

      unawaited(_lightHaptic());
    } catch (e) {
      _addLog('Send remote friend reaction failed: $e');
      if (!mounted) {
        return;
      }
      _showRemoteFriendNotice(
        'Could not send that quick reaction. The match will refresh to the latest state.',
      );
      await _refreshRemoteFriendMatch(silent: true);
    } finally {
      if (mounted) {
        setState(() {
          _remoteFriendReactionInFlight = false;
        });
      }
    }
  }

  Future<void> _openRemoteFriendMatch(String matchId) async {
    if (_remoteFriendOperationInProgress) {
      return;
    }
    setState(() {
      _remoteFriendOperationInProgress = true;
    });
    try {
      await _ensureRemoteFriendLocalUid();
      final result = await RemoteFriendService.instance.refreshMatch(matchId);
      if (!mounted) {
        return;
      }
      await _enterRemoteFriendMatch(
        invite: result.invite,
        snapshot: result.snapshot,
      );
      unawaited(_loadRemoteFriendMemberships(silent: true));
    } catch (e) {
      _addLog('Open remote friend match failed: $e');
      if (!mounted) {
        return;
      }
      await _showThemedErrorDialog(
        title: 'Match Unavailable',
        message:
            'That remote friend match could not be opened right now. Try refreshing the VS menu and opening it again.',
        includeInternetHint: true,
      );
    } finally {
      if (mounted) {
        setState(() {
          _remoteFriendOperationInProgress = false;
        });
      }
    }
  }

  Future<void> _refreshRemoteFriendMatch({bool silent = false}) async {
    final matchId =
        _remoteFriendSnapshot?.matchId ?? _remoteFriendInvite?.matchId;
    if (matchId == null || matchId.isEmpty || _remoteFriendPollInFlight) {
      return;
    }

    _remoteFriendPollInFlight = true;
    try {
      final previousOutcome = _remoteFriendSnapshot?.outcome?.code;
      final fetchedSnapshot = await RemoteFriendService.instance.fetchMatch(
        matchId,
      );
      if (!mounted) {
        return;
      }
      var nextInvite = _remoteFriendInviteFromSnapshot(fetchedSnapshot);
      var nextSnapshot = fetchedSnapshot;
      if (_remoteFriendSnapshotNeedsAuthoritativeRefresh(fetchedSnapshot)) {
        final result = await RemoteFriendService.instance.refreshMatch(matchId);
        if (!mounted) {
          return;
        }
        nextInvite = result.invite;
        nextSnapshot = result.snapshot;
      }
      setState(() {
        _applyRemoteFriendSnapshot(invite: nextInvite, snapshot: nextSnapshot);
      });
      _startRemoteFriendSyncTimers();

      final nextOutcome = nextSnapshot.outcome?.code;
      if (previousOutcome == null && nextOutcome != null) {
        final gameOutcome = _remoteOutcomeToGameOutcome(nextOutcome);
        if (gameOutcome != null) {
          unawaited(_startGameResultReveal(gameOutcome));
        }
      }
    } catch (e) {
      _addLog('Remote friend sync failed: $e');
      if (!mounted) {
        return;
      }
      setState(() {
        _remoteFriendLastError = _cleanRemoteFriendErrorMessage(e);
      });
      if (!silent) {
        await _showThemedErrorDialog(
          title: 'Sync Failed',
          message:
              'Could not refresh this remote friend match. Check your connection and try again.',
          includeInternetHint: true,
        );
      }
    } finally {
      _remoteFriendPollInFlight = false;
    }
  }

  Future<void> _runRemoteFriendAction(RemoteFriendMatchAction action) async {
    final matchId = _remoteFriendSnapshot?.matchId;
    if (matchId == null ||
        matchId.isEmpty ||
        _remoteFriendOperationInProgress) {
      return;
    }

    setState(() {
      _remoteFriendOperationInProgress = true;
    });
    try {
      final previousOutcome = _remoteFriendSnapshot?.outcome?.code;
      final result = await RemoteFriendService.instance.actOnMatch(
        matchId: matchId,
        action: action,
      );
      if (!mounted) {
        return;
      }
      setState(() {
        _applyRemoteFriendSnapshot(
          invite: result.invite,
          snapshot: result.snapshot,
        );
      });
      _startRemoteFriendSyncTimers();
      unawaited(_loadRemoteFriendMemberships(silent: true));

      if (!result.success) {
        _addLog('Remote action rejected: ${result.reason ?? 'unknown'}');
        final failure = _remoteFriendActionFailurePresentation(
          action,
          result.reason,
        );
        await _showThemedErrorDialog(
          title: failure.title,
          message: failure.message,
          includeInternetHint: failure.includeInternetHint,
        );
        return;
      }

      final gameOutcome = _remoteOutcomeToGameOutcome(
        result.snapshot.outcome?.code,
      );
      if (previousOutcome == null && gameOutcome != null) {
        unawaited(_startGameResultReveal(gameOutcome));
      }
    } catch (e) {
      _addLog('Remote friend action failed: $e');
      if (!mounted) {
        return;
      }
      await _showThemedErrorDialog(
        title: 'Action Failed',
        message:
            'Could not update that remote friend match. Check your connection and try again.',
        includeInternetHint: true,
      );
    } finally {
      if (mounted) {
        setState(() {
          _remoteFriendOperationInProgress = false;
        });
      }
    }
  }

  Future<void> _submitRemoteFriendMove(
    String from,
    String to, {
    String? promotion,
  }) async {
    final snapshot = _remoteFriendSnapshot;
    if (snapshot == null ||
        snapshot.matchId.isEmpty ||
        !_isHumanTurnInRemoteFriendGame ||
        _remoteFriendOperationInProgress) {
      return;
    }

    final promotionCode = promotion == null
        ? ''
        : (promotion == 't' ? 'r' : promotion.toLowerCase());
    final moveUci = '$from$to$promotionCode';

    setState(() {
      _remoteFriendOperationInProgress = true;
    });

    try {
      final previousOutcome = _remoteFriendSnapshot?.outcome?.code;
      final result = await RemoteFriendService.instance.submitMove(
        matchId: snapshot.matchId,
        moveUci: moveUci,
        expectedPly: snapshot.nextPly,
      );
      if (!mounted) {
        return;
      }

      if (!result.acceptedMove) {
        _addLog('Remote move rejected: ${result.reason ?? 'unknown'}');
        await _refreshRemoteFriendMatch(silent: true);
        if (mounted) {
          _showRemoteFriendNotice(
            _remoteFriendMoveRejectionMessage(result.reason),
          );
        }
        return;
      }

      setState(() {
        _applyRemoteFriendSnapshot(
          invite: result.invite,
          snapshot: result.snapshot,
        );
      });
      _startRemoteFriendSyncTimers();

      final gameOutcome = _remoteOutcomeToGameOutcome(
        result.snapshot.outcome?.code,
      );
      if (previousOutcome == null && gameOutcome != null) {
        unawaited(_startGameResultReveal(gameOutcome));
      }
    } catch (e) {
      _addLog('Submit remote move failed: $e');
      if (mounted) {
        await _showThemedErrorDialog(
          title: 'Move Sync Failed',
          message:
              'That move could not be synchronized with the private match. The board will refresh to the latest server state.',
          includeInternetHint: true,
        );
        await _refreshRemoteFriendMatch(silent: true);
      }
    } finally {
      if (mounted) {
        setState(() {
          _remoteFriendOperationInProgress = false;
        });
      }
    }
  }

  Future<void> _lightHaptic() async {
    if (!_hapticsEnabled) return;
    await HapticFeedback.lightImpact();
  }

  Future<void> _checkHaptic() async {
    if (!_hapticsEnabled) return;
    await HapticFeedback.selectionClick();
  }

  int get _maxDepthAllowed {
    switch (_depthTier) {
      case 1:
        return 20;
      case 2:
        return 24;
      case 3:
        return 28;
      case 4:
        return _oracleInfiniteDepth;
      default:
        return 20;
    }
  }

  bool get _showsOracleDepthPlus =>
      _depthTier >= 4 && _engineDepth >= _oracleInfiniteDepth;

  bool get _usesInfiniteAnalysisDepth =>
      _isAnalysisMatchMode && _showsOracleDepthPlus;

  String _engineDepthSettingLabel(int depth) {
    if (_depthTier >= 4 && depth >= _oracleInfiniteDepth) {
      return '$_oracleInfiniteDepth+';
    }
    return '$depth';
  }

  String get _maxDepthAllowedLabel =>
      _depthTier >= 4 ? '$_oracleInfiniteDepth+' : '$_maxDepthAllowed';

  int get _maxSuggestionsAllowed =>
      (2 + _extraSuggestionPurchases).clamp(2, 10);

  int get _effectiveMultiPvCount => max(1, _multiPvCount);

  int get _visualSuggestionLineCount =>
      _isBotMatchMode ? max(1, _multiPvCount) : _effectiveMultiPvCount;

  bool get _isAnalysisMatchMode => _matchMode == MatchMode.analysis;

  bool get _isBotMatchMode => _matchMode == MatchMode.bot;

  bool get _isLocalFriendMatchMode => _matchMode == MatchMode.localFriend;

  bool get _isRemoteFriendMatchMode => _matchMode == MatchMode.remoteFriend;

  bool get _isMatchModeActive => !_isAnalysisMatchMode;

  bool get _isTimedLocalFriendFinish =>
      _isLocalFriendMatchMode && _localFriendEndedOnTime;

  bool get _isTimedRemoteFriendFinish =>
      _isRemoteFriendMatchMode && _remoteFriendOutcomeReason == 'timeout';

  RemoteFriendSeat? get _remoteFriendPlayerSeat {
    final snapshot = _remoteFriendSnapshot;
    if (snapshot == null) {
      return null;
    }
    return _remoteFriendPlayerSeatForSnapshot(snapshot);
  }

  bool get _isRemoteFriendPendingMatch =>
      _isRemoteFriendMatchMode &&
      _remoteFriendSnapshot?.status == RemoteFriendMatchStatus.pending;

  bool get _isRemoteFriendActiveMatch =>
      _isRemoteFriendMatchMode &&
      _remoteFriendSnapshot?.status == RemoteFriendMatchStatus.active;

  DateTime? get _remoteFriendPieceSelectionDeadline =>
      _remoteFriendSnapshot?.pieceSelectionDeadlineAt;

  bool get _isRemoteFriendPieceSelectionOpen {
    final snapshot = _remoteFriendSnapshot;
    if (snapshot == null) {
      return false;
    }
    return _remoteFriendPieceSelectionOpenForSnapshot(snapshot);
  }

  Duration get _remoteFriendPieceSelectionRemaining {
    final deadline = _remoteFriendPieceSelectionDeadline;
    if (deadline == null) {
      return Duration.zero;
    }
    final remaining = deadline.difference(DateTime.now());
    if (remaining.isNegative) {
      return Duration.zero;
    }
    return remaining;
  }

  int get _remoteFriendPieceSelectionRemainingSeconds {
    final remaining = _remoteFriendPieceSelectionRemaining;
    if (remaining <= Duration.zero) {
      return 0;
    }
    return ((remaining.inMilliseconds + 999) ~/ 1000).clamp(0, 10);
  }

  bool get _isRemoteFriendTimedMatch =>
      _isRemoteFriendMatchMode &&
      !(_remoteFriendSnapshot?.timeControl.isUntimed ?? true);

  bool get _hasIncomingRemoteDrawOffer {
    final offerByUid = _remoteFriendSnapshot?.drawOfferByUid;
    final localUid = _remoteFriendLocalUid;
    return offerByUid != null &&
        offerByUid.isNotEmpty &&
        offerByUid != localUid;
  }

  bool get _hasOutgoingRemoteDrawOffer {
    final offerByUid = _remoteFriendSnapshot?.drawOfferByUid;
    final localUid = _remoteFriendLocalUid;
    return offerByUid != null &&
        offerByUid.isNotEmpty &&
        offerByUid == localUid;
  }

  PieceThemeMode _pieceThemeModeFromIndex(int index) {
    if (index < 0 || index >= PieceThemeMode.values.length) {
      return PieceThemeMode.classic;
    }
    return PieceThemeMode.values[index];
  }

  PieceThemeMode _remoteFriendPieceThemeForSeat(RemoteFriendSeat seat) {
    final snapshot = _remoteFriendSnapshot;
    if (snapshot == null) {
      return _pieceThemeMode;
    }
    return _pieceThemeModeFromIndex(
      seat == RemoteFriendSeat.white
          ? snapshot.whitePieceThemeIndex
          : snapshot.blackPieceThemeIndex,
    );
  }

  PieceThemeMode _activePieceThemeForPiece(
    String piece, {
    PieceThemeMode? theme,
  }) {
    if (theme != null) {
      return theme;
    }
    if (_isRemoteFriendMatchMode) {
      return _remoteFriendPieceThemeForSeat(
        piece.endsWith('_w') ? RemoteFriendSeat.white : RemoteFriendSeat.black,
      );
    }
    return _pieceThemeMode;
  }

  String _remoteFriendSeatLabel(RemoteFriendSeat? seat) {
    switch (seat) {
      case RemoteFriendSeat.white:
        return 'White';
      case RemoteFriendSeat.black:
        return 'Black';
      case null:
        return 'Unknown';
    }
  }

  _RemoteFriendReactionOption? _remoteFriendReactionOptionForEmoji(
    String emoji,
  ) {
    final normalizedEmoji = emoji.trim();
    if (normalizedEmoji.isEmpty) {
      return null;
    }
    for (final option in <_RemoteFriendReactionOption>[
      ..._remoteFriendStandardReactionOptions,
      ..._remoteFriendStrangeReactionOptions,
    ]) {
      if (option.emoji == normalizedEmoji) {
        return option;
      }
    }
    return null;
  }

  RemoteFriendReaction? _remoteFriendVisibleReactionForSnapshot(
    RemoteFriendMatchSnapshot snapshot,
  ) {
    final reaction = snapshot.reaction;
    if (reaction == null ||
        reaction.emoji.trim().isEmpty ||
        reaction.sentByUid.trim().isEmpty) {
      return null;
    }
    final age = DateTime.now().difference(reaction.sentAt);
    if (age.isNegative || age <= _remoteFriendReactionDisplayDuration) {
      return reaction;
    }
    return null;
  }

  DateTime? _remoteFriendLastReactionAtForSnapshot(
    RemoteFriendMatchSnapshot snapshot,
    RemoteFriendSeat? seat,
  ) {
    switch (seat) {
      case RemoteFriendSeat.white:
        return snapshot.whiteLastReactionAt;
      case RemoteFriendSeat.black:
        return snapshot.blackLastReactionAt;
      case null:
        return null;
    }
  }

  Duration _remoteFriendReactionCooldownRemainingForSnapshot(
    RemoteFriendMatchSnapshot snapshot,
  ) {
    final playerSeat = _remoteFriendPlayerSeatForSnapshot(snapshot);
    final lastReactionAt = _remoteFriendLastReactionAtForSnapshot(
      snapshot,
      playerSeat,
    );
    if (lastReactionAt == null) {
      return Duration.zero;
    }
    final remaining =
        _remoteFriendReactionCooldown -
        DateTime.now().difference(lastReactionAt);
    if (remaining <= Duration.zero) {
      return Duration.zero;
    }
    return remaining;
  }

  bool _remoteFriendNeedsDisplayTickerForSnapshot(
    RemoteFriendMatchSnapshot snapshot,
  ) {
    if (snapshot.status != RemoteFriendMatchStatus.active ||
        snapshot.outcome != null) {
      return false;
    }
    if (_isRemoteFriendTimedMatch || _isRemoteFriendPieceSelectionOpen) {
      return true;
    }
    if (_remoteFriendReactionCooldownRemainingForSnapshot(snapshot) >
        Duration.zero) {
      return true;
    }
    return _remoteFriendVisibleReactionForSnapshot(snapshot) != null;
  }

  String _formatRemoteFriendReactionCooldown(Duration remaining) {
    final seconds = max(1, (remaining.inMilliseconds / 1000).ceil());
    return '${seconds}s';
  }

  String _remoteFriendReactionFailureMessage(String? reason) {
    switch ((reason ?? '').trim()) {
      case 'reaction-cooldown':
        final snapshot = _remoteFriendSnapshot;
        final remaining = snapshot == null
            ? _remoteFriendReactionCooldown
            : _remoteFriendReactionCooldownRemainingForSnapshot(snapshot);
        final retryIn = _formatRemoteFriendReactionCooldown(
          remaining > Duration.zero ? remaining : _remoteFriendReactionCooldown,
        );
        return 'Quick reacts recharge every 30 seconds. Try again in $retryIn.';
      case 'piece-selection-pending':
        return 'Quick reacts open after both players finish locking in their piece skins.';
      case 'expired':
      case 'cancelled':
      case 'completed':
      case 'match-unavailable':
        return 'This remote match is no longer active.';
      case 'not-participant':
        return 'This device is no longer recognized as a participant in that remote match.';
      default:
        return 'Could not send that quick reaction right now. ChessIQ refreshed the match state.';
    }
  }

  void _showLockedRemoteFriendReactionMessage() {
    _showRemoteFriendNotice(
      'The strange reacts unlock after your first random avatar roll.',
    );
  }

