  Widget _remoteFriendPieceThemeChoiceTile({
    required PieceThemeMode mode,
    required bool isWhitePiece,
    required bool selected,
    required VoidCallback? onTap,
  }) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final isLight = theme.brightness == Brightness.light;
    final enabled = onTap != null;
    return AnimatedOpacity(
      opacity: enabled ? 1.0 : 0.46,
      duration: const Duration(milliseconds: 150),
      child: GestureDetector(
        onTap: onTap,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 180),
          curve: Curves.easeOutCubic,
          width: 106,
          padding: const EdgeInsets.fromLTRB(10, 10, 10, 11),
          decoration: BoxDecoration(
            color: selected
                ? Color.alphaBlend(
                    scheme.primary.withValues(alpha: isLight ? 0.16 : 0.22),
                    scheme.surface,
                  )
                : Color.alphaBlend(
                    scheme.primary.withValues(alpha: isLight ? 0.04 : 0.08),
                    scheme.surface,
                  ),
            borderRadius: BorderRadius.circular(18),
            border: Border.all(
              color: selected
                  ? scheme.primary.withValues(alpha: 0.72)
                  : scheme.outline.withValues(alpha: 0.26),
            ),
            boxShadow: selected
                ? <BoxShadow>[
                    BoxShadow(
                      color: scheme.primary.withValues(alpha: 0.18),
                      blurRadius: 16,
                      offset: const Offset(0, 8),
                    ),
                  ]
                : null,
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Align(
                alignment: Alignment.topRight,
                child: AnimatedContainer(
                  duration: const Duration(milliseconds: 180),
                  width: 20,
                  height: 20,
                  decoration: BoxDecoration(
                    color: selected
                        ? scheme.primary
                        : scheme.outline.withValues(alpha: 0.18),
                    shape: BoxShape.circle,
                  ),
                  child: Icon(
                    selected ? Icons.check_rounded : Icons.circle_outlined,
                    size: selected ? 14 : 12,
                    color: selected
                        ? const Color(0xFF07131F)
                        : scheme.onSurface.withValues(alpha: 0.45),
                  ),
                ),
              ),
              const SizedBox(height: 4),
              Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  _pieceImage(
                    isWhitePiece ? 'k_w' : 'k_b',
                    width: 24,
                    height: 24,
                    theme: mode,
                    orientForHeadToHeadPerspective: false,
                  ),
                  const SizedBox(width: 4),
                  _pieceImage(
                    isWhitePiece ? 'q_w' : 'q_b',
                    width: 24,
                    height: 24,
                    theme: mode,
                    orientForHeadToHeadPerspective: false,
                  ),
                ],
              ),
              const SizedBox(height: 10),
              Text(
                _pieceThemeLabel(mode),
                textAlign: TextAlign.center,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: TextStyle(
                  fontSize: 11.5,
                  fontWeight: FontWeight.w800,
                  height: 1.12,
                  color: scheme.onSurface,
                ),
              ),
              const SizedBox(height: 4),
              Text(
                selected ? 'Selected' : 'Tap to use',
                textAlign: TextAlign.center,
                style: TextStyle(
                  fontSize: 10,
                  fontWeight: FontWeight.w700,
                  color: selected
                      ? scheme.primary
                      : scheme.onSurface.withValues(alpha: 0.56),
                ),
              ),
            ],
          ),
        ),
      ),
    );
