    _moveQualityOverlayTimer = null;
    _moveQualityOverlayQuality = null;
    _moveQualityOverlayTitle = null;
    _moveQualityOverlayMessage = null;
    _moveQualityOverlayChargeDelta = null;
    _moveQualityOverlayScoringSuppressedReason = null;
  }

  void _clearCheckAlertState() {
    _checkAlertTimer?.cancel();
    _checkAlertTimer = null;
    _checkAlert = null;
  }

  void _clearSquareToastState() {
    _squareToastTimer?.cancel();
    _squareToastTimer = null;
    _squareToast = null;
  }

  void _showSquareToast({
    required String square,
    required String label,
    required Color accent,
  }) {
    final toast = _SquareToast(
      square: square,
      label: label,
      accent: accent,
      startedAt: DateTime.now(),
      duration: _squareToastDuration,
    );
    _squareToastTimer?.cancel();
    if (!mounted) {
      return;
    }
    setState(() {
      _squareToast = toast;
    });
    _squareToastTimer = Timer(toast.duration, () {
      if (!mounted || _squareToast?.startedAt != toast.startedAt) {
        return;
      }
      setState(_clearSquareToastState);
    });
  }

  void _showCheckAlertForCurrentPosition({bool? moverIsWhite}) {
    final checkedKing = _currentCheckedKingState(moverIsWhite: moverIsWhite);
    if (checkedKing == null) {
      if (_checkAlert != null && mounted) {
        setState(_clearCheckAlertState);
      } else {
        _clearCheckAlertState();
      }
      return;
    }

    final againstViewer = checkedKing.againstViewer;
    final alert = _CheckAlert(
      square: checkedKing.square,
      againstViewer: againstViewer,
      title: againstViewer
          ? (_isBotMatchMode ? 'YOUR KING IN CHECK' : 'KING IN CHECK')
          : 'CHECK',
      subtitle: againstViewer
          ? (_isBotMatchMode
                ? 'Defend immediately before the bot converts.'
                : 'The side you are viewing is under direct attack.')
          : (_isBotMatchMode
                ? 'The enemy king is under pressure.'
                : 'Pressure lands on the opposing king.'),
      accent: againstViewer ? const Color(0xFFE45C5C) : const Color(0xFFFFB347),
      icon: againstViewer
          ? Icons.warning_amber_rounded
          : Icons.flash_on_rounded,
      startedAt: DateTime.now(),
    );

    _checkAlertTimer?.cancel();
    if (!mounted) {
      return;
    }
    setState(() {
      _checkAlert = alert;
    });
    _checkAlertTimer = Timer(_checkAlertDuration, () {
      if (!mounted || _checkAlert?.startedAt != alert.startedAt) {
        return;
      }
      setState(_clearCheckAlertState);
    });
  }

  void _cancelGameResultReveal() {
    _gameResultRevealSequence++;
    _gameResultReveal = null;
  }

  _GameResultReveal _createGameResultReveal(GameOutcome outcome) {
    final isDraw = outcome == GameOutcome.draw;
    final isWin = !isDraw && _isBotMatchMode && _isWinningOutcomeForPov;
    final isTimedLocalFriendFinish = _isTimedLocalFriendFinish && !isDraw;
    final isTimedRemoteFriendFinish = _isTimedRemoteFriendFinish && !isDraw;
    final isRemoteFriendWinForPlayer =
        _isRemoteFriendMatchMode &&
        ((_remoteFriendPlayerSeat == RemoteFriendSeat.white &&
                outcome == GameOutcome.whiteWin) ||
            (_remoteFriendPlayerSeat == RemoteFriendSeat.black &&
                outcome == GameOutcome.blackWin));
    final accent = isDraw
        ? const Color(0xFFD8B640)
        : (isWin || isRemoteFriendWinForPlayer)
        ? const Color(0xFF58E09A)
        : const Color(0xFFE45C5C);
    final title = isDraw
        ? (_isRemoteFriendMatchMode
              ? _remoteFriendOutcomeTitle(outcome)
              : 'DRAW')
        : _isBotMatchMode
        ? (isWin ? 'VICTORY' : 'DEFEAT')
        : _isRemoteFriendMatchMode
        ? _remoteFriendOutcomeTitle(outcome)
        : isTimedLocalFriendFinish
        ? _localFriendTimeoutTitle(outcome)
        : 'CHECKMATE';
    final subtitle = isDraw
        ? (_isRemoteFriendMatchMode
              ? _remoteFriendOutcomeSubtitle(outcome)
              : _drawOutcomeRevealSubtitle(_gameDrawReason))
        : _isBotMatchMode
        ? (isWin
              ? 'Checkmate lands. Take in the final position.'
              : 'Checkmate lands. Watch the last strike finish.')
        : _isRemoteFriendMatchMode
        ? _remoteFriendOutcomeSubtitle(outcome)
        : isTimedLocalFriendFinish
        ? _localFriendTimeoutSubtitle(outcome)
        : 'The final move is locked on the board.';
    final icon = isDraw
        ? Icons.balance_rounded
        : isTimedRemoteFriendFinish ||
              _remoteFriendOutcomeReason == 'resignation'
        ? Icons.flag_rounded
        : isTimedLocalFriendFinish
        ? Icons.flag_rounded
        : isWin
        ? Icons.emoji_events_rounded
        : Icons.crisis_alert_rounded;
    final latestUci = _moveHistory.isNotEmpty ? _moveHistory.last.uci : null;
    final toSquare = latestUci != null && latestUci.length >= 4
        ? latestUci.substring(2, 4)
        : null;

    return _GameResultReveal(
      outcome: outcome,
      title: title,
      subtitle: subtitle,
      accent: accent,
      icon: icon,
      startedAt: DateTime.now(),
      toSquare: toSquare,
    );
  }

  Future<void> _startGameResultReveal(GameOutcome outcome) async {
    final reveal = _createGameResultReveal(outcome);
    final sequence = ++_gameResultRevealSequence;
    if (!mounted) {
      return;
    }

    setState(() {
      _clearMoveQualityOverlay();
      _clearCheckAlertState();
      _gameResultReveal = reveal;
    });

    await Future<void>.delayed(_gameResultRevealDuration);
    if (!mounted ||
        _gameResultRevealSequence != sequence ||
        _gameResultReveal?.startedAt != reveal.startedAt) {
      return;
    }

    await _completeGameResultReveal(sequence: sequence);
  }

  Future<void> _completeGameResultReveal({int? sequence}) async {
    if (_gameResultReveal == null) {
      return;
    }
    if (sequence != null && sequence != _gameResultRevealSequence) {
      return;
    }

    _gameResultRevealSequence++;
    setState(() {
      _gameResultReveal = null;
    });
  }

  Future<void> _skipGameResultReveal() async {
    final reveal = _gameResultReveal;
    if (reveal == null) {
      return;
    }
    if (DateTime.now().difference(reveal.startedAt) <
        _gameResultRevealSkipDelay) {
      return;
    }
    await _completeGameResultReveal();
  }

  void _clearMoveQualityBadge() {
    _lastMoveQualityBadgeQuality = null;
    _lastMoveQualityBadgeSquare = null;
  }

  void _cancelBackgroundMoveQualityConfirmations({
    String reason = 'move-quality pipeline invalidated',
  }) {
    for (final handle
        in _backgroundMoveQualityConfirmationsByFen.values.toList()) {
      handle.cancel(reason: reason);
    }
    _backgroundMoveQualityConfirmationsByFen.clear();
  }

  void _invalidateMoveQualityGradingPipeline({
    bool clearPendingMove = false,
    bool cancelBackgroundConfirmations = true,
  }) {
    _moveQualityGradingGeneration++;
    if (cancelBackgroundConfirmations) {
      _cancelBackgroundMoveQualityConfirmations();
    }
    final active = _gradingSearchCompleter;
    if (active != null && !active.isCompleted) {
      active.complete(null);
    }
    _gradingSearchCompleter = null;
    _gradingSearchLines.clear();
    _analysisRefreshQueuedWhileGrading = false;
    _moveQualityGradingOperation = Future<void>.value();
    if (clearPendingMove) {
      _pendingMoveQualityGrading = null;
      _moveQualityPublishTimer?.cancel();
      _moveQualityPublishTimer = null;
      _deferredMoveQualityPublication = null;
    }
  }

  void _cancelPendingMoveQualityGrading() {
    _invalidateMoveQualityGradingPipeline(clearPendingMove: true);
  }

  // ignore: unused_element
  bool get _hasActiveGradingSearch {
    final active = _gradingSearchCompleter;
    return active != null && !active.isCompleted;
  }

  void _scheduleMoveQualityGrading(
    _PendingMoveQualityGrading pending, {
    EngineLine? livePostMoveLine,
    bool? livePostMoveWhiteToMove,
    EngineRequestRole? livePostMoveRole,
    bool cancelBackgroundConfirmations = false,
  }) {
    _invalidateMoveQualityGradingPipeline(
      cancelBackgroundConfirmations: cancelBackgroundConfirmations,
    );
    final generation = _moveQualityGradingGeneration;
    _moveQualityGradingOperation = Future<void>(() async {
      if (!mounted || generation != _moveQualityGradingGeneration) {
        return;
      }
      await _finalizePendingMoveQualityGrading(
        pending,
        livePostMoveLine: livePostMoveLine,
        livePostMoveWhiteToMove: livePostMoveWhiteToMove,
        livePostMoveRole: livePostMoveRole,
        gradingGeneration: generation,
      );
    });
    unawaited(_moveQualityGradingOperation.catchError((_) {}));
  }

  bool _restorePendingMoveQualityGrading(_PendingMoveQualityGrading pending) {
    final active = _pendingMoveQualityGrading;
    if (active != null &&
        (active.moveIndex != pending.moveIndex || active.uci != pending.uci)) {
      return false;
    }
    _pendingMoveQualityGrading = pending;
    return true;
  }

  void _deferPendingMoveQualityGrading(
    _PendingMoveQualityGrading pending, {
    required bool needsPreMoveConfirmation,
    required bool needsPostMoveConfirmation,
  }) {
    if (!_restorePendingMoveQualityGrading(pending)) {
      return;
    }
    if (needsPreMoveConfirmation) {
      _queueBackgroundMoveQualityConfirmation(
        pending,
        fen: pending.preMoveFen,
        whiteToMove: pending.moverIsWhite,
      );
    }
    if (needsPostMoveConfirmation) {
      _queueBackgroundMoveQualityConfirmation(pending);
    }
  }

  double _pieceMaterialValue(String piece) {
    switch (piece[0]) {
      case 'p':
        return 1.0;
      case 'n':
      case 'b':
        return 3.0;
      case 't':
        return 5.0;
      case 'q':
        return 9.0;
      default:
        return 0.0;
    }
  }

  double _materialCountForSide(Map<String, String> state, bool whiteSide) {
    var total = 0.0;
    for (final piece in state.values) {
      if (piece.endsWith('_w') != whiteSide) {
        continue;
      }
      total += _pieceMaterialValue(piece);
    }
    return total;
  }

  double _materialBalanceForSide(Map<String, String> state, bool whiteSide) {
    return _materialCountForSide(state, whiteSide) -
        _materialCountForSide(state, !whiteSide);
  }

  double _moverEvalPawnsFromWhiteEval(
    double whiteEvalPawns,
    bool moverIsWhite,
  ) {
    return moverIsWhite ? whiteEvalPawns : -whiteEvalPawns;
  }

  double _moverWinProbabilityFromWhiteEval(
    double whiteEvalPawns,
    bool moverIsWhite,
  ) {
    return centipawnsToWinProbability(
      _moverEvalPawnsFromWhiteEval(whiteEvalPawns, moverIsWhite) * 100,
    );
  }

  double _moverWinProbabilityFromEngineLine(
    EngineLine line, {
    required bool whiteToMove,
    required bool moverIsWhite,
  }) {
    final whiteCentipawns = whiteToMove ? line.eval : -line.eval;
    return whiteCentipawnsToMoverWinProbability(
      whiteCentipawns,
      moverIsWhite: moverIsWhite,
    );
  }

  int _preservingContinuationCount(
    List<EngineLine> lines,
    bool Function(double winProbability) predicate,
  ) {
    var count = 0;
    for (final line in lines) {
      if (predicate(centipawnsToWinProbability(line.eval))) {
        count += 1;
      }
    }
    return count;
  }

  int? _moveRankFromLines(List<EngineLine> lines, String uciMove) {
    for (final line in lines) {
      if (line.move == uciMove) {
        return line.multiPv;
      }
    }
    return null;
  }

  int? _cpGapFromBestFromLines(List<EngineLine> lines, String uciMove) {
    if (lines.isEmpty) {
      return null;
    }
    final bestEval = lines.first.eval;
    for (final line in lines) {
      if (line.move == uciMove) {
        return max(0, bestEval - line.eval);
      }
    }
    return null;
  }

  int? _cpGapFromNextBetterFromLines(List<EngineLine> lines, String uciMove) {
    if (lines.length < 2) {
      return null;
    }
    for (var index = 0; index < lines.length; index++) {
      if (lines[index].move != uciMove) {
        continue;
      }
      if (index == 0) {
        return 0;
      }
      return max(0, lines[index - 1].eval - lines[index].eval);
    }
    return null;
  }

  int _currentSideLegalMoveCount() {
    var count = 0;
    for (final entry in boardState.entries) {
      if (!_isCurrentTurnPiece(entry.value)) {
        continue;
      }
      count += _legalMovesFrom(entry.key).length;
    }
    return count;
  }

  List<String> _openingMoveTokensThrough(int moveIndex) {
    if (_moveHistory.isEmpty || moveIndex < 0) {
      return const <String>[];
    }

    final endExclusive = min(moveIndex + 1, _moveHistory.length);
    final sequence = _moveHistory
        .take(endExclusive)
        .map((move) => move.notation)
        .join(' ')
        .trim();
    if (sequence.isEmpty) {
      return const <String>[];
    }

    return _moveSequenceTokens(_normalizeSan(sequence));
  }

  bool _openingFeedbackOnlyApplies(int moveIndex) {
    if (moveIndex < 0) {
      return false;
    }

    return moveIndex < _bookOpeningPlyLimit &&
        matchesRegisteredOpeningPrefix(
          _ecoLines,
          _openingMoveTokensThrough(moveIndex),
        );
  }

  void _publishBookFastPath(_PendingMoveQualityGrading pending) {
    if (!_openingFeedbackOnlyApplies(pending.moveIndex) ||
        pending.moveIndex < 0 ||
        pending.moveIndex >= _moveHistory.length) {
      return;
    }

    final activePending = _pendingMoveQualityGrading;
    if (activePending?.moveIndex == pending.moveIndex &&
        activePending?.uci == pending.uci) {
      _pendingMoveQualityGrading = null;
    }
    final deferred = _deferredMoveQualityPublication;
    if (deferred?.pending.moveIndex == pending.moveIndex &&
        deferred?.pending.uci == pending.uci) {
      _clearDeferredMoveQualityPublication();
    }

    final currentMove = _moveHistory[pending.moveIndex];
    if (currentMove.uci != pending.uci) {
      return;
    }

    final isHumanVsBotMove =
        _isBotMatchMode && pending.moverIsWhite == _humanPlaysWhite;
    final badgeSquare = pending.uci.length >= 4
        ? pending.uci.substring(2, 4)
        : null;
    final opening = _currentOpening.trim();
    var overlayMove = currentMove.copyWith(
      quality: MoveQuality.book,
      qualityExplanation: opening.isEmpty
          ? 'Opening theory'
          : 'Opening: $opening',
      chargeBefore: pending.chargeBefore,
      chargeAfter: pending.chargeBefore,
      scoringSuppressedReason:
          MoveQualityScoringSuppressionReason.openingFeedbackOnly,
    );

    setState(() {
      if (isHumanVsBotMove) {
        final recalculatedHistory = _recalculateVsBotChargeHistory(
          startIndex: pending.moveIndex,
          firstUpdatedMove: overlayMove,
        );
        _moveHistory
          ..clear()
          ..addAll(recalculatedHistory);
        overlayMove = _moveHistory[pending.moveIndex];
        if (pending.chargeEpoch == _vsBotChargeEpoch) {
          _vsBotCharge = _visibleVsBotChargeForHistory(recalculatedHistory);
        }
      } else {
        _moveHistory[pending.moveIndex] = overlayMove;
      }

      if (!_isBotMatchMode || isHumanVsBotMove) {
        _lastMoveQualityBadgeQuality = MoveQuality.book;
        _lastMoveQualityBadgeSquare = badgeSquare;
        _showMoveQualityOverlay(overlayMove, 0);
      }
    });
  }

  MoveQualityConfidence _moveQualityConfidence({
    required List<EngineLine> preMoveLines,
    required int? playedMoveRank,
    required int? cpGapFromBest,
    required int? totalLegalMoveCount,
    required bool insideOpeningExemption,
    required bool usedPreMoveFallback,
  }) {
    final hasDirectComparison = playedMoveRank != null || cpGapFromBest != null;
    if (insideOpeningExemption && !hasDirectComparison) {
      return MoveQualityConfidence.low;
    }
    if (totalLegalMoveCount != null &&
        totalLegalMoveCount > 0 &&
        preMoveLines.length >= totalLegalMoveCount &&
        hasDirectComparison) {
      return MoveQualityConfidence.high;
    }
    if (preMoveLines.length >= _moveQualityGradingMultiPv &&
        hasDirectComparison) {
      return MoveQualityConfidence.high;
    }
    if (preMoveLines.length >= 2 && hasDirectComparison) {
      return MoveQualityConfidence.medium;
    }
    if (usedPreMoveFallback && preMoveLines.length >= 2) {
      return MoveQualityConfidence.medium;
    }
    return MoveQualityConfidence.low;
  }

  int _requiredPreMoveComparisonLineCount(int? totalLegalMoveCount) {
    final legalMoveCount = totalLegalMoveCount ?? _moveQualityGradingMultiPv;
    return max(1, min(legalMoveCount, _moveQualityGradingMultiPv));
  }

  bool _isBoardThemeUnlocked(BoardThemeMode mode) {
    return AppThemeProvider.isBoardThemeIndexUnlocked(
      mode.index,
      themePackOwned: _themePackOwned,
      sakuraBoardOwned: _sakuraBoardOwned,
      tropicalBoardOwned: _tropicalBoardOwned,
    );
  }

  bool _isPieceThemeUnlocked(PieceThemeMode mode) {
    return AppThemeProvider.isPieceThemeIndexUnlocked(
      mode.index,
      piecePackOwned: _piecePackOwned,
      tuttiFruttiOwned: _tuttiFruttiOwned,
      spectralOwned: _spectralOwned,
      monochromePiecesOwned: _monochromePiecesOwned,
    );
  }

  bool _isArrowThemeUnlocked(ArrowThemeMode mode) {
    return AppThemeProvider.isArrowThemeIndexUnlocked(
      mode.index,
      pixelArrowThemeOwned: _pixelArrowThemeOwned,
      heavyArrowThemeOwned: _heavyArrowThemeOwned,
    );
  }

  List<BoardThemeMode> get _availableBoardThemes => BoardThemeMode.values
      .where(_isBoardThemeUnlocked)
      .toList(growable: false);

  List<PieceThemeMode> get _availablePieceThemes => PieceThemeMode.values
      .where(_isPieceThemeUnlocked)
      .toList(growable: false);

  List<ArrowThemeMode> get _availableArrowThemes => ArrowThemeMode.values
      .where(_isArrowThemeUnlocked)
      .toList(growable: false);

  void _normalizeUnlockedThemes() {
    if (!_isBoardThemeUnlocked(_boardThemeMode)) {
      _boardThemeMode = _defaultBoardTheme;
    }
    if (!_isPieceThemeUnlocked(_pieceThemeMode)) {
      _pieceThemeMode = _defaultPieceTheme;
    }
    if (!_isArrowThemeUnlocked(_arrowThemeMode)) {
      _arrowThemeMode = ArrowThemeMode.classic;
    }
  }

  Future<void> _loadStoreState() async {
    try {
      await context.read<EconomyProvider>().refresh(notify: false);
      final prefs = await SharedPreferences.getInstance();
      final decoded = _readStorePayload(prefs);

      final tier = decoded['depthTier'];
      final extraSuggestions = decoded['extraSuggestions'];
      final themePack = decoded['themePackOwned'];
      final sakuraBoard = decoded['sakuraBoardOwned'];
      final tropicalBoard = decoded['tropicalBoardOwned'];
      final piecePack = decoded['piecePackOwned'];
      final pixelArrowTheme = decoded['pixelArrowThemeOwned'];
      final heavyArrowTheme = decoded['heavyArrowThemeOwned'];
      final sacrificeMode = decoded['sacrificeModeOwned'];
      final tuttiFrutti = decoded['tuttiFruttiOwned'];
      final spectral = decoded['spectralOwned'];
      final monochromePieces = decoded['monochromePiecesOwned'];
      final adFree = decoded['adFreeOwned'];
      final academyTuitionPass = decoded['academyTuitionPassOwned'];
      final vsBotMatchStartCount = decoded[_storeVsBotMatchStartCountKey];

      if (tier is int) _depthTier = max(1, tier.clamp(1, 4));
      if (extraSuggestions is int) {
        _extraSuggestionPurchases = extraSuggestions.clamp(0, 8);
      }
      if (themePack is bool) _themePackOwned = themePack;
      if (sakuraBoard is bool) _sakuraBoardOwned = sakuraBoard;
      if (tropicalBoard is bool) _tropicalBoardOwned = tropicalBoard;
      if (piecePack is bool) _piecePackOwned = piecePack;
      if (pixelArrowTheme is bool) _pixelArrowThemeOwned = pixelArrowTheme;
      if (heavyArrowTheme is bool) _heavyArrowThemeOwned = heavyArrowTheme;
      if (sacrificeMode is bool) _sacrificeModeOwned = sacrificeMode;
      if (tuttiFrutti is bool) _tuttiFruttiOwned = tuttiFrutti;
      if (spectral is bool) _spectralOwned = spectral;
      if (monochromePieces is bool) {
        _monochromePiecesOwned = monochromePieces;
      }
      if (adFree is bool) _adFreeOwned = adFree;
      if (academyTuitionPass is bool) {
        _academyTuitionPassOwned = academyTuitionPass;
      }
      if (vsBotMatchStartCount is int) {
        _vsBotMatchStartCount = max(0, vsBotMatchStartCount);
      }

      _engineDepth = _engineDepth.clamp(10, _maxDepthAllowed);
      _multiPvCount = _multiPvCount.clamp(0, _maxSuggestionsAllowed);
      _normalizeUnlockedThemes();

      if (mounted) {
        unawaited(
          context.read<AppThemeProvider>().syncLegacySettings(
            boardThemeIndex: _boardThemeMode.index,
            pieceThemeIndex: _pieceThemeMode.index,
            arrowThemeIndex: _arrowThemeMode.index,
            notify: false,
          ),
        );
      }

      // ── Restore IAP-delivered non-consumable flags ────────────────────────
      if (await PurchaseService.instance.isOwned(IapProducts.resetBoardPass)) {
        _adFreeOwned = true;
      }
      if (await PurchaseService.instance.isOwned(IapProducts.academyPass)) {
        _academyTuitionPassOwned = true;
      }
    } catch (e) {
      debugPrint('Failed to load store state: $e');
    }
  }

  Map<String, dynamic> _readStorePayload(SharedPreferences prefs) {
    final signed = LocalIntegrityService.decodeJson(
      prefs.getString(_storeStateKey),
      scope: _storeIntegrityScope,
    );
    if (signed.data == null || (signed.isSigned && !signed.isValid)) {
      return <String, dynamic>{};
    }
    return signed.data!;
  }

  Future<void> _saveStoreState() async {
    final economy = context.read<EconomyProvider>();
    final prefs = await SharedPreferences.getInstance();
    final payload = <String, dynamic>{
      ..._readStorePayload(prefs),
      'coins': economy.coins,
      'depthTier': _depthTier,
      'extraSuggestions': _extraSuggestionPurchases,
      'themePackOwned': _themePackOwned,
      'sakuraBoardOwned': _sakuraBoardOwned,
      'tropicalBoardOwned': _tropicalBoardOwned,
      'tuttiFruttiOwned': _tuttiFruttiOwned,
      'spectralOwned': _spectralOwned,
      'monochromePiecesOwned': _monochromePiecesOwned,
      'piecePackOwned': _piecePackOwned,
      'pixelArrowThemeOwned': _pixelArrowThemeOwned,
      'heavyArrowThemeOwned': _heavyArrowThemeOwned,
      'sacrificeModeOwned': _sacrificeModeOwned,
      'adFreeOwned': _adFreeOwned,
      'academyTuitionPassOwned': _academyTuitionPassOwned,
      _storeVsBotMatchStartCountKey: _vsBotMatchStartCount,
    };
    await prefs.setString(
      _storeStateKey,
      LocalIntegrityService.wrapJson(payload, scope: _storeIntegrityScope),
    );
  }

  String _storeRewardAdCountdownLabel(Duration remaining) {
    final economy = context.read<EconomyProvider>();
    if (economy.storeRewardLockedUntilTomorrow) {
      return 'tomorrow';
    }
    final totalMinutes = max(
      1,
      remaining.inMinutes + (remaining.inSeconds % 60 == 0 ? 0 : 1),
    );
    final hours = totalMinutes ~/ 60;
    final minutes = totalMinutes % 60;
    if (hours > 0) {
      return '${hours}h ${minutes}m';
    }
    return '${minutes}m';
  }

  Future<void> _loadSavedDefaultSnapshot() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_savedDefaultSnapshotKey);
      if (raw == null || raw.isEmpty) {
        return;
      }

      final decoded = jsonDecode(raw);
      if (decoded is! Map<String, dynamic>) {
        return;
      }

      final savedPerspective = decoded['perspective'];
      final savedDepth = decoded['engineDepth'];
      final savedMultiPv = decoded['multiPvCount'];
      final savedMoveAssessmentEnabled = decoded['moveAssessmentEnabled'];
      final savedLockedHeadToHeadPerspective =
          decoded['lockedHeadToHeadPerspective'];
      final savedHeadToHeadEvalBarEnabled = decoded['headToHeadEvalBarEnabled'];
      final savedOpeningButtonMode = decoded['openingButtonMode'];
      final savedWhiteTurn = decoded['isWhiteTurn'];
      final savedBoard = decoded['boardState'];
      final savedHistory = decoded['moveHistory'];
      final savedHistoryIndex = decoded['historyIndex'];
      final savedPositionHistoryKeys = decoded['positionHistoryKeys'];
      final savedHalfmoveClockHistory = decoded['halfmoveClockHistory'];
      final savedSuggestionsEnabled = decoded['suggestionsEnabled'];
      final savedTopLines = decoded['topLines'];
      final savedCurrentEval = decoded['currentEval'];
      final savedCurrentDepth = decoded['currentDepth'];
      final savedEvalWhiteTurn = decoded['evalWhiteTurn'];
      final savedWhiteKingMoved = decoded['whiteKingMoved'];
      final savedBlackKingMoved = decoded['blackKingMoved'];
      final savedWhiteKingsideRookMoved = decoded['whiteKingsideRookMoved'];
      final savedWhiteQueensideRookMoved = decoded['whiteQueensideRookMoved'];
      final savedBlackKingsideRookMoved = decoded['blackKingsideRookMoved'];
      final savedBlackQueensideRookMoved = decoded['blackQueensideRookMoved'];
      final savedEnPassantTarget = decoded['enPassantTarget'];

      if (!prefs.containsKey(_analysisPerspectiveKey) &&
          savedPerspective is int &&
          savedPerspective >= 0 &&
          savedPerspective < BoardPerspective.values.length) {
        _perspective = BoardPerspective.values[savedPerspective];
        if (_perspective != BoardPerspective.headToHead) {
          _analysisStandardPerspective = _perspective;
        }
      }
      if (!prefs.containsKey(_analysisEngineDepthKey) && savedDepth is int) {
        _engineDepth = savedDepth.clamp(10, _maxDepthAllowed);
      }
      if (!prefs.containsKey(_analysisMultiPvKey) && savedMultiPv is int) {
        _multiPvCount = savedMultiPv.clamp(0, _maxSuggestionsAllowed);
      }
      if (!prefs.containsKey(_analysisMoveAssessmentEnabledKey) &&
          savedMoveAssessmentEnabled is bool) {
        _moveAssessmentEnabled = savedMoveAssessmentEnabled;
      }
      if (!prefs.containsKey(_analysisLockedHeadToHeadPerspectiveKey) &&
          savedLockedHeadToHeadPerspective is bool) {
        _lockedHeadToHeadPerspective = savedLockedHeadToHeadPerspective;
      }
      if (!prefs.containsKey(_analysisHeadToHeadEvalBarEnabledKey) &&
          savedHeadToHeadEvalBarEnabled is bool) {
        _headToHeadEvalBarEnabled = savedHeadToHeadEvalBarEnabled;
      }
      if (!prefs.containsKey(_analysisOpeningButtonModeKey) &&
          savedOpeningButtonMode is int &&
          savedOpeningButtonMode >= 0 &&
          savedOpeningButtonMode < OpeningMode.values.length) {
        final savedMode = OpeningMode.values[savedOpeningButtonMode];
        if (savedMode != OpeningMode.off) {
          _analysisOpeningButtonMode = savedMode;
        }
      }
      if (savedWhiteTurn is bool) {
        _isWhiteTurn = savedWhiteTurn;
      }
      if (savedSuggestionsEnabled is bool) {
        _suggestionsEnabled = savedSuggestionsEnabled;
      }
      if (savedCurrentEval is num) {
        _currentEval = savedCurrentEval.toDouble();
      }
      if (savedCurrentDepth is int) {
        _currentDepth = max(0, savedCurrentDepth);
      }
      if (savedEvalWhiteTurn is bool) {
        _evalWhiteTurn = savedEvalWhiteTurn;
      }
      if (savedWhiteKingMoved is bool) _whiteKingMoved = savedWhiteKingMoved;
      if (savedBlackKingMoved is bool) _blackKingMoved = savedBlackKingMoved;
      if (savedWhiteKingsideRookMoved is bool) {
        _whiteKingsideRookMoved = savedWhiteKingsideRookMoved;
      }
      if (savedWhiteQueensideRookMoved is bool) {
        _whiteQueensideRookMoved = savedWhiteQueensideRookMoved;
      }
      if (savedBlackKingsideRookMoved is bool) {
        _blackKingsideRookMoved = savedBlackKingsideRookMoved;
      }
      if (savedBlackQueensideRookMoved is bool) {
        _blackQueensideRookMoved = savedBlackQueensideRookMoved;
      }
      if (savedEnPassantTarget is String && savedEnPassantTarget.isNotEmpty) {
        _enPassantTarget = savedEnPassantTarget;
      }

      if (savedBoard is Map) {
        boardState = savedBoard.map(
          (key, value) => MapEntry(key.toString(), value.toString()),
        );
      }

      _moveHistory.clear();
      if (savedHistory is List) {
        for (final item in savedHistory) {
          if (item is Map) {
            final restored = _moveRecordFromMap(item);
            if (restored != null) {
              _moveHistory.add(restored);
            }
          }
        }
      }

      if (savedHistoryIndex is int &&
          savedHistoryIndex >= -1 &&
          savedHistoryIndex < _moveHistory.length) {
        _historyIndex = savedHistoryIndex;
      } else {
        _historyIndex = _moveHistory.isEmpty ? -1 : _moveHistory.length - 1;
      }

      _restoreDerivedDrawState(
        savedPositionHistoryKeys: savedPositionHistoryKeys is List
            ? savedPositionHistoryKeys
            : null,
        savedHalfmoveClockHistory: savedHalfmoveClockHistory is List
            ? savedHalfmoveClockHistory
            : null,
      );

      _topLines = <EngineLine>[];
      if (savedTopLines is List) {
        for (final item in savedTopLines) {
          if (item is! Map) continue;
          final restored = EngineLine.fromMap(item);
          if (restored == null || restored.multiPv > _multiPvCount) continue;
          _topLines.add(restored);
        }
        _topLines.sort((a, b) => a.multiPv.compareTo(b.multiPv));
      }

      if (_isHeadToHeadPerspective) {
        _suggestionsEnabled = false;
        _topLines = <EngineLine>[];
        _analysisLines = <EngineLine>[];
        _analysisLinesFen = null;
        _currentDepth = 0;
      }

      // Opening preview arrows are transient UI state and should not survive
      // leaving and re-entering the analysis board.
      _gambitPreviewLines = <EngineLine>[];

      _currentOpening = _findOpeningFromHistory();
      _gambitSelectedFrom = null;
      _holdSelectedFrom = null;
      _legalTargets.clear();
      _gambitAvailableTargets.clear();
      _selectedGambit = null;
      _normalizeUnlockedThemes();
    } catch (e) {
      debugPrint('Failed to load saved default snapshot: $e');
    }
  }

  void _persistCurrentSettings() {
    unawaited(_persistAnalysisSettings());
  }

  Future<void> _persistAnalysisSettings() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setInt(_analysisPerspectiveKey, _perspective.index);
    await prefs.setInt(_analysisEngineDepthKey, _engineDepth);
    await prefs.setInt(_analysisMultiPvKey, _multiPvCount);
    await prefs.setBool(
      _analysisMoveAssessmentEnabledKey,
      _moveAssessmentEnabled,
    );
    await prefs.setBool(
      _analysisLockedHeadToHeadPerspectiveKey,
      _lockedHeadToHeadPerspective,
    );
    await prefs.setBool(
      _analysisHeadToHeadEvalBarEnabledKey,
      _headToHeadEvalBarEnabled,
    );
    await prefs.setInt(
      _analysisOpeningButtonModeKey,
      _analysisOpeningButtonMode.index,
    );
    await _saveCurrentAsDefaultSnapshot(logChange: false);
  }

  void _applySuggestionCount(int value, {bool persist = false}) {
    final clampedValue = value.clamp(0, _maxSuggestionsAllowed);
    setState(() {
      _multiPvCount = clampedValue;
    });
    _analyze();
    if (persist) {
      _persistCurrentSettings();
    }
  }

  void _persistAnalysisSnapshotIfNeeded() {
    if (_isMatchModeActive || _activeSection != AppSection.analysis) {
      return;
    }
    _persistCurrentSettings();
  }

  Future<void> _restoreAnalysisWorkspace() async {
    _resetBoard(withIntro: false);
    await _loadSavedDefaultSnapshot();
    if (!mounted) return;
    setState(() {});
  }

  Future<void> _releaseEngineSession() async {
    _engineStartFuture = null;
    final engine = _engine;
    final sacrificeEngine = _sacrificeScanEngine;
    engine?.cancelSearches(
      roles: <EngineRequestRole>{EngineRequestRole.sacrificeScan},
      reason: 'engine session released',
    );
    sacrificeEngine?.cancelSearches(
      roles: <EngineRequestRole>{EngineRequestRole.sacrificeScan},
      reason: 'engine session released',
    );
    _engine = null;
    _sacrificeScanEngine = null;
    _engineOwner = null;
    _botSearchHandle = null;
    _currentEvalSnapshot = null;
    _sacrificeScanEngineStartFuture = null;
    _cancelBackgroundMoveQualityConfirmations(
      reason: 'engine session released',
    );
    _clearPositionAnalysisCache();
    if (engine != null) {
      try {
        await engine.stop();
      } catch (e) {
        _addLog('Engine release failed: $e');
        debugPrint('Engine release failed: $e');
      }
    }
    if (sacrificeEngine != null) {
      try {
        await sacrificeEngine.stop();
      } catch (e) {
        _addLog('Sacrifice engine release failed: $e');
        debugPrint('Sacrifice engine release failed: $e');
      }
    }
  }

  Map<String, dynamic> _moveRecordToMap(MoveRecord move) {
    return {
      'notation': move.notation,
      'pieceMoved': move.pieceMoved,
      'pieceCaptured': move.pieceCaptured,
      'state': move.state,
      'isWhite': move.isWhite,
      'whiteKingMoved': move.whiteKingMoved,
      'blackKingMoved': move.blackKingMoved,
      'whiteKingsideRookMoved': move.whiteKingsideRookMoved,
      'whiteQueensideRookMoved': move.whiteQueensideRookMoved,
      'blackKingsideRookMoved': move.blackKingsideRookMoved,
      'blackQueensideRookMoved': move.blackQueensideRookMoved,
      'enPassantTarget': move.enPassantTarget,
    };
  }

  MoveRecord? _moveRecordFromMap(Map<dynamic, dynamic> data) {
    try {
      final stateRaw = data['state'];
      if (stateRaw is! Map) {
        return null;
      }
      final mappedState = stateRaw.map(
        (key, value) => MapEntry(key.toString(), value.toString()),
      );
      return MoveRecord(
        notation: (data['notation'] ?? '').toString(),
        pieceMoved: (data['pieceMoved'] ?? '').toString(),
        pieceCaptured: data['pieceCaptured']?.toString(),
        state: mappedState,
        isWhite: data['isWhite'] == true,
        whiteKingMoved: data['whiteKingMoved'] == true,
        blackKingMoved: data['blackKingMoved'] == true,
        whiteKingsideRookMoved: data['whiteKingsideRookMoved'] == true,
        whiteQueensideRookMoved: data['whiteQueensideRookMoved'] == true,
        blackKingsideRookMoved: data['blackKingsideRookMoved'] == true,
        blackQueensideRookMoved: data['blackQueensideRookMoved'] == true,
        enPassantTarget: data['enPassantTarget']?.toString(),
      );
    } catch (_) {
      return null;
    }
  }

  void _resetBoard({bool initialLaunch = false, bool withIntro = true}) {
    _send('stop');
    _send('ucinewgame');
    _stopLocalFriendClock(clearDisplay: true);
    _stopRemoteFriendSyncTimers();
    _clearBotGhostArrows();
    _clearVsBotOverlayState();
    _cancelGameResultReveal();
    _cancelPendingMoveQualityGrading();
    _clearPositionAnalysisCache();
    _clearMoveQualityOverlay();
    _clearMoveQualityBadge();
    boardState = _initialBoardState();
    _isWhiteTurn = true;
    _resetSpecialMoveState();
    _moveHistory.clear();
    _historyIndex = -1;
    _resetDerivedDrawState();
    _currentOpening = '';
    _openingMode = OpeningMode.off;
    _gambitSelectedFrom = null;
    _holdSelectedFrom = null;
    _legalTargets.clear();
    _gambitAvailableTargets.clear();
    _selectedGambit = null;
    _gambitPreviewLines = [];
    _suggestionsEnabled = false;
    _vsBotEvalEnabled = _isBotMatchMode;
    _vsBotOptimalLineRevealActive = false;
    _vsBotCharge = 0;
    _suggestionLaunchInProgress = false;
    _suggestionBurstActive = false;
    _botThinking = false;
    _clearGameOutcomeState();
    _gameResultDialogVisible = false;
    _launchStart = null;
    _launchTargets = <Offset>[];
    _extraLaunchStart = null;
    _extraLaunchTargets = <Offset>[];
    _secondExtraLaunchStart = null;
    _secondExtraLaunchTargets = <Offset>[];
    _launchTargetsEvalBar = false;
    _topLines = [];
    _analysisLines = [];
    _analysisLinesFen = null;
    _currentDepth = 0;
    _currentEval = 0.0;
    _evalWhiteTurn = true;
    if (withIntro) {
      _introCompleted = false;
      _buttonUnlocked = false;
      _introController.forward(from: 0);
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        final delay = initialLaunch
            ? const Duration(milliseconds: 800)
            : Duration.zero;
        Future.delayed(delay, () {
          if (!mounted) return;
          unawaited(_playIntroSound());
        });
        Future.delayed(const Duration(milliseconds: 3000), () {
          if (mounted) setState(() => _buttonUnlocked = true);
        });
      });
    } else {
      _introCompleted = true;
      _buttonUnlocked = true;
      _introController.value = 1.0;
    }
  }

  // --- Engine Logic ---
  Future<void> _startEngine() async {
    if (kIsWeb) {
      _addLog('Engine unavailable on web; running without Stockfish process.');
      return;
    }
    final desiredOwner = _activeEngineOwner;

    if (_engine != null && _engineOwner != desiredOwner) {
      await _releaseEngineSession();
    }

    final nextEngine = _engine != null && _engineOwner == desiredOwner
        ? _engine!
        : createEngineService(owner: desiredOwner);
    _engine = nextEngine;
    _engineOwner = desiredOwner;

    try {
      await nextEngine.startScheduler(
        onTimelineEvent: _handleEngineTimelineEvent,
      );
      if (_shouldRunLiveAnalysis) {
        _analyze();
      }
    } catch (e) {
      if (identical(_engine, nextEngine)) {
        _engine = null;
        _engineOwner = null;
      }
      _addLog('Engine start failed: $e');
      debugPrint('Engine start failed: $e');
    }
  }

  Future<void> _ensureEngineStarted() async {
    if (kIsWeb) return;
    _engineStartFuture ??= _startEngine();
    try {
      await _engineStartFuture;
    } finally {
      _engineStartFuture = null;
    }
  }

  bool get _canUseDedicatedSacrificeScanEngine =>
      !kIsWeb && (Platform.isWindows || Platform.isLinux || Platform.isMacOS);

  Future<CoordinatedEngineService?> _ensureSacrificeScanEngineStarted() async {
    if (!_canUseDedicatedSacrificeScanEngine) {
      return null;
    }

    final engine = _sacrificeScanEngine ??= createIndependentEngineService(
      owner: '$_analysisEngineOwner.sacrifice',
    );
    _sacrificeScanEngineStartFuture ??= engine.startScheduler();
    try {
      await _sacrificeScanEngineStartFuture;
      return engine;
    } catch (error) {
      if (identical(_sacrificeScanEngine, engine)) {
        try {
          await engine.stop();
        } catch (_) {}
        _sacrificeScanEngine = null;
      }
      _addLog('Sacrifice scan engine start failed: $error');
      debugPrint('Sacrifice scan engine start failed: $error');
      return null;
    } finally {
      _sacrificeScanEngineStartFuture = null;
    }
  }

  void _cancelSacrificeScanSearches({
    String reason = 'sacrifice scan refresh',
  }) {
    _engine?.cancelSearches(
      roles: <EngineRequestRole>{EngineRequestRole.sacrificeScan},
      reason: reason,
    );
    _sacrificeScanEngine?.cancelSearches(
      roles: <EngineRequestRole>{EngineRequestRole.sacrificeScan},
      reason: reason,
    );
  }

  void _send(String cmd) => _engine?.send(cmd);

  static const List<String> _analysisEngineRequestCommands = <String>[
    'setoption name UCI_LimitStrength value false',
    'setoption name Skill Level value 20',
    'setoption name Threads value 1',
    'setoption name Contempt value 0',
  ];

  Duration _analysisLiveCompletionTimeout({
    required int depth,
    required int multiPv,
  }) {
    final normalizedDepth = max(10, depth);
    final normalizedMultiPv = max(1, multiPv);
    final extraDepth = normalizedDepth - 10;
    final extraMultiPv = normalizedMultiPv - 1;
    // `go depth` still stops the engine at the requested depth; this timeout is
    // only a safety rail and needs to leave headroom for expensive MultiPV
    // searches instead of truncating them in the high 20s/low 30s.
    final totalMs =
        8000 +
        (extraDepth * 1400) +
        (extraDepth * extraDepth * 40) +
        (extraMultiPv * 4000) +
        (extraDepth * extraMultiPv * 600);
    return Duration(milliseconds: min(totalMs, 120000));
  }

  Duration _moveQualitySearchTimeout({
    required int multiPv,
    required bool backgroundConfirmation,
  }) {
    final normalizedMultiPv = max(1, multiPv);
    final liveBudgetMs = _analysisLiveCompletionTimeout(
      depth: _moveQualityGradingDepth,
      multiPv: normalizedMultiPv,
    ).inMilliseconds;
    final scaledBudgetMs = (liveBudgetMs * 0.45).round();
    final minimumBudgetMs = backgroundConfirmation
        ? (_isBotMatchMode ? 3200 : 5000)
        : (_isBotMatchMode ? 2800 : 4200);
    final maximumBudgetMs = _isBotMatchMode ? 12000 : 18000;
    return Duration(
      milliseconds: min(maximumBudgetMs, max(minimumBudgetMs, scaledBudgetMs)),
    );
  }

  Duration? _moveQualityFirstInfoTimeout({
    required bool backgroundConfirmation,
  }) {
    if (_isBotMatchMode) {
      return backgroundConfirmation
          ? const Duration(milliseconds: 1800)
          : const Duration(milliseconds: 1600);
    }
    return backgroundConfirmation
        ? const Duration(milliseconds: 2600)
        : const Duration(milliseconds: 2200);
  }

  String _nextEngineRequestId(EngineRequestRole role) {
    _engineRequestSequence++;
    return '${role.name}-$_engineRequestSequence';
  }

  void _handleEngineTimelineEvent(EngineTimelineEvent event) {
    final request = event.request;
    final detail = event.detail == null ? '' : ' detail=${event.detail}';
    if (request == null) {
      _addLog('[engine] ${event.type.name}$detail');
      return;
    }
    final budget = request.moveTime != null
        ? '${request.moveTime!.inMilliseconds}ms'
        : request.infinite
        ? 'depth${request.depth ?? _oracleInfiniteDepth}+'
        : 'depth${request.depth ?? 0}';
    _addLog(
      '[engine] ${event.type.name} id=${request.requestId} role=${request.role.name} fen=${request.fenHash} mpv=${request.multiPv} budget=$budget$detail',
    );
  }

  void _rememberPositionAnalysis(String fen, PositionAnalysisCacheEntry entry) {
    _positionAnalysisCacheByFen.remove(fen);
    _positionAnalysisCacheByFen[fen] = entry;
    while (_positionAnalysisCacheByFen.length > _positionAnalysisCacheLimit) {
      _positionAnalysisCacheByFen.remove(
        _positionAnalysisCacheByFen.keys.first,
      );
    }
  }

  PositionAnalysisCacheEntry? _cachedPositionAnalysisForFen(String fen) {
    final cached = _positionAnalysisCacheByFen[fen];
    if (cached == null) {
      return null;
    }
    _positionAnalysisCacheByFen.remove(fen);
    _positionAnalysisCacheByFen[fen] = cached;
    return cached;
  }

  void _recordPositionAnalysisLines(String fen, List<EngineLine> lines) {
    if (lines.isEmpty) {
      return;
    }
    final cached =
        _positionAnalysisCacheByFen[fen] ??
        PositionAnalysisCacheEntry(fen: fen);
    _rememberPositionAnalysis(fen, cached.mergedWithAnalysisLines(lines));
  }

  List<EngineLine> _currentPositionAnalysisLines(String fen) {
    final liveLines = _analysisLinesFen == fen
        ? _analysisLines
        : const <EngineLine>[];
    final cachedLines =
        _cachedPositionAnalysisForFen(fen)?.analysisLines ??
        const <EngineLine>[];
    return preferDeeperAnalysisLines(liveLines, cachedLines);
  }

  String? _confirmedSacrificeAnalysisSignature(String fen) {
    final lines = _currentPositionAnalysisLines(fen).toList(growable: false)
      ..sort((a, b) => a.multiPv.compareTo(b.multiPv));
    if (lines.length < _sacrificeEligibleRootMoveLimit) {
      return null;
    }
    final confirmedLines = lines
        .take(_sacrificeEligibleRootMoveLimit)
        .toList(growable: false);
    if (confirmedLines.any(
      (line) => line.depth < _sacrificeFastConfirmationDepth,
    )) {
      return null;
    }
    return '$fen|${confirmedLines.map((line) => '${line.multiPv}:${line.move}').join(',')}';
  }

  void _maybeRescheduleSacrificePreviewFromAnalysis(String fen) {
    if (!_shouldRunSacrificeScan) {
      return;
    }
    final signature = _confirmedSacrificeAnalysisSignature(fen);
    if (signature == null || signature == _lastSacrificeAnalysisSignature) {
      return;
    }
    _lastSacrificeAnalysisSignature = signature;
    _scheduleSacrificePreviewScan();
  }

  Map<String, int> _moveEvalCpByUci(Iterable<EngineLine> lines) {
    final evalsByUci = <String, int>{};
    for (final line in lines) {
      evalsByUci.putIfAbsent(line.move, () => line.eval);
    }
    return evalsByUci;
  }

  void _clearPositionAnalysisCache() {
    _positionAnalysisCacheByFen.clear();
    _primaryEngineUpdateByFen.clear();
  }

  void _restoreCachedEvalForFen(String fen) {
    final cached = _cachedPositionAnalysisForFen(fen);
    final snapshot = cached?.evalSnapshot;
    if (snapshot == null) {
      _currentEvalSnapshot = null;
      _currentDepth = 0;
      _currentEval = 0.0;
      _evalWhiteTurn = _isWhiteTurn;
      return;
    }
    _applyCanonicalEvalSnapshot(snapshot);
  }

  void _recordPrimaryEngineUpdate(EngineSearchUpdate update) {
    if (!update.isPrimaryVariation) {
      return;
    }
    final fen = update.request.fen;
    final cached =
        _positionAnalysisCacheByFen[fen] ??
        PositionAnalysisCacheEntry(fen: fen);
    _rememberPositionAnalysis(fen, cached.mergedWithPrimaryUpdate(update));
    _primaryEngineUpdateByFen[fen] = update;
    while (_primaryEngineUpdateByFen.length > _positionAnalysisCacheLimit) {
      _primaryEngineUpdateByFen.remove(_primaryEngineUpdateByFen.keys.first);
    }
  }

  bool _shouldPublishEvalSnapshot(EvalSnapshot snapshot) {
    if (!_shouldKeepEvalActive || !snapshot.matchesFen(_genFen())) {
      return false;
    }
    switch (snapshot.role) {
      case EngineRequestRole.liveAnalysis:
        return true;
      case EngineRequestRole.botSearch:
        return _isBotMatchMode && !_isHumanTurnInBotGame;
      case EngineRequestRole.moveGrading:
      case EngineRequestRole.backgroundConfirmation:
      case EngineRequestRole.sacrificeScan:
        return false;
    }
  }

  void _applyCanonicalEvalSnapshot(EvalSnapshot snapshot) {
    _currentEvalSnapshot = snapshot;
    _currentEval = snapshot.pawnsForPov(snapshot.whiteToMove);
    _evalWhiteTurn = snapshot.whiteToMove;
    _currentDepth = snapshot.depth;
  }

  void _maybeResolvePendingMoveQualityFromUpdate(EngineSearchUpdate update) {
    if (!update.isPrimaryVariation) {
      return;
    }
    final pending = _pendingMoveQualityGrading;
    final matchesPostMoveFen = pending?.postMoveFen == update.request.fen;
    final matchesPreMoveFen = pending?.preMoveFen == update.request.fen;
    if (pending == null || (!matchesPostMoveFen && !matchesPreMoveFen)) {
      return;
    }
    _scheduleMoveQualityGrading(
      pending,
      livePostMoveLine: matchesPostMoveFen ? update.line : null,
      livePostMoveWhiteToMove: matchesPostMoveFen
          ? update.request.whiteToMove
          : null,
      livePostMoveRole: matchesPostMoveFen ? update.request.role : null,
    );
  }

  void _handleLiveAnalysisUpdate(EngineSearchUpdate update) {
    _recordPrimaryEngineUpdate(update);
    _maybeResolvePendingMoveQualityFromUpdate(update);
    if (!mounted || !update.request.matchesFen(_genFen())) {
      return;
    }
    if (!_isLegalUciMove(update.line.move)) {
      return;
    }

    final shouldShowVisualSuggestions =
        _shouldShowVisualSuggestions &&
        (!_isBotMatchMode || _isHumanTurnInBotGame);
    final analysisMultiPvCount = _analysisMultiPvCount;
    setState(() {
      _currentDepth = max(_currentDepth, update.line.depth);
      _analysisLinesFen = update.request.fen;
      if (update.isPrimaryVariation &&
          _shouldPublishEvalSnapshot(update.snapshot)) {
        _applyCanonicalEvalSnapshot(update.snapshot);
      }
      _analysisLines.removeWhere(
        (line) =>
            line.multiPv == update.line.multiPv ||
            line.multiPv > analysisMultiPvCount,
      );
      _analysisLines.add(update.line);
      _analysisLines.sort((a, b) => a.multiPv.compareTo(b.multiPv));
      if (shouldShowVisualSuggestions) {
        _topLines.removeWhere(
          (line) =>
              line.multiPv == update.line.multiPv ||
              line.multiPv > _visualSuggestionLineCount,
        );
        if (update.line.multiPv <= _visualSuggestionLineCount) {
          _topLines.add(update.line);
          _topLines.sort((a, b) => a.multiPv.compareTo(b.multiPv));
        }
      } else if (_topLines.isNotEmpty && update.isPrimaryVariation) {
        _topLines = [];
      }
    });
    _recordPositionAnalysisLines(
      update.request.fen,
      _analysisLinesFen == update.request.fen
          ? _analysisLines
          : const <EngineLine>[],
    );
    _maybeRescheduleSacrificePreviewFromAnalysis(update.request.fen);
  }

  void _handleBotSearchUpdate(EngineSearchUpdate update) {
    _recordPrimaryEngineUpdate(update);
    _maybeResolvePendingMoveQualityFromUpdate(update);
    if (!mounted || !_isBotMatchMode || !update.request.matchesFen(_genFen())) {
      return;
    }
    if (!_isLegalUciMove(update.line.move)) {
      return;
    }

    _botSearchLines[update.line.multiPv] = update.line;
    if (update.isPrimaryVariation &&
        _shouldPublishEvalSnapshot(update.snapshot)) {
      setState(() {
        _applyCanonicalEvalSnapshot(update.snapshot);
      });
    }
  }

  bool _shouldQueueBackgroundConfirmation(MoveQualityAssessment assessment) {
    return true;
  }

  void _queueBackgroundMoveQualityConfirmation(
    _PendingMoveQualityGrading pending, {
    String? fen,
    bool? whiteToMove,
  }) {
    final engine = _engine;
    final targetFen = fen ?? pending.postMoveFen;
    if (engine == null || targetFen == null) {
      return;
    }
    if (_backgroundMoveQualityConfirmationsByFen.containsKey(targetFen)) {
      return;
    }

    final targetWhiteToMove =
        whiteToMove ?? pending.postMoveWhiteToMove ?? !pending.moverIsWhite;
    final isPreMoveConfirmation = targetFen == pending.preMoveFen;
    final confirmationMultiPv = isPreMoveConfirmation
        ? _requiredPreMoveComparisonLineCount(pending.totalLegalMoveCount)
        : 1;
    final confirmationMinimumDepth = _moveQualityGradingDepth;
    final confirmationTimeout = _moveQualitySearchTimeout(
      multiPv: confirmationMultiPv,
      backgroundConfirmation: true,
    );
    late final EngineSearchHandle confirmationHandle;
    final confirmationLines = <int, EngineLine>{};
    var consumedPrimaryLine = false;
    confirmationHandle = engine.scheduleSearch(
      EngineRequestSpec(
        requestId: _nextEngineRequestId(
          EngineRequestRole.backgroundConfirmation,
        ),
        role: EngineRequestRole.backgroundConfirmation,
        fen: targetFen,
        whiteToMove: targetWhiteToMove,
        multiPv: confirmationMultiPv,
        depth: _moveQualityGradingDepth,
        timeout: confirmationTimeout,
        firstInfoTimeout: _moveQualityFirstInfoTimeout(
          backgroundConfirmation: true,
        ),
        preCommands: _analysisEngineRequestCommands,
      ),
      onUpdate: (update) {
        _recordPrimaryEngineUpdate(update);
        confirmationLines[update.line.multiPv] = update.line;
        final orderedConfirmationLines = confirmationLines.values.toList()
          ..sort((a, b) => a.multiPv.compareTo(b.multiPv));
        _recordPositionAnalysisLines(
          update.request.fen,
          orderedConfirmationLines,
        );
        if (isPreMoveConfirmation) {
          return;
        }
        if (!update.isPrimaryVariation ||
            consumedPrimaryLine ||
            update.line.depth < confirmationMinimumDepth) {
          return;
        }
        if (!_moveQualityPendingStillMatchesHistory(pending)) {
          if (identical(
            _backgroundMoveQualityConfirmationsByFen[targetFen],
            confirmationHandle,
          )) {
            _backgroundMoveQualityConfirmationsByFen.remove(targetFen);
          }
          confirmationHandle.cancel(reason: 'move no longer matches history');
          return;
        }
        consumedPrimaryLine = true;
        if (identical(
          _backgroundMoveQualityConfirmationsByFen[targetFen],
          confirmationHandle,
        )) {
          _backgroundMoveQualityConfirmationsByFen.remove(targetFen);
        }
        _scheduleMoveQualityGrading(
          pending,
          livePostMoveLine: update.request.fen == pending.postMoveFen
              ? update.line
              : null,
          livePostMoveWhiteToMove: update.request.fen == pending.postMoveFen
              ? update.request.whiteToMove
              : null,
          livePostMoveRole: update.request.fen == pending.postMoveFen
              ? update.request.role
              : null,
        );
        confirmationHandle.cancel(reason: 'background confirmation satisfied');
      },
    );
    _backgroundMoveQualityConfirmationsByFen[targetFen] = confirmationHandle;
    unawaited(
      confirmationHandle.result
          .then((result) {
            if (result.lines.isNotEmpty) {
              _recordPositionAnalysisLines(targetFen, result.lines);
            }
            if (identical(
              _backgroundMoveQualityConfirmationsByFen[targetFen],
              confirmationHandle,
            )) {
              _backgroundMoveQualityConfirmationsByFen.remove(targetFen);
            }
            if (!_moveQualityPendingStillMatchesHistory(pending)) {
              return;
            }
            if (!isPreMoveConfirmation) {
              final resultPrimaryLine = result.lines
                  .where((line) => line.multiPv == 1)
                  .cast<EngineLine?>()
                  .firstWhere((line) => line != null, orElse: () => null);
              _scheduleMoveQualityGrading(
                pending,
                livePostMoveLine: targetFen == pending.postMoveFen
                    ? resultPrimaryLine
                    : null,
                livePostMoveWhiteToMove: targetFen == pending.postMoveFen
                    ? targetWhiteToMove
                    : null,
                livePostMoveRole: targetFen == pending.postMoveFen
                    ? EngineRequestRole.backgroundConfirmation
                    : null,
              );
              return;
            }
            _scheduleMoveQualityGrading(
              pending,
              livePostMoveRole: EngineRequestRole.backgroundConfirmation,
            );
          })
          .whenComplete(() {
            if (identical(
              _backgroundMoveQualityConfirmationsByFen[targetFen],
              confirmationHandle,
            )) {
              _backgroundMoveQualityConfirmationsByFen.remove(targetFen);
            }
          }),
    );
  }

  void _stageMoveQualityPublication(
    _DeferredMoveQualityPublication publication,
  ) {
    _deferredMoveQualityPublication = publication;
    _moveQualityPublishTimer?.cancel();
    final remainingDelay = publication.pending.earliestPublishAt.difference(
      DateTime.now(),
    );
    if (remainingDelay <= Duration.zero) {
      _publishDeferredMoveQualityPublication();
      return;
    }
    _moveQualityPublishTimer = Timer(remainingDelay, () {
      if (!mounted) {
        return;
      }
      _publishDeferredMoveQualityPublication();
    });
  }

  void _clearDeferredMoveQualityPublication() {
    _moveQualityPublishTimer?.cancel();
    _moveQualityPublishTimer = null;
    _deferredMoveQualityPublication = null;
  }

  void _publishDeferredMoveQualityPublication() {
    final publication = _deferredMoveQualityPublication;
    if (publication == null) {
      _moveQualityPublishTimer?.cancel();
      _moveQualityPublishTimer = null;
      return;
    }
    if (publication.pending.earliestPublishAt.isAfter(DateTime.now())) {
      _stageMoveQualityPublication(publication);
      return;
    }
    _clearDeferredMoveQualityPublication();
    _applyMoveQualityPublication(publication);
  }

  void _applyMoveQualityPublication(
    _DeferredMoveQualityPublication publication,
  ) {
    final pending = publication.pending;
    if (!mounted || !_moveQualityPendingStillMatchesHistory(pending)) {
      return;
    }
    final currentMove = _moveHistory[pending.moveIndex];
    final previousPublishedQuality = currentMove.quality;
    final previousPublishedChargeAfter =
        currentMove.chargeAfter ?? pending.chargeBefore;
    if (currentMove.uci != pending.uci) {
      return;
    }

    final isHumanVsBotMove =
        _isBotMatchMode && pending.moverIsWhite == _humanPlaysWhite;
    final assessment = publication.assessment;
    final quality = assessment.quality;
    final badgeSquare = pending.uci.length >= 4
        ? pending.uci.substring(2, 4)
        : null;
    final chargeAfter = isHumanVsBotMove
        ? updatedMoveQualityCharge(
            current: pending.chargeBefore,
            assessment: assessment,
          )
        : pending.chargeBefore;
    final updatedMove = currentMove.copyWith(
      quality: quality,
      preMoveWinProbability: publication.preMoveMoverWinProbability,
      postMoveWinProbability: publication.postMoveMoverWinProbability,
      deltaWinProbabilityLoss: publication.deltaWpLoss,
      qualityExplanation: assessment.explanation,
      moveRank: assessment.moveRank,
      cpGapFromBest: assessment.cpGapFromBest,
      qualityConfidence: assessment.confidence,
      isSacrifice: pending.isSacrifice,
      chargeBefore: pending.chargeBefore,
      chargeAfter: chargeAfter,
      scoringSuppressedReason: assessment.scoringSuppressedReason,
    );
    final shouldShowAssessment =
        publication.sourceRole != EngineRequestRole.backgroundConfirmation ||
        previousPublishedQuality != quality ||
        previousPublishedChargeAfter != chargeAfter;
    final canShowBackgroundCorrection =
        publication.sourceRole != EngineRequestRole.backgroundConfirmation ||
        _moveQualityPendingStillMatchesHistory(pending);
    var overlayMove = updatedMove;
    var overlayChargeDelta = chargeAfter - pending.chargeBefore;

    setState(() {
      if (_pendingMoveQualityGrading?.moveIndex == pending.moveIndex &&
          _pendingMoveQualityGrading?.uci == pending.uci) {
        _pendingMoveQualityGrading = null;
      }
      if (pending.moveIndex < _moveHistory.length &&
          _moveHistory[pending.moveIndex].uci == pending.uci) {
        if (isHumanVsBotMove) {
          final recalculatedHistory = _recalculateVsBotChargeHistory(
            startIndex: pending.moveIndex,
            firstUpdatedMove: updatedMove,
          );
          _moveHistory
            ..clear()
            ..addAll(recalculatedHistory);
          overlayMove = _moveHistory[pending.moveIndex];
          overlayChargeDelta =
              (overlayMove.chargeAfter ?? pending.chargeBefore) -
              previousPublishedChargeAfter;
          if (pending.chargeEpoch == _vsBotChargeEpoch) {
            _vsBotCharge = _visibleVsBotChargeForHistory(recalculatedHistory);
          }
        } else {
          _moveHistory[pending.moveIndex] = updatedMove;
          overlayMove = updatedMove;
        }
      }
      if ((!_isBotMatchMode || isHumanVsBotMove) &&
          shouldShowAssessment &&
          canShowBackgroundCorrection) {
        _lastMoveQualityBadgeQuality = quality;
        _lastMoveQualityBadgeSquare = badgeSquare;
        _showMoveQualityOverlay(overlayMove, overlayChargeDelta);
      }
    });

    final shouldQueueConfirmation =
        _isBotMatchMode && isHumanVsBotMove ||
        _shouldQueueBackgroundConfirmation(assessment);
    if (publication.sourceRole != EngineRequestRole.backgroundConfirmation &&
        !_openingFeedbackOnlyApplies(pending.moveIndex) &&
        shouldQueueConfirmation) {
      if (_isBotMatchMode && isHumanVsBotMove) {
        _queueBackgroundMoveQualityConfirmation(
          pending,
          fen: pending.preMoveFen,
          whiteToMove: pending.moverIsWhite,
        );
      }
      _queueBackgroundMoveQualityConfirmation(pending);
    }

    if (_isBotMatchMode &&
        !_isHumanTurnInBotGame &&
        !_botThinking &&
        _gameOutcome == null) {
      unawaited(_maybeTriggerBotMove());
    }
  }

  bool _moveQualityPendingStillMatchesHistory(
    _PendingMoveQualityGrading pending,
  ) {
    if (pending.moveIndex < 0 || pending.moveIndex >= _moveHistory.length) {
      return false;
    }
    final record = _moveHistory[pending.moveIndex];
    if (record.uci != pending.uci || record.isWhite != pending.moverIsWhite) {
      return false;
    }
    if (!_isBotMatchMode || pending.moverIsWhite != _humanPlaysWhite) {
      return true;
    }
    return pending.moveIndex == _latestHumanVsBotMoveIndex();
  }

  int _latestHumanVsBotMoveIndex() {
    if (!_isBotMatchMode || _moveHistory.isEmpty) {
      return -1;
    }
    final maxIndex = min(_historyIndex, _moveHistory.length - 1);
    for (var index = maxIndex; index >= 0; index--) {
      if (_moveHistory[index].isWhite == _humanPlaysWhite) {
        return index;
      }
    }
    return -1;
  }

  List<MoveRecord> _recalculateVsBotChargeHistory({
    required int startIndex,
    required MoveRecord firstUpdatedMove,
  }) {
    final updatedHistory = List<MoveRecord>.from(_moveHistory);
    if (startIndex < 0 || startIndex >= updatedHistory.length) {
      return updatedHistory;
    }

    var runningCharge =
        firstUpdatedMove.chargeBefore ??
        (startIndex > 0
            ? (updatedHistory[startIndex - 1].chargeAfter ?? 0)
            : 0);

    for (var index = startIndex; index < updatedHistory.length; index++) {
      var move = index == startIndex ? firstUpdatedMove : updatedHistory[index];
      final isHumanVsBotRecordedMove = move.isWhite == _humanPlaysWhite;
      final chargeBefore = runningCharge;
      final chargeAfter =
          !isHumanVsBotRecordedMove ||
              move.scoringSuppressedReason != null ||
              move.quality == null
          ? chargeBefore
          : updatedMoveQualityCharge(
              current: chargeBefore,
              quality: move.quality,
            );
      move = move.copyWith(
        chargeBefore: chargeBefore,
        chargeAfter: chargeAfter,
      );
      updatedHistory[index] = move;
      runningCharge = chargeAfter;
    }

    return updatedHistory;
  }

  int _visibleVsBotChargeForHistory(List<MoveRecord> history) {
    if (history.isEmpty) {
      return 0;
    }
    if (_historyIndex >= 0 && _historyIndex < history.length) {
      return history[_historyIndex].chargeAfter ?? 0;
    }
    return history.last.chargeAfter ?? 0;
  }

  bool get _isHumanTurnInBotGame {
    if (!_isBotMatchMode || _selectedBot == null) return true;
    return _isWhiteTurn == _humanPlaysWhite;
  }

  void _refreshAnalysisForCurrentPosition() {
    if (_engine != null || kIsWeb) {
      _analyze();
      _scheduleSacrificePreviewScan();
      return;
    }

    unawaited(() async {
      await _ensureEngineStarted();
      if (!mounted) {
        return;
      }
      _analyze();
      _scheduleSacrificePreviewScan();
    }());
  }

  void _analyze() {
    final engine = _engine;
    if (engine == null) {
      return;
    }

    final shouldShowVisualSuggestions = _shouldShowVisualSuggestions;
    if (!_shouldRunLiveAnalysis && !_shouldRunSacrificeScan) {
      engine.cancelSearches(
        roles: <EngineRequestRole>{EngineRequestRole.liveAnalysis},
        reason: 'analysis inactive',
      );
      setState(() {
        _topLines = [];
        _analysisLines = [];
        _analysisLinesFen = null;
        _currentDepth = 0;
      });
      return;
    }

    engine.cancelSearches(
      roles: <EngineRequestRole>{EngineRequestRole.liveAnalysis},
      reason: 'analysis refresh',
    );
    setState(() {
      _topLines = [];
      _analysisLines = [];
      _analysisLinesFen = null;
      _currentDepth = 0;
    });
    final analysisMultiPvCount = _analysisMultiPvCount;
    final liveAnalysisTimeout = _usesInfiniteAnalysisDepth
        ? const Duration(days: 1)
        : _isBotMatchMode && !shouldShowVisualSuggestions
        ? const Duration(milliseconds: 1800)
        : _analysisLiveCompletionTimeout(
            depth: _engineDepth,
            multiPv: analysisMultiPvCount,
          );
    engine.scheduleSearch(
      EngineRequestSpec(
        requestId: _nextEngineRequestId(EngineRequestRole.liveAnalysis),
        role: EngineRequestRole.liveAnalysis,
        fen: _genFen(),
        whiteToMove: _isWhiteTurn,
        multiPv: analysisMultiPvCount,
        depth: _engineDepth,
        infinite: _usesInfiniteAnalysisDepth,
        timeout: liveAnalysisTimeout,
        firstInfoTimeout: _isBotMatchMode
            ? null
            : const Duration(milliseconds: 2600),
        preCommands: _analysisEngineRequestCommands,
      ),
      onUpdate: _handleLiveAnalysisUpdate,
    );
  }

  _PendingMoveQualityGrading? _capturePendingMoveQualityGrading({
    required String uciMove,
    required bool moverIsWhite,
    required Map<String, String> nextBoardState,
  }) {
    final canGrade =
        !kIsWeb && (_isBotMatchMode || _runsAnalysisMoveAssessment);
    if (!canGrade) {
      return null;
    }
    if (_isBotMatchMode && moverIsWhite != _humanPlaysWhite) {
      return null;
    }

    final currentFen = _genFen();
    final cachedPosition = _cachedPositionAnalysisForFen(currentFen);
    final livePreMoveSnapshot =
        _currentEvalSnapshot != null &&
            _currentEvalSnapshot!.matchesFen(currentFen)
        ? _currentEvalSnapshot
        : null;
    final preMoveSnapshot = preferBestEvalSnapshot(
      cachedPosition?.evalSnapshot,
      livePreMoveSnapshot,
    );
    final preMoveWhiteEval = preMoveSnapshot?.evalPawnsWhite;
    final preMoveLines = preferDeeperAnalysisLines(
      _analysisLinesFen == currentFen ? _analysisLines : const <EngineLine>[],
      cachedPosition?.analysisLines ?? const <EngineLine>[],
    );
    final totalLegalMoveCount = _currentSideLegalMoveCount();
    return _PendingMoveQualityGrading(
      moveIndex: _historyIndex + 1,
      uci: uciMove,
      moverIsWhite: moverIsWhite,
      earliestPublishAt: DateTime.now().add(_moveQualityPublishDelay),
      preMoveFen: currentFen,
      preMoveLines: preMoveLines,
      moverMaterialBefore: _materialCountForSide(boardState, moverIsWhite),
      moverMaterialAfter: _materialCountForSide(nextBoardState, moverIsWhite),
      chargeBefore: _vsBotCharge,
      chargeEpoch: _vsBotChargeEpoch,
      playedMoveRank: _moveRankFromLines(preMoveLines, uciMove),
      cpGapFromBest: _cpGapFromBestFromLines(preMoveLines, uciMove),
      cpGapFromNextBetter: _cpGapFromNextBetterFromLines(preMoveLines, uciMove),
      totalLegalMoveCount: totalLegalMoveCount,
      analyzedLegalMoveCount: min(totalLegalMoveCount, preMoveLines.length),
      preMoveMoverEvalPawns: preMoveWhiteEval == null
          ? null
          : _moverEvalPawnsFromWhiteEval(preMoveWhiteEval, moverIsWhite),
      preMoveMoverWinProbability: preMoveWhiteEval == null
          ? null
          : _moverWinProbabilityFromWhiteEval(preMoveWhiteEval, moverIsWhite),
    );
  }

  _GradingSearchSnapshot? _buildCurrentGradingSearchSnapshot() {
    final lines = _gradingSearchLines.values.toList()
      ..sort((a, b) => a.multiPv.compareTo(b.multiPv));
    if (lines.isEmpty) {
      return null;
    }
    return _GradingSearchSnapshot(
      lines: lines,
      whiteToMove: _gradingSearchWhiteToMove,
    );
  }

  // ignore: unused_element
  Future<_GradingSearchSnapshot?> _requestGradingSearch({
    required String fen,
    required bool whiteToMove,
    int multiPv = _moveQualityGradingMultiPv,
    int depth = _moveQualityGradingDepth,
    bool resumeAnalysis = true,
    int? restoreMultiPv,
  }) async {
    await _ensureEngineStarted();
    if (_engine == null) {
      return null;
    }

    _gradingSearchLines.clear();
    _gradingSearchMultiPv = multiPv;
    _gradingSearchWhiteToMove = whiteToMove;
    final completer = Completer<_GradingSearchSnapshot?>();
    _gradingSearchCompleter = completer;

    _send('stop');
    _send('setoption name MultiPV value $multiPv');
    _send('position fen $fen');
    _send('go depth $depth');

    try {
      final gradingTimeout = _moveQualitySearchTimeout(
        multiPv: multiPv,
        backgroundConfirmation: false,
      );
      return await completer.future.timeout(
        gradingTimeout,
        onTimeout: _buildCurrentGradingSearchSnapshot,
      );
    } finally {
      if (identical(_gradingSearchCompleter, completer)) {
        _gradingSearchCompleter = null;
      }
      _gradingSearchLines.clear();
      final shouldResumeAnalysis =
          _analysisRefreshQueuedWhileGrading || _shouldRunLiveAnalysis;
      _analysisRefreshQueuedWhileGrading = false;
      _send(
        'setoption name MultiPV value ${restoreMultiPv ?? (_shouldShowVisualSuggestions ? _visualSuggestionLineCount : 1)}',
      );
      if (resumeAnalysis && shouldResumeAnalysis) {
        _analyze();
      }
    }
  }

  Future<_GradingSearchSnapshot?> _requestSacrificeScanSearch({
    required String fen,
    required bool whiteToMove,
    required int depth,
    Duration? timeout,
  }) async {
    CoordinatedEngineService? resolvedEngine;
    if (_canUseDedicatedSacrificeScanEngine) {
      resolvedEngine = await _ensureSacrificeScanEngineStarted();
    } else {
      await _ensureEngineStarted();
      resolvedEngine = _engine;
    }
    if (resolvedEngine == null) {
      return null;
    }

    final handle = resolvedEngine.scheduleSearch(
      EngineRequestSpec(
        requestId: _nextEngineRequestId(EngineRequestRole.sacrificeScan),
        role: EngineRequestRole.sacrificeScan,
        fen: fen,
        whiteToMove: whiteToMove,
        multiPv: 1,
        depth: depth,
        timeout: timeout ?? _sacrificeScanSearchTimeout(depth: depth),
        firstInfoTimeout: _moveQualityFirstInfoTimeout(
          backgroundConfirmation: true,
        ),
        preCommands: _analysisEngineRequestCommands,
      ),
    );
    final result = await handle.result;
    if (result.cancelled || result.failureReason != null) {
      return null;
    }
    if (result.lines.isEmpty) {
      return null;
    }
    return _GradingSearchSnapshot(
      lines: result.lines,
      whiteToMove: whiteToMove,
    );
  }

  int get _sacrificeScanSearchDepth {
    final preferredDepth = _usesInfiniteAnalysisDepth
        ? _defaultEngineDepth
        : min(_engineDepth, _defaultEngineDepth);
    return max(_moveQualityGradingDepth, preferredDepth);
  }

  Duration _sacrificeScanSearchTimeout({required int depth}) {
    final liveBudgetMs = _analysisLiveCompletionTimeout(
      depth: depth,
      multiPv: 1,
    ).inMilliseconds;
    final scaledBudgetMs = (liveBudgetMs * 0.45).round();
    return Duration(milliseconds: min(30000, max(6000, scaledBudgetMs)));
  }

  int? _cachedSacrificeScanBaselineEvalCp(String fen, bool moverIsWhite) {
    final liveSnapshot =
        _currentEvalSnapshot != null && _currentEvalSnapshot!.matchesFen(fen)
        ? _currentEvalSnapshot
        : null;
    final cached = _cachedPositionAnalysisForFen(fen);
    final snapshot = preferBestEvalSnapshot(cached?.evalSnapshot, liveSnapshot);
    return snapshot?.centipawnsForPov(moverIsWhite);
  }

  int? _searchSnapshotEvalCpForPov(
    _GradingSearchSnapshot? snapshot,
    bool povIsWhite,
  ) {
    final line = snapshot?.lines.isNotEmpty == true
        ? snapshot!.lines.first
        : null;
    if (line == null) {
      return null;
    }
    return snapshot!.whiteToMove == povIsWhite ? line.eval : -line.eval;
  }

  bool get _canEvaluateSacrificeAvailability =>
      _isAnalysisMatchMode && _sacrificeModeOwned;

  bool get _hasAvailableSacrificePreview =>
      _canEvaluateSacrificeAvailability &&
      _sacrificePreviewFen == _genFen() &&
      _sacrificePreviewLines.isNotEmpty;

  bool get _hasActiveSacrificeAvailabilityAlert =>
      !_isSacrificeModeActive &&
      _hasAvailableSacrificePreview &&
      _sacrificeAvailabilityAlertUntil?.isAfter(DateTime.now()) == true;

  void _updateSacrificePreviewState({
    required String fen,
    required List<EngineLine> previewLines,
  }) {
    final availabilitySignature = previewLines.isEmpty ? null : fen;
    final shouldTriggerAlert =
        !_isSacrificeModeActive &&
        availabilitySignature != null &&
        availabilitySignature != _lastSacrificeAvailabilityAlertSignature;
    setState(() {
      _sacrificePreviewFen = fen;
      _sacrificePreviewLines = previewLines;
      _lastSacrificeAvailabilityAlertSignature = availabilitySignature;
      if (availabilitySignature == null) {
        _sacrificeAvailabilityAlertUntil = null;
      } else if (shouldTriggerAlert) {
        _sacrificeAvailabilityAlertUntil = DateTime.now().add(
          _sacrificeAvailabilityAlertDuration,
        );
      }
    });
  }

  void _scheduleSacrificePreviewScan() {
    final fen = _genFen();
    _sacrificePreviewScanToken += 1;
    final scanToken = _sacrificePreviewScanToken;
    _cancelSacrificeScanSearches();

    if (!_canEvaluateSacrificeAvailability) {
      if (_sacrificePreviewFen != null || _sacrificePreviewLines.isNotEmpty) {
        _updateSacrificePreviewState(
          fen: fen,
          previewLines: const <EngineLine>[],
        );
      }
      return;
    }

    if (_sacrificePreviewFen != fen) {
      _updateSacrificePreviewState(
        fen: fen,
        previewLines: const <EngineLine>[],
      );
    }

    final moverIsWhite = _isWhiteTurn;
    final boardSnapshot = Map<String, String>.from(boardState);
    _sacrificePreviewScanOperation = _sacrificePreviewScanOperation
        .catchError((_) {})
        .then((_) async {
          await _runSacrificePreviewScan(
            scanToken: scanToken,
            fen: fen,
            moverIsWhite: moverIsWhite,
            boardSnapshot: boardSnapshot,
          );
        });
  }

  Future<void> _runSacrificePreviewScan({
    required int scanToken,
    required String fen,
    required bool moverIsWhite,
    required Map<String, String> boardSnapshot,
  }) async {
    final currentPositionAnalysisLines = _currentPositionAnalysisLines(fen);
    final prioritizedRootLines = currentPositionAnalysisLines.toList(
      growable: false,
    )..sort((left, right) => left.multiPv.compareTo(right.multiPv));
    final confirmedFastPath =
        currentPositionAnalysisLines.isNotEmpty &&
        currentPositionAnalysisLines.first.depth >=
            _sacrificeFastConfirmationDepth;
    final scanDepth = confirmedFastPath
        ? min(_sacrificeScanSearchDepth, _sacrificeFastConfirmationDepth)
        : _sacrificeScanSearchDepth;
    final fastPathDeadline = confirmedFastPath
        ? DateTime.now().add(_sacrificeFastPathBudget)
        : null;
    final rootEnPassantTarget = _enPassantTargetFromFen(fen);
    if (!_canEvaluateSacrificeAvailability ||
        scanToken != _sacrificePreviewScanToken) {
      return;
    }

    Duration? remainingFastPathTimeout() {
      if (fastPathDeadline == null) {
        return null;
      }
      final remaining = fastPathDeadline.difference(DateTime.now());
      if (remaining <= Duration.zero) {
        return Duration.zero;
      }
      return remaining < _sacrificeFastPathSearchTimeout
          ? remaining
          : _sacrificeFastPathSearchTimeout;
    }

    final cachedBaselineEvalCp = _cachedSacrificeScanBaselineEvalCp(
      fen,
      moverIsWhite,
    );
    final baselineSnapshot = cachedBaselineEvalCp == null
        ? await _requestSacrificeScanSearch(
            fen: fen,
            whiteToMove: moverIsWhite,
            depth: scanDepth,
            timeout: remainingFastPathTimeout(),
          )
        : null;
    if (!mounted ||
        scanToken != _sacrificePreviewScanToken ||
        _genFen() != fen) {
      return;
    }

    final baselineEvalCp =
        cachedBaselineEvalCp ??
        _searchSnapshotEvalCpForPov(baselineSnapshot, moverIsWhite);
    if (baselineEvalCp == null) {
      _updateSacrificePreviewState(
        fen: fen,
        previewLines: const <EngineLine>[],
      );
      return;
    }

    final materialBalanceBefore = _materialBalanceForSide(
      boardSnapshot,
      moverIsWhite,
    );
    final rootMoveEvalsCpByUci = _moveEvalCpByUci(currentPositionAnalysisLines);
    final allRootMoves = _verboseMovesForFen(fen).toList(growable: false);
    final eligibleRootUcis = confirmedFastPath
        ? prioritizedRootLines
              .take(_sacrificeEligibleRootMoveLimit)
              .map((line) => line.move)
              .toSet()
        : const <String>{};
    final rootMoves =
        (confirmedFastPath && eligibleRootUcis.isNotEmpty
                ? allRootMoves.where((move) {
                    final uciMove = _uciMoveFromVerboseMove(move);
                    return uciMove != null &&
                        eligibleRootUcis.contains(uciMove);
                  })
                : allRootMoves)
            .toList(growable: true);
    rootMoves.sort((left, right) {
      final leftUci = _uciMoveFromVerboseMove(left);
      final rightUci = _uciMoveFromVerboseMove(right);
      final leftEval = leftUci == null ? null : rootMoveEvalsCpByUci[leftUci];
      final rightEval = rightUci == null
          ? null
          : rootMoveEvalsCpByUci[rightUci];
      if (leftEval != null || rightEval != null) {
        if (leftEval == null) {
          return 1;
        }
        if (rightEval == null) {
          return -1;
        }
        final evalCompare = rightEval.compareTo(leftEval);
        if (evalCompare != 0) {
          return evalCompare;
        }
      }
      if (leftUci == null) {
        return 1;
      }
      if (rightUci == null) {
        return -1;
      }
      return leftUci.compareTo(rightUci);
    });
    final sacrificeCandidates = <_SacrificePreviewCandidate>[];

    rootMoveLoop:
    for (final rootMove in rootMoves) {
      if (!mounted ||
          scanToken != _sacrificePreviewScanToken ||
          _genFen() != fen) {
        return;
      }
      if (fastPathDeadline != null &&
          !fastPathDeadline.isAfter(DateTime.now())) {
        break;
      }

      final rootUci = _uciMoveFromVerboseMove(rootMove);
      if (rootUci == null) {
        continue;
      }
      final rootMovedPiece = boardSnapshot[rootUci.substring(0, 2)];
      if (rootMovedPiece == null) {
        continue;
      }
      final rootCapturedPiece = _capturedPieceForUciMove(
        state: boardSnapshot,
        uciMove: rootUci,
        enPassantTarget: rootEnPassantTarget,
      );
      final rootMoveEvalCp = rootMoveEvalsCpByUci[rootUci];
      final movingPieceValueCp = _pieceValueCp(rootMovedPiece);
      final rootCapturedPieceValueCp = rootCapturedPiece == null
          ? 0
          : _pieceValueCp(rootCapturedPiece);

      final firstPosition = _simulateSacrificePreviewMove(
        fen: fen,
        state: Map<String, String>.from(boardSnapshot),
        uciMove: rootUci,
      );
      if (firstPosition == null) {
        continue;
      }

      final captureReplies = _verboseMovesForFen(firstPosition.fen).where((
        reply,
      ) {
        final captureUci = _uciMoveFromVerboseMove(reply);
        if (captureUci == null) {
          return false;
        }
        return _isRelevantSacrificeCaptureReply(
          firstPosition: firstPosition,
          rootToSquare: rootUci.substring(2, 4),
          moverIsWhite: moverIsWhite,
          captureReplyUci: captureUci,
        );
      });

      for (final captureReply in captureReplies) {
        if (!mounted ||
            scanToken != _sacrificePreviewScanToken ||
            _genFen() != fen) {
          return;
        }
        if (fastPathDeadline != null &&
            !fastPathDeadline.isAfter(DateTime.now())) {
          break rootMoveLoop;
        }

        final captureUci = _uciMoveFromVerboseMove(captureReply);
        if (captureUci == null) {
          continue;
        }

        final capturePosition = _simulateSacrificePreviewMove(
          fen: firstPosition.fen,
          state: firstPosition.boardState,
          uciMove: captureUci,
        );
        if (capturePosition == null) {
          continue;
        }

        final acceptanceTimeout = remainingFastPathTimeout();
        if (acceptanceTimeout != null && acceptanceTimeout <= Duration.zero) {
          break rootMoveLoop;
        }

        final acceptanceSnapshot = await _requestSacrificeScanSearch(
          fen: capturePosition.fen,
          whiteToMove: moverIsWhite,
          depth: scanDepth,
          timeout: acceptanceTimeout,
        );
        if (!mounted ||
            scanToken != _sacrificePreviewScanToken ||
            _genFen() != fen) {
          return;
        }

        final acceptanceDepth = acceptanceSnapshot?.lines.isNotEmpty == true
            ? acceptanceSnapshot!.lines.first.depth
            : scanDepth;
        final acceptedCaptureEvalCp = _searchSnapshotEvalCpForPov(
          acceptanceSnapshot,
          moverIsWhite,
        );
        final isHigherPieceForSmallerTrade =
            movingPieceValueCp > rootCapturedPieceValueCp;

        final shouldProbeImmediateRecapture =
            !confirmedFastPath &&
            ((acceptedCaptureEvalCp != null &&
                    acceptedCaptureEvalCp < baselineEvalCp) ||
                isHigherPieceForSmallerTrade);
        final immediateRecapture = shouldProbeImmediateRecapture
            ? await _bestImmediateRecaptureAfterAcceptedCapture(
                scanToken: scanToken,
                rootFen: fen,
                moverIsWhite: moverIsWhite,
                capturePosition: capturePosition,
                captureReplyUci: captureUci,
                scanDepth: scanDepth,
              )
            : null;
        if (!mounted ||
            scanToken != _sacrificePreviewScanToken ||
            _genFen() != fen) {
          return;
        }

        final candidate = _sacrificePreviewCandidateForAcceptedCapture(
          rootMoveUci: rootUci,
          captureReplyUci: captureUci,
          materialBalanceBefore: materialBalanceBefore,
          materialBalanceAfterCapture: _materialBalanceForSide(
            capturePosition.boardState,
            moverIsWhite,
          ),
          baselineEvalCp: baselineEvalCp,
          acceptedCaptureEvalCp: acceptedCaptureEvalCp,
          rootMoveEvalCp: rootMoveEvalCp,
          movingPieceValueCp: movingPieceValueCp,
          rootCapturedPieceValueCp: rootCapturedPieceValueCp,
          immediateRecapture: immediateRecapture,
          searchDepth: max(
            acceptanceDepth,
            immediateRecapture?.searchDepth ?? acceptanceDepth,
          ),
        );
        if (candidate != null) {
          sacrificeCandidates.add(candidate);
          final previewLines = _previewLinesFromSacrificeCandidates(
            sacrificeCandidates,
          );
          if (previewLines.isNotEmpty) {
            _updateSacrificePreviewState(fen: fen, previewLines: previewLines);
            if (confirmedFastPath &&
                previewLines.length >= _sacrificePreviewLineLimit) {
              break rootMoveLoop;
            }
          }
        }
      }
    }

    if (!mounted ||
        scanToken != _sacrificePreviewScanToken ||
        _genFen() != fen) {
      return;
    }

    _updateSacrificePreviewState(
      fen: fen,
      previewLines: _previewLinesFromSacrificeCandidates(sacrificeCandidates),
    );
  }

  List<Map<String, dynamic>> _verboseMovesForFen(String fen) {
    try {
      final game = chess.Chess.fromFEN(fen);
      return game
          .moves(<String, dynamic>{'verbose': true})
          .whereType<Map>()
          .map((move) => move.cast<String, dynamic>())
          .toList(growable: false);
    } catch (_) {
      return const <Map<String, dynamic>>[];
    }
  }

  String? _uciMoveFromVerboseMove(Map<String, dynamic> move) {
    final from = move['from']?.toString();
    final to = move['to']?.toString();
    if (from == null || from.length != 2 || to == null || to.length != 2) {
      return null;
    }
    final promotion = move['promotion']?.toString().toLowerCase();
    if (promotion == null || promotion.isEmpty) {
      return '$from$to';
    }
    return '$from$to$promotion';
  }

  int _pieceValueCp(String piece) => (_pieceMaterialValue(piece) * 100).round();

  String _capturedSquareForUciMove({
    required Map<String, String> state,
    required String uciMove,
    required String? enPassantTarget,
  }) {
    final from = uciMove.substring(0, 2);
    final to = uciMove.substring(2, 4);
    final movingPiece = state[from];
    if (movingPiece == null) {
      return to;
    }
    final enPassantCaptureSquare = _enPassantCaptureSquare(
      state,
      from,
      to,
      movingPiece,
      enPassantTarget: enPassantTarget,
    );
    return enPassantCaptureSquare ?? to;
  }

  String? _capturedPieceForUciMove({
    required Map<String, String> state,
    required String uciMove,
    required String? enPassantTarget,
  }) {
    final from = uciMove.substring(0, 2);
    final to = uciMove.substring(2, 4);
    final movingPiece = state[from];
    if (movingPiece == null) {
      return null;
    }
    final enPassantCaptureSquare = _enPassantCaptureSquare(
      state,
      from,
      to,
      movingPiece,
      enPassantTarget: enPassantTarget,
    );
    if (enPassantCaptureSquare != null) {
      return state[enPassantCaptureSquare];
    }
    return state[to];
  }

  bool _isRelevantSacrificeCaptureReply({
    required _SacrificePreviewPosition firstPosition,
    required String rootToSquare,
    required bool moverIsWhite,
    required String captureReplyUci,
  }) {
    final firstPositionEnPassantTarget = _enPassantTargetFromFen(
      firstPosition.fen,
    );
    final capturedPiece = _capturedPieceForUciMove(
      state: firstPosition.boardState,
      uciMove: captureReplyUci,
      enPassantTarget: firstPositionEnPassantTarget,
    );
    if (capturedPiece == null || capturedPiece.endsWith('_w') != moverIsWhite) {
      return false;
    }

    final capturedSquare = _capturedSquareForUciMove(
      state: firstPosition.boardState,
      uciMove: captureReplyUci,
      enPassantTarget: firstPositionEnPassantTarget,
    );
    return capturedSquare == rootToSquare;
  }

  Future<_SacrificeRecapturePreview?>
  _bestImmediateRecaptureAfterAcceptedCapture({
    required int scanToken,
    required String rootFen,
    required bool moverIsWhite,
    required _SacrificePreviewPosition capturePosition,
    required String captureReplyUci,
    required int scanDepth,
  }) async {
    final captureSquare = captureReplyUci.substring(2, 4);
    _SacrificeRecapturePreview? bestRecapture;
    final recaptureReplies = _verboseMovesForFen(
      capturePosition.fen,
    ).where((reply) => reply['to']?.toString() == captureSquare);

    for (final recaptureReply in recaptureReplies) {
      if (!mounted ||
          scanToken != _sacrificePreviewScanToken ||
          _genFen() != rootFen) {
        return bestRecapture;
      }

      final recaptureUci = _uciMoveFromVerboseMove(recaptureReply);
      if (recaptureUci == null) {
        continue;
      }

      final recapturePosition = _simulateSacrificePreviewMove(
        fen: capturePosition.fen,
        state: capturePosition.boardState,
        uciMove: recaptureUci,
      );
      if (recapturePosition == null) {
        continue;
      }

      final recaptureSnapshot = await _requestSacrificeScanSearch(
        fen: recapturePosition.fen,
        whiteToMove: recapturePosition.whiteToMove,
        depth: scanDepth,
      );
      if (!mounted ||
          scanToken != _sacrificePreviewScanToken ||
          _genFen() != rootFen) {
        return bestRecapture;
      }

      final recaptureLine = recaptureSnapshot?.lines.isNotEmpty == true
          ? recaptureSnapshot!.lines.first
          : null;
      final recaptureEvalCp = _searchSnapshotEvalCpForPov(
        recaptureSnapshot,
        moverIsWhite,
      );
      if (recaptureLine == null || recaptureEvalCp == null) {
        continue;
      }

      if (bestRecapture == null ||
          recaptureEvalCp > bestRecapture.evalCp ||
          (recaptureEvalCp == bestRecapture.evalCp &&
              recaptureLine.depth > bestRecapture.searchDepth)) {
        bestRecapture = _SacrificeRecapturePreview(
          uciMove: recaptureUci,
          evalCp: recaptureEvalCp,
          searchDepth: recaptureLine.depth,
        );
      }
    }

    return bestRecapture;
  }

  Future<void> _finalizePendingMoveQualityGrading(
    _PendingMoveQualityGrading pending, {
    EngineLine? livePostMoveLine,
    bool? livePostMoveWhiteToMove,
    EngineRequestRole? livePostMoveRole,
    int? gradingGeneration,
  }) async {
    if (gradingGeneration != null &&
        gradingGeneration != _moveQualityGradingGeneration) {
      return;
    }
    final fastPublish =
        livePostMoveRole != EngineRequestRole.backgroundConfirmation;
    final evidence = resolveMoveQualityEvidence(
      moverIsWhite: pending.moverIsWhite,
      capturedPreMoveLines: pending.preMoveLines,
      capturedPreMoveMoverWinProbability: pending.preMoveMoverWinProbability,
      capturedPreMoveMoverEvalPawns: pending.preMoveMoverEvalPawns,
      playedMoveUci: pending.uci,
      requiredPreMoveLineCount: _requiredPreMoveComparisonLineCount(
        pending.totalLegalMoveCount,
      ),
      preMoveCacheEntry: _cachedPositionAnalysisForFen(pending.preMoveFen),
      livePostMoveLine: livePostMoveLine,
      livePostMoveWhiteToMove: livePostMoveWhiteToMove,
      postMoveCacheEntry: pending.postMoveFen == null
          ? null
          : _cachedPositionAnalysisForFen(pending.postMoveFen!),
      minimumDepth: fastPublish
          ? _moveQualityInitialPublishDepth
          : _moveQualityGradingDepth,
      requireCoveredPreMoveComparison: !fastPublish,
    );
    if (!evidence.isReadyToPublish) {
      _deferPendingMoveQualityGrading(
        pending,
        needsPreMoveConfirmation: evidence.needsPreMoveConfirmation,
        needsPostMoveConfirmation: evidence.needsPostMoveConfirmation,
      );
      return;
    }
    final preMoveLines = evidence.preMoveLines;
    final preMoveMoverWinProbability = evidence.preMoveMoverWinProbability;
    final preMoveMoverEvalPawns = evidence.preMoveMoverEvalPawns;
    final usedPreMoveFallback = evidence.usedPreMoveFallback;
    final postMoveLine = evidence.postMoveLine;
    final postMoveWhiteToMove = evidence.postMoveWhiteToMove;
    livePostMoveRole ??= pending.postMoveFen == null
        ? null
        : _positionAnalysisCacheByFen[pending.postMoveFen!]?.evalSnapshot?.role;

    if (gradingGeneration != null &&
        gradingGeneration != _moveQualityGradingGeneration) {
      return;
    }

    if (gradingGeneration != null &&
        gradingGeneration != _moveQualityGradingGeneration) {
      return;
    }

    if (!mounted || !_moveQualityPendingStillMatchesHistory(pending)) {
      return;
    }
    final currentMove = _moveHistory[pending.moveIndex];
    if (currentMove.uci != pending.uci) {
      return;
    }

    final postMoveMoverWinProbability = _moverWinProbabilityFromEngineLine(
      postMoveLine!,
      whiteToMove: postMoveWhiteToMove!,
      moverIsWhite: pending.moverIsWhite,
    );
    final effectivePreMoveMoverWinProbability =
        preMoveMoverWinProbability ?? postMoveMoverWinProbability;
    final loss = deltaWpLoss(
      bestContinuationMoverWinProbability: effectivePreMoveMoverWinProbability,
      playedMoveMoverWinProbability: postMoveMoverWinProbability,
    );
    final insideOpeningExemption = _openingFeedbackOnlyApplies(
      pending.moveIndex,
    );
    final comparisonSnapshot = resolveMoveQualityComparisonSnapshot(
      playedMoveUci: pending.uci,
      preMoveLines: preMoveLines,
      totalLegalMoveCount: pending.totalLegalMoveCount,
      capturedPlayedMoveRank: pending.playedMoveRank,
      capturedCpGapFromBest: pending.cpGapFromBest,
      capturedCpGapFromNextBetter: pending.cpGapFromNextBetter,
    );
    final playedMoveRank = comparisonSnapshot.playedMoveRank;
    final cpGapFromBest = comparisonSnapshot.cpGapFromBest;
    final cpGapFromNextBetter = comparisonSnapshot.cpGapFromNextBetter;
    final analyzedLegalMoveCount = comparisonSnapshot.analyzedLegalMoveCount;
    final confidence = _moveQualityConfidence(
      preMoveLines: preMoveLines,
      playedMoveRank: playedMoveRank,
      cpGapFromBest: cpGapFromBest,
      totalLegalMoveCount: pending.totalLegalMoveCount,
      insideOpeningExemption: insideOpeningExemption,
      usedPreMoveFallback: usedPreMoveFallback,
    );

    final previousMove = pending.moveIndex > 0
        ? _moveHistory[pending.moveIndex - 1]
        : null;
    double? availableReplySwing;
    double? capturedReplySwing;
    if (previousMove != null &&
        previousMove.preMoveWinProbability != null &&
        previousMove.postMoveWinProbability != null &&
        previousMove.isWhite != pending.moverIsWhite) {
      final currentMoverBeforeOpponent =
          1 - previousMove.preMoveWinProbability!;
      final currentMoverAfterOpponent =
          1 - previousMove.postMoveWinProbability!;
      availableReplySwing =
          currentMoverAfterOpponent - currentMoverBeforeOpponent;
      capturedReplySwing =
          postMoveMoverWinProbability - currentMoverBeforeOpponent;
    }

    final assessment = classifyMoveQuality(
      MoveQualityClassificationContext(
        deltaWpLoss: loss,
        preMoveMoverWinProbability: effectivePreMoveMoverWinProbability,
        postMoveMoverWinProbability: postMoveMoverWinProbability,
        preMoveMoverEvalPawns: preMoveMoverEvalPawns ?? 0.0,
        currentOpening: _currentOpening,
        cpGapFromBest: cpGapFromBest,
        cpGapFromNextBetter: cpGapFromNextBetter,
        playedMoveRank: playedMoveRank,
        totalLegalMoveCount: pending.totalLegalMoveCount,
        analyzedLegalMoveCount: analyzedLegalMoveCount,
        insideOpeningExemption: insideOpeningExemption,
        confidence: confidence,
        isSacrifice: pending.isSacrifice,
        preservingNonLosingContinuationCount: _preservingContinuationCount(
          preMoveLines,
          isNonLosingWinProbability,
        ),
        preservingWinningContinuationCount: _preservingContinuationCount(
          preMoveLines,
          isWinningWinProbability,
        ),
        previousOpponentQuality: previousMove?.quality,
        availableReplySwing: availableReplySwing,
        capturedReplySwing: capturedReplySwing,
      ),
    );

    final publication = _DeferredMoveQualityPublication(
      pending: pending,
      assessment: assessment,
      preMoveMoverWinProbability: effectivePreMoveMoverWinProbability,
      postMoveMoverWinProbability: postMoveMoverWinProbability,
      deltaWpLoss: loss,
      sourceRole: livePostMoveRole,
    );
    if (pending.earliestPublishAt.isAfter(DateTime.now())) {
      _stageMoveQualityPublication(publication);
      return;
    }
    _clearDeferredMoveQualityPublication();
    _applyMoveQualityPublication(publication);
  }

  void _showMoveQualityOverlay(MoveRecord move, int chargeDelta) {
    if (!_isBotMatchMode && !_runsAnalysisMoveAssessment) {
      return;
    }
    final quality = move.quality;
    if (quality == null) {
      return;
    }
    final overlayDuration = quality == MoveQuality.book
        ? _bookMoveQualityOverlayDuration
        : _moveQualityOverlayDuration;
    _moveQualityOverlayTimer?.cancel();
    _moveQualityOverlayQuality = quality;
    _moveQualityOverlayTitle = quality == MoveQuality.masterstroke
        ? 'MASTERSTROKE!'
        : quality == MoveQuality.crucial
        ? 'CRUCIAL!'
        : quality.label.toUpperCase();
    _moveQualityOverlayMessage = move.qualityExplanation ?? quality.explanation;
    _moveQualityOverlayChargeDelta = _isBotMatchMode ? chargeDelta : null;
    _moveQualityOverlayScoringSuppressedReason = move.scoringSuppressedReason;
    _moveQualityOverlayTimer = Timer(overlayDuration, () {
      if (!mounted) {
        return;
      }
      setState(_clearMoveQualityOverlay);
    });
  }

  Color _vsBotChargeColor(double progress, _VsBotArcadePalette arcade) {
    if (progress <= 0.5) {
      return Color.lerp(arcade.crimson, arcade.amber, progress / 0.5)!;
    }
    return Color.lerp(arcade.amber, arcade.cyan, (progress - 0.5) / 0.5)!;
  }

  Future<void> _activateVsBotOptimalLineReveal() async {
    if (!_isBotMatchMode || !_isHumanTurnInBotGame || _vsBotCharge < 100) {
      return;
    }
    setState(() {
      _vsBotChargeEpoch++;
      _vsBotCharge = 0;
      _vsBotOptimalLineRevealActive = true;
      _topLines = [];
      _currentDepth = 0;
    });
    _analyze();
  }

  Widget _buildMoveQualityBanner({required bool isLandscape}) {
    if (!_isBotMatchMode && !_runsAnalysisMoveAssessment) {
      return const SizedBox.shrink();
    }
    final quality = _moveQualityOverlayQuality;
    final title = _moveQualityOverlayTitle;
    final message = _moveQualityOverlayMessage;
    if (quality == null || title == null || message == null) {
      return const SizedBox.shrink();
    }

    final contentPadding = EdgeInsets.fromLTRB(
      isLandscape ? 0 : 16,
      isLandscape ? 6 : 2,
      isLandscape ? 0 : 16,
      isLandscape ? 8 : 10,
    );

    if (_isBotMatchMode) {
      final useMonochrome =
          context.watch<AppThemeProvider>().isMonochrome ||
          _isCinematicThemeEnabled;
      final arcade = _vsBotArcadePaletteFor(context, monochrome: useMonochrome);
      final assessmentColor = quality.color;
      final panelAccent = useMonochrome ? arcade.text : assessmentColor;
      final chargeDelta = _moveQualityOverlayChargeDelta;
      final chargeText = switch (_moveQualityOverlayScoringSuppressedReason) {
        MoveQualityScoringSuppressionReason.openingFeedbackOnly =>
          'No points in opening',
        MoveQualityScoringSuppressionReason.obviousMove =>
          'No points for obvious move',
        null =>
          chargeDelta == null
              ? null
              : chargeDelta > 0
              ? '+$chargeDelta charge'
              : chargeDelta < 0
              ? '$chargeDelta charge'
              : 'Charge steady',
      };

      return IgnorePointer(
        child: Padding(
          padding: contentPadding,
          child: ConstrainedBox(
            constraints: BoxConstraints(maxWidth: isLandscape ? 280 : 320),
            child: Container(
              padding: const EdgeInsets.fromLTRB(14, 12, 14, 12),
              decoration: _vsBotArcadePanelDecoration(
                palette: arcade,
                accent: panelAccent,
                radius: 18,
                borderWidth: 2.2,
                inset: true,
                elevated: false,
                fillColor: arcade.panelAlt,
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Text(
                        quality.displaySymbol,
                        style: puzzleAcademyIdentityStyle(
                          palette: arcade.base,
                          size: quality == MoveQuality.masterstroke ? 12 : 10,
                          color: assessmentColor,
                          withGlow: !useMonochrome,
                        ),
                      ),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Text(
                          title,
                          style: puzzleAcademyIdentityStyle(
                            palette: arcade.base,
                            size: 7.8,
                            color: assessmentColor,
                            withGlow: !useMonochrome,
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 8),
                  Text(
                    message,
                    style: GoogleFonts.pixelifySans(
                      color: arcade.text,
                      fontSize: 13,
                      fontWeight: FontWeight.w500,
                      height: 1.14,
                    ),
                  ),
                  if (chargeText != null) ...[
                    const SizedBox(height: 8),
                    Text(
                      chargeText.toUpperCase(),
                      style: puzzleAcademyIdentityStyle(
                        palette: arcade.base,
                        size: 6.4,
                        color: useMonochrome ? arcade.text : assessmentColor,
                      ),
                    ),
                  ],
                ],
              ),
            ),
          ),
        ),
      );
    }

    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final useMonochrome =
        context.watch<AppThemeProvider>().isMonochrome ||
        _isCinematicThemeEnabled;
    final isLight = theme.brightness == Brightness.light;
    final assessmentColor = quality.color;
    final accentColor = useMonochrome ? scheme.onSurface : assessmentColor;
    final panelColor = useMonochrome
        ? Color.alphaBlend(
            scheme.onSurface.withValues(alpha: isLight ? 0.06 : 0.12),
            scheme.surface,
          )
        : Color.alphaBlend(
            assessmentColor.withValues(alpha: isLight ? 0.10 : 0.14),
            scheme.surface,
          );
    final borderColor = useMonochrome
        ? scheme.onSurface.withValues(alpha: isLight ? 0.16 : 0.24)
        : assessmentColor.withValues(alpha: isLight ? 0.28 : 0.40);
    final shadowColor = (useMonochrome ? scheme.shadow : assessmentColor)
        .withValues(alpha: isLight ? 0.10 : 0.18);
    final titleColor = useMonochrome ? assessmentColor : scheme.onSurface;
    final messageColor = scheme.onSurface.withValues(
      alpha: isLight ? 0.76 : 0.82,
    );

    return IgnorePointer(
      child: Padding(
        padding: contentPadding,
        child: ConstrainedBox(
          constraints: BoxConstraints(maxWidth: isLandscape ? 300 : 340),
          child: Container(
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 12),
            decoration: BoxDecoration(
              color: panelColor,
              borderRadius: BorderRadius.circular(18),
              border: Border.all(color: borderColor),
              boxShadow: [
                BoxShadow(
                  color: shadowColor,
                  blurRadius: 18,
                  offset: const Offset(0, 8),
                ),
              ],
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  children: [
                    Text(
                      quality.displaySymbol,
                      style: TextStyle(
                        color: accentColor,
                        fontSize: quality == MoveQuality.masterstroke ? 22 : 18,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(width: 10),
                    Expanded(
                      child: Text(
                        title,
                        style: TextStyle(
                          color: titleColor,
                          fontSize: 15,
                          fontWeight: FontWeight.w800,
                          letterSpacing: 0.5,
                        ),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                Text(
                  message,
                  style: TextStyle(
                    color: messageColor,
                    fontSize: 13.5,
                    fontWeight: FontWeight.w600,
                    height: 1.2,
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  bool get _hasMoveQualityBanner =>
      _moveQualityOverlayQuality != null &&
      _moveQualityOverlayTitle != null &&
      _moveQualityOverlayMessage != null;

  bool get _hasVisibleSuggestedMoves =>
      _shouldShowVisualSuggestions && _topLines.isNotEmpty;

  Widget _buildMoveQualityBannerOverlay({required bool isLandscape}) {
    if (!_hasMoveQualityBanner) {
      return const SizedBox.shrink();
    }

    return Align(
      alignment: isLandscape ? Alignment.topCenter : Alignment.bottomCenter,
      child: _buildMoveQualityBanner(isLandscape: isLandscape),
    );
  }

  Widget _buildPortraitVsBotMoveQualityBannerSceneOverlay() {
    if (!_isBotMatchMode || _gameOutcome != null || !_hasMoveQualityBanner) {
      return const SizedBox.shrink();
    }

    final media = MediaQuery.of(context);
    if (media.orientation == Orientation.landscape) {
      return const SizedBox.shrink();
    }

    final boardRect = _boardRectInScene();
    if (boardRect == null) {
      return const SizedBox.shrink();
    }

    const gapBelowBoard = 12.0;
    return Positioned(
      left: 0,
      right: 0,
      top: boardRect.bottom + gapBelowBoard,
      child: Center(child: _buildMoveQualityBanner(isLandscape: false)),
    );
  }

  Widget _buildPortraitAnalysisMoveQualityBannerSceneOverlay() {
    if (!_isAnalysisMatchMode ||
        _gameOutcome != null ||
        !_hasMoveQualityBanner) {
      return const SizedBox.shrink();
    }

    final media = MediaQuery.of(context);
    if (media.orientation == Orientation.landscape) {
      return const SizedBox.shrink();
    }

    final boardRect = _boardRectInScene();
    if (boardRect == null) {
      return const SizedBox.shrink();
    }

    const gapBelowBoard = 12.0;
    return Positioned(
      left: 0,
      right: 0,
      top: boardRect.bottom + gapBelowBoard,
      child: Center(child: _buildMoveQualityBanner(isLandscape: false)),
    );
  }

  Widget _buildLandscapeVsBotMoveQualityBannerSceneOverlay(Size scene) {
    if (!_isBotMatchMode || _gameOutcome != null || !_hasMoveQualityBanner) {
      return const SizedBox.shrink();
    }

    final media = MediaQuery.of(context);
    if (media.orientation != Orientation.landscape) {
      return const SizedBox.shrink();
    }

    final actionAreaRect = _rectInScene(_actionAreaKey);
    if (actionAreaRect == null) {
      return const SizedBox.shrink();
    }

    const gapAboveActionArea = 14.0;
    return Positioned(
      left: actionAreaRect.left,
      right: max(0.0, scene.width - actionAreaRect.right),
      bottom: max(0.0, scene.height - actionAreaRect.top + gapAboveActionArea),
      child: _buildMoveQualityBannerOverlay(isLandscape: true),
    );
  }

  // ignore: unused_element
  void _parseOutput(String line) {
    final activeGradingSearch = _gradingSearchCompleter;
    final gradingSearchActive =
        activeGradingSearch != null && !activeGradingSearch.isCompleted;

    if (line.startsWith('bestmove')) {
      if (gradingSearchActive) {
        activeGradingSearch.complete(_buildCurrentGradingSearchSnapshot());
        return;
      }

      final activeSearch = _botSearchCompleter;
      if (activeSearch != null && !activeSearch.isCompleted) {
        final sorted = _sortedBotSearchLines();
        if (sorted.isEmpty) {
          final fallback = RegExp(
            r'^bestmove\s+([a-h][1-8][a-h][1-8][nbrq]?)',
          ).firstMatch(line);
          if (fallback != null) {
            activeSearch.complete([
              EngineLine(fallback.group(1)!, 0, _currentDepth, 1),
            ]);
          } else {
            activeSearch.complete(const <EngineLine>[]);
          }
        } else {
          activeSearch.complete(sorted);
        }
      }
      return;
    }

    if (!line.startsWith('info depth')) return;
    final activeSearch = _botSearchCompleter;
    final botSearchActive = activeSearch != null && !activeSearch.isCompleted;
    final shouldShowVisualSuggestions =
        _shouldShowVisualSuggestions &&
        (!_isBotMatchMode || _isHumanTurnInBotGame);
    final analysisMultiPvCount = _analysisMultiPvCount;
    if (!gradingSearchActive &&
        !botSearchActive &&
        !shouldShowVisualSuggestions &&
        !_runsAnalysisMoveAssessment &&
        !_shouldKeepEvalActive) {
      return;
    }
    if (_gameOutcome != null && !botSearchActive && !gradingSearchActive) {
      return;
    }

    final d = RegExp(r'depth (\d+)').firstMatch(line);
    final pv = RegExp(r'multipv (\d+)').firstMatch(line);
    final principalVariation =
        RegExp(r'\bpv\s+(.+)$')
            .firstMatch(line)
            ?.group(1)
            ?.split(RegExp(r'\s+'))
            .where(
              (move) => RegExp(r'^[a-h][1-8][a-h][1-8][nbrq]?$').hasMatch(move),
            )
            .toList(growable: false) ??
        const <String>[];
    final sCp = RegExp(r'score cp (-?\d+)').firstMatch(line);
    final sMate = RegExp(r'score mate (-?\d+)').firstMatch(line);

    if (d != null && principalVariation.isNotEmpty) {
      final depth = int.parse(d.group(1)!);
      final multiPv = int.tryParse(pv?.group(1) ?? '1') ?? 1;
      final maxMultiPvAllowed = gradingSearchActive
          ? _gradingSearchMultiPv
          : botSearchActive
          ? _botSearchMultiPv
          : analysisMultiPvCount;
      if (multiPv > maxMultiPvAllowed) {
        return;
      }
      final move = principalVariation.first;

      int cp;
      double normalizedEval;
      if (sCp != null) {
        cp = int.parse(sCp.group(1)!);
        normalizedEval = cp / 100.0;
      } else if (sMate != null) {
        final mateScore = int.parse(sMate.group(1)!);
        if (mateScore > 0) {
          cp = 10000;
          normalizedEval = 100.0;
        } else if (mateScore < 0) {
          cp = -10000;
          normalizedEval = -100.0;
        } else {
          cp = 0;
          normalizedEval = 0.0;
        }
      } else {
        cp = 0;
        normalizedEval = 0.0;
      }

      final parsedLine = EngineLine(
        move,
        cp,
        depth,
        multiPv,
        principalVariation: principalVariation,
      );

      if (gradingSearchActive) {
        if (multiPv <= _gradingSearchMultiPv) {
          _gradingSearchLines[multiPv] = parsedLine;
        }
        return;
      }

      if (!_isLegalUciMove(move)) {
        return;
      }

      if (botSearchActive) {
        if (!_isBotMatchMode || !_botThinking) {
          _botSearchCompleter = null;
        }
        if (multiPv <= _botSearchMultiPv) {
          _botSearchLines[multiPv] = parsedLine;
        }
        if (_shouldKeepEvalActive && multiPv == 1) {
          setState(() {
            _currentDepth = depth;
            _currentEval = normalizedEval;
            _evalWhiteTurn = _isWhiteTurn;
          });
        }
        if (multiPv == 1) {
          final pending = _pendingMoveQualityGrading;
          if (pending != null) {
            _pendingMoveQualityGrading = null;
            _scheduleMoveQualityGrading(
              pending,
              livePostMoveLine: parsedLine,
              livePostMoveWhiteToMove: _isWhiteTurn,
            );
          }
        }
        if (_botSearchCompleter != null) {
          return;
        }
      }

      setState(() {
        if (_shouldKeepEvalActive) {
          _currentDepth = depth;
          if (multiPv == 1) {
            _currentEval = normalizedEval;
            _evalWhiteTurn = _isWhiteTurn;
          }
        }
        _analysisLines.removeWhere(
          (e) => e.multiPv == multiPv || e.multiPv > analysisMultiPvCount,
        );
        _analysisLines.add(parsedLine);
        _analysisLines.sort((a, b) => a.multiPv.compareTo(b.multiPv));
        if (shouldShowVisualSuggestions) {
          _topLines.removeWhere(
            (e) =>
                e.multiPv == multiPv || e.multiPv > _visualSuggestionLineCount,
          );
          if (multiPv <= _visualSuggestionLineCount) {
            _topLines.add(parsedLine);
            _topLines.sort((a, b) => a.multiPv.compareTo(b.multiPv));
          }
        } else if (_topLines.isNotEmpty && multiPv == 1) {
          _topLines = [];
        }
      });

      if (multiPv == 1) {
        final pending = _pendingMoveQualityGrading;
        if (pending != null) {
          _pendingMoveQualityGrading = null;
          _scheduleMoveQualityGrading(
            pending,
            livePostMoveLine: parsedLine,
            livePostMoveWhiteToMove: _isWhiteTurn,
          );
        }
      }
    }
  }

