  String _endMatchCardTitle(GameOutcome outcome) {
    if (outcome == GameOutcome.draw) {
      if (_isRemoteFriendMatchMode) {
        return _remoteFriendOutcomeTitle(outcome);
      }
      return _drawOutcomePersistentTitle(_gameDrawReason);
    }
    if (_isRemoteFriendMatchMode) {
      return _remoteFriendOutcomeTitle(outcome);
    }
    if (_isTimedLocalFriendFinish) {
      return _localFriendTimeoutTitle(outcome);
    }
    if (_isBotMatchMode) {
      return _isWinningOutcomeForPov ? 'VICTORY' : 'DEFEAT';
    }
    return 'CHECKMATE';
  }

  String _endMatchCardSubtitle(GameOutcome outcome) {
    if (outcome == GameOutcome.draw) {
      if (_isRemoteFriendMatchMode) {
        return _remoteFriendOutcomeSubtitle(outcome);
      }
      return _drawOutcomeRevealSubtitle(_gameDrawReason);
    }
    if (_isRemoteFriendMatchMode) {
      return _remoteFriendOutcomeSubtitle(outcome);
    }
    if (_isTimedLocalFriendFinish) {
      return _localFriendTimeoutSubtitle(outcome);
    }
    if (_isBotMatchMode) {
      return _isWinningOutcomeForPov
          ? 'Checkmate lands. The result is locked in.'
          : 'Checkmate lands. The position is finished.';
    }
    return 'The mating net is fixed on the board.';
  }

  String? _findCurrentKingSquare(bool whiteKing) {
    final king = whiteKing ? 'k_w' : 'k_b';
    for (final entry in boardState.entries) {
      if (entry.value == king) {
        return entry.key;
      }
    }
    return null;
  }

  bool _isCheckAgainstViewer({
    required bool checkedSideIsWhite,
    bool? moverIsWhite,
  }) {
    if (_isBotMatchMode) {
      return checkedSideIsWhite == _humanPlaysWhite;
    }
    if (moverIsWhite != null) {
      return false;
    }
    return checkedSideIsWhite == !_isBlackPovActive;
  }

  _CheckedKingState? _currentCheckedKingState({bool? moverIsWhite}) {
    final states = <_CheckedKingState>[];
    final whiteKingSquare = _findCurrentKingSquare(true);
    if (whiteKingSquare != null && _isKingAttacked(boardState, true)) {
      states.add(
        _CheckedKingState(
          square: whiteKingSquare,
          isWhite: true,
          againstViewer: _isCheckAgainstViewer(
            checkedSideIsWhite: true,
            moverIsWhite: moverIsWhite,
          ),
        ),
      );
    }
    final blackKingSquare = _findCurrentKingSquare(false);
    if (blackKingSquare != null && _isKingAttacked(boardState, false)) {
      states.add(
        _CheckedKingState(
          square: blackKingSquare,
          isWhite: false,
          againstViewer: _isCheckAgainstViewer(
            checkedSideIsWhite: false,
            moverIsWhite: moverIsWhite,
          ),
        ),
      );
    }
    if (states.isEmpty) {
      return null;
    }
    if (states.length == 1) {
      return states.first;
    }
    return states.firstWhere(
      (state) => state.againstViewer,
      orElse: () => states.first,
    );
  }

  Set<String> _currentCheckedKingSquares() {
    final squares = <String>{};
    final whiteKingSquare = _findCurrentKingSquare(true);
    if (whiteKingSquare != null && _isKingAttacked(boardState, true)) {
      squares.add(whiteKingSquare);
    }
    final blackKingSquare = _findCurrentKingSquare(false);
    if (blackKingSquare != null && _isKingAttacked(boardState, false)) {
      squares.add(blackKingSquare);
    }
    return squares;
  }

  _DetectedGameOutcome? _detectCurrentGameOutcome() {
    final whiteKingPresent = boardState.values.contains('k_w');
    final blackKingPresent = boardState.values.contains('k_b');
    if (!whiteKingPresent && !blackKingPresent) {
      return const _DetectedGameOutcome(GameOutcome.draw);
    }
    if (!whiteKingPresent) {
      return const _DetectedGameOutcome(GameOutcome.blackWin);
    }
    if (!blackKingPresent) {
      return const _DetectedGameOutcome(GameOutcome.whiteWin);
    }

    if (!_sideToMoveHasLegalMoves()) {
      if (_isKingAttacked(boardState, _isWhiteTurn)) {
        return _DetectedGameOutcome(
          _isWhiteTurn ? GameOutcome.blackWin : GameOutcome.whiteWin,
        );
      }
      return const _DetectedGameOutcome.draw(DrawReason.stalemate);
    }

    if (_hasInsufficientMaterial()) {
      return const _DetectedGameOutcome.draw(DrawReason.insufficientMaterial);
    }

    if (_currentPositionOccurrenceCount() >= 3) {
      return const _DetectedGameOutcome.draw(DrawReason.threefoldRepetition);
    }

    if (_halfmoveClock >= 100) {
      return const _DetectedGameOutcome.draw(DrawReason.fiftyMoveRule);
    }

    return null;
  }

  Color _displayEvalColor(double eval) {
    final clamped = eval.clamp(-2.0, 2.0);
    const deepYellow = Color(0xFFD8B640);
    const deepLime = Color(0xFF8CBF3F);
    const deepGreen = Color(0xFF33A85C);
    const deepEmerald = Color(0xFF13935A);
    const deepOrange = Color(0xFFC96F3D);
    const deepRed = Color(0xFFB44747);

    // Keep true yellow in the neutral window, then transition smoothly outward.
    if (clamped >= -0.20 && clamped <= 0.20) {
      return deepYellow;
    }

    if (clamped > 0.20 && clamped <= 0.35) {
      final t = ((clamped - 0.20) / 0.15).clamp(0.0, 1.0);
      return Color.lerp(deepYellow, deepLime, t) ?? deepLime;
    }

    if (clamped > 0.35 && clamped <= 1.0) {
      final t = ((clamped - 0.35) / 0.65).clamp(0.0, 1.0);
      return Color.lerp(deepLime, deepGreen, t) ?? deepGreen;
    }

    if (clamped > 1.0) {
      final t = ((clamped - 1.0) / 1.0).clamp(0.0, 1.0);
      return Color.lerp(deepGreen, deepEmerald, t) ?? deepEmerald;
    }

    if (clamped < -0.20 && clamped >= -0.80) {
      final t = ((clamped + 0.80) / 0.60).clamp(0.0, 1.0);
      return Color.lerp(deepOrange, deepYellow, t) ?? deepYellow;
    }

    final t = ((clamped + 2.0) / 1.20).clamp(0.0, 1.0);
    return Color.lerp(deepRed, deepOrange, t) ?? deepRed;
  }

