  void _flashOpeningButtonUnavailable({String? logMessage}) {
    _openingModeFeedbackTimer?.cancel();
    if (logMessage != null && logMessage.isNotEmpty) {
      _addLog(logMessage);
    }
    setState(() {
      _openingButtonFlashRed = true;
      _openingMode = OpeningMode.off;
      _openingModeFeedbackLabel = null;
      _openingModeFeedbackColor = null;
    });
    _openingButtonFlashController.forward(from: 0).then((_) {
      if (!mounted) return;
      setState(() {
        _openingButtonFlashRed = false;
      });
    });
  }

  Set<String> _sourceSquaresWithRegisteredOpenings({bool gambitsOnly = false}) {
    if (!_isCurrentPositionOnOpeningPrefix()) {
      return const <String>{};
    }
    final availableSources = <String>{};
    for (final entry in boardState.entries) {
      final square = entry.key;
      final piece = entry.value;
      if (!_isCurrentTurnPiece(piece)) {
        continue;
      }
      final legalTargets = _legalMovesFrom(square);
      if (legalTargets.isEmpty) {
        continue;
      }
      if (_targetsWithRegisteredGambits(
        square,
        legalTargets,
        gambitsOnly: gambitsOnly,
      ).isNotEmpty) {
        availableSources.add(square);
      }
    }
    return availableSources;
  }

  bool _isCurrentPositionOnOpeningPrefix() {
    if (_moveHistory.isEmpty) {
      return true;
    }
    return matchesRegisteredOpeningPrefix(
      _ecoLines,
      _openingMoveTokensThrough(_moveHistory.length - 1),
    );
  }

  String? _openingModeFeedbackLabelFor(OpeningMode mode) {
    return switch (mode) {
      OpeningMode.yellowGlow => 'select',
      OpeningMode.blueGlow => 'possible',
      OpeningMode.violetGlow => 'gambit',
      OpeningMode.sacrificeGlow => 'sacrifice',
      OpeningMode.off => null,
    };
  }

  void _scheduleOpeningModeFeedbackDismiss() {
    _openingModeFeedbackTimer?.cancel();
    _openingModeFeedbackTimer = Timer(const Duration(milliseconds: 1400), () {
      if (!mounted) return;
      setState(() {
        _openingModeFeedbackLabel = null;
        _openingModeFeedbackColor = null;
      });
    });
  }

  void _toggleGambitMode() {
    final targetMode = _analysisOpeningButtonMode;
    final hasOpeningChoices = _sourceSquaresWithRegisteredOpenings(
      gambitsOnly: false,
    ).isNotEmpty;
    String? feedbackLabel;
    Color? feedbackColor;
    bool refreshAnalysis = false;
    if (targetMode != OpeningMode.sacrificeGlow && !hasOpeningChoices) {
      _flashOpeningButtonUnavailable(
        logMessage:
            'Opening mode unavailable: no registered opening continuations remain from this position.',
      );
      return;
    }

    if (targetMode == OpeningMode.sacrificeGlow && !_sacrificeModeOwned) {
      setState(() {
        _openingMode = OpeningMode.off;
        _clearOpeningModeTransientState();
        feedbackLabel = _openingModeFeedbackLabelFor(OpeningMode.sacrificeGlow);
        feedbackColor = _openingModeButtonColor(OpeningMode.sacrificeGlow);
        _openingModeFeedbackLabel = feedbackLabel;
        _openingModeFeedbackColor = feedbackColor;
      });
      _addLog(
        'Sacrifice mode locked - unlock it in the store for $_sacrificeModePrice coins.',
      );
      if (feedbackLabel != null && feedbackColor != null) {
        _scheduleOpeningModeFeedbackDismiss();
      }
      unawaited(_openStore(initialSection: StoreSection.general));
      return;
    }

    final currentMode = _openingMode;
    final nextMode = currentMode == targetMode ? OpeningMode.off : targetMode;
    refreshAnalysis =
        currentMode == OpeningMode.sacrificeGlow ||
        nextMode == OpeningMode.sacrificeGlow;

    setState(() {
      _openingMode = nextMode;
      _clearOpeningModeTransientState();

      if (nextMode == OpeningMode.yellowGlow) {
        _primeOpeningSelectionFromHeldPiece();
        _addLog('Opening button mode enabled - select opening');
      } else if (nextMode == OpeningMode.blueGlow) {
        _addLog('Opening button mode enabled - showing all possible openings');
      } else if (nextMode == OpeningMode.violetGlow) {
        _primeOpeningSelectionFromHeldPiece();
        _addLog('Opening button mode enabled - possible gambits only');
      } else if (nextMode == OpeningMode.sacrificeGlow) {
        _addLog('Opening button mode enabled - red sacrifice scan');
      } else {
        _addLog(switch (targetMode) {
          OpeningMode.yellowGlow => 'Select opening mode turned off',
          OpeningMode.blueGlow => 'Possible openings mode turned off',
          OpeningMode.violetGlow => 'Possible gambits mode turned off',
          OpeningMode.sacrificeGlow => 'Sacrifice mode turned off',
          OpeningMode.off => 'Opening button mode turned off',
        });
      }

      final feedbackMode = nextMode == OpeningMode.off ? targetMode : nextMode;
      feedbackLabel = _openingModeFeedbackLabelFor(feedbackMode);
      feedbackColor = _openingModeButtonColor(feedbackMode);
      _openingModeFeedbackLabel = feedbackLabel;
      _openingModeFeedbackColor = feedbackColor;
    });

    if (feedbackLabel != null && feedbackColor != null) {
      _scheduleOpeningModeFeedbackDismiss();
    }
    if (nextMode == OpeningMode.blueGlow) {
      _showAllPossibleOpenings();
    }
    if (refreshAnalysis) {
      _refreshAnalysisForCurrentPosition();
    }
  }

  Future<void> _showGameResultDialog(GameOutcome outcome);

  List<EcoLine> _allPossibleOpeningsFromCurrentPosition() {
    final currentMoves = _currentMoveSequence();
    final allOpenings = <String, EcoLine>{};

    for (final line in _ecoLines) {
      final normalizedMoves = line.normalizedMoves.trim().toLowerCase();
      final currentMovesLower = currentMoves.isEmpty ? '' : '$currentMoves ';

      if (currentMoves.isEmpty) {
        allOpenings.putIfAbsent(line.name, () => line);
      } else if (normalizedMoves.startsWith(currentMovesLower.trim()) &&
          normalizedMoves.length > currentMovesLower.trim().length) {
        allOpenings.putIfAbsent(line.name, () => line);
      }
    }

    final openingsList = allOpenings.values.toList();
    openingsList.sort((a, b) {
      final cmp = a.name.compareTo(b.name);
      if (cmp != 0) return cmp;
      return a.moveTokens.length.compareTo(b.moveTokens.length);
    });
    return openingsList;
  }

  String _normalizedOpeningSearchText(String value) {
    return value.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), ' ').trim();
  }

  bool _openingNameMatchesSearchQuery(String openingName, String rawQuery) {
    final normalizedName = _normalizedOpeningSearchText(openingName);
    final normalizedQuery = _normalizedOpeningSearchText(rawQuery);
    if (normalizedQuery.isEmpty) {
      return true;
    }
    if (normalizedName.contains(normalizedQuery)) {
      return true;
    }

    final nameTokens = normalizedName
        .split(RegExp(r'\s+'))
        .where((token) => token.isNotEmpty)
        .toList(growable: false);
    final queryTokens = normalizedQuery
        .split(RegExp(r'\s+'))
        .where((token) => token.isNotEmpty)
        .toList(growable: false);

    if (queryTokens.isEmpty) {
      return true;
    }

    for (final queryToken in queryTokens) {
      final matched = nameTokens.any(
        (nameToken) => nameToken.contains(queryToken),
      );
      if (!matched) {
        return false;
      }
    }
    return true;
  }

