  void _resetSpecialMoveState() {
    _whiteKingMoved = false;
    _blackKingMoved = false;
    _whiteKingsideRookMoved = false;
    _whiteQueensideRookMoved = false;
    _blackKingsideRookMoved = false;
    _blackQueensideRookMoved = false;
    _enPassantTarget = null;
  }

  void _restoreSpecialMoveStateFromRecord(MoveRecord? move) {
    if (move == null) {
      _resetSpecialMoveState();
      return;
    }
    _whiteKingMoved = move.whiteKingMoved;
    _blackKingMoved = move.blackKingMoved;
    _whiteKingsideRookMoved = move.whiteKingsideRookMoved;
    _whiteQueensideRookMoved = move.whiteQueensideRookMoved;
    _blackKingsideRookMoved = move.blackKingsideRookMoved;
    _blackQueensideRookMoved = move.blackQueensideRookMoved;
    _enPassantTarget = move.enPassantTarget;
  }

  void _resetVsBotSessionState() {
    _selectedBot = null;
    _botThinking = false;
    _vsBotSessionWins = 0;
    _vsBotSessionLosses = 0;
    _vsBotSessionDraws = 0;
  }

  void _applyAnalysisModeSectionState(
    AppSection section, {
    bool clearOutcome = true,
    bool clearBotGhostArrows = false,
    bool resetQuizLaunch = true,
    bool resetBotSideChoice = false,
  }) {
    _matchMode = MatchMode.analysis;
    _resetVsBotSessionState();
    _resetRemoteFriendSessionState();
    if (clearOutcome) {
      _clearGameOutcomeState();
    }
    if (clearBotGhostArrows) {
      _clearBotGhostArrows();
    }
    if (resetQuizLaunch) {
      _quizLaunchedFromAcademy = false;
    }
    if (resetBotSideChoice) {
      _botSideChoice = BotSideChoice.random;
    }
    _activeSection = section;
  }

  void _prepareAnalysisMatchEntry(MatchMode matchMode) {
    _activeSection = AppSection.analysis;
    _matchMode = matchMode;
    _analysisEditMode = false;
    if (matchMode != MatchMode.remoteFriend) {
      _resetRemoteFriendSessionState();
    }
  }

  void _openPuzzleAcademyFromMenu() {
    setState(() {
      _applyAnalysisModeSectionState(AppSection.puzzleAcademy);
    });
  }

  void _openVsModeFromMenu() {
    setState(() {
      _applyAnalysisModeSectionState(AppSection.vsMode);
      _selectedVsModeQuickOption = null;
      _vsModeScrollOffset = 0;
      _vsModeLocalTimeControlExpanded = false;
      _vsModeRemoteTimeControlExpanded = false;
      _vsModeRemoteSeatPreferenceExpanded = false;
