  bool get _hasBotAvatarIntroArrived {
    if (!_isBotMatchMode || _introCompleted) {
      return true;
    }
    return _introController.value >= _botAvatarIntroArrivalProgress;
  }

  Duration _remainingBotAvatarIntroDelay() {
    if (_hasBotAvatarIntroArrived) {
      return Duration.zero;
    }
    final duration = _introController.duration;
    if (duration == null) {
      return Duration.zero;
    }
    final remainingProgress =
        (_botAvatarIntroArrivalProgress -
                _introController.value.clamp(0.0, 1.0))
            .clamp(0.0, 1.0);
    return Duration(
      microseconds: (duration.inMicroseconds * remainingProgress).round(),
    );
  }

  void _clearVsBotOverlayState() {
    _clearCheckAlertState();
    _clearSquareToastState();
  }

  Offset? _squareCenterInScene(String square) {
    final boardContext = _boardKey.currentContext;
    final sceneContext = _sceneKey.currentContext;
    if (boardContext == null || sceneContext == null) return null;

    final boardBox = _renderBoxFromContext(boardContext);
    final sceneBox = _renderBoxFromContext(sceneContext);
    if (boardBox == null || sceneBox == null) return null;

    final boardTopLeft = sceneBox.globalToLocal(
      boardBox.localToGlobal(Offset.zero),
    );
    final size = boardBox.size;
    const inset = 2.0;
    final sq = (size.width - inset * 2) / 8;

    var col = square.codeUnitAt(0) - 97;
    var row = int.parse(square[1]) - 1;
    final reverse = _isBotMatchMode
        ? !_humanPlaysWhite
        : (_perspective == BoardPerspective.black) ||
              (_usesTurnAwarePerspective && !_isWhiteTurn);
    if (reverse) {
      col = 7 - col;
    } else {
      row = 7 - row;
    }

    return boardTopLeft +
        Offset(inset + col * sq + sq / 2, inset + row * sq + sq / 2);
  }

  List<String> _launchSquaresForSuggestionCount(int count) {
    const preferred = <String>[
      'e2',
      'd2',
      'g1',
      'c2',
      'b1',
      'g2',
      'b2',
      'a2',
      'f2',
      'h2',
    ];
    final safeCount = count.clamp(1, 8);
    return preferred.take(safeCount).toList();
  }

  String? _extraLaunchSquareForSuggestionCount(int count) {
    if (count >= 9) {
      return 'e2';
    }
    return null;
  }

  String? _secondExtraLaunchSquareForSuggestionCount(int count) {
    if (count >= 10) {
      return 'c2';
    }
    return null;
  }

  Future<void> _fireSuggestionLaunch() async {
    final completer = Completer<void>();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      final buttonContext = _suggestionButtonKey.currentContext;
      final sceneContext = _sceneKey.currentContext;
      if (buttonContext == null || sceneContext == null) {
        if (!completer.isCompleted) completer.complete();
        return;
      }

      final buttonBox = _renderBoxFromContext(buttonContext);
      final sceneBox = _renderBoxFromContext(sceneContext);
      if (buttonBox == null || sceneBox == null) {
        if (!completer.isCompleted) completer.complete();
        return;
      }

      final buttonCenter = _suggestionButtonCenterInScene();
      if (buttonCenter == null) {
        if (!completer.isCompleted) completer.complete();
        return;
      }
      final squares = _launchSquaresForSuggestionCount(_multiPvCount);
      final targets = squares
          .map(_squareCenterInScene)
          .whereType<Offset>()
          .toList();
      final extraSquare = _extraLaunchSquareForSuggestionCount(_multiPvCount);
      final extraTarget = extraSquare == null
          ? null
          : _squareCenterInScene(extraSquare);
      final extraTargets = extraSquare == null
          ? <Offset>[]
          : <Offset>[extraTarget!];
      final secondExtraSquare = _secondExtraLaunchSquareForSuggestionCount(
        _multiPvCount,
      );
      final secondExtraTarget = secondExtraSquare == null
          ? null
          : _squareCenterInScene(secondExtraSquare);
      final secondExtraTargets = secondExtraSquare == null
          ? <Offset>[]
          : <Offset>[secondExtraTarget!];
      if (targets.isEmpty &&
          extraTargets.isEmpty &&
          secondExtraTargets.isEmpty) {
        if (!completer.isCompleted) completer.complete();
        return;
      }

      final pending = <Future<void>>[];

      if (targets.isNotEmpty) {
        setState(() {
          _launchStart = buttonCenter;
          _launchTargets = targets;
          _launchTargetsEvalBar = false;
        });

        pending.add(
          _launchController.forward(from: 0).whenComplete(() {
            if (!mounted) return;
            setState(() {
              _launchStart = null;
              _launchTargets = <Offset>[];
              _launchTargetsEvalBar = false;
            });
          }),
        );
      }

      if (extraTargets.isNotEmpty) {
        pending.add(_fireExtraSuggestionLaunch(buttonCenter, extraTargets));
      }

      if (secondExtraTargets.isNotEmpty) {
        pending.add(
          _fireSecondExtraSuggestionLaunch(buttonCenter, secondExtraTargets),
        );
      }

      Future.wait(pending).whenComplete(() {
        if (!completer.isCompleted) completer.complete();
      });
    });
    await completer.future;
  }

  Future<void> _fireExtraSuggestionLaunch(
    Offset start,
    List<Offset> targets,
  ) async {
    await Future<void>.delayed(_extraSuggestionLaunchDelay);
    if (!mounted || targets.isEmpty) {
      return;
    }

    _extraLaunchController.reset();
    setState(() {
      _extraLaunchStart = start;
      _extraLaunchTargets = targets;
    });

    await _extraLaunchController.forward();
    if (!mounted) {
      return;
    }

    setState(() {
      _extraLaunchStart = null;
      _extraLaunchTargets = <Offset>[];
    });
  }

  Future<void> _fireSecondExtraSuggestionLaunch(
    Offset start,
    List<Offset> targets,
  ) async {
    await Future<void>.delayed(_secondExtraSuggestionLaunchDelay);
    if (!mounted || targets.isEmpty) {
      return;
    }

    _secondExtraLaunchController.reset();
    setState(() {
      _secondExtraLaunchStart = start;
      _secondExtraLaunchTargets = targets;
    });

    await _secondExtraLaunchController.forward();
    if (!mounted) {
      return;
    }

    setState(() {
      _secondExtraLaunchStart = null;
      _secondExtraLaunchTargets = <Offset>[];
    });
  }

  Widget _buildSuggestionLaunchOverlay() {
    if (_launchStart == null || _launchTargets.isEmpty) {
      return const SizedBox.shrink();
    }

    return AnimatedBuilder(
      animation: _launchController,
      builder: (context, child) {
        final rawT = _launchController.value;
        final t = Curves.easeInOutCubic.transform(rawT);
        final start = _launchStart!;

        if (_launchTargetsEvalBar) {
          final end = _launchTargets.first;
          final pulseT = ((t - 0.66) / 0.34).clamp(0.0, 1.0);
          final pulseRadius = 10 + (20 * pulseT);
          final pulseAlpha = (1.0 - pulseT) * 0.70;

          return IgnorePointer(
            child: Stack(
              children: [
                if (pulseT > 0)
                  Positioned(
                    left: end.dx - pulseRadius,
                    top: end.dy - pulseRadius,
                    child: Container(
                      width: pulseRadius * 2,
                      height: pulseRadius * 2,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        border: Border.all(
                          color: const ui.Color.fromARGB(
                            255,
                            66,
                            65,
                            65,
                          ).withValues(alpha: pulseAlpha),
                          width: 1.8,
                        ),
                        boxShadow: [
                          BoxShadow(
                            color: const ui.Color.fromARGB(
                              255,
                              252,
                              252,
                              252,
                            ).withValues(alpha: pulseAlpha * 0.55),
                            blurRadius: 12,
                            spreadRadius: 1,
                          ),
                        ],
                      ),
                    ),
                  ),
                for (int i = 5; i >= 0; i--)
                  Builder(
                    builder: (context) {
                      final delayedT = (t - (i * 0.07)).clamp(0.0, 1.0);
                      if (delayedT <= 0) {
                        return const SizedBox.shrink();
                      }

                      final position = _launchWavePoint(start, end, delayedT);
                      final size = ui.lerpDouble(6.0, 15.0, 1 - (i / 5))!;
                      final color = i.isEven
                          ? const ui.Color.fromARGB(255, 51, 51, 51)
                          : const ui.Color.fromARGB(255, 255, 255, 255);
                      final alpha = (0.24 + ((5 - i) * 0.12)).clamp(0.0, 0.85);

                      return Positioned(
                        left: position.dx - (size / 2),
                        top: position.dy - (size / 2),
                        child: Container(
                          width: size,
                          height: size,
                          decoration: BoxDecoration(
                            shape: BoxShape.circle,
                            color: color.withValues(alpha: alpha),
                            boxShadow: [
                              BoxShadow(
                                color: color.withValues(alpha: alpha),
                                blurRadius: 8 + ((5 - i) * 1.5),
                                spreadRadius: i == 0 ? 1.2 : 0.0,
                              ),
                            ],
                          ),
                        ),
                      );
                    },
                  ),
              ],
            ),
          );
        }
        final launchDurationMs =
            _launchController.duration?.inMilliseconds ?? 650;
        final safeLaunchDurationMs = launchDurationMs <= 0
            ? 1
            : launchDurationMs;

        return IgnorePointer(
          child: Stack(
            children: [
              for (int index = 0; index < _launchTargets.length; index++)
                Builder(
                  builder: (context) {
                    final delayFraction = (index * 20) / safeLaunchDurationMs;
                    if (rawT < delayFraction) {
                      return const SizedBox.shrink();
                    }

                    final launchT = Curves.easeInOutCubic.transform(
                      ((rawT - delayFraction) / (1.0 - delayFraction)).clamp(
                        0.0,
                        1.0,
                      ),
                    );
                    final rippleT = ((launchT - 0.82) / 0.18).clamp(0.0, 1.0);
                    final rippleRadius = 8 + (24 * rippleT);
                    final rippleAlpha = (1.0 - rippleT) * 0.75;
                    final end = _launchTargets[index];
                    final x = ui.lerpDouble(start.dx, end.dx, launchT)!;
                    final arcHeight = 26 + (8 * (index % 3));
                    final sideBias =
                        (index - ((_launchTargets.length - 1) / 2)) * 6.0;
                    final y =
                        ui.lerpDouble(start.dy, end.dy, launchT)! -
                        sin(launchT * pi) * arcHeight;
                    final glow =
                        4 + (5 * (1 - (launchT - 0.7).abs().clamp(0.0, 0.7)));
                    return Stack(
                      children: [
                        if (rippleT > 0)
                          Positioned(
                            left: end.dx - rippleRadius,
                            top: end.dy - rippleRadius,
                            child: Container(
                              width: rippleRadius * 2,
                              height: rippleRadius * 2,
                              decoration: BoxDecoration(
                                shape: BoxShape.circle,
                                border: Border.all(
                                  color: const Color(
                                    0xFF7EDC8A,
                                  ).withValues(alpha: rippleAlpha),
                                  width: 2,
                                ),
                              ),
                            ),
                          ),
                        Positioned(
                          left: x - 4 + sideBias * (1 - launchT),
                          top: y - 4,
                          child: Container(
                            width: 8,
                            height: 8,
                            decoration: BoxDecoration(
                              shape: BoxShape.circle,
                              color: const Color(0xFF7EDC8A),
                              boxShadow: [
                                BoxShadow(
                                  color: const Color(
                                    0xFF7EDC8A,
                                  ).withValues(alpha: 0.85),
                                  blurRadius: glow,
                                  spreadRadius: 1,
                                ),
                              ],
                            ),
                          ),
                        ),
                      ],
                    );
                  },
                ),
            ],
          ),
        );
      },
    );
  }

  Widget _buildExtraSuggestionLaunchOverlay() {
    return _buildDelayedSuggestionLaunchOverlay(
      controller: _extraLaunchController,
      start: _extraLaunchStart,
      targets: _extraLaunchTargets,
    );
  }

  Widget _buildSecondExtraSuggestionLaunchOverlay() {
    return _buildDelayedSuggestionLaunchOverlay(
      controller: _secondExtraLaunchController,
      start: _secondExtraLaunchStart,
      targets: _secondExtraLaunchTargets,
    );
  }

  Widget _buildDelayedSuggestionLaunchOverlay({
    required AnimationController controller,
    required Offset? start,
    required List<Offset> targets,
  }) {
    if (start == null || targets.isEmpty) {
      return const SizedBox.shrink();
    }

    return AnimatedBuilder(
      animation: controller,
      builder: (context, child) {
        final t = Curves.easeInOutCubic.transform(controller.value);
        final rippleT = ((t - 0.82) / 0.18).clamp(0.0, 1.0);
        final rippleRadius = 8 + (24 * rippleT);
        final rippleAlpha = (1.0 - rippleT) * 0.75;

        return IgnorePointer(
          child: Stack(
            children: [
              for (int index = 0; index < targets.length; index++) ...[
                if (rippleT > 0)
                  Positioned(
                    left: targets[index].dx - rippleRadius,
                    top: targets[index].dy - rippleRadius,
                    child: Container(
                      width: rippleRadius * 2,
                      height: rippleRadius * 2,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        border: Border.all(
                          color: const Color(
                            0xFF7EDC8A,
                          ).withValues(alpha: rippleAlpha),
                          width: 2,
                        ),
                      ),
                    ),
                  ),
                Builder(
                  builder: (context) {
                    final end = targets[index];
                    final x = ui.lerpDouble(start.dx, end.dx, t)!;
                    final arcHeight = 26 + (8 * (index % 3));
                    final sideBias = (index - ((targets.length - 1) / 2)) * 6.0;
                    final y =
                        ui.lerpDouble(start.dy, end.dy, t)! -
                        sin(t * pi) * arcHeight;
                    final glow =
                        4 + (5 * (1 - (t - 0.7).abs().clamp(0.0, 0.7)));
                    return Positioned(
                      left: x - 4 + sideBias * (1 - t),
                      top: y - 4,
                      child: Container(
                        width: 8,
                        height: 8,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          color: const Color(0xFF7EDC8A),
                          boxShadow: [
                            BoxShadow(
                              color: const Color(
                                0xFF7EDC8A,
                              ).withValues(alpha: 0.85),
                              blurRadius: glow,
                              spreadRadius: 1,
                            ),
                          ],
                        ),
                      ),
                    );
                  },
                ),
              ],
            ],
          ),
        );
      },
    );
  }

  Widget _buildButtonRippleOverlay() {
    if (_buttonRippleCenter == null) return const SizedBox.shrink();
    return AnimatedBuilder(
      animation: _buttonRippleController,
      builder: (context, child) {
        final t = Curves.easeOut.transform(_buttonRippleController.value);
        return IgnorePointer(
          child: Stack(
            children: [
              for (int i = 0; i < 3; i++)
                Builder(
                  builder: (context) {
                    final delay = i * 0.22;
                    final rt = ((t - delay) / (1.0 - delay)).clamp(0.0, 1.0);
                    final radius = 16 + (54 * rt);
                    final alpha = (1.0 - rt) * 0.28;
                    return Positioned(
                      left: _buttonRippleCenter!.dx - radius,
                      top: _buttonRippleCenter!.dy - radius,
                      child: Container(
                        width: radius * 2,
                        height: radius * 2,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          border: Border.all(
                            color: const Color(
                              0xFF7EDC8A,
                            ).withValues(alpha: alpha),
                            width: 1.5,
                          ),
                        ),
                      ),
                    );
                  },
                ),
            ],
          ),
        );
      },
    );
  }

  String _menuLogoAsset(BuildContext context) {
    return Theme.of(context).brightness == Brightness.light
        ? 'assets/logo2.png'
        : 'assets/logo.png';
