  Widget _buildVsModeScreen() {
    final media = MediaQuery.of(context);
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final isDark = theme.brightness == Brightness.dark;
    final isLandscape = media.orientation == Orientation.landscape;
    final useMonochrome =
        context.watch<AppThemeProvider>().isMonochrome ||
        _isCinematicThemeEnabled;
    final arcade = _vsBotArcadePaletteFor(context, monochrome: useMonochrome);
    final selectedLocalFriendTimeControl = _selectedLocalFriendTimeControl;
    final selectedRemoteFriendTimeControl = _selectedRemoteFriendTimeControl;
    final remoteAccent = useMonochrome
        ? scheme.onSurface
        : Color.lerp(arcade.cyan, arcade.amber, 0.34)!;
    final heroAccent = Color.lerp(arcade.cyan, remoteAccent, 0.5)!;
    final compactWidth = media.size.width <= 390;
    final shortHeight = media.size.height <= 430;
    final chromePadding = compactWidth ? 12.0 : (isLandscape ? 16.0 : 20.0);
    final sectionGap = shortHeight ? 12.0 : 16.0;
    final collapsibleTopChrome = !isLandscape;
    final chromeCollapseT = collapsibleTopChrome
        ? Curves.easeOutCubic.transform(
            (_vsModeScrollOffset / 96.0).clamp(0.0, 1.0),
          )
        : 0.0;
    final scrollTopInset = collapsibleTopChrome
        ? ui.lerpDouble(76.0, 18.0, chromeCollapseT)!
        : 70.0;

    bool handleVsModeScroll(ScrollNotification notification) {
      if (!collapsibleTopChrome || notification.metrics.axis != Axis.vertical) {
        return false;
      }
      final nextOffset = notification.metrics.pixels.clamp(0.0, 96.0);
      if ((nextOffset - _vsModeScrollOffset).abs() < 2.0 &&
          nextOffset != 0.0 &&
          nextOffset != 96.0) {
        return false;
      }
      setState(() {
        _vsModeScrollOffset = nextOffset;
      });
      return false;
    }

    String botDifficultyLabel(BotDifficulty difficulty) {
      return switch (difficulty) {
        BotDifficulty.easy => 'Easy',
        BotDifficulty.medium => 'Medium',
        BotDifficulty.hard => 'Hard',
      };
    }

    TextStyle buildDisplayStyle({
      required Color color,
      double size = 24,
      bool glow = true,
    }) {
      return puzzleAcademyDisplayStyle(
        palette: arcade.base,
        size: size,
        color: color,
        withGlow: glow && !arcade.reducedEffects,
        letterSpacing: size >= 30 ? 0.72 : 0.56,
        height: size >= 30 ? 0.94 : 0.98,
      );
    }

    TextStyle buildHudStyle({
      required Color color,
      double size = 12.2,
      FontWeight weight = FontWeight.w700,
      bool glow = false,
      double letterSpacing = 0.68,
      double height = 1.25,
    }) {
      return puzzleAcademyHudStyle(
        palette: arcade.base,
        size: size,
        weight: weight,
        color: color,
        withGlow: glow && !arcade.reducedEffects,
        letterSpacing: letterSpacing,
        height: height,
      );
    }

    TextStyle buildBodyStyle({
      required Color color,
      double size = 12.4,
      FontWeight weight = FontWeight.w600,
    }) {
      return puzzleAcademyHudStyle(
        palette: arcade.base,
        size: size,
        weight: weight,
        color: color,
        withGlow: false,
        letterSpacing: 0.18,
        height: 1.34,
      );
    }

    Widget buildCardShell({
      required Color accent,
      required Widget child,
      VoidCallback? onTap,
      bool emphasized = false,
    }) {
      final radius = emphasized ? 24.0 : 22.0;
      final decoration = _vsBotArcadePanelDecoration(
        palette: arcade,
        accent: accent,
        radius: radius,
        borderWidth: emphasized ? 2.8 : 2.6,
        fillColor: arcade.panel,
      );
      final content = Padding(
        padding: EdgeInsets.all(compactWidth ? 14 : 16),
        child: child,
      );
      if (onTap == null) {
        return DecoratedBox(decoration: decoration, child: content);
      }
      return puzzleAcademyDecoratedInkWell(
        decoration: decoration,
        borderRadius: BorderRadius.circular(radius),
        onTap: onTap,
        overlayColor: puzzleAcademyInteractiveOverlay(
          palette: arcade.base,
          accent: accent,
        ),
        child: content,
      );
    }

    Widget buildInsetShell({
      required Color accent,
      required Widget child,
      EdgeInsetsGeometry padding = const EdgeInsets.all(12),
    }) {
      return Container(
        decoration: _vsBotArcadePanelDecoration(
          palette: arcade,
          accent: accent,
          radius: 18,
          borderWidth: 2.2,
          inset: true,
          fillColor: arcade.panelAlt,
        ),
        child: Padding(padding: padding, child: child),
      );
    }

    Widget buildTag(
      String label,
      Color accent, {
      IconData? icon,
      bool filled = false,
    }) {
      return PuzzleAcademyTag(
        label: label,
        accent: accent,
        icon: icon,
        compact: true,
        filled: filled,
        monochromeOverride: arcade.monochrome,
        foregroundColor: filled
            ? _vsBotFilledButtonForegroundColor(accent, arcade)
            : null,
      );
    }

    Widget buildSnapshotTile({
      required String label,
      required String value,
      required String detail,
      required IconData icon,
      required Color accent,
      double minWidth = 148,
      double maxWidth = 280,
    }) {
      return ConstrainedBox(
        constraints: BoxConstraints(minWidth: minWidth, maxWidth: maxWidth),
        child: buildInsetShell(
          accent: accent,
          padding: const EdgeInsets.all(12),
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Container(
                width: 34,
                height: 34,
                decoration: _vsBotArcadePanelDecoration(
                  palette: arcade,
                  accent: accent,
                  radius: 12,
                  borderWidth: 1.8,
                  inset: true,
                  elevated: false,
                  fillColor: Color.alphaBlend(
                    accent.withValues(
                      alpha: arcade.monochrome ? 0.10 : (isDark ? 0.18 : 0.14),
