    Widget buildCompactBotPanel() {
      final selectedBot = _selectedBot;
      final showDifficultyTag = selectedBot != null;
      final accent = selectedBot == null
          ? (useMonochrome ? scheme.onSurface : arcade.cyan)
          : _vsBotProfileAccent(selectedBot.profile, arcade);
      return buildCardShell(
        accent: accent,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            buildSectionTitle('CPU MATCH SETUP', accent),
            const SizedBox(height: 10),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                buildTag(
                  'BOT ${selectedBot?.name.toUpperCase() ?? 'NOT SELECTED'}',
                  accent,
                  icon: Icons.smart_toy_outlined,
                ),
                if (showDifficultyTag)
                  buildTag(
                    botDifficultyLabel(_selectedBotDifficulty).toUpperCase(),
                    _botDifficultyColor(_selectedBotDifficulty),
                    icon: Icons.bolt_rounded,
                  ),
              ],
            ),
            const SizedBox(height: 12),
            SizedBox(
              width: double.infinity,
              child: buildActionButton(
                label: selectedBot == null
                    ? 'Open Bot Selector'
                    : 'Retune Bot Match',
                icon: Icons.arrow_forward_rounded,
                onPressed: _openBotSetupFromMenu,
                accent: accent,
              ),
            ),
          ],
        ),
      );
    }

    Widget buildRemoteAccordionPanel({
      required String title,
      required String summary,
      required IconData icon,
      required Color accent,
      required bool expanded,
      required VoidCallback onToggle,
      required Widget child,
    }) {
      return AnimatedSize(
        duration: const Duration(milliseconds: 220),
        curve: Curves.easeOutCubic,
        child: Container(
          decoration: _vsBotArcadePanelDecoration(
            palette: arcade,
            accent: accent,
            radius: 18,
            borderWidth: expanded ? 2.4 : 2.0,
            inset: true,
            elevated: false,
            fillColor: arcade.panelAlt,
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Material(
                color: Colors.transparent,
                child: InkWell(
                  borderRadius: BorderRadius.circular(18),
                  onTap: onToggle,
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(12, 12, 12, 12),
                    child: Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Container(
                          width: 36,
                          height: 36,
                          decoration: _vsBotArcadePanelDecoration(
                            palette: arcade,
                            accent: accent,
                            radius: 12,
                            borderWidth: 1.7,
                            inset: true,
                            elevated: false,
                            fillColor: Color.alphaBlend(
                              accent.withValues(
                                alpha: arcade.monochrome
                                    ? 0.10
                                    : (isDark ? 0.18 : 0.14),
                              ),
                              arcade.panelAlt,
                            ),
                          ),
                          child: Icon(
                            icon,
                            size: 18,
                            color: _vsBotReadableAccentColor(accent, arcade),
                          ),
                        ),
                        const SizedBox(width: 10),
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                title,
                                style: buildHudStyle(
                                  color: accent,
                                  size: 10.8,
                                  weight: FontWeight.w800,
                                  letterSpacing: 0.74,
                                  glow: !arcade.monochrome,
                                ),
                              ),
                              const SizedBox(height: 4),
                              Text(
                                summary,
                                style: buildBodyStyle(
                                  color: arcade.text,
                                  size: 11.8,
                                  weight: FontWeight.w700,
                                ),
                              ),
                            ],
                          ),
                        ),
                        const SizedBox(width: 8),
                        AnimatedRotation(
                          turns: expanded ? 0.5 : 0.0,
                          duration: const Duration(milliseconds: 200),
                          curve: Curves.easeOutCubic,
                          child: Icon(
                            Icons.expand_more_rounded,
                            color: accent,
                            size: 22,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
              if (expanded)
                Padding(
                  padding: const EdgeInsets.fromLTRB(12, 0, 12, 12),
                  child: child,
                ),
            ],
          ),
        ),
      );
    }

    Widget buildCompactLocalPanel() {
