                setState(() {
                  _vsModeRemoteTimeControlExpanded =
                      !_vsModeRemoteTimeControlExpanded;
                });
              },
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    'TIME CONTROL',
                    style: buildHudStyle(
                      color: remoteAccent,
                      size: 10.1,
                      weight: FontWeight.w800,
                      letterSpacing: 0.72,
                    ),
                  ),
                  const SizedBox(height: 8),
                  Wrap(
                    spacing: 8,
                    runSpacing: 8,
                    children: [
                      for (
