    Widget buildHeroPanel() {
      final useSingleColumnHeroCards = !isLandscape && media.size.width <= 430;
      final singleColumnHeroCardHeight = (media.size.height * 0.19)
          .clamp(152.0, 186.0)
          .toDouble();
      final heroCardAspectRatio = media.size.width >= 1100
          ? 2.95
          : media.size.width >= 800
          ? (isLandscape ? 2.75 : 2.45)
          : media.size.width >= 600
          ? (isLandscape ? 2.55 : 2.20)
          : (isLandscape ? 2.35 : 1.75);
      final heroHeadingSize = media.size.width <= 360
          ? 23.5
          : media.size.width <= 430
          ? 25.5
          : media.size.width <= 700
          ? 27.5
          : 30.0;

      Widget buildShineHeading(String text) {
        final headingStyle = buildDisplayStyle(
          color: arcade.text,
          size: heroHeadingSize,
        );
        return SizedBox(
          width: double.infinity,
          child: FittedBox(
            fit: BoxFit.scaleDown,
            alignment: Alignment.centerLeft,
            child: ShaderMask(
              blendMode: BlendMode.srcATop,
              shaderCallback: (bounds) {
                return LinearGradient(
                  begin: const Alignment(-0.9, -0.2),
                  end: const Alignment(1.0, 0.2),
                  colors: [
                    arcade.text.withValues(alpha: 0.86),
                    Colors.white.withValues(alpha: 0.98),
                    arcade.text.withValues(alpha: 0.9),
                  ],
                  stops: const [0.08, 0.46, 0.9],
                ).createShader(bounds);
              },
              child: Text(
                text,
                softWrap: false,
                maxLines: 1,
                style: headingStyle.copyWith(
                  color: Colors.white,
                  shadows: const [
                    Shadow(
                      color: Color(0xB3000000),
                      blurRadius: 8,
                      offset: Offset(0, 2),
                    ),
                  ],
                ),
              ),
            ),
          ),
        );
      }

      Widget buildModeOptionCard({
        required _VsModeQuickOption option,
        required String title,
        String? subtitle,
        required IconData icon,
        required Color accent,
        required String imageAsset,
      }) {
        final selected = _selectedVsModeQuickOption == option;
        final monochromeCardForeground = Colors.white.withValues(alpha: 0.96);
        final modeCardForeground = arcade.monochrome
            ? monochromeCardForeground
            : accent;
        final modeCardReadableAccent = arcade.monochrome
            ? monochromeCardForeground
            : _vsBotReadableAccentColor(accent, arcade);
        final modeCardSubtitleColor = Colors.white.withValues(
          alpha: arcade.monochrome ? 0.98 : 0.95,
        );
        return puzzleAcademyDecoratedInkWell(
          decoration: _vsBotArcadePanelDecoration(
            palette: arcade,
            accent: accent,
            radius: 16,
            borderWidth: selected ? 2.6 : 2.0,
            fillColor: arcade.panelAlt,
          ),
          borderRadius: BorderRadius.circular(16),
          overlayColor: puzzleAcademyInteractiveOverlay(
            palette: arcade.base,
            accent: accent,
          ),
          onTap: () {
            setState(() {
              _selectedVsModeQuickOption = selected ? null : option;
            });
          },
          child: ClipRRect(
            borderRadius: BorderRadius.circular(15),
            child: LayoutBuilder(
              builder: (context, constraints) {
                final expandedCard =
                    useSingleColumnHeroCards ||
                    constraints.maxWidth >= 260 ||
                    constraints.maxHeight >= 150;
                final compactCard =
                    !expandedCard && constraints.maxHeight < 120;
                final zoom = compactCard
                    ? 1.12
                    : expandedCard
                    ? 1.04
                    : 1.08;
                final badgeTop = expandedCard ? 10.0 : 8.0;
                final badgeRight = expandedCard ? 10.0 : 8.0;
                final contentBottom = compactCard
                    ? 8.0
                    : expandedCard
                    ? 14.0
                    : 10.0;
                final horizontalInset = expandedCard ? 14.0 : 10.0;
                final iconShellSize = expandedCard
                    ? 42.0
                    : compactCard
                    ? 32.0
                    : 34.0;
                final iconSize = expandedCard
                    ? 20.0
                    : compactCard
                    ? 17.0
                    : 18.0;
                final hasSubtitle =
                    subtitle != null && subtitle.trim().isNotEmpty;
                final rightEdgeMaskWidth = expandedCard ? 6.0 : 4.0;
                return Stack(
                  fit: StackFit.expand,
                  children: [
                    Positioned.fill(
                      child: Align(
                        alignment: Alignment.centerRight,
                        child: FractionallySizedBox(
                          widthFactor: zoom,
                          heightFactor: zoom,
                          alignment: Alignment.centerRight,
                          child: SizedBox.expand(
                            child: Image.asset(
                              imageAsset,
                              fit: BoxFit.cover,
                              alignment: Alignment.centerRight,
                              errorBuilder: (context, error, stackTrace) {
                                return DecoratedBox(
                                  decoration: BoxDecoration(
                                    gradient: LinearGradient(
                                      begin: Alignment.topLeft,
                                      end: Alignment.bottomRight,
                                      colors: [
                                        accent.withValues(alpha: 0.30),
                                        arcade.panelAlt,
                                      ],
                                    ),
                                  ),
                                );
                              },
                            ),
                          ),
                        ),
                      ),
                    ),
                    Positioned(
                      top: 0,
                      right: 0,
                      bottom: 0,
                      child: IgnorePointer(
                        child: Container(
                          width: rightEdgeMaskWidth,
                          decoration: BoxDecoration(
                            gradient: LinearGradient(
                              begin: Alignment.centerLeft,
                              end: Alignment.centerRight,
                              colors: [
                                Colors.transparent,
                                Color.alphaBlend(
                                  accent.withValues(
                                    alpha: selected ? 0.08 : 0.05,
                                  ),
                                  arcade.panelAlt.withValues(
                                    alpha: selected ? 0.94 : 0.88,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ),
                      ),
                    ),
                    Positioned.fill(
                      child: AnimatedBuilder(
                        animation: _pulseController,
                        builder: (context, child) {
                          final pulse =
                              (sin(
                                    (_pulseController.value * pi * 2) +
                                        (option.index * 0.95),
                                  ) +
                                  1) /
                              2;
                          final borderAlpha = selected
                              ? 0.78
                              : 0.34 + (pulse * 0.18);
                          final glowAlpha = selected
                              ? 0.24
                              : 0.08 + (pulse * 0.10);
                          final sweepLeft =
                              (-constraints.maxWidth * 0.22) +
                              ((constraints.maxWidth * 1.05) *
                                  ((_pulseController.value +
                                          (option.index * 0.17)) %
                                      1.0));

                          return Stack(
                            fit: StackFit.expand,
                            children: [
                              DecoratedBox(
                                decoration: BoxDecoration(
                                  borderRadius: BorderRadius.circular(15),
                                  border: Border.all(
                                    color: accent.withValues(
                                      alpha: borderAlpha,
                                    ),
                                    width: selected ? 1.9 : 1.35,
                                  ),
                                  boxShadow: [
                                    BoxShadow(
                                      color: accent.withValues(
                                        alpha: glowAlpha,
                                      ),
                                      blurRadius: selected ? 22 : 14,
                                      spreadRadius: selected ? 1.1 : 0.25,
                                    ),
                                  ],
                                ),
                              ),
                              Positioned(
                                top: 0,
                                left: sweepLeft,
                                child: IgnorePointer(
                                  child: Container(
                                    width: constraints.maxWidth * 0.34,
                                    height: 2.4,
                                    decoration: BoxDecoration(
                                      borderRadius: BorderRadius.circular(999),
                                      gradient: LinearGradient(
                                        colors: [
                                          Colors.transparent,
                                          accent.withValues(alpha: 0.0),
                                          accent.withValues(
                                            alpha: selected ? 0.92 : 0.72,
                                          ),
                                          Colors.white.withValues(
                                            alpha: selected ? 0.52 : 0.34,
                                          ),
                                          accent.withValues(alpha: 0.0),
                                          Colors.transparent,
                                        ],
                                      ),
                                      boxShadow: [
                                        BoxShadow(
                                          color: accent.withValues(alpha: 0.26),
                                          blurRadius: 10,
                                          spreadRadius: 0.5,
                                        ),
                                      ],
                                    ),
                                  ),
                                ),
                              ),
                            ],
                          );
                        },
                      ),
                    ),
                    Positioned.fill(
                      child: DecoratedBox(
                        decoration: BoxDecoration(
                          gradient: LinearGradient(
                            begin: Alignment.centerLeft,
                            end: Alignment.centerRight,
                            colors: [
                              Colors.black.withValues(
                                alpha: selected ? 0.46 : 0.42,
                              ),
                              Colors.black.withValues(
                                alpha: selected ? 0.14 : 0.10,
                              ),
                            ],
                          ),
                        ),
                      ),
                    ),
                    Positioned.fill(
                      child: DecoratedBox(
                        decoration: BoxDecoration(
                          gradient: LinearGradient(
                            begin: Alignment.topCenter,
                            end: Alignment.bottomCenter,
                            colors: [
                              accent.withValues(alpha: selected ? 0.18 : 0.12),
                              Colors.transparent,
                              Colors.black.withValues(alpha: 0.22),
                            ],
                            stops: const [0.0, 0.62, 1.0],
                          ),
                        ),
                      ),
                    ),
                    Positioned(
                      top: badgeTop,
                      right: badgeRight,
                      child: AnimatedOpacity(
                        duration: const Duration(milliseconds: 180),
                        opacity: selected ? 1 : 0,
                        child: Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 8,
                            vertical: 4,
                          ),
                          decoration: _vsBotArcadePanelDecoration(
                            palette: arcade,
                            accent: accent,
                            radius: 10,
                            borderWidth: 1.4,
                            inset: true,
                            elevated: false,
                            fillColor: Color.alphaBlend(
                              accent.withValues(alpha: 0.30),
                              Colors.black.withValues(alpha: 0.30),
                            ),
                          ),
                          child: Text(
                            'SELECTED',
                            style: buildHudStyle(
                              color: modeCardReadableAccent,
                              size: 9.2,
                              weight: FontWeight.w800,
                              letterSpacing: 0.52,
                              height: 1.0,
                            ),
                          ),
                        ),
                      ),
                    ),
                    Positioned(
                      left: horizontalInset,
                      right: horizontalInset,
                      bottom: contentBottom,
                      child: Row(
                        crossAxisAlignment: CrossAxisAlignment.end,
                        children: [
                          Container(
                            width: iconShellSize,
                            height: iconShellSize,
                            decoration: _vsBotArcadePanelDecoration(
                              palette: arcade,
                              accent: accent,
                              radius: 11,
                              borderWidth: 1.6,
                              inset: true,
                              elevated: false,
                              fillColor: Color.alphaBlend(
                                accent.withValues(
                                  alpha: selected ? 0.24 : 0.16,
                                ),
                                Colors.black.withValues(alpha: 0.42),
                              ),
                            ),
                            child: Icon(
                              icon,
                              size: iconSize,
                              color: modeCardReadableAccent,
                            ),
                          ),
                          SizedBox(width: expandedCard ? 12 : 10),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              mainAxisAlignment: MainAxisAlignment.end,
                              children: [
                                Text(
                                  title,
                                  maxLines: expandedCard ? 2 : 1,
                                  overflow: TextOverflow.ellipsis,
                                  style:
                                      buildHudStyle(
                                        color: modeCardForeground,
                                        size: expandedCard
                                            ? 12.8
                                            : compactCard
                                            ? 10.2
                                            : 10.9,
                                        weight: FontWeight.w800,
                                        letterSpacing: expandedCard
                                            ? 0.74
                                            : 0.68,
                                        height: expandedCard ? 1.06 : 1.0,
                                      ).copyWith(
                                        shadows: const [
                                          Shadow(
                                            color: Color(0xCC000000),
                                            blurRadius: 8,
                                            offset: Offset(0, 2),
                                          ),
                                        ],
                                      ),
                                ),
                                if (hasSubtitle) ...[
                                  SizedBox(height: expandedCard ? 4 : 3),
                                  Text(
                                    subtitle,
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style:
                                        buildBodyStyle(
                                          color: modeCardSubtitleColor,
                                          size: expandedCard
                                              ? 12.1
                                              : compactCard
                                              ? 10.2
                                              : 11.0,
                                          weight: FontWeight.w700,
                                        ).copyWith(
                                          shadows: const [
                                            Shadow(
                                              color: Color(0xCC000000),
                                              blurRadius: 8,
                                              offset: Offset(0, 2),
                                            ),
                                          ],
                                        ),
                                  ),
                                ],
                              ],
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                );
              },
            ),
          ),
        );
      }

      Widget buildModeDetailsPanel(_VsModeQuickOption option) {
        return switch (option) {
          _VsModeQuickOption.crossDevice => buildCompactRemotePanel(),
          _VsModeQuickOption.sharedScreen => buildCompactLocalPanel(),
          _VsModeQuickOption.vsCpu => buildCompactBotPanel(),
          _VsModeQuickOption.quickJoin => buildQuickJoinPanel(),
        };
      }

      Widget buildModeSelectionPrompt() {
        return buildCardShell(
          accent: heroAccent,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              buildSectionTitle('MATCH SETUP', heroAccent),
              const SizedBox(height: 10),
              Text(
                'Select a match type to open its setup panel. Tap the same card again to close it.',
                style: buildBodyStyle(color: arcade.textMuted, size: 11.8),
              ),
            ],
          ),
        );
      }

      Widget buildInlineModeStack({
        required _VsModeQuickOption option,
        required String title,
        String? subtitle,
        required IconData icon,
        required Color accent,
        required String imageAsset,
        double? forcedHeight,
        bool includeDetails = false,
      }) {
        final selected = _selectedVsModeQuickOption == option;
        final card = buildModeOptionCard(
          option: option,
          title: title,
          subtitle: subtitle,
          icon: icon,
          accent: accent,
          imageAsset: imageAsset,
        );
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            if (forcedHeight != null)
              SizedBox(
                width: double.infinity,
                height: forcedHeight,
                child: card,
              )
            else
              AspectRatio(aspectRatio: heroCardAspectRatio, child: card),
            if (includeDetails && selected) ...[
              const SizedBox(height: 12),
              buildModeDetailsPanel(option),
            ],
          ],
        );
      }

      Widget buildModeColumn(
        List<
          ({
            _VsModeQuickOption option,
            String title,
            String? subtitle,
            IconData icon,
            Color accent,
            String imageAsset,
          })
        >
        entries, {
        bool includeDetails = false,
      }) {
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            for (int index = 0; index < entries.length; index++) ...[
              buildInlineModeStack(
                option: entries[index].option,
                title: entries[index].title,
                subtitle: entries[index].subtitle,
                icon: entries[index].icon,
                accent: entries[index].accent,
                imageAsset: entries[index].imageAsset,
                includeDetails: includeDetails,
              ),
              if (index != entries.length - 1) const SizedBox(height: 12),
            ],
          ],
        );
      }

      final localTimeSummary =
          selectedLocalFriendTimeControl.initialTime == null
          ? 'Untimed'
          : _formatLocalFriendTimeControl(selectedLocalFriendTimeControl);
      final remoteTimeSummary = selectedRemoteFriendTimeControl.isUntimed
          ? 'Untimed Invite'
          : _formatRemoteFriendTimeControl(selectedRemoteFriendTimeControl);
      final modeCards =
          <
            ({
              _VsModeQuickOption option,
              String title,
              String? subtitle,
              IconData icon,
              Color accent,
              String imageAsset,
            })
          >[
            (
              option: _VsModeQuickOption.crossDevice,
              title: '1V1 CROSS-PLAY',
              subtitle: remoteTimeSummary,
              icon: Icons.wifi_tethering_rounded,
              accent: remoteAccent,
              imageAsset: 'assets/vs/a1.png',
            ),
            (
              option: _VsModeQuickOption.vsCpu,
              title: '1 PLAYER VS CPU',
              subtitle: null,
              icon: Icons.smart_toy_outlined,
              accent: arcade.cyan,
              imageAsset: 'assets/vs/a4.png',
            ),
            (
              option: _VsModeQuickOption.sharedScreen,
              title: '1V1 SHARED SCREEN',
              subtitle: localTimeSummary,
              icon: Icons.people_alt_outlined,
              accent: arcade.amber,
              imageAsset: 'assets/vs/a2.png',
            ),
            (
              option: _VsModeQuickOption.quickJoin,
              title: 'QUICK JOIN CODE',
              subtitle: _remoteFriendOperationInProgress
                  ? 'Working...'
                  : 'Paste invite code',
              icon: Icons.key_rounded,
              accent: heroAccent,
              imageAsset: 'assets/vs/a3.png',
            ),
          ];
      final leftColumnModeCards =
          <
            ({
              _VsModeQuickOption option,
              String title,
              String? subtitle,
              IconData icon,
              Color accent,
              String imageAsset,
            })
          >[modeCards[0], modeCards[2]];
      final rightColumnModeCards =
          <
            ({
              _VsModeQuickOption option,
              String title,
              String? subtitle,
              IconData icon,
              Color accent,
              String imageAsset,
            })
          >[modeCards[1], modeCards[3]];
      final selectedModeOption = _selectedVsModeQuickOption;
      final selectedModePanel = selectedModeOption == null
          ? buildModeSelectionPrompt()
          : buildModeDetailsPanel(selectedModeOption);
      final showDetachedModePanel =
          !useSingleColumnHeroCards && (isLandscape || media.size.width >= 860);

      return buildCardShell(
        accent: heroAccent,
        emphasized: true,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Icon(Icons.sports_esports_rounded, size: 18, color: heroAccent),
                const SizedBox(width: 8),
                Text(
                  'PLAY CHESS',
                  style: buildHudStyle(
                    color: heroAccent,
                    size: 11.0,
                    weight: FontWeight.w800,
                    letterSpacing: 0.78,
                    height: 1.0,
                  ),
                ),
                const Spacer(),
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 5,
                  ),
                  decoration: _vsBotArcadePanelDecoration(
                    palette: arcade,
                    accent: arcade.amber,
                    radius: 10,
                    borderWidth: 1.4,
                    inset: true,
                    elevated: false,
                    fillColor: Color.alphaBlend(
                      arcade.amber.withValues(
                        alpha: useMonochrome ? 0.08 : 0.16,
                      ),
                      arcade.panelAlt,
                    ),
                  ),
                  child: Text(
                    useMonochrome ? 'MONO' : 'ARCADE',
                    style: buildHudStyle(
                      color: arcade.amber,
                      size: 9.6,
                      weight: FontWeight.w800,
                      letterSpacing: 0.62,
                      height: 1.0,
                    ),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 10),
            buildShineHeading('Choose Match Type'),
            const SizedBox(height: 12),
            if (useSingleColumnHeroCards) ...[
              Column(
                children: [
                  for (int index = 0; index < modeCards.length; index++) ...[
                    buildInlineModeStack(
                      option: modeCards[index].option,
                      title: modeCards[index].title,
                      subtitle: modeCards[index].subtitle,
                      icon: modeCards[index].icon,
                      accent: modeCards[index].accent,
                      imageAsset: modeCards[index].imageAsset,
                      forcedHeight: singleColumnHeroCardHeight,
                      includeDetails: true,
                    ),
                    if (index != modeCards.length - 1)
                      const SizedBox(height: 12),
                  ],
                ],
              ),
            ] else if (showDetachedModePanel)
              LayoutBuilder(
                builder: (context, constraints) {
                  final detailsWidth = constraints.maxWidth >= 980
                      ? 360.0
                      : 320.0;
                  return Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Expanded(
                        child: Row(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Expanded(
                              child: buildModeColumn(leftColumnModeCards),
                            ),
                            const SizedBox(width: 10),
                            Expanded(
                              child: buildModeColumn(rightColumnModeCards),
                            ),
                          ],
                        ),
                      ),
                      const SizedBox(width: 12),
                      SizedBox(width: detailsWidth, child: selectedModePanel),
                    ],
                  );
                },
              )
            else
              Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Expanded(
                    child: buildModeColumn(
                      leftColumnModeCards,
                      includeDetails: true,
                    ),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: buildModeColumn(
                      rightColumnModeCards,
                      includeDetails: true,
                    ),
                  ),
                ],
              ),
          ],
        ),
      );
    }

    // ignore: unused_element
    Widget buildBotModeCard() {
      final selectedBot = _selectedBot;
      final hasSelectedBot = selectedBot != null;
      final accent = selectedBot == null
          ? (useMonochrome ? scheme.onSurface : arcade.cyan)
          : _vsBotProfileAccent(selectedBot.profile, arcade);
      final difficultyAccent = selectedBot == null
          ? arcade.amber
          : _botDifficultyColor(_selectedBotDifficulty);

      return buildCardShell(
        accent: accent,
        onTap: _openBotSetupFromMenu,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            buildCardHeader(
              label: 'BOT MATCH',
              title: 'Play vs Bot',
              subtitle:
                  selectedBot?.description ??
                  'Open the refined setup flow to choose an opponent, your side, and the match pressure before the board loads.',
              icon: Icons.smart_toy_outlined,
              accent: accent,
            ),
            const SizedBox(height: 12),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                buildTag(
                  hasSelectedBot
                      ? botDifficultyLabel(_selectedBotDifficulty).toUpperCase()
                      : 'BOT PICK',
                  hasSelectedBot ? difficultyAccent : accent,
                  icon: hasSelectedBot
                      ? Icons.bolt_rounded
                      : Icons.smart_toy_outlined,
                ),
                buildTag('SIDE PICK', arcade.amber, icon: Icons.flag_outlined),
                buildTag('QUICK SETUP', arcade.cyan, icon: Icons.tune_rounded),
              ],
            ),
            const SizedBox(height: 12),
            Wrap(
              spacing: 10,
              runSpacing: 10,
              children: [
                buildSnapshotTile(
                  label: 'BOT',
                  value: selectedBot?.name ?? 'Select Bot',
                  detail:
                      selectedBot?.description ??
                      'Choose a character profile before you launch the board.',
                  icon: Icons.smart_toy_outlined,
                  accent: accent,
                  minWidth: 170,
                ),
                buildSnapshotTile(
                  label: hasSelectedBot ? 'PRESSURE' : 'SETUP',
                  value: hasSelectedBot
                      ? botDifficultyLabel(_selectedBotDifficulty)
                      : 'Bot + Side + Difficulty',
                  detail: hasSelectedBot
                      ? 'Reopen setup any time to retune difficulty or side.'
                      : 'Choose the bot, your side, and the match pressure before launch.',
                  icon: hasSelectedBot
                      ? Icons.bolt_rounded
                      : Icons.tune_rounded,
                  accent: hasSelectedBot ? difficultyAccent : arcade.cyan,
                  minWidth: 170,
                ),
              ],
            ),
            const SizedBox(height: 12),
            SizedBox(
              width: double.infinity,
              child: buildActionButton(
                label: selectedBot == null
                    ? 'Open Bot Selector'
                    : 'Retune Bot Match',
                icon: Icons.arrow_forward_rounded,
                onPressed: _openBotSetupFromMenu,
                accent: accent,
              ),
            ),
          ],
        ),
      );
    }

    // ignore: unused_element
    Widget buildLocalModeCard() {
      final summaryLabel = selectedLocalFriendTimeControl.initialTime == null
          ? 'Untimed'
          : _formatLocalFriendTimeControl(selectedLocalFriendTimeControl);
      final timeControlPanel = buildSectionPanel(
        title: 'TIME CONTROL',
        accent: arcade.amber,
        child: Wrap(
          spacing: 8,
          runSpacing: 8,
          children: [
            for (
              int index = 0;
              index < _localFriendTimeControls.length;
              index++
            )
              buildChoiceChip(
                label: _formatLocalFriendTimeControl(
                  _localFriendTimeControls[index],
                ),
                selected: _localFriendTimeControlIndex == index,
                onSelected: (_) {
                  unawaited(_setLocalFriendTimeControlIndex(index));
                },
                accent: arcade.amber,
              ),
          ],
        ),
      );
      final summaryPanel = buildSectionPanel(
        title: 'MATCH SNAPSHOT',
        accent: arcade.amber,
        child: Wrap(
          spacing: 10,
          runSpacing: 10,
          children: [
            buildSnapshotTile(
              label: 'CLOCK',
              value: summaryLabel,
              detail: selectedLocalFriendTimeControl.initialTime == null
                  ? 'Untimed pass-and-play on a single board.'
                  : 'Both players share one device with the same start time.',
              icon: Icons.timer_outlined,
              accent: arcade.amber,
              minWidth: 170,
              maxWidth: 240,
            ),
            buildSnapshotTile(
              label: 'BOARD',
              value: 'Fixed Orientation',
              detail:
                  'The board stays anchored for both players across the table.',
              icon: Icons.stay_current_portrait_rounded,
              accent: arcade.amber,
              minWidth: 170,
              maxWidth: 240,
            ),
          ],
        ),
      );

      return buildCardShell(
        accent: arcade.amber,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            buildCardHeader(
              label: 'LOCAL MATCH',
              title: '1v1 on This Device',
              subtitle:
                  'Two players, one device, fixed board orientation, and optional clocks in a cleaner pass-and-play setup.',
              icon: Icons.people_alt_outlined,
              accent: arcade.amber,
            ),
            const SizedBox(height: 12),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                buildTag(
                  'SAME SCREEN',
                  arcade.amber,
                  icon: Icons.stay_current_portrait_rounded,
                ),
                buildTag(
                  'FIXED BOARD',
                  arcade.amber,
                  icon: Icons.swap_vert_rounded,
                ),
                buildTag(
                  'OPTIONAL CLOCK',
                  arcade.amber,
                  icon: Icons.timer_outlined,
                ),
              ],
            ),
            const SizedBox(height: 12),
            LayoutBuilder(
              builder: (context, constraints) {
                final wide = constraints.maxWidth >= 620;
                if (!wide) {
                  return Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      timeControlPanel,
                      const SizedBox(height: 12),
                      summaryPanel,
                    ],
                  );
                }

                return Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Expanded(flex: 6, child: timeControlPanel),
                    const SizedBox(width: 12),
                    Expanded(flex: 5, child: summaryPanel),
                  ],
                );
              },
            ),
            const SizedBox(height: 12),
            SizedBox(
              width: double.infinity,
              child: buildActionButton(
                label: 'Start Local 1V1',
                icon: Icons.play_arrow_rounded,
                onPressed: () => unawaited(_startLocalFriendMatch()),
                accent: arcade.amber,
              ),
            ),
          ],
        ),
      );
    }

    // ignore: unused_element
    Widget buildRemoteModeCard() {
      Widget buildRecentMatchesContent() {
        if (_remoteFriendMemberships.isEmpty) {
          return Text(
            _remoteFriendMembershipsLoading
                ? 'Checking your recent private matches...'
                : _remoteFriendLastError == null
                ? 'No private remote matches yet. Create an invite or join a friend with a code.'
                : 'Remote matches could not be refreshed just now. You can still create or join an invite above.',
            style: buildBodyStyle(color: arcade.textMuted, size: 11.8),
          );
        }

        if (_remoteFriendMemberships.length <= 3) {
          return Column(
            children: List<Widget>.generate(
              _remoteFriendMemberships.length,
              (index) => Padding(
                padding: EdgeInsets.only(
                  bottom: index == _remoteFriendMemberships.length - 1 ? 0 : 10,
                ),
                child: buildRemoteMembershipTile(
                  _remoteFriendMemberships[index],
                ),
              ),
              growable: false,
            ),
          );
        }

        final listHeight = min(336.0, 96.0 * _remoteFriendMemberships.length);

        return SizedBox(
          height: listHeight,
          child: Scrollbar(
            child: ListView.separated(
              primary: false,
              padding: EdgeInsets.zero,
              itemCount: _remoteFriendMemberships.length,
              separatorBuilder: (context, index) => const SizedBox(height: 10),
              itemBuilder: (context, index) {
                return buildRemoteMembershipTile(
                  _remoteFriendMemberships[index],
                );
              },
            ),
          ),
        );
      }

      final remoteSnapshotPanel = buildSectionPanel(
        title: 'MATCH SNAPSHOT',
        accent: remoteAccent,
        child: Wrap(
          spacing: 10,
          runSpacing: 10,
          children: [
            buildSnapshotTile(
              label: 'CLOCK',
              value: selectedRemoteFriendTimeControl.isUntimed
                  ? 'Untimed Invite'
                  : _formatRemoteFriendTimeControl(
                      selectedRemoteFriendTimeControl,
                    ),
              detail: 'Server-synced time state across both devices.',
              icon: Icons.timer_outlined,
              accent: remoteAccent,
              minWidth: 170,
            ),
            buildSnapshotTile(
              label: 'SEAT',
              value: remoteSeatPreferenceLabel(_remoteFriendSeatPreference),
              detail:
                  'Your color request is applied before piece selection opens.',
              icon: Icons.flag_outlined,
              accent: remoteAccent,
              minWidth: 170,
            ),
            buildSnapshotTile(
              label: 'RETENTION',
              value: '24h / 6h Cleanup',
              detail:
                  'Finished or expired matches are swept away automatically.',
              icon: Icons.auto_delete_rounded,
              accent: arcade.amber,
              minWidth: 170,
            ),
          ],
        ),
      );
      final timeControlPanel = buildSectionPanel(
        title: 'TIME CONTROL',
        accent: remoteAccent,
        child: Wrap(
          spacing: 8,
          runSpacing: 8,
          children: [
            for (
              int index = 0;
              index < _localFriendTimeControls.length;
              index++
            )
              buildChoiceChip(
                label: _formatRemoteFriendTimeControl(
                  RemoteFriendTimeControl(
                    initialSeconds:
                        _localFriendTimeControls[index]
                            .initialTime
                            ?.inSeconds ??
                        0,
                    incrementSeconds:
                        _localFriendTimeControls[index].increment.inSeconds,
                  ),
                ),
                selected: _remoteFriendTimeControlIndex == index,
                onSelected: _remoteFriendOperationInProgress
                    ? null
                    : (_) {
                        unawaited(_setRemoteFriendTimeControlIndex(index));
                      },
                accent: remoteAccent,
              ),
          ],
        ),
      );
      final seatPreferencePanel = buildSectionPanel(
        title: 'SEAT PREFERENCE',
        accent: remoteAccent,
        child: Wrap(
          spacing: 8,
          runSpacing: 8,
          children: [
            for (final entry in <(RemoteFriendSeatPreference, String)>[
              (RemoteFriendSeatPreference.random, 'Random'),
              (RemoteFriendSeatPreference.white, 'White'),
              (RemoteFriendSeatPreference.black, 'Black'),
            ])
              buildChoiceChip(
                label: entry.$2,
                selected: _remoteFriendSeatPreference == entry.$1,
                onSelected: _remoteFriendOperationInProgress
                    ? null
                    : (_) {
                        unawaited(_setRemoteFriendSeatPreference(entry.$1));
                      },
                accent: remoteAccent,
              ),
          ],
        ),
      );
      final syncedClocksSelector = Wrap(
        spacing: 8,
        runSpacing: 8,
        children: [
          buildTag('SYNCED CLOCKS', remoteAccent, icon: Icons.sync_alt_rounded),
        ],
      );

      return buildCardShell(
        accent: remoteAccent,
        emphasized: true,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            buildCardHeader(
              label: 'PRIVATE MATCH',
              title: 'Cross-Device 1v1',
              subtitle:
                  'Invite-only play across devices with server validation, synced clocks, and a cleaner lobby that stays usable on mobile.',
              icon: Icons.wifi_tethering_rounded,
              accent: remoteAccent,
            ),
            const SizedBox(height: 12),
            LayoutBuilder(
              builder: (context, constraints) {
                final modeTags = Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: [
                    buildTag(
                      'INVITE ONLY',
                      remoteAccent,
                      icon: Icons.password_rounded,
                    ),
                    buildTag(
                      'SERVER RULES',
                      remoteAccent,
                      icon: Icons.verified_outlined,
                    ),
                  ],
                );
                final infoPod = _buildVsBotActionPod(
                  label: 'Guide',
                  accent: remoteAccent,
                  control: _buildVsBotControlButton(
                    icon: Icons.info_outline_rounded,
                    onTap: () => unawaited(showRemoteMatchInfoDialog()),
                    accent: remoteAccent,
                  ),
                );

                if (constraints.maxWidth < 470) {
                  return Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [modeTags, const SizedBox(height: 10), infoPod],
                  );
                }

                return Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Expanded(child: modeTags),
                    const SizedBox(width: 12),
                    infoPod,
                  ],
                );
              },
            ),
            const SizedBox(height: 12),
            remoteSnapshotPanel,
            const SizedBox(height: 12),
            LayoutBuilder(
              builder: (context, constraints) {
                final wide = constraints.maxWidth >= 650;
                if (!wide) {
                  return Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      timeControlPanel,
                      const SizedBox(height: 12),
                      seatPreferencePanel,
                      const SizedBox(height: 12),
                      syncedClocksSelector,
                    ],
                  );
                }

                return Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Expanded(child: timeControlPanel),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.stretch,
                        children: [
                          seatPreferencePanel,
                          const SizedBox(height: 12),
                          syncedClocksSelector,
                        ],
                      ),
                    ),
                  ],
                );
              },
            ),
            const SizedBox(height: 12),
            buildSectionPanel(
              title: 'LOBBY ACTIONS',
              accent: remoteAccent,
              child: LayoutBuilder(
                builder: (context, constraints) {
                  final createInviteButton = buildActionButton(
                    label: 'Create Invite',
                    icon: Icons.add_link_rounded,
                    onPressed: _remoteFriendOperationInProgress
                        ? null
                        : () => unawaited(_createRemoteFriendInvite()),
                    accent: remoteAccent,
                  );
                  final joinCodeButton = buildActionButton(
                    label: 'Join Code',
                    icon: Icons.key_rounded,
                    onPressed: _remoteFriendOperationInProgress
                        ? null
                        : () => unawaited(_joinRemoteFriendInvite()),
                    accent: remoteAccent,
                    filled: false,
                  );

                  if (constraints.maxWidth < 470) {
                    return Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        SizedBox(
                          width: double.infinity,
                          child: createInviteButton,
                        ),
                        const SizedBox(height: 10),
                        SizedBox(width: double.infinity, child: joinCodeButton),
                      ],
                    );
                  }

                  return Row(
                    children: [
                      Expanded(child: createInviteButton),
                      const SizedBox(width: 10),
                      Expanded(child: joinCodeButton),
                    ],
                  );
                },
              ),
            ),
            const SizedBox(height: 12),
            buildInsetShell(
              accent: remoteAccent,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Expanded(
                        child: buildSectionTitle(
                          'RECENT PRIVATE MATCHES',
                          remoteAccent,
                        ),
                      ),
                      const SizedBox(width: 8),
                      if (_remoteFriendMembershipsLoading)
                        SizedBox(
                          width: 16,
                          height: 16,
                          child: CircularProgressIndicator(
                            strokeWidth: 2,
                            color: remoteAccent,
                          ),
                        )
                      else
                        _buildVsBotControlButton(
                          icon: Icons.refresh_rounded,
                          onTap: () =>
                              unawaited(_loadRemoteFriendMemberships()),
                          accent: remoteAccent,
                        ),
                    ],
                  ),
                  const SizedBox(height: 10),
                  buildRecentMatchesContent(),
                ],
              ),
            ),
          ],
        ),
      );
    }

    return Container(
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [
            Color.alphaBlend(
              arcade.cyan.withValues(alpha: useMonochrome ? 0.02 : 0.06),
              scheme.surface,
            ),
            scheme.surface,
            Color.alphaBlend(
              arcade.amber.withValues(alpha: useMonochrome ? 0.02 : 0.05),
              scheme.surfaceContainerHighest,
            ),
          ],
          stops: const [0.0, 0.54, 1.0],
        ),
      ),
      child: Stack(
        children: [
          Positioned(
            top: -90,
            left: -70,
            child: Container(
              width: 220,
              height: 220,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: arcade.cyan.withValues(alpha: isDark ? 0.10 : 0.06),
              ),
            ),
          ),
          Positioned(
            bottom: -100,
            right: -80,
            child: Container(
              width: 240,
              height: 240,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: arcade.amber.withValues(alpha: isDark ? 0.08 : 0.05),
              ),
            ),
          ),
          SafeArea(
            child: Padding(
              padding: EdgeInsets.fromLTRB(
                chromePadding,
                0,
                chromePadding,
                compactWidth ? 12 : 16,
              ),
              child: Stack(
                children: [
                  NotificationListener<ScrollNotification>(
                    onNotification: handleVsModeScroll,
                    child: Align(
                      alignment: Alignment.topCenter,
                      child: ConstrainedBox(
                        constraints: const BoxConstraints(maxWidth: 1160),
                        child: SingleChildScrollView(
                          padding: EdgeInsets.only(
                            top: scrollTopInset,
                            bottom: sectionGap,
                          ),
                          child: LayoutBuilder(
                            builder: (context, constraints) {
                              return Column(
                                crossAxisAlignment: CrossAxisAlignment.stretch,
                                children: [buildHeroPanel()],
                              );
                            },
                          ),
                        ),
                      ),
                    ),
                  ),
                  Positioned(
                    top: compactWidth ? 12 : 14,
                    left: 0,
                    right: 0,
                    child: Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Transform.scale(
                          scale: collapsibleTopChrome
                              ? ui.lerpDouble(1.0, 0.94, chromeCollapseT)!
                              : 1.0,
                          alignment: Alignment.topLeft,
                          child: _buildVsBotControlButton(
                            icon: Icons.arrow_back_rounded,
                            onTap: _goToMenu,
                            accent: arcade.crimson,
                          ),
                        ),
                        const Spacer(),
                        IgnorePointer(
                          ignoring: chromeCollapseT > 0.72,
                          child: Opacity(
                            opacity: collapsibleTopChrome
                                ? (1.0 - chromeCollapseT).clamp(0.0, 1.0)
                                : 1.0,
                            child: Transform.translate(
                              offset: Offset(
                                0,
                                collapsibleTopChrome
                                    ? ui.lerpDouble(
                                        0.0,
                                        -14.0,
                                        chromeCollapseT,
                                      )!
                                    : 0.0,
                              ),
                              child: _buildVsBotControlButton(
                                controlKey: const ValueKey<String>(
                                  'analysis_vs_mode_credits_trigger',
                                ),
                                icon: Icons.info_outline_rounded,
                                onTap: () =>
                                    unawaited(showPlayChessInfoDialog()),
                                accent: useMonochrome
                                    ? scheme.onSurface
                                    : arcade.cyan,
                              ),
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildBotSetupScreen();
