  Widget _buildAnalysisBoardScaffold(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final isDark = theme.brightness == Brightness.dark;
    final useMonochrome =
        context.watch<AppThemeProvider>().isMonochrome ||
        _isCinematicThemeEnabled;
    final reverse = _boardReversed;
    final isLandscape =
        MediaQuery.of(context).orientation == Orientation.landscape;
    final pageBackground = scheme.surface;
    final bgTop = Color.alphaBlend(
      scheme.primary.withValues(alpha: isDark ? 0.16 : 0.05),
      scheme.surface,
    );
    final bgBottom = Color.alphaBlend(
      scheme.secondary.withValues(alpha: isDark ? 0.10 : 0.04),
      scheme.surface,
    );
    final leftBlob = useMonochrome
        ? AppThemeProvider.monochromeBlueOrbColor(isDark: isDark)
        : const Color(0xFF3F6ED8);
    final rightBlob = useMonochrome
        ? AppThemeProvider.monochromeYellowOrbColor(isDark: isDark)
        : const Color(0xFFB9A46A);

    return Scaffold(
      body: Container(
        decoration: BoxDecoration(
          gradient: LinearGradient(
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
            colors: [bgTop, pageBackground, bgBottom],
            stops: const [0.0, 0.55, 1.0],
          ),
        ),
        child: Stack(
          children: [
            Positioned(
              top: -120,
              left: -80,
              child: Container(
                width: 280,
                height: 280,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: leftBlob.withValues(alpha: isDark ? 0.16 : 0.09),
                ),
              ),
            ),
            Positioned(
              bottom: -120,
              right: -90,
              child: Container(
                width: 260,
                height: 260,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: rightBlob.withValues(alpha: isDark ? 0.12 : 0.08),
                ),
              ),
            ),
            Center(
              child: LayoutBuilder(
                builder: (context, constraints) {
                  double maxWidth = constraints.maxWidth;
                  double maxHeight = constraints.maxHeight;
                  final double width = maxWidth;
                  final double height = maxHeight;

                  final double scale = (width / 430.0).clamp(0.8, 1.4);
                  final showRemoteFriendClockStrip =
                      _isRemoteFriendMatchMode && _showsFriendClockPanels;
                  const double portraitToolboxGap = 12.0;
                  final portraitBoardRect =
                      !isLandscape && _isAnalysisEditModeActive
                      ? _boardRectInScene()
                      : null;
                  final portraitToolboxWidth = portraitBoardRect == null
                      ? null
                      : min(portraitBoardRect.width, 420.0);

                  return SizedBox(
                    key: _sceneKey,
                    width: width,
                    height: height,
                    child: Stack(
                      children: [
                        AbsorbPointer(
                          absorbing: _gameResultReveal != null,
                          child: SafeArea(
                            child: isLandscape
                                ? Column(
                                    children: [
                                      _buildHeader(scale),
                                      Expanded(
                                        child: Padding(
                                          padding: const EdgeInsets.fromLTRB(
                                            10,
                                            8,
                                            10,
                                            8,
                                          ),
                                          child: LayoutBuilder(
                                            builder: (context, inner) {
                                              final usesRemoteFriendSidePanel =
                                                  _isRemoteFriendMatchMode;
                                              final usesExpandedSidePanel =
                                                  _isAnalysisMatchMode ||
                                                  usesRemoteFriendSidePanel;
                                              final sideWidth =
                                                  usesRemoteFriendSidePanel
                                                  ? (inner.maxWidth * 0.40)
                                                        .clamp(320.0, 420.0)
                                                  : (inner.maxWidth *
                                                            (usesExpandedSidePanel
                                                                ? 0.34
                                                                : 0.28))
                                                        .clamp(
                                                          usesExpandedSidePanel
                                                              ? 220.0
                                                              : 188.0,
                                                          usesExpandedSidePanel
                                                              ? 360.0
                                                              : 280.0,
                                                        );
                                              const double evalBarW = 22.0;
                                              final boardSectionWidth = max(
                                                0.0,
                                                inner.maxWidth - sideWidth - 12,
                                              );
                                              final boardSize = max(
                                                0.0,
                                                min(
                                                  boardSectionWidth - evalBarW,
                                                  inner.maxHeight,
                                                ),
                                              );
                                              final boardSlack = max(
                                                0.0,
                                                boardSectionWidth -
                                                    evalBarW -
                                                    boardSize,
                                              );
                                              final landscapeBoardLead =
                                                  usesExpandedSidePanel
                                                  ? 0.0
                                                  : min(
                                                      boardSlack,
                                                      sideWidth * 0.34,
                                                    );
                                              return Stack(
                                                clipBehavior: Clip.none,
                                                children: [
                                                  Row(
                                                    crossAxisAlignment:
                                                        CrossAxisAlignment
                                                            .stretch,
                                                    children: [
                                                      Expanded(
                                                        flex: 7,
                                                        child: LayoutBuilder(
                                                          builder: (context, boardBox) {
                                                            return Center(
                                                              child: SizedBox(
                                                                width:
                                                                    boardSectionWidth,
                                                                child: Row(
                                                                  crossAxisAlignment:
