                                                                      ),
                                                                    SizedBox(
                                                                      key:
                                                                          _evalBarVerticalKey,
                                                                      width:
                                                                          evalBarW,
                                                                      height:
                                                                          boardSize,
                                                                      child: Center(
                                                                        child: _buildEvalBarVertical(
                                                                          scale,
                                                                        ),
                                                                      ),
                                                                    ),
                                                                    SizedBox(
                                                                      key:
                                                                          _boardKey,
                                                                      width:
                                                                          boardSize,
                                                                      height:
                                                                          boardSize,
                                                                      child: _buildBoardScene(
                                                                        reverse,
                                                                      ),
                                                                    ),
                                                                  ],
                                                                ),
                                                              ),
                                                            );
                                                          },
                                                        ),
                                                      ),
                                                      const SizedBox(width: 12),
                                                      SizedBox(
                                                        width: sideWidth,
                                                        child: LayoutBuilder(
                                                          builder:
                                                              (
                                                                context,
                                                                sideConstraints,
                                                              ) {
                                                                final suggestionsHeight =
                                                                    (sideConstraints.maxHeight *
                                                                            0.46)
                                                                        .clamp(
                                                                          96.0,
                                                                          250.0,
                                                                        );
                                                                final historyHeight =
                                                                    (sideConstraints.maxHeight *
                                                                            0.16)
                                                                        .clamp(
                                                                          46.0,
                                                                          72.0,
                                                                        );
                                                                final hasLandscapeTitle =
                                                                    _isAnalysisMatchMode &&
                                                                    (_selectedGambit !=
                                                                            null ||
                                                                        _currentOpening
                                                                            .isNotEmpty);
                                                                final landscapeBannerTop =
                                                                    _isBotMatchMode
                                                                    ? 10.0
