                                                                                  const SizedBox(
                                                                                    height: 10,
                                                                                  ),
                                                                                  _buildFriendClockPanel(
                                                                                    white: _friendClockBottomShowsWhite,
                                                                                    isLandscape: true,
                                                                                  ),
                                                                                ],
                                                                              ),
                                                                            ),
                                                                          if (!(_isRemoteFriendMatchMode &&
                                                                              _isRemoteFriendPendingMatch))
                                                                            Padding(
                                                                              padding: const EdgeInsets.only(
                                                                                bottom: 10,
                                                                              ),
                                                                              child: Align(
                                                                                alignment: Alignment.center,
                                                                                child: _buildEditModeDepthCluster(
                                                                                  scale,
                                                                                  scheme,
                                                                                  includeEvalCounter: true,
                                                                                ),
                                                                              ),
                                                                            ),
                                                                          if (_isAnalysisMatchMode &&
                                                                              _selectedGambit !=
                                                                                  null)
                                                                            Align(
                                                                              alignment: Alignment.center,
                                                                              child: Padding(
                                                                                padding: const EdgeInsets.only(
                                                                                  bottom: 6,
                                                                                ),
                                                                                child: Text(
                                                                                  _selectedGambit!.name,
                                                                                  style: TextStyle(
                                                                                    fontSize: 13,
                                                                                    fontWeight: FontWeight.w700,
                                                                                    color: useMonochrome
                                                                                        ? scheme.onSurface.withValues(
                                                                                            alpha: 0.86,
                                                                                          )
                                                                                        : const Color(
                                                                                            0xFFD8B640,
                                                                                          ),
                                                                                  ),
                                                                                  maxLines: 2,
                                                                                  overflow: TextOverflow.ellipsis,
                                                                                ),
                                                                              ),
                                                                            )
                                                                          else if (_isAnalysisMatchMode &&
                                                                              _currentOpening.isNotEmpty)
                                                                            Align(
                                                                              alignment: Alignment.center,
                                                                              child: Padding(
                                                                                padding: const EdgeInsets.only(
                                                                                  bottom: 6,
                                                                                ),
                                                                                child: _buildOpeningLabel(
                                                                                  scale,
                                                                                ),
                                                                              ),
                                                                            ),
                                                                          if (_isAnalysisMatchMode)
                                                                            _buildSuggestedMovesList(
                                                                              height: suggestionsHeight,
                                                                              padding: const EdgeInsets.symmetric(
                                                                                horizontal: 0,
                                                                                vertical: 8,
                                                                              ),
                                                                            ),
                                                                          if (_isAnalysisMatchMode)
                                                                            _buildHistoryBar(
                                                                              height: historyHeight,
                                                                              margin: const EdgeInsets.symmetric(
                                                                                vertical: 6,
                                                                              ),
                                                                            ),
                                                                          const Spacer(),
                                                                          _buildActionArea(
                                                                            compactBottom:
                                                                                8,
                                                                            horizontal:
                                                                                0,
                                                                          ),
                                                                        ],
                                                                      ),
                                                                    ),
                                                                    if (_isAnalysisEditModeActive)
                                                                      Align(
                                                                        alignment:
                                                                            Alignment.center,
                                                                        child: SizedBox(
                                                                          width: min(
                                                                            sideConstraints.maxWidth,
                                                                            220.0,
                                                                          ),
                                                                          child: _buildEditModeToolbox(
                                                                            isLandscape:
                                                                                true,
                                                                          ),
                                                                        ),
                                                                      ),
                                                                    if (_hasMoveQualityBanner &&
                                                                        !_isBotMatchMode)
