  Widget _buildHeader(double scale) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final isDark = theme.brightness == Brightness.dark;
    final useMonochrome =
        context.watch<AppThemeProvider>().isMonochrome ||
        _isCinematicThemeEnabled;
    final media = MediaQuery.of(context);
    final isLandscape = media.orientation == Orientation.landscape;
    final compactBotHeader =
        _isBotMatchMode && !isLandscape && media.size.width <= 390;
    final selectedBot = _selectedBot;
    final selectedBotAvatarAsset = selectedBot == null
        ? null
        : _selectedBotAvatarAsset(selectedBot);
    final botArcade = _vsBotArcadePaletteFor(
      context,
      monochrome: useMonochrome,
    );
    final botAccent = selectedBot == null
        ? botArcade.cyan
        : Color.lerp(
            _vsBotProfileAccent(selectedBot.profile, botArcade),
            _botDifficultyColor(_selectedBotDifficulty),
            0.45,
          )!;
    final portraitStatusAccent = _gameOutcome != null
        ? (_gameOutcome == GameOutcome.draw
              ? botArcade.amber
              : _isWinningOutcomeForPov
              ? botArcade.victory
              : botArcade.crimson)
        : _botThinking
        ? botArcade.amber
        : _isHumanTurnInBotGame
        ? botArcade.cyan
        : botArcade.crimson;
    final portraitStatusLabel = _gameOutcome != null
        ? 'MATCH END'
        : _botThinking
        ? 'BOT THINKING'
        : _isHumanTurnInBotGame
        ? 'PLAYER TURN'
        : 'BOT TURN';
    final localFriendStatusAccent = _gameOutcome != null
        ? (_gameOutcome == GameOutcome.draw
              ? botArcade.amber
              : const Color(0xFFE45C5C))
        : _isWhiteTurn
        ? botArcade.cyan
        : botArcade.amber;
    final localFriendStatusLabel = _gameOutcome != null
        ? 'MATCH END'
        : _isWhiteTurn
        ? 'WHITE TURN'
        : 'BLACK TURN';
    final remoteSnapshot = _remoteFriendSnapshot;
    final remoteStatusAccent = _gameOutcome != null
        ? (_gameOutcome == GameOutcome.draw
              ? botArcade.amber
              : const Color(0xFFE45C5C))
        : remoteSnapshot == null
        ? scheme.onSurface.withValues(alpha: 0.72)
        : remoteSnapshot.status == RemoteFriendMatchStatus.pending
        ? botArcade.amber
        : remoteSnapshot.status == RemoteFriendMatchStatus.expired ||
              remoteSnapshot.status == RemoteFriendMatchStatus.cancelled
        ? scheme.onSurface.withValues(alpha: 0.70)
        : (_hasIncomingRemoteDrawOffer || _hasOutgoingRemoteDrawOffer)
        ? botArcade.amber
        : _isHumanTurnInRemoteFriendGame
        ? botArcade.cyan
        : botArcade.crimson;
    final remoteStatusLabel = _gameOutcome != null
        ? 'MATCH END'
        : remoteSnapshot == null
        ? 'SYNCING'
        : remoteSnapshot.status == RemoteFriendMatchStatus.pending
        ? 'WAITING'
        : remoteSnapshot.status == RemoteFriendMatchStatus.expired
        ? 'EXPIRED'
        : remoteSnapshot.status == RemoteFriendMatchStatus.cancelled
        ? 'CANCELLED'
        : _hasIncomingRemoteDrawOffer
        ? 'DRAW OFFER'
        : _hasOutgoingRemoteDrawOffer
        ? 'DRAW SENT'
        : _isHumanTurnInRemoteFriendGame
        ? 'YOUR TURN'
        : 'FRIEND TURN';
    final remoteSeatLabel = _remoteFriendPlayerSeat == RemoteFriendSeat.black
        ? 'BLACK'
        : 'WHITE';
    final remoteStatusDetail = remoteSnapshot == null
        ? 'Connecting...'
        : remoteSnapshot.status == RemoteFriendMatchStatus.pending
        ? 'Code ${remoteSnapshot.inviteCode}'
        : remoteSnapshot.status == RemoteFriendMatchStatus.expired
        ? 'Invite expired before the match started.'
        : remoteSnapshot.status == RemoteFriendMatchStatus.cancelled
        ? 'The pending invite was cancelled.'
        : '$remoteSeatLabel | ${_formatRemoteFriendTimeControl(remoteSnapshot.timeControl)}';
    final portraitFilledTagForeground = botArcade.monochrome
        ? botArcade.text
        : const Color(0xFF0B0F16);
    if (isLandscape) {
      return SizedBox.shrink();
    }

    Widget buildPortraitBotStatusTag({required bool compact}) {
      if (!_isBotMatchMode || selectedBot == null) {
        return const SizedBox.shrink();
      }

      return PuzzleAcademyTag(
        label: portraitStatusLabel,
        accent: portraitStatusAccent,
        compact: compact,
        filled: _gameOutcome == null && _isHumanTurnInBotGame,
        foregroundColor: _gameOutcome == null && _isHumanTurnInBotGame
            ? portraitFilledTagForeground
            : null,
      );
    }

    Widget buildPortraitBotIdentityCluster({
      required double avatarSize,
      required double iconSize,
      required double shadowBlurRadius,
      required Offset shadowOffset,
      bool includeOverlay = false,
      bool includeStatusTag = true,
    }) {
      final avatar = _wrapBotAvatarInteractive(
        scale,
        InkWell(
          onTap: _onBotAvatarTapped,
          borderRadius: BorderRadius.circular(999),
          child: Opacity(
            opacity: _botAvatarIntroOpacity,
            child: Container(
              key: _botAvatarWidgetKey,
              width: avatarSize,
              height: avatarSize,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                border: Border.all(color: botAccent.withValues(alpha: 0.58)),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withValues(alpha: isDark ? 0.24 : 0.10),
                    blurRadius: shadowBlurRadius,
                    offset: shadowOffset,
                  ),
                ],
              ),
              child: ClipOval(
                child: selectedBotAvatarAsset != null
                    ? Image.asset(selectedBotAvatarAsset, fit: BoxFit.cover)
                    : Container(
                        color: Color.alphaBlend(
                          scheme.primary.withValues(alpha: 0.08),
                          scheme.surface,
                        ),
                        alignment: Alignment.center,
                        child: Icon(
                          Icons.smart_toy_outlined,
                          color: botAccent,
                          size: iconSize,
                        ),
                      ),
              ),
            ),
          ),
        ),
      );

      final avatarCluster = includeOverlay
          ? Stack(
              clipBehavior: Clip.none,
              alignment: Alignment.centerRight,
              children: [
                Positioned(
                  left: _botAvatarOverlayOnRight
                      ? avatarSize + (8 * scale)
                      : null,
                  right: _botAvatarOverlayOnRight
                      ? null
                      : avatarSize + (8 * scale),
                  child: IgnorePointer(child: _buildBotAvatarOverlay(scale)),
                ),
                avatar,
              ],
            )
          : avatar;

      return Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          avatarCluster,
          if (includeStatusTag) ...[
            SizedBox(width: 8 * scale),
            buildPortraitBotStatusTag(compact: true),
          ],
        ],
      );
    }

    Widget buildCompactBotHeaderIdentity() {
      return Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Padding(
                key: const ValueKey<String>('analysis_bot_credits_trigger'),
                padding: EdgeInsets.symmetric(
                  vertical: 2 * scale,
                  horizontal: 2 * scale,
                ),
                child: Image.asset(
                  'assets/ChessIQ.png',
                  width: 98 * scale,
                  height: 28 * scale,
                  fit: BoxFit.contain,
                ),
              ),
              SizedBox(
                width: 98 * scale,
                child: Text(
                  selectedBot?.name ?? '',
                  textAlign: TextAlign.center,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: puzzleAcademyIdentityStyle(
                    palette: botArcade.base,
                    size: 5.8 * scale,
                    color: botAccent,
                    withGlow: true,
                  ),
                ),
              ),
            ],
          ),
          if (_isBotMatchMode && selectedBot != null) ...[
            SizedBox(width: 8 * scale),
            buildPortraitBotIdentityCluster(
              avatarSize: 34 * scale,
              iconSize: 18 * scale,
              shadowBlurRadius: 9 * scale,
              shadowOffset: const Offset(0, 2),
              includeStatusTag: false,
            ),
          ],
        ],
      );
    }

    Widget buildHeaderIdentity() {
      return Row(
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          Expanded(
            child: Align(
              alignment: Alignment.centerLeft,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.center,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Padding(
                    key: const ValueKey<String>('analysis_bot_credits_trigger'),
                    padding: EdgeInsets.symmetric(
                      vertical: 2 * scale,
                      horizontal: 2 * scale,
                    ),
                    child: Image.asset(
                      'assets/ChessIQ.png',
                      width: 120 * scale,
                      height: 34 * scale,
                      fit: BoxFit.contain,
                    ),
                  ),
                  SizedBox(
                    width: 120 * scale,
                    child: _isBotMatchMode
                        ? Text(
                            selectedBot?.name ?? '',
                            textAlign: TextAlign.center,
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,
                            style: puzzleAcademyIdentityStyle(
                              palette: botArcade.base,
                              size: 6.8 * scale,
                              color: botAccent,
                              withGlow: true,
                            ),
                          )
                        : Text(
                            _isLocalFriendMatchMode
                                ? 'VS FRIEND'
                                : _isRemoteFriendMatchMode
                                ? 'REMOTE FRIEND'
                                : 'Engine: Stockfish 18',
                            textAlign: TextAlign.center,
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                              color: scheme.onSurface.withValues(alpha: 0.54),
                              fontSize: 10 * scale,
                              letterSpacing: 0.4,
                            ),
                          ),
                  ),
                ],
              ),
            ),
          ),
          if (_isBotMatchMode && selectedBot != null)
            FittedBox(
              fit: BoxFit.scaleDown,
              alignment: Alignment.centerRight,
              child: buildPortraitBotIdentityCluster(
                avatarSize: 38 * scale,
                iconSize: 20 * scale,
                shadowBlurRadius: 11 * scale,
                shadowOffset: const Offset(0, 3),
                includeOverlay: true,
                includeStatusTag: false,
              ),
            ),
        ],
      );
    }

    Widget buildCenterEvalCounter() {
      return Visibility(
        visible: _shouldShowCenterEvalCounter,
        maintainSize: true,
        maintainAnimation: true,
        maintainState: true,
        child: _buildAnalysisEvalCounterChip(scale: scale, scheme: scheme),
      );
    }

    final headerIdentity = buildHeaderIdentity();
    final centerEvalCounter = buildCenterEvalCounter();
    final depthCluster = _buildEditModeDepthCluster(scale, scheme);
    final rightAccessoryAlignment =
        (_isBotMatchMode && selectedBot != null) ||
            _isLocalFriendMatchMode ||
            _isRemoteFriendMatchMode
        ? Alignment.centerRight
        : Alignment.center;
    final rightAccessory = _isBotMatchMode && selectedBot != null
        ? Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              buildPortraitBotStatusTag(compact: true),
              if (_shouldShowDepthCounter) SizedBox(width: 10 * scale),
              if (_shouldShowDepthCounter) depthCluster,
            ],
          )
        : _isLocalFriendMatchMode
        ? Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.end,
            children: [
              PuzzleAcademyTag(
                label: localFriendStatusLabel,
                accent: localFriendStatusAccent,
                compact: true,
              ),
              const SizedBox(height: 4),
              Text(
                _formatLocalFriendTimeControl(_selectedLocalFriendTimeControl),
                style: TextStyle(
                  color: scheme.onSurface.withValues(alpha: 0.62),
                  fontSize: 10.5 * scale,
                  fontWeight: FontWeight.w700,
                  letterSpacing: 0.3,
                ),
              ),
            ],
          )
        : _isRemoteFriendMatchMode
        ? Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.end,
            children: [
              PuzzleAcademyTag(
                label: remoteStatusLabel,
                accent: remoteStatusAccent,
                compact: true,
                filled: _gameOutcome == null && _isHumanTurnInRemoteFriendGame,
                foregroundColor:
                    _gameOutcome == null && _isHumanTurnInRemoteFriendGame
                    ? portraitFilledTagForeground
                    : null,
              ),
              const SizedBox(height: 4),
              Text(
                remoteStatusDetail,
                style: TextStyle(
                  color: scheme.onSurface.withValues(alpha: 0.62),
                  fontSize: 10.5 * scale,
                  fontWeight: FontWeight.w700,
                  letterSpacing: 0.3,
                ),
              ),
            ],
          )
        : depthCluster;
    final portraitHeaderBody = compactBotHeader
        ? LayoutBuilder(
            builder: (context, constraints) {
              final compactGap = 8 * scale;
              final centerReservedWidth = _shouldShowCenterEvalCounter
                  ? min(100 * scale, constraints.maxWidth * 0.30)
                  : 0.0;
              final sideMaxWidth = _shouldShowCenterEvalCounter
                  ? max(
                      0.0,
                      (constraints.maxWidth -
                              centerReservedWidth -
                              (compactGap * 2)) /
                          2,
                    )
                  : max(0.0, (constraints.maxWidth - compactGap) / 2);

              return SizedBox(
                height: 48 * scale,
                child: Stack(
                  alignment: Alignment.center,
                  children: [
                    if (_shouldShowCenterEvalCounter)
                      Align(
                        alignment: Alignment.center,
                        child: FittedBox(
                          fit: BoxFit.scaleDown,
                          child: centerEvalCounter,
                        ),
                      ),
                    Align(
                      alignment: Alignment.centerLeft,
                      child: ConstrainedBox(
                        constraints: BoxConstraints(maxWidth: sideMaxWidth),
                        child: FittedBox(
                          fit: BoxFit.scaleDown,
                          alignment: Alignment.centerLeft,
                          child: buildCompactBotHeaderIdentity(),
                        ),
                      ),
                    ),
                    Align(
                      alignment: Alignment.centerRight,
                      child: ConstrainedBox(
                        constraints: BoxConstraints(maxWidth: sideMaxWidth),
                        child: rightAccessory,
                      ),
                    ),
                  ],
                ),
              );
            },
          )
        : Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              Expanded(child: headerIdentity),
              Expanded(child: Center(child: centerEvalCounter)),
              Expanded(
                child: Align(
                  alignment: rightAccessoryAlignment,
                  child: rightAccessory,
                ),
              ),
            ],
          );

    return Padding(
      padding: EdgeInsets.symmetric(
        horizontal: 14 * scale,
        vertical: 8 * scale,
      ),
      child: portraitHeaderBody,
    );
  }

  Widget _buildAnalysisEvalCounterChip({
    required double scale,
    required ColorScheme scheme,
  }) {
    final theme = Theme.of(context);
    final isDark = theme.brightness == Brightness.dark;
    final useMonochrome =
        context.watch<AppThemeProvider>().isMonochrome ||
        _isCinematicThemeEnabled;
    final displayedEval = _displayEvalForPov();
    final displayedEvalColor = useMonochrome
        ? const Color(0xFFEEEEEE)
        : _evalColorForUi(displayedEval);

    return Container(
      padding: EdgeInsets.symmetric(
        horizontal: 14 * scale,
        vertical: 6 * scale,
      ),
      decoration: BoxDecoration(
        color: useMonochrome
            ? const Color(0xFF161B21)
            : Color.alphaBlend(
                scheme.primary.withValues(alpha: isDark ? 0.14 : 0.05),
                scheme.surface,
              ).withValues(alpha: 0.92),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(
          color: useMonochrome
              ? const Color(0xFF89929D).withValues(alpha: 0.34)
              : scheme.outline.withValues(alpha: 0.34),
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: isDark ? 0.30 : 0.10),
            blurRadius: 14,
            offset: const Offset(0, 4),
          ),
        ],
      ),
      child: Text(
        _evalTextForUi(displayedEval),
        style: TextStyle(
          fontWeight: FontWeight.bold,
          color: displayedEvalColor,
          fontSize: 14 * scale,
        ),
      ),
    );
  }

  Widget _buildEditModeDepthCluster(
    double scale,
    ColorScheme scheme, {
    bool includeEvalCounter = false,
  }) {
    final showEditModeButton = _canUseAnalysisEditMode;
    final showDepthCounter = _shouldShowDepthCounter;
    final showEvalCounter = includeEvalCounter && _shouldShowCenterEvalCounter;
    if (!showEditModeButton && !showDepthCounter && !showEvalCounter) {
      return const SizedBox.shrink();
    }

    final clusterWidth = showEvalCounter
        ? (showEditModeButton ? 250 * scale : 156 * scale)
        : (showEditModeButton ? 168 * scale : 72 * scale);
    return SizedBox(
      width: clusterWidth,
      height: 30,
      child: Stack(
        alignment: Alignment.center,
        children: [
          if (showEvalCounter)
            Align(
              alignment: Alignment.centerLeft,
              child: ConstrainedBox(
                constraints: BoxConstraints(maxWidth: 92 * scale),
                child: FittedBox(
                  fit: BoxFit.scaleDown,
                  alignment: Alignment.centerLeft,
                  child: _buildAnalysisEvalCounterChip(
                    scale: scale,
                    scheme: scheme,
                  ),
                ),
              ),
            ),
          if (showDepthCounter)
            Align(
              alignment: Alignment.centerRight,
              child: Text(
                'Depth $_currentDepth',
                style: TextStyle(
                  color: scheme.onSurface.withValues(alpha: 0.54),
                  fontSize: 11 * scale,
                ),
              ),
            ),
          if (showEditModeButton)
            Align(
              alignment: Alignment.center,
              child: SizedBox(
                width: 30,
                height: 30,
                child: IconButton(
                  onPressed: () {
                    _setAnalysisEditMode(!_isAnalysisEditModeActive);
                  },
                  icon: SizedBox(
                    width: 18,
                    height: 18,
                    child: Image.asset(
                      _isAnalysisEditModeActive
                          ? 'assets/pieces/edit board.png'
                          : 'assets/pieces/edit no board.png',
                      width: 18,
                      height: 18,
                      fit: BoxFit.contain,
                      filterQuality: FilterQuality.medium,
                    ),
                  ),
                  tooltip: _isAnalysisEditModeActive
                      ? 'Edit mode on (any move allowed)'
                      : 'Edit mode off (legal moves only)',
                  splashRadius: 18,
                  visualDensity: VisualDensity.compact,
                  padding: EdgeInsets.zero,
                  constraints: const BoxConstraints.tightFor(
                    width: 30,
                    height: 30,
                  ),
                ),
              ),
            ),
        ],
      ),
    );
  }

  Widget _buildEvalBarHorizontal(double scale) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final useMonochrome =
        context.watch<AppThemeProvider>().isMonochrome ||
        _isCinematicThemeEnabled;
    final showEvalBar = _shouldKeepEvalActive;
    final displayedEval = _displayEvalForPov();

    if (!useMonochrome) {
      final displayedEvalColor = _evalColorForUi(displayedEval);
      final showWinningAura = _isWinningOutcomeForPov || displayedEval > 5.0;
      final fill = _evalFillForUi(displayedEval);
      return Visibility(
        visible: showEvalBar,
        maintainAnimation: true,
        maintainSize: true,
        maintainState: true,
        child: Container(
          height: 6 * scale,
          width: double.infinity,
          margin: EdgeInsets.symmetric(
            horizontal: 18 * scale,
            vertical: 4 * scale,
          ),
          decoration: BoxDecoration(
            color: scheme.outline.withValues(alpha: 0.24),
            borderRadius: BorderRadius.circular(2 * scale),
          ),
          child: FractionallySizedBox(
            alignment: Alignment.centerLeft,
            widthFactor: fill,
            child: Container(
              decoration: BoxDecoration(
                color: displayedEvalColor,
                borderRadius: BorderRadius.circular(2 * scale),
                boxShadow: [
                  BoxShadow(
                    color:
                        (showWinningAura
                                ? const Color(0xFFD8B640)
                                : displayedEvalColor)
                            .withValues(alpha: 0.65),
                    blurRadius: showWinningAura ? 10 * scale : 4 * scale,
                    spreadRadius: showWinningAura ? 1.2 : 0,
                  ),
                ],
              ),
            ),
          ),
        ),
      );
    }

    final Color whiteSegmentColor = const Color(0xFFF3F5F7);
    final Color blackSegmentColor = const Color(0xFF151A20);
    final Color trackBorderColor = const Color(
      0xFF78818C,
    ).withValues(alpha: 0.46);
    final bool leftSideIsWhite = !_isBlackPovActive;
    final Color leftColor = leftSideIsWhite
        ? whiteSegmentColor
        : blackSegmentColor;
    final Color rightColor = leftSideIsWhite
        ? blackSegmentColor
        : whiteSegmentColor;
    final double leftShare = _evalFillForUi(displayedEval);
    final bool turnMatchesLeft = _isWhiteTurn == leftSideIsWhite;
    final Alignment overlayAlignment = turnMatchesLeft
        ? Alignment.centerLeft
        : Alignment.centerRight;
    final double overlayWidthFactor = turnMatchesLeft
        ? leftShare
        : (1.0 - leftShare);
    final Color baseColor = turnMatchesLeft ? rightColor : leftColor;
    final Color overlayColor = turnMatchesLeft ? leftColor : rightColor;

    return Visibility(
      visible: showEvalBar,
      maintainAnimation: true,
      maintainSize: true,
      maintainState: true,
      child: Container(
        height: 6 * scale,
        width: double.infinity,
        margin: EdgeInsets.symmetric(
          horizontal: 18 * scale,
          vertical: 4 * scale,
        ),
        decoration: BoxDecoration(
          color: baseColor,
          borderRadius: BorderRadius.circular(2 * scale),
          border: Border.all(color: trackBorderColor, width: 0.8 * scale),
        ),
        child: FractionallySizedBox(
          alignment: overlayAlignment,
          widthFactor: overlayWidthFactor,
          child: Container(
            decoration: BoxDecoration(
              color: overlayColor,
              borderRadius: BorderRadius.circular(2 * scale),
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildEvalBarVertical(double scale) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final useMonochrome =
        context.watch<AppThemeProvider>().isMonochrome ||
        _isCinematicThemeEnabled;
    final showEvalBar = _shouldKeepEvalActive;
    final displayedEval = _displayEvalForPov();
    final fill = _evalFillForUi(displayedEval);
    final showWinningAura = _isWinningOutcomeForPov || displayedEval > 5.0;

    final int topFlex = max(1, ((1.0 - fill) * 100).round());
    final int bottomFlex = max(1, (fill * 100).round());

    if (!useMonochrome) {
      // Themed color mode: bottom = player's eval color, top = opponent track
      final displayedEvalColor = _evalColorForUi(displayedEval);
      final auraColor = showWinningAura
          ? const Color(0xFFD8B640)
          : displayedEvalColor;
      return Visibility(
        visible: showEvalBar,
        maintainAnimation: true,
        maintainSize: true,
        maintainState: true,
        child: Container(
          width: 10 * scale,
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(5 * scale),
            color: scheme.outline.withValues(alpha: 0.24),
            border: Border.all(color: scheme.outline.withValues(alpha: 0.32)),
            boxShadow: [
              BoxShadow(
                color: auraColor.withValues(
                  alpha: showWinningAura ? 0.55 : 0.40,
                ),
                blurRadius: showWinningAura ? 10 * scale : 4 * scale,
                spreadRadius: showWinningAura ? 1.2 : 0,
              ),
            ],
          ),
          child: ClipRRect(
            borderRadius: BorderRadius.circular(5 * scale),
            child: Column(
              children: [
                Expanded(
                  flex: topFlex,
                  child: Container(
                    color: scheme.outline.withValues(alpha: 0.18),
                  ),
                ),
                Expanded(
                  flex: bottomFlex,
                  child: Container(color: displayedEvalColor),
                ),
              ],
            ),
          ),
        ),
      );
    }

    // Monochrome mode: classic black/white segments
    final Color lightSeg = const Color(0xFFF3F5F7);
    final Color darkSeg = const Color(0xFF151A20);
    final bool bottomIsWhite = !_isBlackPovActive;
    final Color bottomColor = bottomIsWhite ? lightSeg : darkSeg;
    final Color topColor = bottomIsWhite ? darkSeg : lightSeg;

    return Visibility(
      visible: showEvalBar,
      maintainAnimation: true,
      maintainSize: true,
      maintainState: true,
      child: Container(
        width: 10 * scale,
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(5 * scale),
          border: Border.all(
            color: const Color(0xFF78818C).withValues(alpha: 0.46),
            width: 0.9 * scale,
          ),
        ),
        child: ClipRRect(
          borderRadius: BorderRadius.circular(5 * scale),
          child: Column(
            children: [
              Expanded(
                flex: topFlex,
                child: Container(color: topColor),
              ),
              Expanded(
                flex: bottomFlex,
                child: Container(color: bottomColor),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildOpeningLabel(double scale) {
    final scheme = Theme.of(context).colorScheme;
    final useMonochrome =
        context.watch<AppThemeProvider>().isMonochrome ||
        _isCinematicThemeEnabled;
    final label = _selectedGambit?.name ?? _currentOpening;
    return SizedBox(
      height: 24 * scale,
      child: Visibility(
        visible: label.isNotEmpty,
        maintainAnimation: true,
        maintainSize: true,
        maintainState: true,
        child: Padding(
          padding: EdgeInsets.symmetric(
            horizontal: 14 * scale,
            vertical: 4 * scale,
          ),
          child: Text(
            label,
            textAlign: TextAlign.center,
            style: TextStyle(
              color: useMonochrome
                  ? scheme.onSurface.withValues(alpha: 0.86)
                  : (_selectedGambit != null
                        ? const Color(0xFFD8B640)
                        : scheme.onSurface.withValues(alpha: 0.72)),
              fontSize: _selectedGambit != null ? (13 * scale) : (12 * scale),
              fontWeight: FontWeight.w600,
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildBoard(bool reverse) {
    final darkSquareColor = _darkSquareColorForTheme();
    final lightSquareColor = _lightSquareColorForTheme();
    final useMonochrome =
        context.watch<AppThemeProvider>().isMonochrome ||
        _isCinematicThemeEnabled;
    final arcade = _vsBotArcadePaletteFor(context, monochrome: useMonochrome);
    final compactBotFrame = _isCompactBotFrame(context);
    final boardBorderWidth = _boardFrameBorderWidth();
    final boardInnerPadding = _boardInnerPaddingForContext(context);
    final boardAccent = _isBotMatchMode
        ? (_selectedBot == null
              ? arcade.cyan
              : Color.lerp(
                  _vsBotProfileAccent(_selectedBot!.profile, arcade),
                  _botDifficultyColor(_selectedBotDifficulty),
                  0.45,
                )!)
        : Colors.white10;
    final innerBoardRadius = _isBotMatchMode
        ? (compactBotFrame ? 8.0 : 10.0)
        : 4.0;
    final activeMove = _historyIndex >= 0 && _historyIndex < _moveHistory.length
        ? _moveHistory[_historyIndex]
        : null;
    final activeMoveQuality = !_isBotMatchMode && !_runsAnalysisMoveAssessment
        ? null
        : _isBotMatchMode
        ? _lastMoveQualityBadgeQuality
        : activeMove?.quality;
    final activeMoveQualitySquare =
        !_isBotMatchMode && !_runsAnalysisMoveAssessment
        ? null
        : _isBotMatchMode
        ? _lastMoveQualityBadgeSquare
        : activeMove?.uci != null && activeMove!.uci!.length >= 4
        ? activeMove.uci!.substring(2, 4)
        : null;
    final openingOptionSourceSquares = _openingMode == OpeningMode.off
        ? const <String>{}
        : _sourceSquaresWithRegisteredOpenings(
            gambitsOnly: _isGambitsOnlyOpeningMode,
          );
    final previewLines = _openingPreviewArrowLines();
    final hasSacrificePreview =
        _isSacrificeModeActive && previewLines.isNotEmpty;
    final previewMoveSquares = previewLines.isEmpty
        ? const <String>{}
        : _getPreviewMoveSqares(previewLines);
    final checkedKingSquares = _currentCheckedKingSquares();

    return Container(
      decoration: _isBotMatchMode
          ? _vsBotArcadePanelDecoration(
              palette: arcade,
              accent: boardAccent,
              radius: compactBotFrame ? 16 : 18,
              borderWidth: boardBorderWidth,
              fillColor: arcade.panelAlt,
            )
          : BoxDecoration(
              border: Border.all(
                color: Colors.white10,
                width: boardBorderWidth,
              ),
              borderRadius: BorderRadius.circular(4),
            ),
      padding: _isBotMatchMode
          ? EdgeInsets.all(boardInnerPadding)
          : EdgeInsets.zero,
      child: ClipRRect(
        borderRadius: BorderRadius.circular(innerBoardRadius),
        child: LayoutBuilder(
          builder: (context, boardConstraints) {
            final boardSize = Size(
              boardConstraints.maxWidth,
              boardConstraints.maxHeight,
            );
            return Listener(
              behavior: HitTestBehavior.deferToChild,
              onPointerDown: (event) {
                _lastEditDragEraseSquare = null;
                _handleEditEraserPointer(
                  event.localPosition,
                  boardSize,
                  reverse,
                );
              },
              onPointerMove: (event) => _handleEditEraserPointer(
                event.localPosition,
                boardSize,
                reverse,
              ),
              onPointerUp: (_) => _lastEditDragEraseSquare = null,
              onPointerCancel: (_) => _lastEditDragEraseSquare = null,
              child: GridView.builder(
                physics: const NeverScrollableScrollPhysics(),
                gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                  crossAxisCount: 8,
                ),
                itemCount: 64,
                itemBuilder: (context, i) {
                  final visualFile = i % 8;
                  final visualRankFromTop = i ~/ 8;
                  int row = reverse ? (i ~/ 8) : (7 - i ~/ 8);
                  int col = reverse ? (7 - i % 8) : (i % 8);
                  String sq =
                      String.fromCharCode(97 + col) + (row + 1).toString();
                  bool isDark = (row + col) % 2 == 0;
                  String? p = boardState[sq];
                  final showFileLabel = visualRankFromTop == 7;
                  final showRankLabel = visualFile == 0;
                  final labelColor = isDark
                      ? lightSquareColor
                      : darkSquareColor;
                  final isGambitSelected = _gambitSelectedFrom == sq;
                  final isHoldSelected = _holdSelectedFrom == sq;
                  final isLegalTarget = _legalTargets.contains(sq);
                  final isGambitAvailableTarget = _gambitAvailableTargets
                      .contains(sq);
                  final showOpeningSelectionDots =
                      _isOpeningSelectionMode && isGambitAvailableTarget;
                  final showLockedLegalDots =
                      !_isAnalysisEditModeActive && !_isOpeningSelectionMode;
                  final showTargetDot =
                      isLegalTarget &&
                      (showOpeningSelectionDots || showLockedLegalDots);
                  final isCaptureTarget = isLegalTarget && p != null;
                  final isCheckedKingSquare = checkedKingSquares.contains(sq);
                  final showMoveQualityBadge =
                      activeMoveQuality != null &&
                      activeMoveQualitySquare == sq;
                  final canHumanDragPiece = _canHumanInteractWithBoardPiece(p);
                  const legalDotBase = Color(0xFF9EA8BA);

                  return DragTarget<_BoardDragPayload>(
                    onAcceptWithDetails: (d) {
                      if (_isOpeningSelectionMode && _selectedGambit == null) {
                        final fromSquare = d.data.fromSquare;
                        if (fromSquare != null) {
                          _handleGambitDragDrop(fromSquare, sq);
                        }
                        return;
                      }
                      final fromSquare = d.data.fromSquare;
                      if (fromSquare != null) {
                        unawaited(_attemptMove(fromSquare, sq));
                        return;
                      }
                      if (_isAnalysisEditModeActive &&
                          !_isOpeningSelectionMode) {
                        _placeEditModePiece(d.data.piece, sq);
                      }
                    },
                    builder: (context, candidateData, rejectedData) =>
                        Container(
                          decoration: BoxDecoration(
                            color: isDark ? darkSquareColor : lightSquareColor,
                            border: (isGambitSelected || isHoldSelected)
                                ? Border.all(
                                    color: _openingSelectionAccent,
                                    width: 2,
                                  )
                                : null,
                          ),
                          child: GestureDetector(
                            behavior: HitTestBehavior.opaque,
                            onTap: () => _blocksDirectBoardMoveSelection
                                ? _handleBoardTap(sq)
                                : _handleHoldTap(sq),
                            onLongPress: () {
                              if (_blocksDirectBoardMoveSelection) return;
                              if (!canHumanDragPiece) return;
                              setState(() {
                                _holdSelectedFrom = sq;
                                _gambitSelectedFrom = null;
                                _legalTargets
                                  ..clear()
                                  ..addAll(
                                    _isAnalysisEditModeActive
                                        ? <String>{}
                                        : _legalMovesFrom(sq),
                                  );
                              });
                            },
                            child: Stack(
                              fit: StackFit.expand,
                              children: [
                                if (showMoveQualityBadge)
                                  Positioned(
                                    top: 2,
                                    right: 2,
                                    child: Container(
                                      padding: const EdgeInsets.symmetric(
                                        horizontal: 4,
                                        vertical: 1,
                                      ),
                                      decoration: BoxDecoration(
                                        color: Colors.black.withValues(
                                          alpha: _isBotMatchMode ? 0.72 : 0.56,
                                        ),
                                        borderRadius: BorderRadius.circular(7),
                                        border: Border.all(
                                          color: activeMoveQuality.color
                                              .withValues(
                                                alpha: useMonochrome
                                                    ? 0.0
                                                    : 0.55,
                                              ),
                                        ),
                                        boxShadow: [
                                          BoxShadow(
                                            color: useMonochrome
                                                ? Colors.black.withValues(
                                                    alpha: 0.18,
                                                  )
                                                : activeMoveQuality.color
