                                  ),
                                if (isCheckedKingSquare)
                                  Positioned.fill(
                                    child: IgnorePointer(
                                      child: Padding(
                                        padding: EdgeInsets.all(
                                          _isBotMatchMode ? 4.0 : 3.5,
                                        ),
                                        child: DecoratedBox(
                                          decoration: BoxDecoration(
                                            borderRadius: BorderRadius.circular(
                                              _isBotMatchMode ? 9 : 7,
                                            ),
                                            gradient: RadialGradient(
                                              colors: [
                                                const Color(
                                                  0xFFEA4E4E,
                                                ).withValues(alpha: 0.16),
                                                const Color(
                                                  0xFFEA4E4E,
                                                ).withValues(alpha: 0.04),
                                                Colors.transparent,
                                              ],
                                              stops: const [0.0, 0.56, 1.0],
                                            ),
                                            border: Border.all(
                                              color: const Color(
                                                0xFFEA4E4E,
                                              ).withValues(alpha: 0.96),
                                              width: _isBotMatchMode
                                                  ? 2.2
                                                  : 2.0,
                                            ),
                                            boxShadow: [
                                              BoxShadow(
                                                color: const Color(
                                                  0xFFEA4E4E,
                                                ).withValues(alpha: 0.22),
                                                blurRadius: 12,
                                                spreadRadius: 0.4,
                                              ),
                                            ],
                                          ),
                                        ),
                                      ),
                                    ),
                                  ),
                                if (showFileLabel || showRankLabel)
                                  Positioned(
                                    left: 3,
                                    bottom: 2,
                                    child: Column(
                                      crossAxisAlignment:
                                          CrossAxisAlignment.start,
                                      mainAxisSize: MainAxisSize.min,
                                      children: [
                                        if (showRankLabel)
                                          Text(
                                            (row + 1).toString(),
                                            style: TextStyle(
                                              fontSize: 8,
                                              height: 1,
                                              letterSpacing: 0.1,
                                              fontWeight: FontWeight.w600,
                                              color: labelColor.withValues(
                                                alpha: 0.92,
                                              ),
                                            ),
                                          ),
                                        if (showFileLabel)
                                          Text(
                                            String.fromCharCode(97 + col),
                                            style: TextStyle(
                                              fontSize: 8,
                                              height: 1,
                                              letterSpacing: 0.1,
                                              fontWeight: FontWeight.w600,
                                              color: labelColor.withValues(
                                                alpha: 0.92,
                                              ),
                                            ),
                                          ),
                                      ],
                                    ),
                                  ),
                                if (p != null)
                                  Center(
                                    child: Draggable<_BoardDragPayload>(
                                      maxSimultaneousDrags: canHumanDragPiece
                                          ? 1
                                          : 0,
                                      data: _BoardDragPayload.fromBoard(
                                        fromSquare: sq,
                                        piece: p,
                                      ),
                                      feedback: _buildPieceGlow(
                                        p,
                                        motionSeed: sq,
                                      ),
                                      onDragStarted: () {
                                        if (!canHumanDragPiece) {
                                          return;
                                        }
                                        setState(() {
                                          if (_isOpeningSelectionMode) {
                                            _selectGambitSource(sq);
                                          } else {
                                            _holdSelectedFrom = sq;
                                            _gambitSelectedFrom = null;
                                            _legalTargets
                                              ..clear()
                                              ..addAll(
                                                _isAnalysisEditModeActive
                                                    ? <String>{}
                                                    : _legalMovesFrom(sq),
                                              );
                                            _gambitAvailableTargets.clear();
                                          }
                                        });
                                      },
                                      onDragEnd: (details) {
                                        if (!details.wasAccepted) {
                                          setState(() {
                                            _holdSelectedFrom = null;
                                            _gambitSelectedFrom = null;
                                            _legalTargets.clear();
                                            _gambitAvailableTargets.clear();
                                          });
                                        }
                                      },
                                      childWhenDragging: Opacity(
                                        opacity: 0.2,
                                        child: _pieceImage(
                                          p,
                                          orientForHeadToHeadPerspective: true,
                                          motionSeed: '$sq-dragging',
                                        ),
                                      ),
                                      child: () {
                                        String? glowColor;
                                        if (_isOpeningSelectionMode &&
                                            _gambitSelectedFrom == sq) {
                                          glowColor = _isGambitsOnlyOpeningMode
                                              ? 'violet'
                                              : 'yellow';
                                        } else if (previewMoveSquares.contains(
                                          sq,
                                        )) {
                                          glowColor = hasSacrificePreview
                                              ? 'red'
                                              : _isGambitsOnlyOpeningMode
                                              ? 'violet'
                                              : 'yellow';
                                        } else if (openingOptionSourceSquares
                                            .contains(sq)) {
                                          glowColor = 'yellow';
                                        }
                                        return _buildPieceWithGlow(
                                          p,
                                          glowColor,
                                          motionSeed: sq,
                                        );
                                      }(),
                                    ),
                                  ),
                              ],
                            ),
                          ),
                        ),
                  );
                },
              ),
            );
          },
        ),
      ),
    );
  }

