  bool get _showsFriendClockPanels =>
      (_isLocalFriendMatchMode && _hasTimedLocalFriendClock) ||
      (_isRemoteFriendMatchMode && _remoteFriendSnapshot != null);

  Widget _buildRemoteFriendClockStrip({required bool isLandscape}) {
    if (!_isRemoteFriendMatchMode || !_showsFriendClockPanels) {
      return const SizedBox.shrink();
    }

    final spacing = isLandscape ? 10.0 : 12.0;

    return Padding(
      padding: EdgeInsets.symmetric(horizontal: isLandscape ? 0 : 12),
      child: Row(
        children: [
          Expanded(
            child: _buildRemoteFriendClockCard(
              white: _friendClockTopShowsWhite,
            ),
          ),
          SizedBox(width: spacing),
          Expanded(
            child: _buildRemoteFriendClockCard(
              white: _friendClockBottomShowsWhite,
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildFriendClockPanel({
    required bool white,
    required bool isLandscape,
  }) {
    final card = _isLocalFriendMatchMode
        ? _buildLocalFriendClockCard(white: white)
        : _isRemoteFriendMatchMode
        ? _buildRemoteFriendClockCard(white: white)
        : null;
    if (card == null) {
      return const SizedBox.shrink();
    }

    final facesOppositePlayer =
        _isLocalFriendMatchMode && white == _friendClockTopShowsWhite;

    return Padding(
      padding: EdgeInsets.symmetric(horizontal: isLandscape ? 0 : 12),
      child: Align(
        alignment: Alignment.center,
        child: facesOppositePlayer
            ? Transform.rotate(angle: pi, child: card)
            : card,
      ),
    );
  }

  int _clockLowTimeWarningThresholdMs(Duration initialTime) {
    final warningSeconds = max(
      12,
      min(90, (initialTime.inSeconds / 6).round()),
    );
    return warningSeconds * Duration.millisecondsPerSecond;
  }

  int _clockCriticalTimeWarningThresholdMs(Duration initialTime) {
    final criticalSeconds = max(
      5,
      min(30, (initialTime.inSeconds / 12).round()),
    );
    return criticalSeconds * Duration.millisecondsPerSecond;
  }

  double _clockLowTimePulseStrength({
    required Duration remaining,
    required Duration? initialTime,
  }) {
    if (initialTime == null || initialTime <= Duration.zero) {
      return 0;
    }

    final remainingMs = max(0, remaining.inMilliseconds);
    final warningThresholdMs = _clockLowTimeWarningThresholdMs(initialTime);
    if (remainingMs >= warningThresholdMs) {
      return 0;
    }

    final pulse = (sin(_pulseController.value * pi * 2) + 1) / 2;
    final warningProgress =
        1 - (remainingMs / warningThresholdMs).clamp(0.0, 1.0);
    var strength =
        Curves.easeOut.transform(warningProgress.clamp(0.0, 1.0)) *
        (0.12 + pulse * 0.12);

    final criticalThresholdMs = _clockCriticalTimeWarningThresholdMs(
      initialTime,
    );
    if (remainingMs <= criticalThresholdMs) {
      final criticalProgress =
          1 - (remainingMs / criticalThresholdMs).clamp(0.0, 1.0);
      strength +=
          Curves.easeOut.transform(criticalProgress.clamp(0.0, 1.0)) *
          (0.08 + pulse * 0.10);
    }

    return strength.clamp(0.0, 0.42);
  }

  Widget _buildRemoteFriendClockCard({required bool white}) {
    final snapshot = _remoteFriendSnapshot;
    if (snapshot == null) {
      return const SizedBox.shrink();
    }

    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final isDark = theme.brightness == Brightness.dark;
    final useMonochrome =
        context.watch<AppThemeProvider>().isMonochrome ||
        _isCinematicThemeEnabled;
    final seat = white ? RemoteFriendSeat.white : RemoteFriendSeat.black;
    final occupantUid = white ? snapshot.whiteUid : snapshot.blackUid;
    final isLocalSeat =
        occupantUid != null && occupantUid == _remoteFriendLocalUid;
    final isActive =
        _gameOutcome == null &&
        snapshot.status == RemoteFriendMatchStatus.active &&
        (snapshot.activeClockSeat == seat ||
            (!_isRemoteFriendTimedMatch && snapshot.whiteToMove == white));
    final isWinner =
        _gameOutcome != null &&
        ((white && _gameOutcome == GameOutcome.whiteWin) ||
            (!white && _gameOutcome == GameOutcome.blackWin));
    final isLoser =
        _gameOutcome != null &&
        ((white && _gameOutcome == GameOutcome.blackWin) ||
            (!white && _gameOutcome == GameOutcome.whiteWin));
    final accent = isWinner
        ? _remoteFriendReadyAccent(scheme, useMonochrome: useMonochrome)
        : isLoser
        ? _remoteFriendDangerAccent(scheme, useMonochrome: useMonochrome)
        : isActive
        ? (isLocalSeat
              ? _remoteFriendLocalAccent(scheme, useMonochrome: useMonochrome)
              : _remoteFriendOpponentAccent(
                  scheme,
                  useMonochrome: useMonochrome,
                ))
        : isLocalSeat
        ? scheme.onSurface.withValues(alpha: 0.84)
        : scheme.onSurface.withValues(alpha: 0.68);
    final roleLabel = occupantUid == null
        ? 'OPEN'
        : isLocalSeat
        ? 'YOU'
        : 'FRIEND';
    final label = '$roleLabel | ${white ? 'WHITE' : 'BLACK'}';
    final detail = snapshot.status == RemoteFriendMatchStatus.pending
        ? (occupantUid == null
              ? 'OPEN SEAT'
              : isLocalSeat
              ? 'WAITING'
              : 'READY')
        : snapshot.status == RemoteFriendMatchStatus.expired
        ? 'EXPIRED'
        : snapshot.status == RemoteFriendMatchStatus.cancelled
        ? 'CANCELLED'
        : _gameOutcome == GameOutcome.draw
        ? 'DRAW'
        : snapshot.outcome?.reason == 'timeout'
        ? (isWinner
              ? 'WON ON TIME'
              : isLoser
              ? 'FLAGGED'
              : 'TIME')
        : snapshot.outcome?.reason == 'resignation'
        ? (isWinner
              ? 'WON'
              : isLoser
              ? 'RESIGNED'
              : 'ENDED')
        : _hasIncomingRemoteDrawOffer && isLocalSeat
        ? 'RESPOND'
        : _hasOutgoingRemoteDrawOffer && isLocalSeat
        ? 'DRAW SENT'
        : _isRemoteFriendTimedMatch
        ? (isActive ? 'TO MOVE' : 'WAITING')
        : snapshot.whiteToMove == white
        ? 'TO MOVE'
        : 'WAITING';
    final timeText = _isRemoteFriendTimedMatch
        ? _formatLocalFriendClock(_remoteFriendDisplayedClock(white: white))
        : 'UNTIMED';
    final recentReaction = _remoteFriendVisibleReactionForSnapshot(snapshot);
    final seatReaction =
        recentReaction != null &&
            occupantUid != null &&
            recentReaction.sentByUid == occupantUid
        ? recentReaction
        : null;

    return AnimatedContainer(
      duration: const Duration(milliseconds: 180),
      curve: Curves.easeOut,
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
      constraints: const BoxConstraints(minWidth: 152),
      decoration: BoxDecoration(
        color: Color.alphaBlend(
          accent.withValues(alpha: isDark ? 0.16 : 0.10),
          scheme.surface,
        ),
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: accent.withValues(alpha: 0.46), width: 1.4),
        boxShadow: [
          BoxShadow(
            color: accent.withValues(alpha: isActive ? 0.20 : 0.10),
            blurRadius: isActive ? 18 : 12,
            offset: const Offset(0, 6),
          ),
        ],
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(
            label,
            style: TextStyle(
              color: accent,
              fontSize: 10.5,
              fontWeight: FontWeight.w800,
              letterSpacing: 0.6,
            ),
          ),
          const SizedBox(height: 4),
          Text(
            timeText,
            style: TextStyle(
              color: scheme.onSurface,
              fontSize: 18,
              fontWeight: FontWeight.w900,
              letterSpacing: 0.3,
            ),
          ),
          const SizedBox(height: 2),
          Text(
            detail,
            style: TextStyle(
              color: scheme.onSurface.withValues(alpha: 0.66),
              fontSize: 10.5,
              fontWeight: FontWeight.w700,
              letterSpacing: 0.4,
            ),
          ),
          if (seatReaction != null)
            _remoteFriendReactionClockBadge(
              emoji: seatReaction.emoji,
              label: isLocalSeat ? 'You reacted' : 'Friend reacted',
              accent: accent,
            ),
        ],
      ),
    );
  }

  Widget _buildLocalFriendClockCard({required bool white}) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final isDark = theme.brightness == Brightness.dark;
    final useMonochrome =
        context.watch<AppThemeProvider>().isMonochrome ||
        _isCinematicThemeEnabled;
    final isActive =
        _gameOutcome == null && _localFriendActiveClockIsWhite == white;
    final isWinner =
        _gameOutcome != null &&
        ((white && _gameOutcome == GameOutcome.whiteWin) ||
            (!white && _gameOutcome == GameOutcome.blackWin));
    final isLoser =
        _gameOutcome != null &&
        ((white && _gameOutcome == GameOutcome.blackWin) ||
            (!white && _gameOutcome == GameOutcome.whiteWin));
    final accent = isWinner
        ? const Color(0xFF58E09A)
        : isLoser
        ? const Color(0xFFE45C5C)
        : isActive
        ? (white
              ? (useMonochrome ? scheme.onSurface : const Color(0xFF5AAEE8))
              : (useMonochrome ? scheme.onSurface : const Color(0xFFD8B640)))
        : scheme.onSurface.withValues(alpha: 0.72);
    final label =
        '${_localFriendSeatLabelForColor(white)} | ${white ? 'WHITE' : 'BLACK'}';
    final seatScore = _localFriendSeatScoreForColor(white);
    final detail = _gameOutcome == null
        ? (_hasTimedLocalFriendClock
              ? (isActive ? 'TO MOVE' : 'WAITING')
              : 'UNTIMED')
        : _gameOutcome == GameOutcome.draw
        ? 'DRAW'
        : _localFriendEndedOnTime
        ? (isWinner ? 'WON ON TIME' : 'FLAGGED')
        : (isWinner ? 'WINNER' : 'CHECKMATED');

    return AnimatedBuilder(
      animation: _pulseController,
      builder: (context, child) {
        final remaining = _hasTimedLocalFriendClock
            ? _localFriendDisplayedClock(white: white)
            : Duration.zero;
        final warningStrength = isActive && _gameOutcome == null
            ? _clockLowTimePulseStrength(
                remaining: remaining,
                initialTime: _selectedLocalFriendTimeControl.initialTime,
              )
            : 0.0;
        const warningColor = Color(0xFFE66565);
        final displayAccent =
            Color.lerp(accent, warningColor, warningStrength) ?? accent;
        final fillColor = Color.alphaBlend(
          Color.lerp(
                accent.withValues(alpha: isDark ? 0.16 : 0.10),
                warningColor.withValues(alpha: isDark ? 0.22 : 0.14),
                warningStrength,
              ) ??
              accent.withValues(alpha: isDark ? 0.16 : 0.10),
          scheme.surface,
        );
        final borderColor =
            Color.lerp(
              accent.withValues(alpha: 0.46),
              warningColor.withValues(alpha: isDark ? 0.70 : 0.58),
              warningStrength,
            ) ??
            accent.withValues(alpha: 0.46);
        final shadowColor =
            Color.lerp(
              accent.withValues(alpha: isActive ? 0.20 : 0.10),
              warningColor.withValues(alpha: isActive ? 0.24 : 0.12),
              warningStrength,
            ) ??
            accent.withValues(alpha: isActive ? 0.20 : 0.10);
        final timeTextColor =
            Color.lerp(
              scheme.onSurface,
              warningColor.withValues(alpha: 0.96),
              warningStrength * 0.24,
            ) ??
            scheme.onSurface;
        final detailColor =
            Color.lerp(
              scheme.onSurface.withValues(alpha: 0.66),
              warningColor.withValues(alpha: 0.88),
              warningStrength * 0.16,
            ) ??
            scheme.onSurface.withValues(alpha: 0.66);
        final timeText = _hasTimedLocalFriendClock
            ? _formatLocalFriendClock(remaining)
            : 'UNTIMED';

        return Container(
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
          constraints: const BoxConstraints(minWidth: 136),
          decoration: BoxDecoration(
            color: fillColor,
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: borderColor, width: 1.4),
            boxShadow: [
              BoxShadow(
                color: shadowColor,
                blurRadius: isActive ? 18 + warningStrength * 5 : 12,
                offset: const Offset(0, 6),
              ),
            ],
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              SizedBox(
                width: double.infinity,
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Flexible(
                      child: Text(
                        label,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          color: displayAccent,
                          fontSize: 11,
                          fontWeight: FontWeight.w800,
                          letterSpacing: 0.7,
                        ),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 6,
                        vertical: 3,
                      ),
                      decoration: BoxDecoration(
                        color: displayAccent.withValues(
                          alpha: isDark ? 0.20 : 0.12,
                        ),
                        borderRadius: BorderRadius.circular(999),
                        border: Border.all(
                          color: displayAccent.withValues(alpha: 0.34),
                        ),
                      ),
                      child: Text(
                        'S $seatScore',
                        style: TextStyle(
                          color: displayAccent,
                          fontSize: 9.2,
                          fontWeight: FontWeight.w800,
                          letterSpacing: 0.42,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 4),
              Text(
                timeText,
                style: TextStyle(
                  color: timeTextColor,
                  fontSize: 18,
                  fontWeight: FontWeight.w900,
                  letterSpacing: 0.3,
                ),
              ),
              const SizedBox(height: 2),
              Text(
                detail,
                style: TextStyle(
                  color: detailColor,
                  fontSize: 10.5,
                  fontWeight: FontWeight.w700,
                  letterSpacing: 0.4,
                ),
              ),
            ],
          ),
        );
      },
    );
  }

  Widget _buildEditToolboxPieceTile(
    _EditToolboxPiece entry, {
    required double tileSize,
    required double pieceSize,
    required double feedbackSize,
  }) {
    final theme = Theme.of(context);
    final scheme = Theme.of(context).colorScheme;
    final isDark = theme.brightness == Brightness.dark;
    final isSelected = _selectedEditToolboxPiece == entry.piece;
    final borderRadius = tileSize >= 60 ? 16.0 : 12.0;
    final accentColor = isDark
        ? const Color(0xFFFFD166)
        : const Color(0xFFB77912);
    final tileBackgroundColor = Color.alphaBlend(
      scheme.surface.withValues(alpha: isDark ? 0.74 : 0.90),
      isDark ? const Color(0xFF11161F) : Colors.white,
    );

    return Tooltip(
      message: entry.label,
      waitDuration: const Duration(milliseconds: 400),
      child: Draggable<_BoardDragPayload>(
        data: _BoardDragPayload.palette(piece: entry.piece),
        feedback: Material(
          color: Colors.transparent,
          child: SizedBox(
            width: feedbackSize,
            height: feedbackSize,
            child: Center(
              child: _pieceImage(
                entry.piece,
                width: pieceSize + 10,
                height: pieceSize + 10,
              ),
            ),
          ),
        ),
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: () => _toggleEditToolboxSelection(entry.piece),
          child: AnimatedContainer(
            duration: const Duration(milliseconds: 140),
            width: tileSize,
            height: tileSize,
            alignment: Alignment.center,
            decoration: BoxDecoration(
              color: isSelected
                  ? Color.alphaBlend(
                      accentColor.withValues(alpha: isDark ? 0.18 : 0.20),
                      tileBackgroundColor,
                    )
                  : tileBackgroundColor,
              borderRadius: BorderRadius.circular(borderRadius),
              border: Border.all(
                color: isSelected
                    ? accentColor.withValues(alpha: isDark ? 0.88 : 0.70)
                    : scheme.outline.withValues(alpha: isDark ? 0.24 : 0.32),
                width: isSelected ? 1.4 : 1,
              ),
              boxShadow: isSelected
                  ? [
                      BoxShadow(
                        color: accentColor.withValues(
                          alpha: isDark ? 0.18 : 0.14,
                        ),
                        blurRadius: 10,
                        offset: const Offset(0, 3),
                      ),
                    ]
                  : const <BoxShadow>[],
            ),
            child: _pieceImage(
              entry.piece,
              width: pieceSize,
              height: pieceSize,
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildEditModeToolbox({required bool isLandscape}) {
    if (!_isAnalysisEditModeActive) {
      return const SizedBox.shrink();
    }
    final theme = Theme.of(context);
    final scheme = Theme.of(context).colorScheme;
    final isDark = theme.brightness == Brightness.dark;
    final accentColor = isDark
        ? const Color(0xFFFFD166)
        : const Color(0xFFB77912);
    final panelBackgroundColor = Color.alphaBlend(
      scheme.surface.withValues(alpha: isDark ? 0.82 : 0.96),
      isDark ? const Color(0xFF0F141C) : Colors.white,
    );
    final panelBorderColor = accentColor.withValues(
      alpha: isDark ? 0.38 : 0.28,
    );
    final actionButtonColor = Color.alphaBlend(
      scheme.surface.withValues(alpha: isDark ? 0.70 : 0.92),
      isDark ? const Color(0xFF121821) : Colors.white,
    );
    final whitePieces = _editToolboxPieces
        .where((entry) => entry.piece.endsWith('_w'))
        .toList(growable: false);
    final blackPieces = _editToolboxPieces
        .where((entry) => entry.piece.endsWith('_b'))
        .toList(growable: false);

    return Material(
      color: Colors.transparent,
      child: Container(
        padding: EdgeInsets.fromLTRB(
          isLandscape ? 12 : 14,
          isLandscape ? 10 : 12,
          isLandscape ? 12 : 14,
          isLandscape ? 10 : 12,
        ),
        decoration: BoxDecoration(
          color: panelBackgroundColor,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: panelBorderColor, width: 1.2),
          boxShadow: [
            BoxShadow(
              color: scheme.shadow.withValues(alpha: isDark ? 0.30 : 0.14),
              blurRadius: 20,
              offset: const Offset(0, 8),
            ),
          ],
        ),
        child: LayoutBuilder(
          builder: (context, toolboxConstraints) {
            final sectionSpacing = isLandscape ? 8.0 : 8.0;
            final columnsPerRow = isLandscape ? 3 : 5;
            final widthBasedTileSize =
                ((toolboxConstraints.maxWidth -
                            (sectionSpacing * (columnsPerRow - 1))) /
                        columnsPerRow)
                    .clamp(isLandscape ? 48.0 : 48.0, isLandscape ? 60.0 : 68.0)
                    .toDouble();
            final maxHeight = toolboxConstraints.maxHeight;
            final fixedHeightBudget =
                42.0 +
                18.0 +
                (isLandscape ? sectionSpacing * 2 : 12.0) +
                (isLandscape ? 12.0 : 0.0);
            final heightBasedTileSize = maxHeight.isFinite
                ? ((maxHeight - fixedHeightBudget) / (isLandscape ? 4 : 2))
                      .clamp(
                        isLandscape ? 44.0 : 48.0,
                        isLandscape ? 60.0 : 68.0,
                      )
                      .toDouble()
                : widthBasedTileSize;
            final tileSize = min(
              widthBasedTileSize,
              heightBasedTileSize,
            ).toDouble();
            final pieceSize = (tileSize * (isLandscape ? 0.62 : 0.60))
                .clamp(30.0, 42.0)
                .toDouble();
            final feedbackSize = (tileSize + (isLandscape ? 10.0 : 8.0))
                .clamp(56.0, 78.0)
                .toDouble();

            Widget buildActionButton({
              required Widget child,
              required String tooltip,
              required VoidCallback onPressed,
              bool selected = false,
            }) {
              return Tooltip(
                message: tooltip,
                waitDuration: const Duration(milliseconds: 300),
                child: Material(
                  color: Colors.transparent,
                  child: InkWell(
                    onTap: onPressed,
                    borderRadius: BorderRadius.circular(12),
                    child: AnimatedContainer(
                      duration: const Duration(milliseconds: 140),
                      width: 36,
                      height: 36,
                      decoration: BoxDecoration(
                        color: selected
                            ? Color.alphaBlend(
                                accentColor.withValues(
                                  alpha: isDark ? 0.18 : 0.16,
                                ),
                                actionButtonColor,
                              )
                            : actionButtonColor,
                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(
                          color: selected
                              ? accentColor.withValues(
                                  alpha: isDark ? 0.88 : 0.68,
                                )
                              : scheme.outline.withValues(
                                  alpha: isDark ? 0.22 : 0.30,
                                ),
                        ),
                      ),
                      child: Center(child: child),
                    ),
                  ),
                ),
              );
            }

            List<List<_EditToolboxPiece>> buildRows(
              List<_EditToolboxPiece> pieces,
            ) {
              if (!isLandscape) {
                return <List<_EditToolboxPiece>>[pieces];
              }
              return <List<_EditToolboxPiece>>[
                pieces.take(3).toList(growable: false),
                pieces.skip(3).toList(growable: false),
              ];
            }

            Widget buildPieceSection(List<_EditToolboxPiece> pieces) {
              final rows = buildRows(pieces);
              return Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  for (
                    int rowIndex = 0;
                    rowIndex < rows.length;
                    rowIndex++
                  ) ...[
                    Row(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        for (
                          int pieceIndex = 0;
                          pieceIndex < rows[rowIndex].length;
                          pieceIndex++
                        ) ...[
                          _buildEditToolboxPieceTile(
                            rows[rowIndex][pieceIndex],
                            tileSize: tileSize,
                            pieceSize: pieceSize,
                            feedbackSize: feedbackSize,
                          ),
                          if (pieceIndex < rows[rowIndex].length - 1)
                            SizedBox(width: sectionSpacing),
                        ],
                      ],
                    ),
                    if (rowIndex < rows.length - 1)
                      SizedBox(height: sectionSpacing),
                  ],
                ],
              );
            }

            return Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Expanded(
                      child: Align(
                        alignment: Alignment.centerLeft,
                        child: TextButton(
                          onPressed: _confirmCleanEditBoard,
                          style: TextButton.styleFrom(
                            foregroundColor: accentColor,
                            padding: const EdgeInsets.symmetric(
                              horizontal: 10,
                              vertical: 8,
                            ),
                            minimumSize: Size.zero,
                            tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                            visualDensity: VisualDensity.compact,
                          ),
                          child: const Text('Clear'),
                        ),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Tooltip(
                      message: _isWhiteTurn
                          ? 'Switch turn (white to move)'
                          : 'Switch turn (black to move)',
                      waitDuration: const Duration(milliseconds: 300),
                      child: GestureDetector(
                        onTap: _toggleEditToolboxTurn,
                        child: SizedBox(
                          width: 36,
                          height: 36,
                          child: Center(
                            child: Padding(
                              padding: const EdgeInsets.all(1.4),
                              child: Image.asset(
                                'assets/pieces/switch.png',
                                fit: BoxFit.contain,
                              ),
                            ),
                          ),
                        ),
                      ),
                    ),
                    const SizedBox(width: 6),
                    Tooltip(
                      message: 'Erase pieces',
                      waitDuration: const Duration(milliseconds: 300),
                      child: GestureDetector(
                        onTap: _toggleEditToolboxEraser,
                        child: AnimatedContainer(
                          duration: const Duration(milliseconds: 140),
                          width: 36,
                          height: 36,
                          decoration: BoxDecoration(
                            boxShadow: _editToolboxEraserSelected
                                ? <BoxShadow>[
                                    BoxShadow(
                                      color: accentColor.withValues(
                                        alpha: 0.30,
                                      ),
                                      blurRadius: 14,
                                      spreadRadius: 1.5,
                                    ),
                                  ]
                                : null,
                          ),
                          child: Center(
                            child: Padding(
                              padding: const EdgeInsets.all(5.0),
                              child: Image.asset(
                                'assets/pieces/eraser.png',
                                fit: BoxFit.contain,
                              ),
                            ),
                          ),
                        ),
                      ),
                    ),
                    const SizedBox(width: 6),
                    buildActionButton(
                      child: Icon(
                        Icons.close_rounded,
                        color: scheme.onSurface.withValues(
                          alpha: isDark ? 0.82 : 0.74,
                        ),
                        size: 20,
                      ),
                      tooltip: 'Close edit toolbox',
                      onPressed: () => _setAnalysisEditMode(false),
                    ),
                  ],
                ),
                const SizedBox(height: 6),
                buildPieceSection(whitePieces),
                const SizedBox(height: 10),
                buildPieceSection(blackPieces),
              ],
            );
          },
        ),
      ),
    );
  }

  Widget _buildHistoryMoveChip(MoveRecord move, bool active) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final useMonochrome =
        context.watch<AppThemeProvider>().isMonochrome ||
        _isCinematicThemeEnabled;
    final isDark = theme.brightness == Brightness.dark;

    final backgroundColor = active
        ? (useMonochrome
              ? scheme.onSurface.withValues(alpha: isDark ? 0.14 : 0.12)
              : Color.alphaBlend(
                  scheme.primary.withValues(alpha: isDark ? 0.24 : 0.18),
                  scheme.surface,
                ))
        : (useMonochrome
              ? scheme.surface.withValues(alpha: isDark ? 0.24 : 0.92)
              : scheme.surface.withValues(alpha: isDark ? 0.72 : 0.72));

    final borderColor = active
        ? (useMonochrome
              ? scheme.onSurface.withValues(alpha: 0.18)
              : scheme.primary.withValues(alpha: 0.35))
        : scheme.outline.withValues(alpha: 0.12);

    final textColor = active
        ? scheme.onSurface
        : useMonochrome
        ? scheme.onSurface.withValues(alpha: 0.70)
        : scheme.onSurface.withValues(alpha: 0.68);
    final quality = _isBotMatchMode || _runsAnalysisMoveAssessment
        ? move.quality
        : null;
    final emphasisQuality =
        quality == MoveQuality.masterstroke || quality == MoveQuality.crucial;

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
      decoration: BoxDecoration(
        color: backgroundColor,
        border: Border.all(color: borderColor),
        borderRadius: BorderRadius.circular(6),
      ),
      child: Row(
        children: [
          _pieceImage(move.pieceMoved, width: 18, height: 18),
          if (quality != null) ...[
            const SizedBox(width: 6),
            Text(
              quality.displaySymbol,
              style: TextStyle(
                color: quality.color,
                fontSize: quality == MoveQuality.oversight ? 11 : 13,
                fontWeight: emphasisQuality ? FontWeight.w900 : FontWeight.w800,
                letterSpacing: emphasisQuality ? 0.4 : 0.2,
              ),
            ),
          ],
          const SizedBox(width: 4),
          Text(move.notation, style: TextStyle(color: textColor, fontSize: 13)),
          if (move.pieceCaptured != null) ...[
            const SizedBox(width: 4),
            _pieceImage(move.pieceCaptured!, width: 16, height: 16),
          ],
        ],
      ),
    );
  }

  Widget _buildPieceGlow(String p, {String? motionSeed}) {
    final glowColor = _isSacrificeModeActive
        ? const Color(0xFFE65151)
        : _isGambitsOnlyOpeningMode
        ? const Color(0xFFB16CFF)
        : _openingMode == OpeningMode.yellowGlow
        ? const Color(0xFFFFD166)
        : const Color(0xFF5AAEE8);

    return Container(
      width: 70,
      height: 70,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        boxShadow: [
          BoxShadow(
            color: glowColor.withValues(alpha: 0.6),
            blurRadius: 25,
            spreadRadius: 5,
          ),
        ],
      ),
      child: _pieceImage(
        p,
        orientForHeadToHeadPerspective: true,
        motionSeed: motionSeed,
      ),
    );
  }

  Set<String> _getPreviewMoveSqares([Iterable<EngineLine>? previewLines]) {
    final squares = <String>{};
    for (final line in previewLines ?? _openingPreviewArrowLines()) {
      if (line.move.length >= 4) {
        final from = line.move.substring(0, 2);
        final to = line.move.substring(2, 4);
        squares.add(from);
        squares.add(to);
      }
    }
    return squares;
  }

  Widget _buildPieceWithGlow(
    String piece,
    String? selectedGlowColor, {
    String? motionSeed,
  }) {
    if (selectedGlowColor == null) {
      return _pieceImage(
        piece,
        orientForHeadToHeadPerspective: true,
        motionSeed: motionSeed,
      );
    }

    final glowColor = selectedGlowColor == 'yellow'
        ? const Color(0xFFFFD166)
        : selectedGlowColor == 'violet'
        ? const Color(0xFFB16CFF)
        : selectedGlowColor == 'red'
        ? const Color(0xFFE65151)
        : const Color(0xFF5AAEE8);

    return Container(
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        boxShadow: [
          BoxShadow(
            color: glowColor.withValues(alpha: 0.7),
            blurRadius: 12,
            spreadRadius: 3,
          ),
        ],
      ),
      child: _pieceImage(
        piece,
        orientForHeadToHeadPerspective: true,
        motionSeed: motionSeed,
      ),
    );
  }

  Widget _buildAnimatedArrows(bool reverse) {
    final previewLines = _openingPreviewArrowLines();
    final lines = previewLines.isNotEmpty ? previewLines : _topLines;
    final showSequenceNumbers = previewLines.isNotEmpty;
    final hasSacrificePreview =
        _isSacrificeModeActive && previewLines.isNotEmpty;
    final previewArrowColor =
        _isGambitsOnlyOpeningMode && _gambitPreviewLines.isNotEmpty
        ? const Color(0xFFB16CFF)
        : _openingMode == OpeningMode.yellowGlow &&
              _gambitPreviewLines.isNotEmpty
        ? const Color(0xFFFFD166)
        : null;
    final previewArrowGlowColor = hasSacrificePreview
        ? const Color(0xFFE65151)
        : null;
    final boardInset = _boardGridInsetForContext(context);
    return AnimatedBuilder(
      animation: _pulseController,
      builder: (context, child) => IgnorePointer(
        child: Stack(
          fit: StackFit.expand,
          children: [
            CustomPaint(
              size: Size.infinite,
              painter: EnergyArrowPainter(
                lines: lines,
                bestEval: (_currentEval * 100).toInt(),
                progress: _pulseController.value,
                reverse: reverse,
                showSequenceNumbers: showSequenceNumbers,
                overrideColor: previewArrowColor,
                glowColor: previewArrowGlowColor,
                themeMode: _arrowThemeMode,
                pixelKnightTurnedHeadScale: previewLines.isEmpty ? 1.35 : 1.0,
                boardInset: boardInset,
              ),
            ),
            ..._botGhostArrows.map(
              (ghost) => AnimatedOpacity(
                opacity: ghost.opacity,
                duration: const Duration(milliseconds: 3000),
                curve: Curves.easeOut,
                child: CustomPaint(
                  size: Size.infinite,
                  painter: EnergyArrowPainter(
                    lines: [ghost.line],
                    bestEval: 0,
                    progress: 0,
                    reverse: reverse,
                    overrideColor: const Color(0xFF6D7482),
                    staticArrowStyle: true,
                    themeMode: _arrowThemeMode,
                    boardInset: boardInset,
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildSuggestedMovesList({
    double height = 130,
    EdgeInsets padding = const EdgeInsets.symmetric(
      vertical: 10,
      horizontal: 20,
    ),
    int? maxVisibleMoves,
    AlignmentGeometry alignment = Alignment.topCenter,
  }) {
    final suggestedLines = List<EngineLine>.from(_topLines)
      ..sort((a, b) => a.multiPv.compareTo(b.multiPv));
    final visibleLines = maxVisibleMoves == null
        ? suggestedLines
        : suggestedLines.take(maxVisibleMoves).toList(growable: false);
    final showSuggestions =
        _shouldShowVisualSuggestions && visibleLines.isNotEmpty;
    final usePixelSuggestionFont = _arrowThemeMode == ArrowThemeMode.pixel;
    const suggestionShadows = <Shadow>[
      Shadow(
        color: Color(0xFF757575),
        offset: Offset(0.5, 0.5),
        blurRadius: 0.8,
      ),
      Shadow(
        color: Color(0xFF757575),
        offset: Offset(-0.5, 0.5),
        blurRadius: 0.8,
      ),
      Shadow(
        color: Color(0xFF757575),
        offset: Offset(0.5, -0.5),
        blurRadius: 0.8,
      ),
      Shadow(
        color: Color(0xFF757575),
        offset: Offset(-0.5, -0.5),
        blurRadius: 0.8,
      ),
    ];

    TextStyle suggestionLabelStyle({
      required Color color,
      required double size,
      required FontWeight fontWeight,
    }) {
      if (usePixelSuggestionFont) {
        return GoogleFonts.pixelifySans(
          color: color,
          fontSize: size,
          fontWeight: fontWeight,
          height: 1.0,
          shadows: suggestionShadows,
        );
      }
      return TextStyle(
        color: color,
        fontSize: size,
        fontWeight: fontWeight,
        shadows: suggestionShadows,
      );
    }

    return SizedBox(
      height: height,
      child: showSuggestions
          ? Align(
              alignment: alignment,
              child: SingleChildScrollView(
                padding: padding,
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: visibleLines.map((l) {
                    String from = l.move.substring(0, 2);
                    String to = l.move.substring(2, 4);
                    String? movingPiece = boardState[from];
                    if (movingPiece == null) return const SizedBox.shrink();
                    String? capturedPiece = boardState[to];
                    bool isCapture = capturedPiece != null;
                    String pieceLetter = movingPiece.startsWith('p')
                        ? ''
                        : movingPiece[0].toUpperCase();
                    String notation = pieceLetter + (isCapture ? 'x' : '') + to;
                    Color color = _getRelativeColorForWidget(l.eval, l.multiPv);
                    double eval = l.eval / 100.0;
                    return Padding(
                      padding: const EdgeInsets.symmetric(vertical: 4),
                      child: Row(
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [
                          _pieceImage(movingPiece, width: 24, height: 24),
                          const SizedBox(width: 8),
                          Text(
                            notation,
                            style: suggestionLabelStyle(
                              color: color,
                              size: 16,
                              fontWeight: l.multiPv == 1
                                  ? FontWeight.bold
                                  : FontWeight.normal,
                            ),
                          ),
                          if (isCapture) ...[
                            const SizedBox(width: 8),
                            _pieceImage(capturedPiece, width: 20, height: 20),
                          ],
                          const SizedBox(width: 8),
                          Text(
                            eval >= 0
                                ? '+${eval.toStringAsFixed(2)}'
                                : eval.toStringAsFixed(2),
                            style: suggestionLabelStyle(
                              color: color,
                              size: 14,
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                        ],
                      ),
                    );
                  }).toList(),
                ),
              ),
            )
          : const SizedBox.shrink(),
    );
  }

  Color _getRelativeColorForWidget(int currentEval, int multiPv) {
    if (multiPv == 1) return const Color(0xFF00FF88);
    int loss = ((_currentEval * 100).toInt() - currentEval).abs();
    if (loss < 30) return const Color(0xFF00FF88).withValues(alpha: 0.7);
    if (loss < 100) return Colors.yellowAccent;
    if (loss < 250) return Colors.orangeAccent;
    return Colors.redAccent;
  }

  Widget _buildHistoryBar({
    double height = 60,
    EdgeInsets margin = const EdgeInsets.symmetric(vertical: 10),
  }) {
    return Container(
      height: height,
      margin: margin,
      child: ListView.builder(
        controller: _historyScrollController,
        scrollDirection: Axis.horizontal,
        padding: const EdgeInsets.symmetric(horizontal: 20),
        itemCount: _moveHistory.length,
        itemBuilder: (context, i) {
          final m = _moveHistory[i];
          bool active = i == _historyIndex;
          return GestureDetector(
            onTap: () => _jumpToMove(i),
            child: _buildHistoryMoveChip(m, active),
          );
        },
      ),
    );
  }

  void _undoBotTurn() {
    if (!_isBotMatchMode || _moveHistory.isEmpty) return;

    _send('stop');
    _cancelGameResultReveal();
    final preserveSpentPowerCharge =
        _vsBotOptimalLineRevealActive && _isHumanTurnInBotGame;
    final chargeAtUndo = _vsBotCharge;
    int? restoredCharge;
    setState(() {
      _botThinking = false;
      _botSearchHandle = null;
      _botSearchCompleter = null;
      _pendingMoveQualityGrading = null;
      _vsBotOptimalLineRevealActive = false;
      _clearMoveQualityOverlay();
      _clearMoveQualityBadge();

      int safety = 4;
      do {
        final removed = _moveHistory.removeLast();
        _popLastDerivedDrawState();
        if (removed.isWhite == _humanPlaysWhite) {
          restoredCharge = removed.chargeBefore;
        }
        _historyIndex = _moveHistory.length - 1;

        if (_moveHistory.isEmpty) {
          boardState = _initialBoardState();
          _isWhiteTurn = true;
          _resetSpecialMoveState();
        } else {
          boardState = Map.from(_moveHistory.last.state);
          _isWhiteTurn = !_moveHistory.last.isWhite;
          _restoreSpecialMoveStateFromRecord(_moveHistory.last);
        }
        safety -= 1;
      } while (_moveHistory.isNotEmpty && !_isHumanTurnInBotGame && safety > 0);

      _currentOpening = _findOpeningFromHistory();
      _holdSelectedFrom = null;
      _gambitSelectedFrom = null;
      _legalTargets.clear();
      _gambitAvailableTargets.clear();
      _selectedGambit = null;
      _gambitPreviewLines = [];
      _openingMode = OpeningMode.off;
      _topLines = [];
      _analysisLines = [];
      _analysisLinesFen = null;
      _clearGameOutcomeState();
      _gameResultDialogVisible = false;
      _restoreCachedEvalForFen(_genFen());
      _vsBotCharge = preserveSpentPowerCharge
          ? chargeAtUndo
          : restoredCharge ??
                (_moveHistory.isEmpty
                    ? 0
                    : (_moveHistory.last.chargeAfter ?? 0));
    });

    _refreshAnalysisForCurrentPosition();
    unawaited(_maybeTriggerBotMove());
  }

  Widget _buildVsBotControlButton({
    Key? controlKey,
    required IconData icon,
    required VoidCallback? onTap,
    required Color accent,
  }) {
    final media = MediaQuery.of(context);
    final useMonochrome =
        context.watch<AppThemeProvider>().isMonochrome ||
        _isCinematicThemeEnabled;
    final arcade = _vsBotArcadePaletteFor(context, monochrome: useMonochrome);
    final compactControl =
        media.size.width <= 390 ||
        (media.orientation == Orientation.landscape &&
            media.size.height <= 430);
    final controlSize = compactControl ? 52.0 : 56.0;
    final controlRadius = compactControl ? 16.0 : 18.0;
    final readableAccent = _vsBotReadableAccentColor(accent, arcade);
    final panelRadius = BorderRadius.circular(controlRadius);

    return AnimatedOpacity(
      opacity: onTap == null ? 0.42 : 1.0,
      duration: const Duration(milliseconds: 150),
      child: SizedBox(
        key: controlKey,
        width: controlSize,
        height: controlSize,
        child: puzzleAcademyDecoratedInkWell(
          decoration: _vsBotArcadePanelDecoration(
            palette: arcade,
            accent: accent,
            radius: controlRadius,
            borderWidth: 2.4,
            inset: true,
            elevated: onTap != null,
            fillColor: arcade.panelAlt,
          ),
          borderRadius: panelRadius,
          onTap: onTap,
          overlayColor: puzzleAcademyInteractiveOverlay(
            palette: arcade.base,
            accent: accent,
          ),
          child: SizedBox.expand(
            child: Center(
              child: Icon(
                icon,
                color: onTap == null ? arcade.textMuted : readableAccent,
                size: compactControl ? 22 : 24,
              ),
            ),
          ),
        ),
      ),
    );
  }

