  Widget _buildBotUndoButton() {
    final useMonochrome =
        context.watch<AppThemeProvider>().isMonochrome ||
        _isCinematicThemeEnabled;
    final arcade = _vsBotArcadePaletteFor(context, monochrome: useMonochrome);
    final undoAccent = _selectedBot == null
        ? arcade.cyan
        : Color.lerp(
            _vsBotProfileAccent(_selectedBot!.profile, arcade),
            _botDifficultyColor(_selectedBotDifficulty),
            0.35,
          )!;

    return _buildVsBotControlButton(
      icon: Icons.undo_rounded,
      onTap: _moveHistory.isNotEmpty ? _undoBotTurn : null,
      accent: undoAccent,
    );
  }

  Widget _buildActionArea({double compactBottom = 20, double horizontal = 20}) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final isLight = theme.brightness == Brightness.light;
    final media = MediaQuery.of(context);
    final isLandscape = media.orientation == Orientation.landscape;
    final compactRemoteActionPanel =
        _isRemoteFriendMatchMode &&
        ((!isLandscape && media.size.width <= 430) ||
            (isLandscape && media.size.height <= 500));
    final endedOutcome = _gameOutcome;

    Widget buildEndMatchButton({
      required Color accent,
      required Color background,
      required Color foreground,
      required Color borderColor,
      required TextStyle titleStyle,
      required TextStyle subtitleStyle,
      required IconData icon,
      required String resultTitle,
      required String resultSubtitle,
    }) {
      final buttonRadius = BorderRadius.circular(18);
      return SizedBox(
        width: double.infinity,
        child: puzzleAcademyDecoratedInkWell(
          decoration: BoxDecoration(
            color: background,
            borderRadius: buttonRadius,
            border: Border.all(color: borderColor, width: 2.2),
            boxShadow: [
              BoxShadow(
                color: accent.withValues(alpha: 0.18),
                blurRadius: 18,
                offset: const Offset(0, 8),
              ),
            ],
          ),
          borderRadius: buttonRadius,
          onTap: _gameResultDialogVisible || endedOutcome == null
              ? null
              : () => unawaited(_showGameResultDialog(endedOutcome)),
          child: Padding(
            padding: const EdgeInsets.fromLTRB(18, 16, 18, 16),
            child: Row(
              children: [
                Container(
                  width: 46,
                  height: 46,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: accent.withValues(alpha: 0.14),
                    border: Border.all(color: accent.withValues(alpha: 0.45)),
                  ),
                  child: Icon(icon, color: accent, size: 24),
                ),
                const SizedBox(width: 14),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        resultTitle,
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                        style: titleStyle,
                      ),
                      const SizedBox(height: 4),
                      Text(
                        resultSubtitle,
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                        style: subtitleStyle,
                      ),
                    ],
                  ),
                ),
                const SizedBox(width: 10),
                Icon(
                  Icons.chevron_right_rounded,
                  color: foreground.withValues(alpha: 0.86),
                  size: 28,
                ),
              ],
            ),
          ),
        ),
      );
    }

    Widget buildRemoteActionButton({
      required String label,
      required IconData icon,
      required VoidCallback? onPressed,
      required Color accent,
      bool primary = false,
    }) {
      final background = primary
          ? Color.alphaBlend(
              accent.withValues(alpha: isLight ? 0.84 : 0.72),
              scheme.surface,
            )
          : Color.alphaBlend(
              accent.withValues(alpha: isLight ? 0.10 : 0.16),
              scheme.surface,
            );
      final foreground = primary ? const Color(0xFF0B0F16) : accent;

      return AnimatedOpacity(
        opacity: onPressed == null ? 0.48 : 1.0,
        duration: const Duration(milliseconds: 150),
        child: FilledButton.icon(
          onPressed: onPressed,
          style: FilledButton.styleFrom(
            backgroundColor: background,
            foregroundColor: foreground,
            padding: EdgeInsets.symmetric(
              horizontal: compactRemoteActionPanel ? 12 : 14,
              vertical: compactRemoteActionPanel ? 10 : 12,
            ),
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(14),
              side: BorderSide(color: accent.withValues(alpha: 0.42)),
            ),
          ),
          icon: Icon(icon, size: 18),
          label: Text(
            label,
            style: TextStyle(
              fontSize: compactRemoteActionPanel ? 13.2 : 14,
              fontWeight: FontWeight.w800,
              letterSpacing: 0.2,
            ),
          ),
        ),
      );
    }

    if (_isBotMatchMode) {
      final useMonochrome =
          context.watch<AppThemeProvider>().isMonochrome ||
          _isCinematicThemeEnabled;
      final arcade = _vsBotArcadePaletteFor(context, monochrome: useMonochrome);
      final selectedBot = _selectedBot;
      final profileAccent = selectedBot == null
          ? arcade.cyan
          : _vsBotProfileAccent(selectedBot.profile, arcade);
      final difficultyAccent = selectedBot == null
          ? arcade.amber
          : _botDifficultyColor(_selectedBotDifficulty);
      final statusAccent = _gameOutcome != null
          ? _vsBotOutcomeAccent(
              arcade,
              isDraw: _gameOutcome == GameOutcome.draw,
              isWin: _isWinningOutcomeForPov,
            )
          : _botThinking
          ? arcade.amber
          : _isHumanTurnInBotGame
          ? arcade.cyan
          : arcade.crimson;
      final statusLabel = _gameOutcome != null
          ? 'MATCH END'
          : _botThinking
          ? 'BOT THINKING'
          : _isHumanTurnInBotGame
          ? 'PLAYER TURN'
          : 'BOT TURN';
      final filledTagForeground = arcade.monochrome
          ? arcade.text
          : const Color(0xFF0B0F16);
      final showStatusTagInDeck = isLandscape;
      final showEndMatchButton = endedOutcome != null;
      const portraitSuggestionsPadding = EdgeInsets.symmetric(horizontal: 20);
      final portraitSuggestionsLayout =
          !isLandscape && _hasVisibleSuggestedMoves
          ? _portraitFloatingSuggestionsLayout(
              padding: portraitSuggestionsPadding,
            )
          : null;
      final showFloatingPortraitSuggestionsOverlay =
          portraitSuggestionsLayout != null;

      final deck = Container(
        decoration: _vsBotArcadePanelDecoration(
          palette: arcade,
          accent: profileAccent,
          radius: 22,
          borderWidth: 2.8,
          fillColor: arcade.panel,
        ),
        padding: const EdgeInsets.fromLTRB(14, 10, 14, 10),
        child: LayoutBuilder(
          builder: (context, inner) {
            final statusTag = PuzzleAcademyTag(
              label: statusLabel,
              accent: statusAccent,
              compact: true,
              filled: _gameOutcome == null && _isHumanTurnInBotGame,
              foregroundColor: _gameOutcome == null && _isHumanTurnInBotGame
                  ? filledTagForeground
                  : null,
            );

            final deckContent = Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                if (showStatusTagInDeck) ...[
                  Align(alignment: Alignment.centerLeft, child: statusTag),
                  const SizedBox(height: 6),
                ],
                if (showEndMatchButton)
                  buildEndMatchButton(
                    accent: statusAccent,
                    background: Color.alphaBlend(
                      statusAccent.withValues(
                        alpha: arcade.monochrome ? 0.12 : 0.16,
                      ),
                      arcade.panelAlt,
                    ),
                    foreground: arcade.text,
                    borderColor: statusAccent.withValues(alpha: 0.62),
                    titleStyle: puzzleAcademyDisplayStyle(
                      palette: arcade.base,
                      size: 16,
                      color: statusAccent,
                      withGlow: true,
                    ),
                    subtitleStyle: puzzleAcademyHudStyle(
                      palette: arcade.base,
                      size: 10.8,
                      color: arcade.textMuted,
                    ),
                    icon: endedOutcome == GameOutcome.draw
                        ? Icons.balance_rounded
                        : _isWinningOutcomeForPov
                        ? Icons.emoji_events_rounded
                        : Icons.flag_rounded,
                    resultTitle: _endMatchCardTitle(endedOutcome),
                    resultSubtitle: _endMatchCardSubtitle(endedOutcome),
                  )
                else
                  Builder(
                    builder: (context) {
                      final actionSpacing = inner.maxWidth <= 280
                          ? 4.0
                          : inner.maxWidth <= 360
                          ? 6.0
                          : 8.0;
                      final powerPod = _buildVsBotActionPod(
                        label: 'Charge',
                        accent: difficultyAccent,
                        control: _buildSuggestionTriggerButton(),
                      );
                      final actionPods = <Widget>[
                        _buildVsBotActionPod(
                          label: 'Return',
                          accent: arcade.crimson,
                          control: _buildVsBotControlButton(
                            icon: Icons.exit_to_app_rounded,
                            onTap: _openBotSetupFromMenu,
                            accent: arcade.crimson,
                          ),
                        ),
                        _buildVsBotActionPod(
                          label: 'Store',
                          accent: arcade.amber,
                          control: _buildVsBotControlButton(
                            controlKey: _storeButtonKey,
                            icon: Icons.storefront_outlined,
                            onTap: _openStore,
                            accent: arcade.amber,
                          ),
                        ),
                        _buildVsBotActionPod(
                          label: 'Undo',
                          accent: profileAccent,
                          control: _buildBotUndoButton(),
                        ),
                        _buildVsBotActionPod(
                          label: 'Config',
                          accent: arcade.cyan,
                          control: _buildVsBotControlButton(
                            icon: Icons.tune_rounded,
                            onTap: () => _openSettings(fromAnalysisMode: false),
                            accent: arcade.cyan,
                          ),
                        ),
                      ];

                      return Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Align(alignment: Alignment.center, child: powerPod),
                          const SizedBox(height: 6),
                          Row(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              for (
                                int index = 0;
                                index < actionPods.length;
                                index++
                              ) ...[
                                Expanded(
                                  child: FittedBox(
                                    fit: BoxFit.scaleDown,
                                    child: actionPods[index],
                                  ),
                                ),
                                if (index < actionPods.length - 1)
                                  SizedBox(width: actionSpacing),
                              ],
                            ],
                          ),
                        ],
                      );
                    },
                  ),
              ],
            );

            return deckContent;
          },
        ),
      );

      return Padding(
        key: _actionAreaKey,
        padding: EdgeInsets.only(
          bottom: compactBottom,
          left: horizontal,
          right: horizontal,
        ),
        child: Stack(
          clipBehavior: Clip.none,
          children: [
            deck,
            if (showFloatingPortraitSuggestionsOverlay)
              Positioned(
                left: 0,
                right: 0,
                top: portraitSuggestionsLayout.topOffset,
                child: _buildSuggestedMovesList(
                  height: portraitSuggestionsLayout.height,
                  padding: portraitSuggestionsPadding,
                  maxVisibleMoves: portraitSuggestionsLayout.maxVisibleMoves,
                  alignment: Alignment.topCenter,
                ),
              ),
          ],
        ),
      );
    }

    if (_isRemoteFriendMatchMode && endedOutcome == null) {
      final remoteSnapshot = _remoteFriendSnapshot;
      final remoteSeat = _remoteFriendPlayerSeat;
      final remoteSeatLabel = _remoteFriendSeatLabel(remoteSeat);
      final remotePieceSelectionOpen = _isRemoteFriendPieceSelectionOpen;
      final remoteSelectionRemainingSeconds =
          _remoteFriendPieceSelectionRemainingSeconds;
      final remoteSelectionProgress = remotePieceSelectionOpen
          ? min(
              1.0,
              max(
                0.0,
                _remoteFriendPieceSelectionRemaining.inMilliseconds / 10000,
              ),
            )
          : 0.0;
      final remotePlayerTheme = remoteSeat == null
          ? _pieceThemeMode
          : _remoteFriendPieceThemeForSeat(remoteSeat);
      final remoteOpponentSeat = remoteSeat == null
          ? null
          : (remoteSeat == RemoteFriendSeat.white
                ? RemoteFriendSeat.black
                : RemoteFriendSeat.white);
      final remoteOpponentSeatLabel = _remoteFriendSeatLabel(
        remoteOpponentSeat,
      );
      final remoteOpponentTheme = remoteOpponentSeat == null
          ? _pieceThemeMode
          : _remoteFriendPieceThemeForSeat(remoteOpponentSeat);
      final compactPendingInviteLayout =
          _isRemoteFriendPendingMatch && compactRemoteActionPanel;
      final remoteUseMonochrome =
          context.watch<AppThemeProvider>().isMonochrome ||
          _isCinematicThemeEnabled;
      final remoteLocalAccent = _remoteFriendLocalAccent(
        scheme,
        useMonochrome: remoteUseMonochrome,
      );
      final remoteOpponentAccent = _remoteFriendOpponentAccent(
        scheme,
        useMonochrome: remoteUseMonochrome,
      );
      final remoteReadyAccent = _remoteFriendReadyAccent(
        scheme,
        useMonochrome: remoteUseMonochrome,
      );
      final remoteDangerAccent = _remoteFriendDangerAccent(
        scheme,
        useMonochrome: remoteUseMonochrome,
      );
      final avatarInventory = context.watch<AvatarInventoryProvider>();
      final strangeReactionsUnlocked =
          avatarInventory.hasUnlockedStrangeReactions;
      final remoteErrorText = _remoteFriendLastError?.trim();
      final hasRemoteError =
          remoteErrorText != null && remoteErrorText.isNotEmpty;
      final remoteAccent = remotePieceSelectionOpen
          ? remoteOpponentAccent
          : _hasIncomingRemoteDrawOffer || _hasOutgoingRemoteDrawOffer
          ? remoteOpponentAccent
          : _isHumanTurnInRemoteFriendGame
          ? remoteLocalAccent
          : const Color(0xFF7D8CA3);
      final remoteSelectionUrgent =
          remotePieceSelectionOpen && remoteSelectionRemainingSeconds <= 3;
      final remoteSelectionAccent = remoteSelectionUrgent
          ? remoteDangerAccent
          : remoteAccent;
      final remoteStatusText = (remoteSnapshot == null
          ? 'Synchronizing remote friend match...'
          : _isRemoteFriendPendingMatch
          ? 'Share code ${remoteSnapshot.inviteCode} with your friend to start the match.'
          : remotePieceSelectionOpen
          ? _remoteFriendPieceSelectionReady
                ? remoteSeat == null
                      ? 'Ready. Your saved default skin is locked in, and the match starts in $remoteSelectionRemainingSeconds seconds.'
                      : 'Ready. Your ${remoteSeatLabel.toLowerCase()} pieces will use ${_pieceThemeLabel(remotePlayerTheme)} while your friend keeps ${_pieceThemeLabel(remoteOpponentTheme)} on the other side. Match starts in $remoteSelectionRemainingSeconds seconds.'
                : remoteSeat == null
                ? 'Choose your piece skin in $remoteSelectionRemainingSeconds seconds. If you do nothing, your current default skin will be used.'
                : 'You are $remoteSeatLabel. Pick the skin for your ${remoteSeatLabel.toLowerCase()} pieces. Your friend keeps their own ${_remoteFriendSeatLabel(remoteOpponentSeat).toLowerCase()}-side skin, and the match starts in $remoteSelectionRemainingSeconds seconds.'
          : remoteSnapshot.status == RemoteFriendMatchStatus.expired
          ? 'This invite expired before the game began. Return to VS mode to create a new code.'
          : remoteSnapshot.status == RemoteFriendMatchStatus.cancelled
          ? 'This invite was cancelled. Return to VS mode to create a new private match.'
          : _hasIncomingRemoteDrawOffer
          ? 'Your friend offered a draw. Accept or decline to continue.'
          : _hasOutgoingRemoteDrawOffer
          ? 'Draw offer sent. The board will update when your friend responds.'
          : 'Moves and clocks are synchronized from the private match.');
      final remoteBusyText = !_remoteFriendOperationInProgress
          ? null
          : _isRemoteFriendPendingMatch
          ? 'Updating the invite for both phones...'
          : remotePieceSelectionOpen
          ? 'Saving your piece-skin pairing choice...'
          : 'Synchronizing the private match...';
      final remoteVisibleReaction = remoteSnapshot == null
          ? null
          : _remoteFriendVisibleReactionForSnapshot(remoteSnapshot);
      final remoteVisibleReactionOption = remoteVisibleReaction == null
          ? null
          : _remoteFriendReactionOptionForEmoji(remoteVisibleReaction.emoji);
      final remoteReactionSentByLocal =
          remoteVisibleReaction != null &&
          remoteVisibleReaction.sentByUid == _remoteFriendLocalUid;
      final remoteReactionAccent = remoteVisibleReaction == null
          ? remoteAccent
          : remoteReactionSentByLocal
          ? remoteLocalAccent
          : remoteOpponentAccent;
      final remoteReactionCooldownRemaining = remoteSnapshot == null
          ? Duration.zero
          : _remoteFriendReactionCooldownRemainingForSnapshot(remoteSnapshot);
      final remoteReactionReady =
          remoteReactionCooldownRemaining == Duration.zero &&
          !_remoteFriendReactionInFlight &&
          !_remoteFriendOperationInProgress;
      final remoteReactionStatusText = _remoteFriendReactionInFlight
          ? 'Sending...'
          : remoteReactionCooldownRemaining > Duration.zero
          ? 'Ready again in ${_formatRemoteFriendReactionCooldown(remoteReactionCooldownRemaining)}'
          : 'Ready now';
      final remoteMetaChips = <Widget>[
        if (_isRemoteFriendPendingMatch && remoteSnapshot != null)
          _remoteFriendSurfaceChip(
            label: 'Code ${remoteSnapshot.inviteCode}',
            accent: remoteLocalAccent,
            icon: Icons.key_rounded,
          ),
        if (_isRemoteFriendActiveMatch && remoteSeat != null)
          _remoteFriendSurfaceChip(
            label: 'You | $remoteSeatLabel',
            accent: remoteLocalAccent,
            icon: Icons.person_rounded,
          ),
        if (_isRemoteFriendActiveMatch)
          _remoteFriendSurfaceChip(
            label: remotePieceSelectionOpen
                ? 'Skin pairing'
                : 'Private live sync',
            accent: remoteOpponentAccent,
            icon: remotePieceSelectionOpen
                ? Icons.palette_outlined
                : Icons.link_rounded,
          ),
      ];
      final showRemoteReactionTray =
          _isRemoteFriendActiveMatch &&
          !remotePieceSelectionOpen &&
          remoteSnapshot != null &&
          remoteSnapshot.status == RemoteFriendMatchStatus.active &&
          remoteSnapshot.outcome == null;
      final shouldScrollRemoteActionBody =
          isLandscape &&
          media.size.height <= 420 &&
          (remotePieceSelectionOpen || showRemoteReactionTray);
      final buttons = <Widget>[
        buildRemoteActionButton(
          label: 'VS Mode',
          icon: Icons.arrow_back_rounded,
          onPressed: _remoteFriendOperationInProgress
              ? null
              : _openVsModeFromMenu,
          accent: scheme.onSurface,
        ),
        if (_isRemoteFriendPendingMatch) ...[
          buildRemoteActionButton(
            label: compactPendingInviteLayout ? 'Copy' : 'Copy Code',
            icon: Icons.copy_all_rounded,
            onPressed: _remoteFriendOperationInProgress
                ? null
                : () => unawaited(_copyRemoteFriendInviteCode()),
            accent: remoteLocalAccent,
          ),
          buildRemoteActionButton(
            label: 'Share Code',
            icon: Icons.share_rounded,
            onPressed: _remoteFriendOperationInProgress
                ? null
                : () => unawaited(_shareRemoteFriendInviteCode()),
            accent: remoteLocalAccent,
          ),
          buildRemoteActionButton(
            label: compactPendingInviteLayout ? 'Cancel' : 'Cancel Invite',
            icon: Icons.close_rounded,
            onPressed: _remoteFriendOperationInProgress
                ? null
                : () => unawaited(
                    _runRemoteFriendAction(
                      RemoteFriendMatchAction.cancelPending,
                    ),
                  ),
            accent: remoteDangerAccent,
            primary: true,
          ),
        ] else if (_isRemoteFriendActiveMatch) ...[
          if (!remotePieceSelectionOpen && _hasIncomingRemoteDrawOffer)
            buildRemoteActionButton(
              label: 'Accept Draw',
              icon: Icons.handshake_outlined,
              onPressed: _remoteFriendOperationInProgress
                  ? null
                  : () => unawaited(
                      _runRemoteFriendAction(
                        RemoteFriendMatchAction.acceptDraw,
                      ),
                    ),
              accent: remoteOpponentAccent,
              primary: true,
            ),
          if (!remotePieceSelectionOpen && _hasIncomingRemoteDrawOffer)
            buildRemoteActionButton(
              label: 'Decline',
              icon: Icons.close_rounded,
              onPressed: _remoteFriendOperationInProgress
                  ? null
                  : () => unawaited(
                      _runRemoteFriendAction(
                        RemoteFriendMatchAction.declineDraw,
                      ),
                    ),
              accent: remoteDangerAccent,
            ),
          if (!remotePieceSelectionOpen && !_hasIncomingRemoteDrawOffer)
            buildRemoteActionButton(
              label: _hasOutgoingRemoteDrawOffer ? 'Draw Sent' : 'Offer Draw',
              icon: Icons.handshake_outlined,
              onPressed:
                  _remoteFriendOperationInProgress ||
                      _hasOutgoingRemoteDrawOffer
                  ? null
                  : () => unawaited(
                      _runRemoteFriendAction(RemoteFriendMatchAction.offerDraw),
                    ),
              accent: remoteOpponentAccent,
              primary: !_hasOutgoingRemoteDrawOffer,
            ),
          if (!remotePieceSelectionOpen)
            buildRemoteActionButton(
              label: 'Resign',
              icon: Icons.flag_rounded,
              onPressed: _remoteFriendOperationInProgress
                  ? null
                  : () => unawaited(
                      _runRemoteFriendAction(RemoteFriendMatchAction.resign),
                    ),
              accent: remoteDangerAccent,
              primary: true,
            ),
        ],
        buildRemoteActionButton(
          label: 'Refresh',
          icon: Icons.sync_rounded,
          onPressed: _remoteFriendOperationInProgress
              ? null
              : () => unawaited(_refreshRemoteFriendMatch()),
          accent: remoteAccent,
        ),
      ];

      final remoteActionCard = Container(
        width: double.infinity,
        padding: compactRemoteActionPanel
            ? const EdgeInsets.fromLTRB(14, 12, 14, 12)
            : const EdgeInsets.fromLTRB(16, 14, 16, 14),
        decoration: BoxDecoration(
          color: Color.alphaBlend(
            remoteAccent.withValues(alpha: isLight ? 0.08 : 0.14),
            scheme.surface,
          ),
          borderRadius: BorderRadius.circular(18),
          border: Border.all(color: remoteAccent.withValues(alpha: 0.30)),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              _isRemoteFriendPendingMatch
                  ? 'Remote Friend Invite'
                  : remotePieceSelectionOpen
                  ? 'Piece Skin Pairing'
                  : _isRemoteFriendActiveMatch
                  ? 'Remote Friend Match'
                  : 'Remote Friend Session',
              style: TextStyle(
                color: scheme.onSurface,
                fontSize: compactRemoteActionPanel ? 14.0 : 15,
                fontWeight: FontWeight.w800,
              ),
            ),
            const SizedBox(height: 6),
            Text(
              remoteStatusText,
              maxLines: compactRemoteActionPanel && _isRemoteFriendPendingMatch
                  ? 2
                  : null,
              overflow: compactRemoteActionPanel && _isRemoteFriendPendingMatch
                  ? TextOverflow.ellipsis
                  : TextOverflow.visible,
              style: TextStyle(
                color: scheme.onSurface.withValues(alpha: 0.72),
                fontSize: compactRemoteActionPanel ? 11.8 : 12.5,
                height: 1.32,
                fontWeight: FontWeight.w600,
              ),
            ),
            if (remoteMetaChips.isNotEmpty) ...[
              const SizedBox(height: 10),
              Wrap(spacing: 8, runSpacing: 8, children: remoteMetaChips),
            ],
            if (hasRemoteError) ...[
              const SizedBox(height: 10),
              _remoteFriendInlineErrorBanner(
                message: remoteErrorText,
                accent: remoteDangerAccent,
                onDismiss: () => setState(() {
                  _remoteFriendLastError = null;
                }),
                onRetry: () => unawaited(_refreshRemoteFriendMatch()),
              ),
            ],
            if (remoteBusyText != null) ...[
              const SizedBox(height: 10),
              Container(
                width: double.infinity,
                padding: const EdgeInsets.symmetric(
                  horizontal: 12,
                  vertical: 10,
                ),
                decoration: BoxDecoration(
                  color: Color.alphaBlend(
                    remoteAccent.withValues(alpha: isLight ? 0.08 : 0.14),
                    scheme.surface,
                  ),
                  borderRadius: BorderRadius.circular(14),
                  border: Border.all(
                    color: remoteAccent.withValues(alpha: 0.22),
                  ),
                ),
                child: Row(
                  children: [
                    SizedBox(
                      width: 16,
                      height: 16,
                      child: CircularProgressIndicator(
                        strokeWidth: 2.2,
                        valueColor: AlwaysStoppedAnimation<Color>(remoteAccent),
                      ),
                    ),
                    const SizedBox(width: 10),
                    Expanded(
                      child: Text(
                        remoteBusyText,
                        style: TextStyle(
                          color: scheme.onSurface.withValues(alpha: 0.78),
                          fontSize: 11.8,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ],
            if (showRemoteReactionTray && remoteVisibleReaction != null) ...[
              const SizedBox(height: 10),
              _remoteFriendReactionBanner(
                emoji: remoteVisibleReaction.emoji,
                title: remoteReactionSentByLocal
                    ? 'You reacted'
                    : 'Friend reacted',
                subtitle: remoteReactionSentByLocal
                    ? '${remoteVisibleReactionOption?.label ?? 'Quick reaction'} sent to the other phone.'
                    : '${remoteVisibleReactionOption?.label ?? 'Quick reaction'} just came in from your friend.',
                accent: remoteReactionAccent,
              ),
            ],
            if (showRemoteReactionTray) ...[
              const SizedBox(height: 12),
              Container(
                width: double.infinity,
                padding: const EdgeInsets.all(12),
                decoration: BoxDecoration(
                  color: Color.alphaBlend(
                    remoteLocalAccent.withValues(alpha: isLight ? 0.06 : 0.12),
                    scheme.surface,
                  ),
                  borderRadius: BorderRadius.circular(16),
                  border: Border.all(
                    color: remoteLocalAccent.withValues(alpha: 0.20),
                  ),
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        Expanded(
                          child: Text(
                            'Quick reacts',
                            style: TextStyle(
                              color: scheme.onSurface,
                              fontSize: 12.8,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                        ),
                        Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 10,
                            vertical: 6,
                          ),
                          decoration: BoxDecoration(
                            color: remoteReactionAccent.withValues(
                              alpha: isLight ? 0.12 : 0.20,
                            ),
                            borderRadius: BorderRadius.circular(999),
                          ),
                          child: Text(
                            remoteReactionStatusText,
                            style: TextStyle(
                              color: scheme.onSurface,
                              fontSize: 10.6,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 6),
                    Text(
                      strangeReactionsUnlocked
                          ? 'Tap any emoji to send it across the private match. Every react has a 30-second cooldown.'
                          : '12 standard reacts are ready now. The 5 strange ones unlock after your first random avatar roll.',
                      style: TextStyle(
                        color: scheme.onSurface.withValues(alpha: 0.70),
                        fontSize: 11.4,
                        height: 1.28,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                    const SizedBox(height: 10),
                    _remoteFriendSurfaceChip(
                      label: 'Standard set',
                      accent: remoteLocalAccent,
                      icon: Icons.sentiment_satisfied_alt_rounded,
                    ),
                    const SizedBox(height: 8),
                    Wrap(
                      spacing: 8,
                      runSpacing: 8,
                      children: [
                        for (final option
                            in _remoteFriendStandardReactionOptions)
                          _remoteFriendReactionChip(
                            option: option,
                            accent: remoteLocalAccent,
                            onTap: remoteReactionReady
                                ? () => unawaited(
                                    _sendRemoteFriendReaction(option.emoji),
                                  )
                                : null,
                          ),
                      ],
                    ),
                    const SizedBox(height: 12),
                    Container(
                      width: double.infinity,
                      padding: const EdgeInsets.all(10),
                      decoration: BoxDecoration(
                        color: Color.alphaBlend(
                          remoteOpponentAccent.withValues(
                            alpha: isLight ? 0.06 : 0.12,
                          ),
                          scheme.surface,
                        ),
                        borderRadius: BorderRadius.circular(14),
                        border: Border.all(
                          color: remoteOpponentAccent.withValues(alpha: 0.16),
                        ),
                      ),
