              child: SingleChildScrollView(
                primary: false,
                child: remoteActionCard,
              ),
            )
          : remoteActionCard;

      return Padding(
        padding: EdgeInsets.only(
          bottom: compactBottom,
          left: horizontal,
          right: horizontal,
        ),
        child: remoteActionBody,
      );
