  Future<void> _showLegalNoticeDialog({
    required String title,
    required String assetPath,
    required Color accent,
  }) async {
    final scrollController = ScrollController();
    try {
      await showDialog<void>(
        context: context,
        builder: (dialogContext) {
          final appTheme = context.watch<AppThemeProvider>();
          final useMonochrome =
              appTheme.isMonochrome || _isCinematicThemeEnabled;
          final theme = Theme.of(dialogContext);
          final scheme = theme.colorScheme;
          final isLightTheme = theme.brightness == Brightness.light;
          final noticeHasLightSurface = useMonochrome || isLightTheme;
          final dialogHeight = min(
            MediaQuery.of(dialogContext).size.height * 0.86,
            760.0,
          );
          final dialogAccentColor = useMonochrome
              ? scheme.onSurface.withValues(alpha: 0.92)
              : accent;
          final dialogBackgroundStart = noticeHasLightSurface
              ? scheme.surface
              : const Color(0xFF071429);
          final dialogBackgroundEnd = noticeHasLightSurface
              ? Color.alphaBlend(
                  scheme.onSurface.withValues(alpha: 0.06),
                  scheme.surface,
                )
              : const Color(0xFF040D1D);
          return Dialog(
            backgroundColor: Colors.transparent,
            elevation: 0,
            child: Container(
              constraints: BoxConstraints(
                maxWidth: 700,
                maxHeight: dialogHeight,
              ),
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                  colors: [dialogBackgroundStart, dialogBackgroundEnd],
                ),
                borderRadius: BorderRadius.circular(18),
                border: Border.all(
                  color: dialogAccentColor.withValues(alpha: 0.35),
                ),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withValues(alpha: 0.42),
                    blurRadius: 24,
                    offset: const Offset(0, 10),
                  ),
                ],
              ),
              child: Column(
                children: [
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.fromLTRB(16, 12, 12, 12),
                    decoration: BoxDecoration(
                      border: Border(
                        bottom: BorderSide(
                          color: accent.withValues(alpha: 0.24),
                        ),
                      ),
                    ),
                    child: Row(
                      children: [
                        Icon(
                          Icons.description_outlined,
                          color: dialogAccentColor,
                          size: 18,
                        ),
                        const SizedBox(width: 8),
                        Expanded(
                          child: Text(
                            title,
                            style: TextStyle(
                              color: dialogAccentColor,
                              fontWeight: FontWeight.w700,
                              fontSize: 13.2,
                              letterSpacing: 0.2,
                            ),
                          ),
                        ),
                        IconButton(
                          onPressed: () => Navigator.of(dialogContext).pop(),
                          icon: Icon(
                            Icons.close,
                            color: scheme.onSurface.withValues(alpha: 0.72),
                          ),
                          tooltip: 'Close legal notice',
                        ),
                      ],
                    ),
                  ),
                  Expanded(
                    child: FutureBuilder<String>(
                      future: _loadLegalNoticeText(assetPath),
                      builder: (context, snapshot) {
                        if (snapshot.connectionState != ConnectionState.done) {
                          return const Center(
                            child: CircularProgressIndicator(strokeWidth: 2),
                          );
                        }

                        if (snapshot.hasError || !snapshot.hasData) {
                          return Padding(
                            padding: const EdgeInsets.all(18),
                            child: Text(
                              'Unable to load this notice from app assets.',
                              style: TextStyle(
                                color: Colors.white.withValues(alpha: 0.78),
                                fontSize: 12.2,
                              ),
                            ),
                          );
                        }

                        final lines = const LineSplitter().convert(
                          snapshot.data!.replaceAll('\r\n', '\n'),
                        );
                        return Scrollbar(
                          controller: scrollController,
                          thumbVisibility: true,
                          child: ListView.builder(
                            controller: scrollController,
                            padding: const EdgeInsets.fromLTRB(16, 14, 16, 16),
                            itemCount: lines.length,
                            itemBuilder: (context, index) {
                              final line = lines[index];
                              final trimmed = line.trim();

                              if (trimmed.isEmpty) {
                                return const SizedBox(height: 10);
                              }
                              if (trimmed.startsWith('### ')) {
                                return Padding(
                                  padding: const EdgeInsets.only(bottom: 6),
                                  child: Text(
                                    trimmed.substring(4),
                                    style: TextStyle(
                                      color: dialogAccentColor.withValues(
                                        alpha: 0.95,
                                      ),
                                      fontSize: 13.2,
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                );
                              }
                              if (trimmed.startsWith('## ')) {
                                return Padding(
                                  padding: const EdgeInsets.only(bottom: 7),
                                  child: Text(
                                    trimmed.substring(3),
                                    style: TextStyle(
                                      color: dialogAccentColor.withValues(
                                        alpha: 0.97,
                                      ),
                                      fontSize: 14,
                                      fontWeight: FontWeight.w800,
                                    ),
                                  ),
                                );
                              }
                              if (trimmed.startsWith('# ')) {
                                return Padding(
                                  padding: const EdgeInsets.only(bottom: 8),
                                  child: Text(
                                    trimmed.substring(2),
                                    style: TextStyle(
                                      color: dialogAccentColor,
                                      fontSize: 15.2,
                                      fontWeight: FontWeight.w900,
                                    ),
                                  ),
                                );
                              }

                              if (trimmed.startsWith('- ') ||
                                  trimmed.startsWith('* ')) {
                                return Padding(
                                  padding: const EdgeInsets.only(
                                    left: 4,
                                    bottom: 6,
                                  ),
                                  child: Row(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.start,
                                    children: [
                                      Text(
                                        '• ',
                                        style: TextStyle(
                                          color: dialogAccentColor.withValues(
                                            alpha: 0.9,
                                          ),
                                          fontSize: 12.6,
                                          fontWeight: FontWeight.w700,
                                        ),
                                      ),
                                      Expanded(
                                        child: SelectableText(
                                          trimmed.substring(2),
                                          style: TextStyle(
                                            color: scheme.onSurface.withValues(
                                              alpha: 0.88,
                                            ),
                                            fontSize: 12.35,
                                            height: 1.42,
                                          ),
                                        ),
                                      ),
                                    ],
                                  ),
                                );
                              }

                              return Padding(
                                padding: const EdgeInsets.only(bottom: 6),
                                child: SelectableText(
                                  line,
                                  style: TextStyle(
                                    color: scheme.onSurface.withValues(
                                      alpha: 0.86,
                                    ),
                                    fontSize: 12.3,
                                    height: 1.42,
                                  ),
                                ),
                              );
                            },
                          ),
                        );
                      },
                    ),
                  ),
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.fromLTRB(14, 10, 14, 12),
                    decoration: BoxDecoration(
                      border: Border(
                        top: BorderSide(
                          color: dialogAccentColor.withValues(alpha: 0.2),
                        ),
                      ),
                    ),
                    child: Align(
                      alignment: Alignment.centerRight,
                      child: FilledButton.icon(
                        onPressed: () => Navigator.of(dialogContext).pop(),
                        icon: const Icon(Icons.check_rounded),
                        label: const Text('Done'),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          );
        },
      );
    } finally {
      scrollController.dispose();
    }
  }

  Future<String> _loadLegalNoticeText(String assetPath) async {
    try {
      final text = await rootBundle.loadString(assetPath);
      return _normalizeLegalNoticeTextForDisplay(assetPath, text);
    } catch (_) {
      if (!kIsWeb) {
        final candidates = <String>{
          assetPath,
          '${Directory.current.path}${Platform.pathSeparator}$assetPath',
        };
        for (final path in candidates) {
          final file = File(path);
          if (await file.exists()) {
            final text = await file.readAsString();
            return _normalizeLegalNoticeTextForDisplay(assetPath, text);
          }
        }
      }
      throw Exception('Unable to load legal notice: $assetPath');
    }
  }

  String _normalizeLegalNoticeTextForDisplay(String assetPath, String text) {
    final normalized = text.replaceAll('\r\n', '\n');
    if (assetPath == 'LICENSE') {
      return _normalizeLicenseTextForDisplay(normalized);
    }
    return normalized;
  }

  String _normalizeLicenseTextForDisplay(String text) {
    final output = <String>[];
    final paragraph = <String>[];

    void flushParagraph() {
      if (paragraph.isEmpty) {
        return;
      }
      output.addAll(_formatLicenseParagraphForDisplay(paragraph));
      paragraph.clear();
    }

    void pushBlankLine() {
      if (output.isEmpty || output.last.isEmpty) {
        return;
      }
      output.add('');
    }

    for (final line in text.split('\n')) {
      if (line.trim().isEmpty) {
        flushParagraph();
        pushBlankLine();
        continue;
      }
      paragraph.add(line);
    }
    flushParagraph();

    while (output.isNotEmpty && output.last.isEmpty) {
      output.removeLast();
    }

    return output.join('\n');
  }

  List<String> _formatLicenseParagraphForDisplay(List<String> rawLines) {
    final trimmedLines = rawLines
        .map((line) => line.trim())
        .where((line) => line.isNotEmpty)
        .toList(growable: false);
    if (trimmedLines.isEmpty) {
      return const <String>[];
    }

    final firstTrimmedLine = trimmedLines.first;
    if (_isLicenseHeadingParagraph(trimmedLines)) {
      return trimmedLines;
    }

    if (_isLicenseIndentedExampleParagraph(rawLines, firstTrimmedLine)) {
      return trimmedLines.map((line) => '    $line').toList(growable: false);
    }

    final merged = trimmedLines
        .join(' ')
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
    return <String>[merged];
  }

  bool _isLicenseHeadingParagraph(List<String> trimmedLines) {
    if (trimmedLines.length == 2 &&
        trimmedLines.first == 'GNU GENERAL PUBLIC LICENSE' &&
        trimmedLines.last.startsWith('Version ')) {
      return true;
    }

    if (trimmedLines.length != 1) {
      return false;
    }

    switch (trimmedLines.first) {
      case 'Preamble':
      case 'TERMS AND CONDITIONS':
      case 'END OF TERMS AND CONDITIONS':
      case 'How to Apply These Terms to Your New Programs':
        return true;
    }
    return false;
  }

  bool _isLicenseIndentedExampleParagraph(
    List<String> rawLines,
    String firstTrimmedLine,
  ) {
    if (RegExp(r'^[a-z]\)').hasMatch(firstTrimmedLine)) {
      return false;
    }

    return rawLines.every(
      (line) => line.trim().isNotEmpty && _leadingWhitespaceCount(line) >= 8,
    );
  }

  int _leadingWhitespaceCount(String line) {
    var count = 0;
    while (count < line.length) {
      final codeUnit = line.codeUnitAt(count);
      if (codeUnit != 0x20 && codeUnit != 0x09) {
        break;
      }
      count += 1;
    }
    return count;
  }

  Widget _buildCreditsDynamicBackdrop({
    required _CreditsDialogVisuals visuals,
  }) {
    final t = _pulseController.value;
    final wave = t * pi * 2;
    final lineColors = <Color>[
      visuals.primaryAccent,
      visuals.secondaryAccent,
      visuals.tertiaryAccent,
      visuals.primaryAccent,
    ];
    final lineAlignments = <Alignment>[
      const Alignment(-0.18, -0.26),
      const Alignment(0.22, -0.06),
      const Alignment(-0.04, 0.28),
      const Alignment(0.38, 0.34),
    ];
    final lineRotations = <double>[-0.18, 0.12, -0.42, 0.36];
    final lineWidths = <double>[150, 170, 140, 128];
    final coreNodes = <({double x, double y, Color color})>[
      (x: 0.16 + 0.02 * sin(wave), y: 0.22, color: visuals.primaryAccent),
      (x: 0.34, y: 0.35 + 0.02 * cos(wave), color: visuals.secondaryAccent),
      (x: 0.58 + 0.015 * cos(wave), y: 0.24, color: visuals.primaryAccent),
      (x: 0.78, y: 0.38 + 0.02 * sin(wave), color: visuals.tertiaryAccent),
      (x: 0.28, y: 0.68, color: visuals.secondaryAccent),
      (x: 0.56 + 0.02 * sin(wave), y: 0.58, color: visuals.primaryAccent),
      (x: 0.82, y: 0.70, color: visuals.tertiaryAccent),
    ];

    Color dotColorForRole(_CreditsBackdropDotRole role) {
      switch (role) {
        case _CreditsBackdropDotRole.green:
          return Color.lerp(
                const Color(0xFF7EDC8A),
                visuals.tertiaryAccent,
                visuals.themeBlend,
              ) ??
              visuals.tertiaryAccent;
        case _CreditsBackdropDotRole.blue:
          return Color.lerp(
                const Color(0xFF2A6CF0),
                visuals.primaryAccent,
                visuals.themeBlend,
              ) ??
              visuals.primaryAccent;
        case _CreditsBackdropDotRole.yellow:
          return Color.lerp(
                const Color(0xFFD8B640),
                visuals.secondaryAccent,
                visuals.themeBlend,
              ) ??
              visuals.secondaryAccent;
      }
    }

    return ClipRRect(
      borderRadius: visuals.shellRadius,
      child: Stack(
        children: <Widget>[
          Positioned.fill(
            child: DecoratedBox(
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                  colors: <Color>[
                    visuals.shellStart,
                    visuals.panel.withValues(alpha: 0.96),
                    visuals.shellEnd,
                  ],
                ),
              ),
            ),
          ),
          if (visuals.themeBlend > 0.08 || visuals.glitchStrength > 0.01)
            Positioned.fill(
              child: CustomPaint(
                painter: _CreditsRetroBackdropPainter(
                  phase: t,
                  themeBlend: visuals.themeBlend,
                  glitchStrength: visuals.glitchStrength,
                  gridColor: visuals.primaryAccent,
                  scanColor: visuals.palette.text,
                  highlightColor: visuals.secondaryAccent,
                  reducedEffects: visuals.reducedEffects,
                ),
              ),
            ),
          for (var index = 0; index < lineColors.length; index++)
            Positioned.fill(
              child: Align(
                alignment: lineAlignments[index],
                child: Transform.rotate(
                  angle: lineRotations[index],
                  child: Container(
                    width: lineWidths[index],
                    height: visuals.isRetro ? 1.8 : 1.2,
                    decoration: BoxDecoration(
                      color: lineColors[index].withValues(
                        alpha: visuals.isRetro ? 0.18 : 0.10,
                      ),
                      boxShadow: <BoxShadow>[
                        BoxShadow(
                          color: lineColors[index].withValues(
                            alpha: visuals.isRetro ? 0.14 : 0.06,
                          ),
                          blurRadius: visuals.isRetro ? 12 : 10,
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            ),
          for (final node in coreNodes)
            Positioned.fill(
              child: Align(
                alignment: Alignment(node.x * 2 - 1, node.y * 2 - 1),
                child: Container(
                  width: visuals.isRetro ? 18 : 16,
                  height: visuals.isRetro ? 18 : 16,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    boxShadow: <BoxShadow>[
                      BoxShadow(
                        color: node.color.withValues(
                          alpha: visuals.isRetro ? 0.24 : 0.12,
                        ),
                        blurRadius: visuals.isRetro ? 18 : 16,
                        spreadRadius: visuals.isRetro ? 5 : 4,
                      ),
                    ],
                  ),
                  child: Center(
                    child: Container(
                      width: visuals.isRetro ? 6 : 5,
                      height: visuals.isRetro ? 6 : 5,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        color: node.color.withValues(alpha: 0.92),
                      ),
                    ),
                  ),
                ),
              ),
            ),
          for (final dot in _creditsBackdropDots)
            Positioned.fill(
              child: Align(
                alignment: Alignment(dot.position.dx, dot.position.dy),
                child: Builder(
                  builder: (context) {
                    final displayColor = dotColorForRole(dot.role);
                    return Container(
                      width: dot.radius * 2,
                      height: dot.radius * 2,
                      decoration: BoxDecoration(
                        shape: visuals.isRetro
                            ? BoxShape.rectangle
                            : BoxShape.circle,
                        borderRadius: visuals.isRetro
                            ? BorderRadius.circular(2)
                            : null,
                        color: displayColor.withValues(alpha: 0.16),
                        boxShadow: <BoxShadow>[
                          BoxShadow(
                            color: displayColor.withValues(alpha: 0.28),
                            blurRadius: dot.radius * 3,
                            spreadRadius: dot.radius * 0.8,
                          ),
                        ],
                      ),
                      child: dot.role == _CreditsBackdropDotRole.green
                          ? Center(
                              child: Container(
                                width: dot.radius,
                                height: dot.radius,
                                decoration: BoxDecoration(
                                  shape: visuals.isRetro
                                      ? BoxShape.rectangle
                                      : BoxShape.circle,
                                  borderRadius: visuals.isRetro
                                      ? BorderRadius.circular(1)
                                      : null,
                                  color: displayColor,
                                ),
                              ),
                            )
                          : null,
                    );
                  },
                ),
              ),
            ),
          Positioned.fill(
            child: DecoratedBox(
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  colors: <Color>[
                    visuals.panel.withValues(alpha: 0.01),
                    visuals.panel.withValues(
                      alpha: visuals.isRetro ? 0.16 : 0.08,
                    ),
                  ],
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildCreditRow(
    String role,
    String name, {
    required _CreditsDialogVisuals visuals,
  }) {
    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.fromLTRB(14, 12, 14, 12),
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: <Color>[
            visuals.panel.withValues(alpha: 0.94),
            visuals.panelAlt.withValues(alpha: visuals.isRetro ? 0.82 : 0.90),
          ],
        ),
        borderRadius: BorderRadius.circular(visuals.isRetro ? 10 : 16),
        border: Border.all(
          color: visuals.frame.withValues(alpha: visuals.isRetro ? 0.72 : 0.28),
          width: visuals.isRetro ? 1.8 : 1.0,
        ),
        boxShadow: puzzleAcademySurfaceGlow(
          visuals.edgeGlow,
          monochrome: visuals.palette.monochrome,
          strength: visuals.isRetro ? 0.12 : 0.08,
        ),
      ),
      child: LayoutBuilder(
        builder: (context, constraints) {
          final compact = constraints.maxWidth < 360;
          final roleWidget = Text(
            role.toUpperCase(),
            textAlign: compact ? TextAlign.left : TextAlign.right,
            style: _creditsLabelStyle(
              visuals,
              size: 11.4,
              color: visuals.primaryAccent,
            ),
          );
          final valueWidget = Text(
            name,
            style: _creditsBodyStyle(
              visuals,
              size: 13.2,
              color: visuals.palette.text,
              weight: FontWeight.w700,
            ),
          );

          if (compact) {
            return Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: <Widget>[
                roleWidget,
                const SizedBox(height: 6),
                valueWidget,
              ],
            );
          }

          return Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: <Widget>[
              SizedBox(width: 166, child: roleWidget),
              const SizedBox(width: 14),
              Expanded(child: valueWidget),
            ],
          );
        },
      ),
    );
  }

  Future<void> _confirmReset() async {
    final result = await showDialog<String?>(
      context: context,
      builder: (context) {
        final theme = Theme.of(context);
        final scheme = theme.colorScheme;
        final useMonochrome =
            context.watch<AppThemeProvider>().isMonochrome ||
            _isCinematicThemeEnabled;
        final isVsBot = _isBotMatchMode;
        final dialogSurface = useMonochrome
            ? scheme.surface
            : Color.alphaBlend(
                scheme.primary.withValues(alpha: 0.10),
                scheme.surface,
              );
        final dialogAccent = useMonochrome
            ? Color.alphaBlend(
                scheme.onSurface.withValues(alpha: 0.08),
                scheme.surface,
              )
            : Color.alphaBlend(
                scheme.secondary.withValues(alpha: 0.10),
                scheme.surface,
              );
        final buttonPrimarySurface = useMonochrome
            ? scheme.onSurface.withValues(alpha: 0.12)
            : scheme.primary;
        final buttonSecondary = useMonochrome
            ? scheme.onSurface.withValues(alpha: 0.92)
            : scheme.secondary;
        final buttonBackground = useMonochrome
            ? scheme.surfaceContainerHighest.withValues(alpha: 0.85)
            : scheme.surfaceContainerHighest;
        final buttonSecondaryForeground = useMonochrome
            ? scheme.onSurface
            : ThemeData.estimateBrightnessForColor(buttonSecondary) ==
                  Brightness.light
            ? const Color(0xFF111418)
            : Colors.white;
        final buttonSecondaryBackground = Color.alphaBlend(
          buttonSecondary.withValues(alpha: useMonochrome ? 0.22 : 0.34),
          buttonBackground,
        );
        return Dialog(
          backgroundColor: Colors.transparent,
          elevation: 0,
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 420),
            child: Container(
              padding: const EdgeInsets.fromLTRB(18, 16, 18, 14),
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                  colors: [dialogSurface, dialogAccent],
                ),
                borderRadius: BorderRadius.circular(18),
                border: Border.all(
                  color: scheme.outline.withValues(alpha: 0.28),
                ),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withValues(alpha: 0.52),
                    blurRadius: 30,
                    offset: const Offset(0, 12),
                  ),
                ],
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Row(
                    children: [
                      Icon(
                        Icons.tune_rounded,
                        size: 18,
                        color: scheme.onSurface.withValues(alpha: 0.85),
                      ),
                      const SizedBox(width: 8),
                      Text(
                        'Return Menu',
                        style: TextStyle(
                          color: scheme.onSurface,
                          fontSize: 16,
                          fontWeight: FontWeight.w800,
                          letterSpacing: 0.25,
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 14),
                  SizedBox(
                    width: double.infinity,
                    height: 44,
                    child: FilledButton(
                      onPressed: () => Navigator.of(context).pop('reset'),
                      style: FilledButton.styleFrom(
                        backgroundColor: buttonPrimarySurface,
                        foregroundColor: scheme.onSurface,
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(12),
                        ),
                        padding: const EdgeInsets.symmetric(horizontal: 12),
                      ),
                      child: Row(
                        mainAxisAlignment: MainAxisAlignment.center,
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Container(
                            width: 20,
                            height: 20,
                            decoration: BoxDecoration(
                              borderRadius: BorderRadius.circular(4),
                              border: Border.all(
                                color: Colors.white.withValues(alpha: 0.35),
                              ),
                            ),
                            padding: const EdgeInsets.all(1),
                            child: FittedBox(
                              fit: BoxFit.contain,
                              child: _boardThemeSwatch(_boardThemeMode),
                            ),
                          ),
                          const SizedBox(width: 10),
                          const Text('Reset Board'),
                        ],
                      ),
                    ),
                  ),
                  if (isVsBot) ...[
                    const SizedBox(height: 8),
                    SizedBox(
                      width: double.infinity,
                      height: 42,
                      child: FilledButton.icon(
                        onPressed: () => Navigator.of(context).pop('opponent'),
                        style: FilledButton.styleFrom(
                          backgroundColor: buttonSecondaryBackground,
                          foregroundColor: buttonSecondaryForeground,
                          side: BorderSide(
                            color: buttonSecondary.withValues(
                              alpha: useMonochrome ? 0.28 : 0.38,
                            ),
                            width: 1.6,
                          ),
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(12),
                          ),
                          padding: const EdgeInsets.symmetric(horizontal: 14),
                        ),
                        icon: Icon(
                          Icons.smart_toy_outlined,
                          size: 18,
                          color: buttonSecondaryForeground,
                        ),
                        label: Text('New Opponent'),
                      ),
                    ),
                  ],
                  const SizedBox(height: 8),
                  SizedBox(
                    width: double.infinity,
                    height: 42,
                    child: FilledButton.icon(
                      onPressed: () => Navigator.of(context).pop('menu'),
                      style: FilledButton.styleFrom(
                        backgroundColor: buttonBackground,
                        foregroundColor: scheme.onSurface,
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(12),
                        ),
                        padding: const EdgeInsets.symmetric(horizontal: 14),
                      ),
                      icon: Icon(
                        Icons.menu_rounded,
                        size: 18,
                        color: scheme.onSurface,
                      ),
                      label: Text('Main Menu'),
                    ),
                  ),
                  const SizedBox(height: 8),
                  SizedBox(
                    width: double.infinity,
                    height: 40,
                    child: OutlinedButton(
                      onPressed: () => Navigator.of(context).pop(),
                      style: OutlinedButton.styleFrom(
                        foregroundColor: scheme.onSurface,
                        side: BorderSide(
                          color: scheme.outline.withValues(alpha: 0.38),
                        ),
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(10),
                        ),
                        padding: EdgeInsets.zero,
                      ),
                      child: const Text('Cancel'),
                    ),
                  ),
                ],
              ),
            ),
          ),
        );
      },
    );

    if (!mounted) return;

    if (result == 'reset') {
      // Let the return menu fully dismiss before presenting the sponsored break.
      await Future<void>.delayed(Duration.zero);
      await _performResetWithSponsoredBreak();
    } else if (result == 'opponent') {
      _openBotSetupFromMenu();
    } else if (result == 'menu') {
      _goToMenu();
    }
  }

  void _openAppearanceSettings() {
    _openSettings(
      fromAnalysisMode:
          _activeSection == AppSection.analysis && _isAnalysisMatchMode,
    );
  }

  Future<void> _openSettings({
    bool isAcademyMode = false,
    bool fromAnalysisMode = false,
  }) async {
    final themeProvider = context.read<AppThemeProvider>();
    final isBoardAnalysisPage =
        _activeSection == AppSection.analysis && _isAnalysisMatchMode;
    final isVsBotPage = _isBotMatchMode;
    final showBoardPerspectiveSection =
        !isAcademyMode && fromAnalysisMode && isBoardAnalysisPage;
    final showEngineControlsSection =
        !isAcademyMode && (isBoardAnalysisPage || isVsBotPage);

    if (isBoardAnalysisPage && _perspective != BoardPerspective.headToHead) {
      _analysisStandardPerspective = _perspective;
    }

    await showUniversalSettingsSheet(
      context: context,
      title: 'Settings',
      isAcademyMode: isAcademyMode,
      themeMode: themeProvider.themeMode,
      themeStyle: themeProvider.themeStyle,
      onThemeModeChanged: (mode) async {
        await themeProvider.setThemeMode(mode);
      },
      onThemeStyleChanged: (style) async {
        await _setCinematicThemeEnabled(style == AppThemeStyle.monochrome);
      },
      soundEnabled: !_muteSounds,
      hapticsEnabled: _hapticsEnabled,
      onSoundEnabledChanged: (enabled) async {
        await _setMute(!enabled);
      },
      onHapticsEnabledChanged: (enabled) async {
        await _setHapticsEnabled(enabled);
      },
      boardThemeSelectorBuilder: (setSheetState, markChanged) {
        return Wrap(
          spacing: 10,
          runSpacing: 10,
          alignment: WrapAlignment.center,
          children: _availableBoardThemes
              .map(
                (mode) => _boardThemeOption(mode, setSheetState, markChanged),
              )
              .toList(),
        );
      },
      pieceThemeSelectorBuilder: (setSheetState, markChanged) {
        return Wrap(
          spacing: 10,
          runSpacing: 10,
          alignment: WrapAlignment.center,
          children: _availablePieceThemes
              .map(
                (mode) => _pieceThemeOption(mode, setSheetState, markChanged),
              )
              .toList(),
        );
      },
      arrowThemeSelectorBuilder: (setSheetState, markChanged) {
        return Wrap(
          spacing: 10,
          runSpacing: 10,
          alignment: WrapAlignment.center,
          children: _availableArrowThemes
              .map(
                (mode) => _arrowThemeOption(mode, setSheetState, markChanged),
              )
              .toList(growable: false),
        );
      },
      showBoardPerspectiveSection: showBoardPerspectiveSection,
      boardPerspectiveSectionBuilder: showBoardPerspectiveSection
          ? (setSheetState, markChanged) {
              final theme = Theme.of(context);
              return Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    'Board Perspective',
                    style: theme.textTheme.titleSmall?.copyWith(
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                  const SizedBox(height: 10),
                  Wrap(
                    spacing: 10,
                    runSpacing: 10,
                    alignment: WrapAlignment.spaceBetween,
                    children: [
                      _perspectiveOption(
                        'White',
                        BoardPerspective.white,
                        setSheetState,
                        markChanged,
                      ),
                      _perspectiveOption(
                        'Black',
                        BoardPerspective.black,
                        setSheetState,
                        markChanged,
                      ),
                      _perspectiveOption(
                        'Auto',
                        BoardPerspective.auto,
                        setSheetState,
                        markChanged,
                      ),
                    ],
                  ),
                ],
              );
            }
          : null,
      showEngineControlsSection: showEngineControlsSection,
      engineDepth: _engineDepth,
      maxEngineDepth: _maxDepthAllowed,
      engineDepthLabelBuilder: _engineDepthSettingLabel,
      suggestedMoves: _multiPvCount,
      maxSuggestedMoves: _maxSuggestionsAllowed,
      onEngineDepthChanged: (value) {
        final changed = value != _engineDepth;
        setState(() => _engineDepth = value);
        if (changed) {
          _clearPositionAnalysisCache();
        }
        _analyze();
      },
      onEngineDepthChangeEnd: (value) {
        final changed = value != _engineDepth;
        setState(() => _engineDepth = value);
        if (changed) {
          _clearPositionAnalysisCache();
        }
        _persistCurrentSettings();
      },
      onSuggestedMovesChanged: (value) {
        _applySuggestionCount(value);
      },
      onSuggestedMovesChangeEnd: (value) {
        _applySuggestionCount(value, persist: true);
      },
      extraSectionsBuilder: (sheetContext, setSheetState, markChanged) {
        final theme = Theme.of(sheetContext);
        final scheme = theme.colorScheme;
        final sectionColor = Color.alphaBlend(
          scheme.primary.withValues(alpha: 0.06),
          scheme.surface,
        );
        final borderColor = scheme.outline.withValues(alpha: 0.24);
        final sections = <Widget>[];

        if (isBoardAnalysisPage) {
          sections.add(
            Container(
              padding: const EdgeInsets.fromLTRB(14, 8, 14, 6),
              decoration: BoxDecoration(
                color: sectionColor,
                border: Border.all(color: borderColor),
                borderRadius: BorderRadius.circular(16),
              ),
              child: SwitchListTile.adaptive(
                contentPadding: EdgeInsets.zero,
                value: _moveAssessmentEnabled,
                title: const Text('Move Assessment'),
                subtitle: const Text(
                  'Show best, good, solid, and mistake labels after moves, independent from center suggestions.',
                ),
                onChanged: (enabled) {
                  if (enabled == _moveAssessmentEnabled) {
                    return;
                  }
                  markChanged();
                  unawaited(_setMoveAssessmentEnabled(enabled));
                  setSheetState(() {});
                },
              ),
            ),
          );
        }

        final hasAllThemes =
            _availableBoardThemes.length >= BoardThemeMode.values.length &&
            _availablePieceThemes.length >= PieceThemeMode.values.length &&
            _availableArrowThemes.length >= ArrowThemeMode.values.length;
        final hasAllStockfishUpgrades =
            _depthTier >= 3 && _maxSuggestionsAllowed >= 10;

        if (!hasAllThemes || !hasAllStockfishUpgrades) {
          final storeButtonLabel = hasAllThemes
              ? 'Open Stockfish Upgrades'
              : 'Open Theme Store';
          final storeButtonIcon = hasAllThemes
              ? Icons.upgrade_rounded
              : Icons.auto_awesome_rounded;
          final initialStoreSection = hasAllThemes
              ? StoreSection.general
              : StoreSection.themes;

          sections.add(
            Container(
              padding: const EdgeInsets.all(14),
              decoration: BoxDecoration(
                color: sectionColor,
                border: Border.all(color: borderColor),
                borderRadius: BorderRadius.circular(16),
              ),
              child: FilledButton.icon(
                onPressed: () {
                  Navigator.of(sheetContext).pop();
                  Future.microtask(
                    () => _openStore(initialSection: initialStoreSection),
                  );
                },
                icon: Icon(storeButtonIcon, size: 18),
                label: Text(storeButtonLabel),
              ),
            ),
          );
        }

        if (isBoardAnalysisPage) {
          final advancedSectionColor = Color.alphaBlend(
            scheme.outline.withValues(alpha: 0.05),
            sectionColor,
          );
          final advancedBorderColor = scheme.outline.withValues(alpha: 0.20);
          final advancedLabelColor = scheme.onSurface.withValues(alpha: 0.58);
          final secondaryTextColor = scheme.onSurface.withValues(alpha: 0.74);
          final nestedSectionColor = Color.alphaBlend(
            scheme.primary.withValues(alpha: 0.05),
            scheme.surface,
          );

          Widget buildOpeningButtonModeTile(OpeningMode mode) {
            final selected = _analysisOpeningButtonMode == mode;
            final locked =
                mode == OpeningMode.sacrificeGlow && !_sacrificeModeOwned;
            final accent = _openingModeButtonColor(mode);
            final tileFill = Color.alphaBlend(
              accent.withValues(alpha: selected ? 0.14 : 0.05),
              scheme.surface,
            );
            final tileBorder = selected
                ? accent.withValues(alpha: 0.60)
                : accent.withValues(alpha: locked ? 0.18 : 0.28);
            final titleColor = locked
                ? scheme.onSurface.withValues(alpha: 0.52)
                : selected
                ? accent
                : scheme.onSurface;
            final bodyColor = locked
                ? scheme.onSurface.withValues(alpha: 0.44)
                : scheme.onSurface.withValues(alpha: 0.70);

            return Opacity(
              opacity: locked ? 0.76 : 1,
              child: Material(
                color: Colors.transparent,
                child: InkWell(
                  borderRadius: BorderRadius.circular(14),
                  onTap: locked
                      ? null
                      : () {
                          if (_analysisOpeningButtonMode == mode) {
                            return;
                          }
                          markChanged();
                          unawaited(_setAnalysisOpeningButtonMode(mode));
                          setSheetState(() {});
                        },
                  child: Ink(
                    padding: const EdgeInsets.all(12),
                    decoration: BoxDecoration(
                      color: tileFill,
                      borderRadius: BorderRadius.circular(14),
                      border: Border.all(color: tileBorder),
                      boxShadow: selected
                          ? [
                              BoxShadow(
                                color: accent.withValues(alpha: 0.16),
                                blurRadius: 16,
                                offset: const Offset(0, 6),
                              ),
                            ]
                          : null,
                    ),
                    child: Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Container(
                          width: 40,
                          height: 40,
                          decoration: BoxDecoration(
                            color: Color.alphaBlend(
                              accent.withValues(alpha: selected ? 0.20 : 0.10),
                              scheme.surface,
                            ),
                            borderRadius: BorderRadius.circular(12),
                            border: Border.all(
                              color: accent.withValues(alpha: 0.34),
                            ),
                          ),
                          child: Icon(
                            _openingButtonModeIcon(mode),
                            color: locked
                                ? accent.withValues(alpha: 0.55)
                                : accent,
                            size: 20,
                          ),
                        ),
                        const SizedBox(width: 10),
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Row(
                                children: [
                                  Expanded(
                                    child: Text(
                                      _openingButtonModeTitle(mode),
                                      style: theme.textTheme.titleSmall
                                          ?.copyWith(
                                            color: titleColor,
                                            fontWeight: FontWeight.w800,
                                          ),
                                    ),
                                  ),
                                  if (selected)
                                    Icon(
                                      Icons.check_circle_rounded,
                                      color: accent,
                                      size: 18,
                                    )
                                  else if (locked)
                                    Icon(
                                      Icons.lock_outline_rounded,
                                      color: scheme.onSurface.withValues(
                                        alpha: 0.42,
                                      ),
                                      size: 18,
                                    ),
                                ],
                              ),
                              const SizedBox(height: 4),
                              Text(
                                _openingButtonModeDescription(mode),
                                style: theme.textTheme.bodySmall?.copyWith(
                                  color: bodyColor,
                                  height: 1.28,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            );
          }

          sections.add(
            Container(
              padding: const EdgeInsets.fromLTRB(14, 14, 14, 12),
              decoration: BoxDecoration(
                color: advancedSectionColor,
                border: Border.all(color: advancedBorderColor),
                borderRadius: BorderRadius.circular(16),
              ),
              child: AnimatedSize(
                duration: const Duration(milliseconds: 220),
                curve: Curves.easeOutCubic,
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'ADVANCED BOARD LAYOUT',
                      style: theme.textTheme.labelSmall?.copyWith(
                        color: advancedLabelColor,
                        fontWeight: FontWeight.w900,
                        letterSpacing: 0.7,
                      ),
                    ),
                    const SizedBox(height: 10),
                    Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                'Head-to-head board',
                                style: theme.textTheme.titleMedium?.copyWith(
                                  fontWeight: FontWeight.w700,
                                ),
                              ),
                              const SizedBox(height: 4),
                              Text(
