  String _avatarRollRateLabel(double rate) {
    final rounded = rate.roundToDouble();
    if ((rate - rounded).abs() < 0.001) {
      return '${rounded.toInt()}%';
    }
    return '${rate.toStringAsFixed(1)}%';
  }

  Future<void> _openTermsOfServiceLink() async {
    final launched = await launchUrl(chessIqTermsOfServiceUri);
    if (launched || !mounted) {
      return;
    }
    await Clipboard.setData(
      const ClipboardData(text: chessIqTermsOfServiceUrl),
    );
    if (!mounted) {
      return;
    }
    ChessIqTransientMessage.show(
      context,
      title: 'Terms link copied',
      message: 'Could not open the Terms of Service here.',
