  Future<void> _purchaseAvatarRoll() async {
    final avatarInventory = context.read<AvatarInventoryProvider>();
    final economy = context.read<EconomyProvider>();
    await avatarInventory.load();

    if (!avatarInventory.hasAvailablePaidRolls) {
      _addLog('All rollable avatars already owned');
      if (mounted) {
        await _showThemedErrorDialog(
          title: 'Avatar Vault Complete',
          message: 'You already own every avatar available from random rolls.',
        );
      }
      return;
    }

    final price = _storefrontCoinPrice(
      StoreOfferIds.avatarRoll,
      AvatarInventoryProvider.paidRollPrice,
    );
    if (!await economy.spendCoins(price)) {
      _addLog('Not enough coins for avatar roll');
      return;
    }

    final result = await avatarInventory.rollPaidAvatar();
    if (result == null) {
      _addLog('Avatar roll failed: no rollable avatar available');
      return;
    }

    unawaited(_playStorePurchaseSound());
    _addLog(
      'Avatar unlocked: ${result.avatar.name} (${result.bucket.label.toLowerCase()})',
    );
    await _showAvatarRollRevealDialog(result.avatar);
  }

  Future<void> _performResetWithSponsoredBreak() async {
    final adService = AdService.instance;
    final shouldAttemptAd =
        !_adFreeOwned && adService.boardResetCooldownRemaining == Duration.zero;
    final wasLocalFriendMatch = _isLocalFriendMatchMode;
    final wasBotMatch = _isBotMatchMode;
    final advanceCompletedLocalFriendRound =
        wasLocalFriendMatch && _gameOutcome != null;
    if (shouldAttemptAd) {
      final shown = await adService.maybeShowBoardResetInterstitial();
      if (!shown) {
        _addLog('Reset interstitial unavailable; continuing without ad');
      } else {
        await _handleAnalysisInterstitialShown();
      }
    }
    if (wasBotMatch) {
      await _handleVsBotMatchStarted();
    }
    if (!mounted) return;
    setState(() {
      if (advanceCompletedLocalFriendRound) {
        _advanceLocalFriendSeriesToNextRound();
      }
      _resetBoard();
      if (wasLocalFriendMatch) {
        _initializeLocalFriendClocks();
      } else {
        _analyze();
      }
    });
    _persistAnalysisSnapshotIfNeeded();
    if (wasLocalFriendMatch) {
      _startLocalFriendClockForCurrentTurn();
    }
    unawaited(_maybeTriggerBotMove());
  }

  Future<void> _watchRewardAdFromStore() async {
    if (!mounted) return;
    final economy = context.read<EconomyProvider>();
    if (!economy.canClaimStoreReward) {
      return;
    }

    final rewardEarned = await AdService.instance.showRewardedAd(
      placement: RewardedPlacement.storeReward,
    );
    if (!mounted) return;
    if (!rewardEarned) {
      await _showThemedErrorDialog(
        title: 'Ad Unavailable',
        message: 'Rewarded ad is unavailable or was not completed.',
        includeInternetHint: true,
      );
      _addLog('Rewarded store ad unavailable or not completed');
      return;
    }

    final claimed = await economy.claimStoreRewardAd();
    if (!claimed) {
      return;
    }

    setState(() {});
    unawaited(_playCoinRewardSound());
    await _saveStoreState();
    _addLog('Reward ad claimed (+120 coins)');
  }

  Future<void> _buyCoinPack(int amount, String label) async {
    final productId = amount == IapProducts.coinPackSAmount
        ? IapProducts.coinPackS
        : IapProducts.coinPackL;

    final success = await PurchaseService.instance.buy(productId);
    if (!success || !mounted) return;

    // EconomyProvider was already credited by PurchaseService._deliver().
    await _saveStoreState();
    if (label == 'Coin Pack L') {
      unawaited(_playCoinBagSoundL());
    } else {
      unawaited(_playCoinBagSound());
    }
    _addLog('Purchased $label (+$amount coins)');
  }

  Future<void> _buyAdFree() async {
    if (_adFreeOwned) return;

    final success = await PurchaseService.instance.buy(
      IapProducts.resetBoardPass,
    );
    if (!success || !mounted) return;

    _adFreeOwned = true;
    await _saveStoreState();
    unawaited(_playStorePurchaseSound());
    _addLog('$_cleanPlayPassTitle activated');
    if (!mounted) return;
    await showDialog<void>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Purchase Complete'),
        content: const Text(
          'Clean Play No-Ad Pass activated. Analysis resets, bot rematches, and new bot matches stay ad-free.',
        ),
        actions: [
          FilledButton(
            onPressed: () => Navigator.of(dialogContext).pop(),
            child: const Text('OK'),
          ),
        ],
      ),
    );
  }

  Future<void> _buyAcademyTuitionPass() async {
    if (_academyTuitionPassOwned) return;

    final success = await PurchaseService.instance.buy(IapProducts.academyPass);
    if (!success || !mounted) return;

    _academyTuitionPassOwned = true;
    await _saveStoreState();
    unawaited(_playStorePurchaseSound());
    _addLog('Academy Tuition Pass activated');
    if (!mounted) return;
    await showDialog<void>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Purchase Complete'),
        content: const Text('Academy Tuition Pass activated.'),
        actions: [
          FilledButton(
            onPressed: () => Navigator.of(dialogContext).pop(),
            child: const Text('OK'),
          ),
        ],
      ),
    );
  }

  String _promoUnlockLabel(String unlockKey) {
    switch (unlockKey) {
      case 'themePackOwned':
        return 'Theme Pack';
      case 'sakuraBoardOwned':
        return 'Sakura board';
      case 'tropicalBoardOwned':
        return 'Tropical board';
      case 'piecePackOwned':
        return 'Piece Set Pack';
      case 'tuttiFruttiOwned':
        return 'Tutti Frutti pieces';
      case 'spectralOwned':
        return 'Spectral pieces';
      case 'monochromePiecesOwned':
        return 'Monochrome pieces';
      case 'pixelArrowThemeOwned':
        return '8-Bit arrows';
      case 'heavyArrowThemeOwned':
        return 'Massive 3D arrows';
      case 'sacrificeModeOwned':
        return 'Sacrifice Mode';
      case 'adFreeOwned':
        return _cleanPlayPassTitle;
      case 'academyTuitionPassOwned':
        return 'Academy Tuition Pass';
