  Widget _buildHeadToHeadEvalBarToggleButton({
    required ColorScheme scheme,
    required bool isLight,
  }) {
    final useMonochrome =
        context.watch<AppThemeProvider>().isMonochrome ||
        _isCinematicThemeEnabled;
    final activeAccent = useMonochrome
        ? scheme.onSurface
        : _evalColorForUi(_displayEvalForPov());
    final iconColor = _headToHeadEvalBarEnabled
        ? activeAccent
        : scheme.onSurface.withValues(alpha: isLight ? 0.78 : 0.58);
    final backgroundColor = Color.alphaBlend(
      (_headToHeadEvalBarEnabled ? activeAccent : scheme.primary).withValues(
        alpha: _headToHeadEvalBarEnabled
            ? (isLight ? 0.16 : 0.10)
            : (isLight ? 0.10 : 0.05),
      ),
      scheme.surface,
    );
    final borderColor = _headToHeadEvalBarEnabled
        ? activeAccent.withValues(alpha: isLight ? 0.56 : 0.36)
        : scheme.outline.withValues(alpha: isLight ? 0.38 : 0.24);

    return Tooltip(
      message: _headToHeadEvalBarEnabled ? 'Hide eval bar' : 'Show eval bar',
      waitDuration: const Duration(milliseconds: 300),
      child: SizedBox.square(
        dimension: 40,
        child: IconButton(
          onPressed: () {
            unawaited(_setHeadToHeadEvalBarEnabled(!_headToHeadEvalBarEnabled));
          },
          icon: Icon(Icons.stacked_bar_chart_rounded, color: iconColor),
          style: IconButton.styleFrom(
            backgroundColor: backgroundColor,
            side: BorderSide(color: borderColor),
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(12),
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildHeadToHeadGlyph(
    BuildContext context, {
    double iconSize = 16,
    double labelSize = 9,
    bool compact = false,
  }) {
    final scheme = Theme.of(context).colorScheme;
    final accent = scheme.primary;
    final playerColor = scheme.onSurface.withValues(alpha: 0.82);
    final opponentColor = scheme.onSurface.withValues(alpha: 0.62);
    final spacing = compact ? 2.0 : 4.0;

    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        Icon(Icons.person_rounded, size: iconSize, color: playerColor),
        SizedBox(width: spacing),
        Container(
          padding: EdgeInsets.symmetric(
            horizontal: compact ? 4 : 5,
            vertical: compact ? 2 : 3,
          ),
          decoration: BoxDecoration(
            color: accent.withValues(alpha: compact ? 0.12 : 0.14),
            borderRadius: BorderRadius.circular(999),
            border: Border.all(color: accent.withValues(alpha: 0.26)),
          ),
          child: Text(
            'VS',
            style: TextStyle(
              color: accent,
              fontSize: labelSize,
              fontWeight: FontWeight.w800,
              letterSpacing: compact ? 0.3 : 0.5,
              height: 1,
            ),
          ),
        ),
        SizedBox(width: spacing),
        Icon(Icons.person_rounded, size: iconSize, color: opponentColor),
      ],
    );
  }

  void _applyPerspectiveSelection(BoardPerspective perspective) {
    if (perspective != BoardPerspective.headToHead) {
      _analysisStandardPerspective = perspective;
    } else if (_perspective != BoardPerspective.headToHead) {
      _analysisStandardPerspective = _perspective;
    }

    if (_perspective == perspective) {
      return;
    }

    setState(() {
      _perspective = perspective;
      if (perspective == BoardPerspective.headToHead) {
        _suggestionsEnabled = false;
        _openingMode = OpeningMode.off;
        _openingModeFeedbackLabel = null;
        _openingModeFeedbackColor = null;
        _selectedGambit = null;
        _gambitPreviewLines = <EngineLine>[];
        _gambitSelectedFrom = null;
        _legalTargets.clear();
        _gambitAvailableTargets.clear();
        _topLines = <EngineLine>[];
        _analysisLines = <EngineLine>[];
        _analysisLinesFen = null;
        _currentDepth = 0;
      }
    });

    if (perspective == BoardPerspective.headToHead) {
      _cancelSacrificeScanSearches(reason: 'head-to-head perspective');
      if (_analysisEditMode) {
        _setAnalysisEditMode(false);
      }
      _send('stop');
      if (_headToHeadEvalBarEnabled) {
        _analyze();
      }
    }

    _persistCurrentSettings();
  }

  Widget _perspectiveOption(
    String label,
    BoardPerspective p,
    StateSetter setL,
    VoidCallback markChanged,
  ) {
    final selectedPerspective = _perspective == BoardPerspective.headToHead
        ? (_analysisStandardPerspective == BoardPerspective.headToHead
              ? _defaultPerspective
              : _analysisStandardPerspective)
        : _perspective;
    final sel = selectedPerspective == p;
    final scheme = Theme.of(context).colorScheme;
    Widget kingWidget;
    if (p == BoardPerspective.white) {
      kingWidget = _pieceImage('k_w', width: 20, height: 20);
    } else if (p == BoardPerspective.black) {
      kingWidget = _pieceImage('k_b', width: 20, height: 20);
    } else if (p == BoardPerspective.headToHead) {
      kingWidget = _buildHeadToHeadGlyph(context, iconSize: 13, labelSize: 8);
    } else {
      kingWidget = Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          _pieceImage('k_w', width: 15, height: 15),
          Icon(
            Icons.sync,
            size: 11,
            color: scheme.onSurface.withValues(alpha: 0.7),
          ),
          _pieceImage('k_b', width: 15, height: 15),
        ],
      );
    }
    return GestureDetector(
      onTap: () {
        if (sel) return;
        markChanged();
        _applyPerspectiveSelection(p);
        setL(() {});
      },
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
        decoration: BoxDecoration(
          color: sel
              ? scheme.primary.withValues(alpha: 0.20)
              : Color.alphaBlend(
                  scheme.primary.withValues(alpha: 0.05),
                  scheme.surface,
                ),
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
            color: sel
                ? scheme.primary.withValues(alpha: 0.62)
                : scheme.outline.withValues(alpha: 0.30),
          ),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            kingWidget,
            const SizedBox(width: 5),
            Text(label, style: TextStyle(color: scheme.onSurface)),
          ],
        ),
      ),
    );
  }

  Widget _boardThemeOption(
    BoardThemeMode mode,
    StateSetter setL,
    VoidCallback markChanged,
  ) {
    final selected = _boardThemeMode == mode;
    return ThemeSelectorTile(
      selected: selected,
      onTap: () {
        if (selected) return;
        markChanged();
        setState(() => _boardThemeMode = mode);
        setL(() {});
        _persistCurrentSettings();
        unawaited(
          context.read<AppThemeProvider>().setBoardThemeIndex(mode.index),
        );
      },
      child: _boardThemeSwatch(mode),
    );
