  Widget _pieceImage(
    String piece, {
    double? width,
    double? height,
    PieceThemeMode? theme,
    bool applyBlackOutline = true,
    double blackOutlineOverflowPx = 0,
    bool orientForHeadToHeadPerspective = false,
    String? motionSeed,
  }) {
    final activeTheme = _activePieceThemeForPiece(piece, theme: theme);
    final assetPiece = AppThemeProvider.pieceAssetForIndex(
      activeTheme.index,
      piece,
    );
    final baseImage = Image.asset(
      'assets/pieces/$assetPiece.png',
      width: width,
      height: height,
    );
    final tinted = activeTheme == PieceThemeMode.classic
        ? baseImage
        : ColorFiltered(
            colorFilter: ColorFilter.mode(
              _pieceTintColor(piece, activeTheme),
              BlendMode.modulate,
            ),
            child: baseImage,
          );

    final isBlackPiece = piece.endsWith('_b');
    final isSpectral = activeTheme == PieceThemeMode.spectral;
    Widget result;

    Widget maybeOrientForHeadToHeadPerspective(Widget child) {
      if (!orientForHeadToHeadPerspective || !_isHeadToHeadPerspective) {
        return child;
      }

      if (!_isLockedHeadToHeadPerspective) {
        return child;
      }

      final shouldRotateForTopSeat = _isLocalFriendMatchMode
          ? isBlackPiece == _localFriendBottomSeatIsWhite
          : isBlackPiece;

      if (!shouldRotateForTopSeat) {
        return child;
      }

      return Transform.rotate(angle: pi, child: child);
    }

    if (!isBlackPiece || !applyBlackOutline) {
      if (!isSpectral) {
        result = tinted;
      } else {
        result = Stack(
          clipBehavior: Clip.none,
          children: [
            for (final offset in const [
              Offset(-0.8, -0.8),
              Offset(0.8, -0.5),
              Offset(-0.5, 0.8),
              Offset(0.8, 0.8),
            ])
              Transform.translate(
                offset: offset,
                child: Opacity(
                  opacity: 0.18,
                  child: ColorFiltered(
                    colorFilter: ColorFilter.mode(
                      _pieceTintColor(
                        piece,
                        activeTheme,
                      ).withValues(alpha: 0.4),
                      BlendMode.srcIn,
                    ),
                    child: baseImage,
                  ),
                ),
              ),
            tinted,
          ],
        );
      }
    } else {
      final outlineOffsets = blackOutlineOverflowPx <= 0
          ? AppThemeProvider.darkPieceOutlineOffsets
          : AppThemeProvider.darkPieceOutlineOffsets
                .map((offset) {
                  final distance = offset.distance;
                  if (distance == 0) {
                    return offset;
                  }
                  final extraRadius = blackOutlineOverflowPx * 0.5;
                  return Offset(
                    offset.dx + (offset.dx / distance) * extraRadius,
                    offset.dy + (offset.dy / distance) * extraRadius,
                  );
                })
                .toList(growable: false);

      result = Stack(
        clipBehavior: Clip.none,
        children: [
          if (isSpectral)
            for (final offset in const [
              Offset(-0.8, -0.8),
              Offset(0.8, -0.5),
              Offset(-0.5, 0.8),
              Offset(0.8, 0.8),
            ])
              Transform.translate(
                offset: offset,
                child: Opacity(
                  opacity: 0.18,
                  child: ColorFiltered(
                    colorFilter: ColorFilter.mode(
                      _pieceTintColor(
                        piece,
                        activeTheme,
                      ).withValues(alpha: 0.4),
                      BlendMode.srcIn,
                    ),
                    child: baseImage,
                  ),
                ),
              ),
          for (final offset in outlineOffsets)
            Transform.translate(
              offset: offset,
              child: Opacity(
                opacity: 0.18,
                child: Image.asset(
                  'assets/pieces/$assetPiece.png',
                  width: width,
                  height: height,
                  color: const Color(0xFFF7FBFF),
                  colorBlendMode: BlendMode.srcIn,
                ),
              ),
            ),
          tinted,
        ],
      );
    }

    if (!isSpectral) {
      return maybeOrientForHeadToHeadPerspective(result);
    }

    return maybeOrientForHeadToHeadPerspective(
      AnimatedBuilder(
        animation: _pulseController,
        builder: (context, child) {
          final phase = _pieceThemePhase(piece, motionSeed);
          final phase2 = _pieceThemePhase2(piece, motionSeed);
          final phase3 = _pieceThemePhase3(piece, motionSeed);
          final frequency =
              0.48 + (_pieceThemeHash(piece, motionSeed) % 13) * 0.017;
          final elapsedSeconds =
              _spectralMotionClock.elapsedMicroseconds /
              Duration.microsecondsPerSecond;
          final t = elapsedSeconds * frequency + phase;
          final shimmer =
              (sin(t * 1.17) * 0.42) +
              (sin(t * 0.73 + phase2) * 0.34) +
              (cos(t * 1.43 + phase3) * 0.24);
          final pulse = (0.46 + shimmer * 0.08).clamp(0.36, 0.56);
          final flutterOffset = Offset(
            cos(t * 1.31 + phase2) * (0.14 + pulse * 0.18),
            sin(t * 1.47 + phase3) * (0.12 + pulse * 0.20),
          );
          final glowColor = _pieceTintColor(
            piece,
            activeTheme,
          ).withValues(alpha: (0.20 + pulse * 0.18).clamp(0.22, 0.36));
          final trailOffsets =
              <Offset>[
                    const Offset(-0.85, -0.62),
                    const Offset(0.78, -0.18),
                    const Offset(-0.42, 0.88),
                  ]
                  .map(
                    (offset) =>
                        offset * (0.74 + pulse * 0.34) +
                        flutterOffset * (0.34 + pulse * 0.12),
                  )
                  .toList(growable: false);

          return Container(
            decoration: BoxDecoration(
              boxShadow: [
                BoxShadow(
                  color: glowColor,
                  blurRadius: 11 + pulse * 8,
                  spreadRadius: 1.2 + pulse * 1.8,
                ),
              ],
            ),
            child: Stack(
              clipBehavior: Clip.none,
              children: [
                for (final offset in trailOffsets)
                  Transform.translate(
                    offset: offset,
                    child: Opacity(
                      opacity: (0.095 - pulse * 0.018).clamp(0.055, 0.10),
                      child: ColorFiltered(
                        colorFilter: ColorFilter.mode(
                          glowColor.withValues(alpha: 0.20),
                          BlendMode.srcIn,
                        ),
                        child: baseImage,
                      ),
                    ),
                  ),
                Transform.translate(
                  offset: flutterOffset * 0.38,
                  child: result,
                ),
              ],
            ),
          );
        },
      ),
    );
  }

  int _pieceThemeHash(String piece, String? motionSeed) {
    final key = '$piece:${motionSeed ?? piece}';
    return key.codeUnits.fold<int>(0, (sum, value) => sum + value * 31);
  }

  double _pieceThemePhase(String piece, [String? motionSeed]) {
    return (_pieceThemeHash(piece, motionSeed) % 1000) * 0.0062831853;
  }

  double _pieceThemePhase2(String piece, [String? motionSeed]) {
    return ((_pieceThemeHash(piece, motionSeed) * 3 + 17) % 1000) *
        0.0062831853;
  }

  double _pieceThemePhase3(String piece, [String? motionSeed]) {
    return ((_pieceThemeHash(piece, motionSeed) * 5 + 43) % 1000) *
        0.0062831853;
  }

  Color _pieceTintColor(String piece, PieceThemeMode theme) {
    return AppThemeProvider.pieceTintColorForIndex(theme.index, piece);
  }

